--
-- Name: _guard_hard_delete_agent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._guard_hard_delete_agent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agent_tenant_id uuid;
BEGIN
  -- Get the agent's tenant
  SELECT tenant_id INTO v_agent_tenant_id FROM agents WHERE id = OLD.id;
  
  -- V-14002 FIX: Check role is scoped to the agent's tenant, not any tenant
  IF NOT EXISTS (
    SELECT 1 FROM user_roles 
    WHERE user_id = auth.uid() 
    AND role IN ('admin', 'super_admin')
    AND (tenant_id = v_agent_tenant_id OR role = 'super_admin')
  ) THEN
    INSERT INTO security_logs (event_type, severity, message, user_id, tenant_id)
    VALUES ('UNAUTHORIZED_DELETE_ATTEMPT', 'critical', 
      'Unauthorized hard_delete_agent attempt', auth.uid()::text, 
      COALESCE(v_agent_tenant_id::text, 'unknown'));
    RAISE EXCEPTION 'Unauthorized: admin role in agent tenant required for hard_delete_agent';
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: acknowledge_all_alerts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acknowledge_all_alerts(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count integer;
  v_user_id uuid;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  v_user_id := auth.uid();

  -- Verify user has access to this tenant
  IF NOT EXISTS (
    SELECT 1 FROM user_roles
    WHERE user_id = v_user_id
      AND tenant_id = p_tenant_id
      AND role IN ('admin', 'super_admin')
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Unauthorized'
    );
  END IF;

  -- Acknowledge all unresolved alerts (including resolved_by and human_reviewed for critical alerts)
  UPDATE system_alerts
  SET 
    resolved = true,
    resolved_at = NOW(),
    resolved_by = v_user_id,
    acknowledged = true,
    acknowledged_at = NOW(),
    acknowledged_by = v_user_id,
    human_reviewed = true,
    reviewed_by = v_user_id,
    reviewed_at = NOW(),
    resolution_notes = 'Reconhecido em massa pelo administrador'
  WHERE tenant_id = p_tenant_id
    AND resolved = false;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'acknowledged_count', v_count
  );
END;
$$;


--
-- Name: aggregate_daily_metrics(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aggregate_daily_metrics(p_date date DEFAULT (CURRENT_DATE - 1)) RETURNS TABLE(agents_processed bigint, rows_inserted bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agents BIGINT := 0;
  v_inserted BIGINT := 0;
BEGIN
  PERFORM _assert_service_role_or_super_admin(); -- SSA-SEC-008

  INSERT INTO public.agent_metrics_daily (
    tenant_id, agent_id, metric_date,
    avg_cpu_percent, max_cpu_percent, min_cpu_percent,
    avg_memory_percent, max_memory_percent, min_memory_percent,
    avg_disk_percent, max_disk_percent,
    sample_count, max_uptime_seconds
  )
  SELECT 
    m.tenant_id, m.agent_id, p_date,
    ROUND(AVG(m.cpu_usage_percent), 2), MAX(m.cpu_usage_percent), MIN(m.cpu_usage_percent),
    ROUND(AVG(m.memory_usage_percent), 2), MAX(m.memory_usage_percent), MIN(m.memory_usage_percent),
    ROUND(AVG(m.disk_usage_percent), 2), MAX(m.disk_usage_percent),
    COUNT(*)::INTEGER, MAX(m.uptime_seconds)
  FROM public.agent_system_metrics_partitioned m
  WHERE m.collected_at >= p_date::timestamp with time zone
    AND m.collected_at < (p_date + 1)::timestamp with time zone
  GROUP BY m.tenant_id, m.agent_id
  ON CONFLICT (agent_id, metric_date) DO UPDATE SET
    avg_cpu_percent = EXCLUDED.avg_cpu_percent, max_cpu_percent = EXCLUDED.max_cpu_percent,
    min_cpu_percent = EXCLUDED.min_cpu_percent, avg_memory_percent = EXCLUDED.avg_memory_percent,
    max_memory_percent = EXCLUDED.max_memory_percent, min_memory_percent = EXCLUDED.min_memory_percent,
    avg_disk_percent = EXCLUDED.avg_disk_percent, max_disk_percent = EXCLUDED.max_disk_percent,
    sample_count = EXCLUDED.sample_count, max_uptime_seconds = EXCLUDED.max_uptime_seconds;
  
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  SELECT COUNT(DISTINCT agent_id) INTO v_agents
  FROM public.agent_system_metrics_partitioned
  WHERE collected_at >= p_date::timestamp with time zone
    AND collected_at < (p_date + 1)::timestamp with time zone;
  
  agents_processed := v_agents;
  rows_inserted := v_inserted;
  RETURN NEXT;
END;
$$;


