--
-- Name: ai_shadow_validate_action(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_shadow_validate_action() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.risk_level = 'low' THEN
    NEW.ai_validation_status := 'pass';
    NEW.ai_validation_reason := 'Low risk action. No anomalies detected.';
  ELSIF NEW.risk_level = 'medium' THEN
    NEW.ai_validation_status := 'pass';
    NEW.ai_validation_reason := 'Medium risk action. Within acceptable parameters.';
  ELSE
    NEW.ai_validation_status := 'warn';
    NEW.ai_validation_reason := 'High risk action. Recommend human review.';
  END IF;
  NEW.ai_validated_at := NOW();
  RETURN NEW;
END;
$$;


--
-- Name: ai_validate_action(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_validate_action() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Critical actions always require escalation
  IF NEW.action_type IN ('agent_isolate', 'policy_disable', 'network_isolate', 'kill_process', 'revoke_token') THEN
    NEW.ai_validation_status := 'escalate';
    NEW.ai_validation_score := 0.95;
    NEW.ai_validation_reason := 'Critical action requires dual approval';
    NEW.requires_approval := true;
    
  -- High-risk actions need human review
  ELSIF NEW.action_type IN ('quarantine', 'stop_service', 'disable_service', 'restart_agent') THEN
    NEW.ai_validation_status := 'escalate';
    NEW.ai_validation_score := 0.7;
    NEW.ai_validation_reason := 'High-risk action requires human review';
    NEW.requires_approval := true;
    
  -- Medium-risk actions can be batched
  ELSIF NEW.action_type IN ('update_policy', 'create_job', 'acknowledge_alert') THEN
    NEW.ai_validation_status := 'pass';
    NEW.ai_validation_score := 0.4;
    NEW.ai_validation_reason := 'Medium-risk action validated for batch review';
    
  -- Low-risk actions can auto-execute
  ELSE
    NEW.ai_validation_status := 'pass';
    NEW.ai_validation_score := 0.1;
    NEW.ai_validation_reason := 'Low-risk action auto-validated';
  END IF;
  
  NEW.ai_validated_at := NOW();
  
  RETURN NEW;
END;
$$;


--
-- Name: alert_long_offline_agents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.alert_long_offline_agents() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agent RECORD;
  v_count int := 0;
  v_existing int;
BEGIN
  -- V-14004 FIX: Require service_role or super_admin
  PERFORM _assert_service_role_or_super_admin();

  FOR v_agent IN
    SELECT id, agent_name, tenant_id, last_heartbeat,
      EXTRACT(EPOCH FROM (NOW() - last_heartbeat)) / 3600 AS hours_offline
    FROM agents
    WHERE status = 'inactive'
      AND last_heartbeat IS NOT NULL
      AND last_heartbeat < NOW() - interval '48 hours'
  LOOP
    SELECT COUNT(*) INTO v_existing FROM system_alerts
    WHERE agent_id = v_agent.id AND alert_type = 'agent_long_offline' AND resolved = false;

    IF v_existing = 0 THEN
      INSERT INTO system_alerts (
        tenant_id, agent_id, alert_type, severity, title, message, details, source
      ) VALUES (
        v_agent.tenant_id, v_agent.id, 'agent_long_offline', 'high',
        'Agente offline há mais de 48h: ' || v_agent.agent_name,
        'O agente ' || v_agent.agent_name || ' está sem comunicação há ' || ROUND(v_agent.hours_offline::numeric) || ' horas.',
        jsonb_build_object('agent_name', v_agent.agent_name, 'hours_offline', ROUND(v_agent.hours_offline::numeric), 'last_heartbeat', v_agent.last_heartbeat),
        'system'
      );
      v_count := v_count + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('alerts_created', v_count);
END;
$$;


