CREATE FUNCTION public.alert_on_integrity_breach() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT NEW.chain_valid AND NOT COALESCE(NEW.alert_sent, false) THEN
    INSERT INTO public.system_alerts (tenant_id, alert_type, severity, title, message)
    VALUES (
      NEW.tenant_id,
      'audit_integrity_breach',
      'critical',
      'Violação de Integridade Detectada',
      format('Cadeia de auditoria quebrada. %s logs afetados.', COALESCE(NEW.breaks_detected, 0))
    );
    NEW.alert_sent := true;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: apply_agent_isolation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_agent_isolation(p_agent_id uuid, p_reason text DEFAULT 'Automated isolation due to security threats'::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- SECURITY: Verify agent belongs to caller's tenant (or caller is super admin)
  IF NOT EXISTS (
    SELECT 1 FROM public.agents a
    WHERE a.id = p_agent_id
    AND (a.tenant_id = get_active_tenant_id() OR is_current_super_admin())
  ) THEN
    RAISE EXCEPTION 'Unauthorized: Agent % does not belong to your tenant', p_agent_id;
  END IF;

  -- Isolate the agent
  UPDATE public.agents
  SET 
    is_isolated = true,
    isolated_at = NOW(),
    isolation_reason = p_reason
  WHERE id = p_agent_id;
  
  -- Cancel all pending jobs for this agent
  UPDATE public.jobs
  SET 
    status = 'cancelled',
    error_message = 'Cancelled: Agent isolated - ' || p_reason,
    completed_at = NOW()
  WHERE agent_id = p_agent_id
    AND status IN ('queued', 'delivered');
  
  RETURN FOUND;
END;
$$;


