-- Name: FUNCTION apply_agent_isolation(p_agent_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.apply_agent_isolation(p_agent_id uuid, p_reason text) IS 'SECURITY: Tenant-verified agent isolation. Requires caller to own the agent via tenant_id check. ADR-VELLUM-001.';


--
-- Name: apply_agent_throttle(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_agent_throttle(p_agent_id uuid, p_poll_interval_seconds integer DEFAULT 300, p_reason text DEFAULT 'Automated throttle due to high request rate'::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- SECURITY: Verify agent belongs to caller's tenant (or caller is super admin)
  IF NOT EXISTS (
    SELECT 1 FROM public.agents a
    WHERE a.id = p_agent_id
    AND (a.tenant_id = get_active_tenant_id() OR is_current_super_admin())
  ) THEN
    RAISE EXCEPTION 'Unauthorized: Agent % does not belong to your tenant', p_agent_id;
  END IF;

  UPDATE public.agents
  SET 
    is_throttled = true,
    throttled_at = NOW(),
    throttle_reason = p_reason,
    poll_interval_seconds = p_poll_interval_seconds
  WHERE id = p_agent_id;
  
  RETURN FOUND;
END;
$$;


