--
-- Name: archive_agent(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_agent(p_agent_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant_id uuid;
  v_caller_tenant uuid;
BEGIN
  SELECT tenant_id INTO v_tenant_id FROM public.agents WHERE id = p_agent_id;
  IF v_tenant_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Agent not found');
  END IF;

  v_caller_tenant := public.get_active_tenant_id();
  IF v_caller_tenant IS NULL OR v_caller_tenant <> v_tenant_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  UPDATE public.agents
  SET status = 'archived', archived_at = now(), archived_reason = 'user_requested'
  WHERE id = p_agent_id AND tenant_id = v_tenant_id;

  INSERT INTO public.agent_archive_events (agent_id, tenant_id, reason, actor_type, actor_id)
  VALUES (p_agent_id, v_tenant_id, 'user_requested', 'user', auth.uid());

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: archive_old_evidence_logs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_old_evidence_logs(retention_days integer DEFAULT 90) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  archived_count INTEGER;
BEGIN
  PERFORM _assert_service_role_or_super_admin(); -- SSA-SEC-008

  DELETE FROM agent_evidence_logs 
  WHERE created_at < NOW() - (retention_days || ' days')::INTERVAL;
  
  GET DIAGNOSTICS archived_count = ROW_COUNT;
  RETURN archived_count;
END;
$$;


--
-- Name: FUNCTION archive_old_evidence_logs(retention_days integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.archive_old_evidence_logs(retention_days integer) IS 'Archives evidence logs older than specified days (default 90). Returns count of deleted rows.';


--
-- Name: archive_old_executions(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_old_executions(p_older_than_days integer DEFAULT 90, p_batch_size integer DEFAULT 1000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_archived INTEGER := 0;
  v_deleted INTEGER := 0;
BEGIN
  IF NOT is_current_super_admin() THEN
    RAISE EXCEPTION 'Only super_admin can archive executions';
  END IF;

  -- Etapa 1: Arquivar execuções antigas (CTE correto)
  WITH to_archive AS (
    SELECT id FROM job_executions
    WHERE created_at < NOW() - (p_older_than_days || ' days')::INTERVAL
      AND archived_at IS NULL
    LIMIT p_batch_size
  )
  UPDATE job_executions je
  SET archived_at = NOW()
  FROM to_archive ta
  WHERE je.id = ta.id;
  
  GET DIAGNOSTICS v_archived = ROW_COUNT;
  
  -- Etapa 2: Deletar com CTE (CORREÇÃO CRÍTICA - PostgreSQL não suporta LIMIT em DELETE)
  WITH to_delete AS (
    SELECT id FROM job_executions
    WHERE archived_at < NOW() - INTERVAL '30 days'
    LIMIT p_batch_size
  )
  DELETE FROM job_executions je
  USING to_delete td
  WHERE je.id = td.id;
  
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  
  RETURN jsonb_build_object(
    'archived', v_archived,
    'deleted', v_deleted,
    'older_than_days', p_older_than_days
  );
END;
$$;


--
-- Name: FUNCTION archive_old_executions(p_older_than_days integer, p_batch_size integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.archive_old_executions(p_older_than_days integer, p_batch_size integer) IS 'Arquiva e deleta job_executions antigas. Usa CTE para batch (PostgreSQL não suporta LIMIT em DELETE).';


--
-- Name: assert_system_allows_jobs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_system_allows_jobs() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  current_mode system_operational_mode;
BEGIN
  SELECT mode INTO current_mode FROM system_global_state LIMIT 1;
  
  IF current_mode = 'emergency_stop' THEN
    RAISE EXCEPTION 'System in emergency mode - jobs blocked';
  END IF;
END;
$$;


--
-- Name: assert_system_not_stopped(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_system_not_stopped() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.system_global_state
    WHERE mode = 'emergency_stop'
      AND (expires_at IS NULL OR expires_at > now())
    ORDER BY triggered_at DESC
    LIMIT 1
  ) THEN
    RAISE EXCEPTION 'SYSTEM HALTED BY GLOBAL KILL SWITCH';
  END IF;
END;
$$;


--
-- Name: audit_ai_action_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_ai_action_changes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.audit_logs (
    tenant_id, user_id, action, resource_type, resource_id,
    details, success, state_before, state_after
  ) VALUES (
    COALESCE(NEW.tenant_id, OLD.tenant_id),
    auth.uid(),
    TG_OP || '_ai_action',
    'ai_action',
    COALESCE(NEW.id, OLD.id)::text,
    jsonb_build_object(
      'action_type', COALESCE(NEW.action_type, OLD.action_type),
      'insight_id', COALESCE(NEW.insight_id, OLD.insight_id),
      'status', COALESCE(NEW.status, OLD.status),
      'risk_level', COALESCE(NEW.risk_level, OLD.risk_level)
    ),
    true,
    CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) ELSE NULL END,
    to_jsonb(NEW)
  );
  RETURN NEW;
END;
$$;


--
-- Name: audit_credential_rotation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_credential_rotation() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_stale_hmac INTEGER := 0;
  v_stale_tokens INTEGER := 0;
  v_stale_keys INTEGER := 0;
  v_threshold INTERVAL := '90 days';
  v_system_tenant_id UUID;
BEGIN
  -- Get a system tenant for alerts
  SELECT id INTO v_system_tenant_id FROM tenants ORDER BY created_at ASC LIMIT 1;

  SELECT COUNT(*) INTO v_stale_hmac
  FROM agents a
  WHERE a.status = 'active'
    AND a.enrolled_at < NOW() - v_threshold
    AND NOT EXISTS (
      SELECT 1 FROM secret_rotation_log srl
      WHERE srl.secret_name = 'hmac_secret:' || a.id::text
        AND srl.rotated_at > NOW() - v_threshold
    );

  SELECT COUNT(*) INTO v_stale_tokens
  FROM agent_tokens at2
  JOIN agents a ON a.id = at2.agent_id
  WHERE a.status = 'active'
    AND at2.is_active = true
    AND at2.created_at < NOW() - v_threshold;

  SELECT COUNT(*) INTO v_stale_keys
  FROM enrollment_keys ek
  WHERE ek.is_active = true
    AND ek.created_at < NOW() - v_threshold;

  INSERT INTO secret_rotation_log (
    secret_name, rotated_at, rotated_by, rotation_method, status, notes, tenant_id
  ) VALUES (
    'credential_audit',
    NOW(),
    'system:rotate-audit',
    'automated_audit',
    CASE WHEN (v_stale_hmac + v_stale_tokens + v_stale_keys) = 0 THEN 'healthy' ELSE 'warning' END,
    format('Audit: %s stale HMAC secrets, %s stale tokens, %s stale enrollment keys (threshold: 90 days)',
      v_stale_hmac, v_stale_tokens, v_stale_keys),
    v_system_tenant_id
  );

  IF (v_stale_hmac + v_stale_tokens + v_stale_keys) > 0 AND v_system_tenant_id IS NOT NULL THEN
    INSERT INTO system_alerts (
      tenant_id, alert_type, severity, title, message, details, source
    ) VALUES (
      v_system_tenant_id,
      'credential_rotation_overdue',
      'high',
      'Credenciais com rotação atrasada detectadas',
      format('%s HMAC secrets, %s tokens e %s enrollment keys sem rotação há mais de 90 dias',
        v_stale_hmac, v_stale_tokens, v_stale_keys),
      jsonb_build_object(
        'stale_hmac', v_stale_hmac,
        'stale_tokens', v_stale_tokens,
        'stale_keys', v_stale_keys,
        'threshold_days', 90
      ),
      'rotate-audit'
    );
  END IF;

  RETURN jsonb_build_object(
    'stale_hmac', v_stale_hmac,
    'stale_tokens', v_stale_tokens,
    'stale_keys', v_stale_keys,
    'total_stale', v_stale_hmac + v_stale_tokens + v_stale_keys,
    'status', CASE WHEN (v_stale_hmac + v_stale_tokens + v_stale_keys) = 0 THEN 'healthy' ELSE 'warning' END,
    'audited_at', NOW()
  );
END;
$$;


--
-- Name: audit_dlq_operations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_dlq_operations() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.resolved_by IS NULL THEN
      RAISE EXCEPTION 'DLQ_SECURITY: Cannot delete unreviewed DLQ item. Review required before disposal.'
        USING ERRCODE = '23514';
    END IF;
    IF auth.uid() IS NOT NULL THEN
      INSERT INTO audit_logs (tenant_id, user_id, action, resource_type, resource_id, details, success)
      VALUES (
        OLD.tenant_id, auth.uid(), 'dlq_item_deleted', 'failed_jobs_dlq', OLD.id::text,
        jsonb_build_object('job_type', OLD.job_type, 'risk_category', OLD.risk_category), true
      );
    END IF;
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.resolved_by IS NOT NULL AND OLD.resolved_by IS NULL THEN
      IF auth.uid() IS NOT NULL THEN
        INSERT INTO audit_logs (tenant_id, user_id, action, resource_type, resource_id, details, success)
        VALUES (
          NEW.tenant_id, auth.uid(), 'dlq_item_reviewed', 'failed_jobs_dlq', NEW.id::text,
          jsonb_build_object('resolved_by', NEW.resolved_by, 'review_notes', NEW.review_notes, 'risk_category', NEW.risk_category), true
        );
      END IF;
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'INSERT' THEN
    -- Skip audit log for system-generated inserts (no authenticated user)
    IF auth.uid() IS NOT NULL THEN
      INSERT INTO audit_logs (tenant_id, user_id, action, resource_type, resource_id, details, success)
      VALUES (
        NEW.tenant_id, auth.uid(),
        'dlq_item_created', 'failed_jobs_dlq', NEW.id::text,
        jsonb_build_object('job_type', NEW.job_type, 'error_message', NEW.error_message), true
      );
    END IF;
    RETURN NEW;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: authorize_agent_recovery(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authorize_agent_recovery(p_agent_id uuid, p_approved_by uuid, p_expires_in_minutes integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
  v_caller_tenant UUID;
  v_mode TEXT;
  v_event_id UUID;
  v_auth_id UUID;
  v_payload JSONB;
BEGIN
  -- SSA-SEC-008: Validate caller has access to agent's tenant
  v_caller_tenant := get_active_tenant_id();
  
  SELECT tenant_id, agent_mode INTO v_tenant_id, v_mode FROM agents WHERE id = p_agent_id;
  IF v_tenant_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Agent not found'); END IF;
  
  -- Cross-tenant check
  IF v_tenant_id IS DISTINCT FROM v_caller_tenant AND NOT is_current_super_admin() THEN
    INSERT INTO security_logs (tenant_id, ip_address, endpoint, attack_type, severity, blocked, details)
    VALUES (v_caller_tenant, 'system', 'authorize_agent_recovery', 'cross_tenant_attempt', 'critical', true,
      jsonb_build_object('user_id', auth.uid(), 'agent_id', p_agent_id, 'agent_tenant', v_tenant_id, 'caller_tenant', v_caller_tenant));
    RETURN jsonb_build_object('success', false, 'error', 'TENANT_MISMATCH');
  END IF;
  
  IF v_mode != 'SAFE_MODE' THEN RETURN jsonb_build_object('success', false, 'error', 'Not in SAFE_MODE'); END IF;
  
  SELECT id INTO v_event_id FROM agent_safe_mode_events
  WHERE agent_id = p_agent_id AND resolved_at IS NULL ORDER BY created_at DESC LIMIT 1;
  
  v_payload := jsonb_build_object(
    'agent_id', p_agent_id,
    'transition', 'SAFE_MODE → RECOVERY',
    'issued_at', NOW(),
    'expires_at', NOW() + (p_expires_in_minutes || ' minutes')::INTERVAL,
    'approved_by', p_approved_by
  );
  
  INSERT INTO agent_recovery_authorizations (
    agent_id, tenant_id, safe_mode_event_id, requested_by, approved_by,
    signed_payload, status, expires_at
  ) VALUES (
    p_agent_id, v_tenant_id, v_event_id, p_approved_by, p_approved_by,
    v_payload, 'approved', NOW() + (p_expires_in_minutes || ' minutes')::INTERVAL
  ) RETURNING id INTO v_auth_id;
  
  UPDATE agents SET agent_mode = 'RECOVERY' WHERE id = p_agent_id;
  
  RETURN jsonb_build_object('success', true, 'authorization_id', v_auth_id, 'signed_payload', v_payload);
END;
$$;


--
-- Name: FUNCTION authorize_agent_recovery(p_agent_id uuid, p_approved_by uuid, p_expires_in_minutes integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.authorize_agent_recovery(p_agent_id uuid, p_approved_by uuid, p_expires_in_minutes integer) IS 'SSA-SEC-008: Requires tenant match or super_admin. Cross-tenant attempts logged to security_logs.';


--
-- Name: auto_acknowledge_old_insights(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_acknowledge_old_insights() RETURNS TABLE(acknowledged_count integer, insight_ids uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count INTEGER;
  v_ids UUID[];
BEGIN
  PERFORM _assert_service_role_or_super_admin(); -- SSA-SEC-008

  WITH updated AS (
    UPDATE public.ai_insights
    SET acknowledged = true, acknowledged_at = NOW()
    WHERE acknowledged = false AND severity = 'info'
      AND created_at < NOW() - INTERVAL '30 days'
    RETURNING id
  )
  SELECT COUNT(*)::INTEGER, ARRAY_AGG(id)
  INTO v_count, v_ids FROM updated;
  
  IF v_count > 0 THEN RAISE NOTICE 'Auto-acknowledged % old info insights', v_count; END IF;
  RETURN QUERY SELECT v_count, COALESCE(v_ids, ARRAY[]::UUID[]);
END;
$$;


--
-- Name: auto_activate_emergency_mode(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_activate_emergency_mode() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.alert_type IN ('rls_violation', 'rls_disabled') 
     AND NEW.severity = 'critical' THEN
    
    IF NOT EXISTS (
      SELECT 1 FROM system_global_state 
      WHERE mode = 'emergency_stop' 
      AND triggered_at > now() - interval '1 hour'
    ) THEN
      INSERT INTO system_global_state (mode, reason, triggered_by)
      VALUES (
        'emergency_stop',
        format('Auto-triggered: %s', NEW.message),
        '00000000-0000-0000-0000-000000000000'::uuid
      );
      
      -- V-14001 FIX: Use NEW.tenant_id instead of random (SELECT id FROM tenants LIMIT 1)
      INSERT INTO audit_logs (event_type, details, user_id, tenant_id)
      VALUES (
        'emergency_mode_auto_activated',
        jsonb_build_object(
          'alert_id', NEW.id,
          'alert_type', NEW.alert_type,
          'reason', NEW.message,
          'triggered_at', now()
        ),
        '00000000-0000-0000-0000-000000000000'::uuid,
        NEW.tenant_id
      );
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION auto_activate_emergency_mode(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auto_activate_emergency_mode() IS 'ADR-026: Security Operations Framework - Automatically activates emergency mode on critical security alerts';


--
-- Name: auto_approve_safe_actions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_approve_safe_actions(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_approved_count int := 0;
  v_categories text[];
  v_result jsonb;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  -- Only allow service_role or super_admin
  IF NOT (
    current_setting('request.jwt.claims', true)::jsonb->>'role' = 'service_role'
    OR EXISTS (SELECT 1 FROM user_roles WHERE user_id = auth.uid() AND role = 'super_admin')
    OR EXISTS (SELECT 1 FROM user_roles WHERE user_id = auth.uid() AND role = 'admin' AND tenant_id = p_tenant_id)
  ) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  -- Get safe categories (requires_approval = false AND is_enabled = true)
  SELECT array_agg(action_type) INTO v_categories
  FROM ai_action_configs
  WHERE requires_approval = false AND is_enabled = true;

  IF v_categories IS NULL OR array_length(v_categories, 1) = 0 THEN
    RETURN jsonb_build_object('approved_count', 0, 'categories', '[]'::jsonb, 'message', 'No auto-approvable categories found');
  END IF;

  -- Bulk approve pending actions in safe categories
  WITH approved AS (
    UPDATE ai_actions
    SET status = 'approved',
        approved_at = now(),
        approved_by = COALESCE(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid)
    WHERE status = 'pending'
      AND action_type = ANY(v_categories)
      AND (p_tenant_id IS NULL OR tenant_id = p_tenant_id)
    RETURNING id
  )
  SELECT count(*) INTO v_approved_count FROM approved;

  RETURN jsonb_build_object(
    'approved_count', v_approved_count,
    'categories', to_jsonb(v_categories),
    'message', format('%s actions auto-approved across %s categories', v_approved_count, array_length(v_categories, 1))
  );
END;
$$;


--
-- Name: auto_cancel_archived_agent_jobs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_cancel_archived_agent_jobs() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cancelled_count integer := 0;
BEGIN
  -- V-14006 FIX: Require service_role or super_admin
  PERFORM _assert_service_role_or_super_admin();

  WITH cancelled AS (
    UPDATE jobs j
    SET 
      status = 'cancelled',
      finished_at = now(),
      error_message = 'Auto-cancelled: agent archived'
    FROM agents a
    WHERE j.agent_id = a.id
      AND a.archived_at IS NOT NULL
      AND j.status IN ('pending', 'queued', 'delivered')
    RETURNING j.id, j.tenant_id, j.agent_id, j.agent_name, j.type, j.payload
  )
  SELECT count(*) INTO v_cancelled_count FROM cancelled;

  INSERT INTO failed_jobs_dlq (original_job_id, tenant_id, agent_id, agent_name, job_type, payload, error_message, status, first_failure_at, last_failure_at, failure_class, created_at)
  SELECT j.id, j.tenant_id, j.agent_id, j.agent_name, j.type, j.payload, 
    'Auto-cancelled: agent archived', 'ignored', now(), now(), 'agent_archived', now()
  FROM jobs j
  JOIN agents a ON j.agent_id = a.id
  WHERE a.archived_at IS NOT NULL
    AND j.status = 'cancelled'
    AND j.error_message = 'Auto-cancelled: agent archived'
    AND NOT EXISTS (SELECT 1 FROM failed_jobs_dlq dlq WHERE dlq.original_job_id = j.id)
  ON CONFLICT DO NOTHING;

  RETURN v_cancelled_count;
END;
$$;


--
-- Name: auto_cancel_jobs_on_agent_offline(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_cancel_jobs_on_agent_offline() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  cancelled_count INTEGER;
BEGIN
  -- Only trigger when agent transitions TO offline/inactive
  IF (NEW.agent_state = 'offline' AND OLD.agent_state IS DISTINCT FROM 'offline')
     OR (NEW.status = 'inactive' AND OLD.status != 'inactive') THEN
    
    UPDATE jobs
    SET status = 'cancelled',
        error_message = '[AUTO-CANCEL] Agent went offline/inactive at ' || now()::text
    WHERE agent_id = NEW.id
      AND status IN ('pending', 'queued');
    
    GET DIAGNOSTICS cancelled_count = ROW_COUNT;
    
    IF cancelled_count > 0 THEN
      RAISE LOG 'auto_cancel_jobs: Cancelled % jobs for agent % (%)',
        cancelled_count, NEW.agent_name, NEW.id;
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION auto_cancel_jobs_on_agent_offline(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auto_cancel_jobs_on_agent_offline() IS 'Cancela automaticamente jobs pendentes quando um agente fica offline (sem heartbeat há mais de 30 minutos)';


--
-- Name: auto_cancel_zombie_jobs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_cancel_zombie_jobs() RETURNS TABLE(cancelled_count integer, job_ids uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cancelled_count INTEGER;
  v_job_ids UUID[];
BEGIN
  PERFORM _assert_service_role_or_super_admin(); -- SSA-SEC-008

  WITH cancelled_jobs AS (
    UPDATE jobs
    SET status = 'failed',
        error_message = 'Auto-cancelled: Job stuck in delivered state for >2 hours (Zombie TTL)',
        completed_at = NOW()
    WHERE status = 'delivered'
      AND delivered_at < NOW() - INTERVAL '2 hours'
    RETURNING id, agent_name, tenant_id
  ),
  logged AS (
    INSERT INTO security_logs (tenant_id, ip_address, endpoint, attack_type, severity, blocked, details)
    SELECT tenant_id, 'system', 'zombie_job_cleanup', 'zombie_job_ttl', 'medium', false,
      jsonb_build_object('job_id', id, 'agent_name', agent_name, 'action', 'auto_cancelled', 'ttl_hours', 2)
    FROM cancelled_jobs
    RETURNING 1
  )
  SELECT COUNT(*)::INTEGER, ARRAY_AGG(id)
  INTO v_cancelled_count, v_job_ids FROM cancelled_jobs;
  
  IF v_cancelled_count > 0 THEN
    RAISE NOTICE '[SSA-003] Zombie Job TTL: % jobs cancelled', v_cancelled_count;
  END IF;
  
  RETURN QUERY SELECT COALESCE(v_cancelled_count, 0), COALESCE(v_job_ids, ARRAY[]::UUID[]);
END;
$$;


--
-- Name: FUNCTION auto_cancel_zombie_jobs(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auto_cancel_zombie_jobs() IS 'SSA-003: Auto-cancela jobs em estado "delivered" há mais de 2 horas. 
Previne zombie jobs que bloqueiam o sistema.';


--
-- Name: auto_classify_job_failure(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_classify_job_failure() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'failed' AND NEW.failure_class IS NULL THEN
    NEW.failure_class := classify_job_failure(NEW.error_message);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: auto_cleanup_stale_operations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_cleanup_stale_operations() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  dlq_cleaned int := 0;
  jobs_cancelled int := 0;
BEGIN
  -- V-14005 FIX: Require service_role or super_admin
  PERFORM _assert_service_role_or_super_admin();

  WITH resolved AS (
    UPDATE failed_jobs_dlq 
    SET status = 'resolved',
        resolved_at = now(),
        resolution_notes = 'Auto-cleanup: item pendente por mais de 6h',
        resolution_source = 'auto_cleanup'
    WHERE status = 'pending' 
      AND created_at < now() - interval '6 hours'
    RETURNING id
  )
  SELECT count(*) INTO dlq_cleaned FROM resolved;

  WITH cancelled AS (
    UPDATE jobs 
    SET status = 'cancelled', completed_at = now()
    WHERE status = 'delivered' 
      AND completed_at IS NULL
      AND created_at < now() - interval '1 hour'
      AND agent_id IN (
        SELECT id FROM agents WHERE status IN ('offline', 'inactive')
      )
    RETURNING id
  )
  SELECT count(*) INTO jobs_cancelled FROM cancelled;

  RETURN jsonb_build_object(
    'dlq_cleaned', dlq_cleaned,
    'jobs_cancelled', jobs_cancelled,
    'executed_at', now()
  );
END;
$$;


--
-- Name: auto_clear_force_update_on_match(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_clear_force_update_on_match() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Only clear force_update flags when:
  -- 1. There IS a pending force_update (force_update_at is set)
  -- 2. The agent_version ACTUALLY CHANGED in this update
  -- 3. The new version matches the target force_update_version
  IF NEW.force_update_at IS NOT NULL
     AND NEW.force_update_version IS NOT NULL
     AND NEW.agent_version IS DISTINCT FROM OLD.agent_version
     AND NEW.agent_version = NEW.force_update_version
  THEN
    NEW.force_update_version := NULL;
    NEW.force_update_reason := 'auto_cleared_version_matched';
    NEW.force_update_at := NULL;
    NEW.force_update_delivered_count := 0;
    NEW.force_update_first_delivered_at := NULL;
    NEW.force_update_override_safe_mode := false;
    NEW.force_update_override_safe_mode_expires_at := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: auto_close_stale_orphan_tasks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_close_stale_orphan_tasks() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  closed_count integer;
BEGIN
  -- V-14009 FIX: Require service_role or super_admin
  PERFORM _assert_service_role_or_super_admin();

  UPDATE tasks 
  SET status = 'resolved', updated_at = now()
  WHERE assigned_to IS NULL 
    AND status NOT IN ('completed', 'cancelled', 'resolved')
    AND created_at < now() - interval '24 hours';
  
  GET DIAGNOSTICS closed_count = ROW_COUNT;
  
  IF closed_count > 0 THEN
    RAISE NOTICE 'Auto-resolved % orphan tasks older than 24h', closed_count;
  END IF;
END;
$$;


--
-- Name: FUNCTION auto_close_stale_orphan_tasks(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auto_close_stale_orphan_tasks() IS 'Zero-Gap: Auto-resolve orphan tasks (no owner) older than 24h to prevent cycle accumulation.';


--
-- Name: auto_collect_task_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_collect_task_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'in_progress' AND OLD.status = 'open' THEN
    INSERT INTO audit_logs (
      tenant_id,
      action,
      actor_id,
      resource_type,
      resource_id,
      details,
      success
    ) VALUES (
      NEW.tenant_id,
      'evidence_collection_triggered',
      NULL,
      'task',
      NEW.id::text,
      jsonb_build_object(
        'task_id', NEW.id,
        'task_title', NEW.title,
        'source_type', NEW.source_type,
        'fingerprint_id', NEW.fingerprint_id,
        'actor_type', 'system'
      ),
      true
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: auto_create_evidence_from_execution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_create_evidence_from_execution() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agent_name text;
  v_tenant_id uuid;
  v_event_type text;
BEGIN
  -- Determine event type
  IF NEW.status = 'completed' THEN
    v_event_type := 'job_execution';
  ELSIF NEW.status = 'failed' THEN
    v_event_type := 'error';
  ELSE
    RETURN NEW;
  END IF;

  -- Get agent info
  SELECT a.hostname, a.tenant_id INTO v_agent_name, v_tenant_id
  FROM agents a WHERE a.id = NEW.agent_id;

  IF v_tenant_id IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO agent_evidence_logs (
    agent_id, agent_name, tenant_id, event_type, event_data, evidence_hash, severity
  ) VALUES (
    NEW.agent_id,
    COALESCE(v_agent_name, 'unknown'),
    v_tenant_id,
    v_event_type,
    jsonb_build_object(
      'execution_id', NEW.id,
      'job_id', NEW.job_id,
      'status', NEW.status,
      'exit_code', NEW.exit_code,
      'started_at', NEW.started_at,
      'finished_at', NEW.finished_at
    ),
    encode(digest(NEW.id::text || NEW.status || COALESCE(NEW.started_at::text, ''), 'sha256'), 'hex'),
    CASE WHEN NEW.status = 'failed' THEN 'high' ELSE 'low' END
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Evidence creation failed: %', SQLERRM;
  RETURN NEW;
END;
$$;


--
-- Name: auto_create_task_for_critical_alert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_create_task_for_critical_alert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.severity IN ('critical', 'high') THEN
    INSERT INTO public.tasks (
      tenant_id, source_type, source_id, title, description, 
      severity, status, requires_human_review, auto_generated
    )
    SELECT 
      NEW.tenant_id,
      'system_alert',
      NEW.id,  -- UUID direto, sem ::text
      'Alerta: ' || COALESCE(NEW.alert_type, 'Sistema'),
      COALESCE(NEW.message, 'Alerta de sistema requer atenção'),
      NEW.severity,
      'open',
      NEW.severity = 'critical',
      true
    WHERE NOT EXISTS (
      SELECT 1 FROM public.tasks t 
      WHERE t.source_type = 'system_alert' 
        AND t.source_id = NEW.id  -- UUID = UUID
    );
  END IF;
  RETURN NEW;
END;
$$;


