--
-- Name: auto_insert_failed_job_to_dlq(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_insert_failed_job_to_dlq() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Só atuar quando job transita PARA failed
  IF OLD.status IS DISTINCT FROM 'failed' AND NEW.status = 'failed' THEN
    -- Inserir na DLQ se não existir
    INSERT INTO public.failed_jobs_dlq (
      original_job_id, 
      tenant_id, 
      agent_id, 
      agent_name, 
      job_type,
      payload, 
      error_message, 
      failure_class, 
      status,
      created_at,
      last_failure_at
    )
    VALUES (
      NEW.id,
      NEW.tenant_id,
      NEW.agent_id,
      NEW.agent_name,
      NEW.type,
      NEW.payload,
      NEW.error_message,
      NEW.failure_class,
      'pending',
      NOW(),
      NOW()
    )
    ON CONFLICT (original_job_id) DO UPDATE SET
      error_count = public.failed_jobs_dlq.error_count + 1,
      last_failure_at = NOW(),
      error_message = EXCLUDED.error_message,
      failure_class = EXCLUDED.failure_class;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION auto_insert_failed_job_to_dlq(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auto_insert_failed_job_to_dlq() IS 'ADR-031: Insere job falho na DLQ automaticamente';


--
-- Name: auto_mark_agents_inactive(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_mark_agents_inactive() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count integer := 0;
  v_threshold interval := '10 minutes';
  v_cutoff timestamptz := now() - v_threshold;
  v_result jsonb;
BEGIN
  -- Mark agents as offline if no heartbeat for > 10 minutes
  UPDATE agents
  SET 
    status = 'offline',
    agent_state = 'offline',
    agent_state_changed_at = now(),
    agent_state_reason = format('Auto-marked offline: no heartbeat for >%s', v_threshold)
  WHERE status = 'active'
    AND last_heartbeat IS NOT NULL
    AND last_heartbeat < v_cutoff;
  
  GET DIAGNOSTICS v_count = ROW_COUNT;
  
  v_result := jsonb_build_object(
    'success', true,
    'agents_marked_offline', v_count,
    'threshold', v_threshold::text,
    'cutoff_time', v_cutoff,
    'executed_at', now()
  );
  
  -- Log to cron health
  INSERT INTO cron_health_checks (cron_name, last_success_at, consecutive_failures, updated_at, last_result)
  VALUES ('auto-mark-inactive', now(), 0, now(), v_result)
  ON CONFLICT (cron_name) DO UPDATE SET
    last_success_at = now(),
    consecutive_failures = 0,
    last_error = NULL,
    updated_at = now(),
    last_result = EXCLUDED.last_result;
  
  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION auto_mark_agents_inactive(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auto_mark_agents_inactive() IS 'Automatically marks agents as inactive when no heartbeat received for >2 hours. Should be called by cron every 15 minutes.';


--
-- Name: auto_pause_scheduling(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_pause_scheduling() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Agent transitioning TO inactive status
  IF NEW.status = 'inactive' AND OLD.status != 'inactive' THEN
    NEW.scheduling_paused := true;
    NEW.scheduling_paused_reason := 'auto: agent went inactive at ' || now()::text;
  END IF;

  -- Agent transitioning FROM inactive to active (resume)
  IF NEW.status = 'active' AND OLD.status = 'inactive' THEN
    NEW.scheduling_paused := false;
    NEW.scheduling_paused_reason := null;
  END IF;

  -- Agent_state going offline while status is still active → pause scheduling
  IF NEW.agent_state = 'offline' AND (OLD.agent_state IS DISTINCT FROM 'offline') THEN
    NEW.scheduling_paused := true;
    NEW.scheduling_paused_reason := 'auto: agent_state went offline at ' || now()::text;
  END IF;

  -- Agent_state recovering from offline → resume scheduling
  IF OLD.agent_state = 'offline' AND NEW.agent_state != 'offline' THEN
    NEW.scheduling_paused := false;
    NEW.scheduling_paused_reason := null;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: auto_pause_scheduling_on_inactive(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_pause_scheduling_on_inactive() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Agent transitioning TO inactive
  IF NEW.status = 'inactive' AND OLD.status != 'inactive' THEN
    NEW.scheduling_paused := true;
    NEW.scheduling_paused_reason := 'auto: agent went inactive at ' || now()::text;
  END IF;

  -- Agent transitioning FROM inactive to active (resume)
  IF NEW.status = 'active' AND OLD.status = 'inactive' THEN
    NEW.scheduling_paused := false;
    NEW.scheduling_paused_reason := null;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: auto_populate_agent_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_populate_agent_id() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Se agent_id é NULL mas agent_name está presente, buscar o agent_id
  IF NEW.agent_id IS NULL AND NEW.agent_name IS NOT NULL THEN
    SELECT id INTO NEW.agent_id
    FROM public.agents
    WHERE agent_name = NEW.agent_name
      AND tenant_id = NEW.tenant_id
    LIMIT 1;
    
    -- Log se não encontrou agente (debug)
    IF NEW.agent_id IS NULL THEN
      RAISE NOTICE 'auto_populate_agent_id: Agent not found for name=%, tenant=%', NEW.agent_name, NEW.tenant_id;
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


