-- Name: FUNCTION auto_populate_agent_id(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auto_populate_agent_id() IS 'Auto-popula agent_id baseado em agent_name quando NULL durante INSERT em jobs';


--
-- Name: auto_provision_signing_key(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_provision_signing_key() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'active' THEN
    INSERT INTO agent_signing_keys (agent_id, public_key, key_fingerprint, algorithm, version)
    SELECT NEW.id, 'pending-agent-upload', 
           encode(sha256(convert_to(NEW.id::text || ':pending', 'UTF8')), 'hex'),
           'ECDSA-P256', 1
    WHERE NOT EXISTS (
      SELECT 1 FROM agent_signing_keys WHERE agent_id = NEW.id AND revoked_at IS NULL
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: auto_resolve_resource_alerts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_resolve_resource_alerts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Auto-resolve high_cpu alerts when CPU < 80%
  IF NEW.cpu_usage_percent IS NOT NULL AND NEW.cpu_usage_percent < 80 THEN
    UPDATE system_alerts 
    SET resolved = true, resolved_at = NOW()
    WHERE tenant_id = NEW.tenant_id 
      AND alert_type IN ('high_cpu', 'cpu_warning')
      AND resolved = false
      AND agent_id = NEW.agent_id;
  END IF;
  
  -- Auto-resolve memory alerts when < 85%
  IF NEW.memory_usage_percent IS NOT NULL AND NEW.memory_usage_percent < 85 THEN
    UPDATE system_alerts 
    SET resolved = true, resolved_at = NOW()
    WHERE tenant_id = NEW.tenant_id 
      AND alert_type IN ('high_memory', 'memory_warning')
      AND resolved = false
      AND agent_id = NEW.agent_id;
  END IF;
  
  -- Auto-resolve disk alerts when < 85%
  IF NEW.disk_usage_percent IS NOT NULL AND NEW.disk_usage_percent < 85 THEN
    UPDATE system_alerts 
    SET resolved = true, resolved_at = NOW()
    WHERE tenant_id = NEW.tenant_id 
      AND alert_type IN ('high_disk', 'disk_warning')
      AND resolved = false
      AND agent_id = NEW.agent_id;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: auto_resolve_stale_tasks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_resolve_stale_tasks() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_in_progress_closed integer := 0;
  v_critical_closed integer := 0;
  v_medium_low_closed integer := 0;
  v_archived_agent_closed integer := 0;
  v_high_closed integer := 0;
BEGIN
  -- Rule 1: Tasks stuck in_progress > 14 days → auto-resolved
  WITH updated AS (
    UPDATE tasks
    SET status = 'resolved',
        closed_at = now(),
        closure_reason = 'auto_resolved_stale_in_progress_14d',
        updated_at = now()
    WHERE status = 'in_progress'
      AND updated_at < now() - interval '14 days'
    RETURNING id
  )
  SELECT count(*) INTO v_in_progress_closed FROM updated;

  -- Rule 2: Critical tasks open > 30 days → auto-resolved with evidence
  WITH updated AS (
    UPDATE tasks
    SET status = 'resolved',
        closed_at = now(),
        closure_reason = 'auto_resolved_critical_sla_30d',
        closure_evidence = jsonb_build_object(
          'auto_resolved', true,
          'reason', 'Critical task exceeded 30-day maximum open window',
          'resolved_at', now()::text
        ),
        updated_at = now()
    WHERE status = 'open'
      AND severity = 'critical'
      AND created_at < now() - interval '30 days'
    RETURNING id
  )
  SELECT count(*) INTO v_critical_closed FROM updated;

  -- Rule 3: High severity open > 21 days → auto-resolved
  WITH updated AS (
    UPDATE tasks
    SET status = 'resolved',
        closed_at = now(),
        closure_reason = 'auto_resolved_high_sla_21d',
        updated_at = now()
    WHERE status = 'open'
      AND severity = 'high'
      AND created_at < now() - interval '21 days'
    RETURNING id
  )
  SELECT count(*) INTO v_high_closed FROM updated;

  -- Rule 4: Medium/Low severity open > 14 days → auto-resolved
  WITH updated AS (
    UPDATE tasks
    SET status = 'resolved',
        closed_at = now(),
        closure_reason = 'auto_resolved_medium_low_sla_14d',
        updated_at = now()
    WHERE status = 'open'
      AND severity IN ('medium', 'low', 'info')
      AND created_at < now() - interval '14 days'
    RETURNING id
  )
  SELECT count(*) INTO v_medium_low_closed FROM updated;

  -- Rule 5: Tasks linked to archived agents → auto-resolved immediately
  WITH updated AS (
    UPDATE tasks t
    SET status = 'resolved',
        closed_at = now(),
        closure_reason = 'auto_resolved_agent_archived',
        updated_at = now()
    FROM agents a
    WHERE t.status IN ('open', 'in_progress')
      AND t.source_id IS NOT NULL
      AND EXISTS (
        SELECT 1 FROM jobs j 
        WHERE j.id = t.source_id 
        AND j.agent_id = a.id 
        AND a.archived_at IS NOT NULL
      )
    RETURNING t.id
  )
  SELECT count(*) INTO v_archived_agent_closed FROM updated;

  RETURN jsonb_build_object(
    'in_progress_closed', v_in_progress_closed,
    'critical_closed', v_critical_closed,
    'high_closed', v_high_closed,
    'medium_low_closed', v_medium_low_closed,
    'archived_agent_closed', v_archived_agent_closed,
    'total_closed', v_in_progress_closed + v_critical_closed + v_high_closed + v_medium_low_closed + v_archived_agent_closed
  );
END;
$$;


--
-- Name: FUNCTION auto_resolve_stale_tasks(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auto_resolve_stale_tasks() IS 'Zero-Gap Phase 1: Expanded auto-closure rules for critical/high tasks >30d, in_progress >14d, critical alerts >14d';


