--
-- Name: auto_set_tenant_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_set_tenant_id() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Se tenant_id já foi fornecido explicitamente, usar sem modificação
  IF NEW.tenant_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  
  -- Tentar buscar do JWT
  NEW.tenant_id := public.get_active_tenant_id();
  
  -- Se obteve do JWT, retornar
  IF NEW.tenant_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  
  -- Se ainda NULL, verificar contexto
  -- Para operações de sistema (triggers cascateados, service_role), 
  -- permitir NULL apenas para tabelas não-críticas
  IF current_setting('role', true) IN ('service_role', 'postgres', 'supabase_admin') 
     OR current_user IN ('postgres', 'supabase_admin') THEN
    -- Logar com sampling para evitar flood (1% das vezes)
    IF random() < 0.01 THEN
      RAISE LOG '[auto_set_tenant_id] No tenant_id for system operation on % by %', 
        TG_TABLE_NAME, current_user;
    END IF;
    
    -- Tabelas críticas DEVEM ter tenant_id explícito
    IF TG_TABLE_NAME IN ('security_logs', 'audit_logs') THEN
      RAISE EXCEPTION 'tenant_id must be provided explicitly for % (system operation)', TG_TABLE_NAME
        USING ERRCODE = '23502';
    END IF;
    
    -- Para outras tabelas, permitir NULL em operações de sistema
    -- (a aplicação deve garantir que tenant_id é passado quando necessário)
    RETURN NEW;
  END IF;
  
  -- Para usuários normais, tenant_id é obrigatório
  RAISE EXCEPTION 'tenant_id cannot be NULL and no active tenant found in JWT for table %', TG_TABLE_NAME
    USING ERRCODE = '23502';
END;
$$;


--
-- Name: FUNCTION auto_set_tenant_id(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auto_set_tenant_id() IS 'ADR-028 P0-03: Auto-populates tenant_id from JWT claim if not provided';


--
-- Name: backfill_audit_log_hashes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.backfill_audit_log_hashes(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS TABLE(updated_count integer, tenant_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_log RECORD;
  v_previous_hash TEXT := 'GENESIS';
  v_count INTEGER := 0;
  v_current_tenant UUID;
  v_new_integrity TEXT;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  IF NOT is_current_super_admin() THEN
    RAISE EXCEPTION 'Only super_admin can backfill audit log hashes (SSA-SEC-008)';
  END IF;

  ALTER TABLE audit_logs DISABLE TRIGGER tr_prevent_audit_modification;
  ALTER TABLE audit_logs DISABLE TRIGGER trg_immutable_audit_logs;

  BEGIN
    FOR v_current_tenant IN 
      SELECT DISTINCT al.tenant_id 
      FROM audit_logs al 
      WHERE (p_tenant_id IS NULL OR al.tenant_id = p_tenant_id)
      ORDER BY al.tenant_id
    LOOP
      v_previous_hash := 'GENESIS';
      v_count := 0;
      
      FOR v_log IN 
        SELECT al.id, al.created_at, al.action, al.resource_type, al.resource_id, al.state_before, al.state_after
        FROM audit_logs al
        WHERE al.tenant_id = v_current_tenant
        ORDER BY al.created_at ASC, al.id ASC
      LOOP
        v_new_integrity := encode(sha256(convert_to(
          v_previous_hash || 
          v_log.id::text || 
          COALESCE(v_log.action, '') || 
          COALESCE(v_log.resource_type, '') ||
          COALESCE(v_log.resource_id, '') ||
          COALESCE(v_log.state_before::text, '{}') ||
          COALESCE(v_log.state_after::text, '{}') ||
          COALESCE(v_log.created_at::text, ''),
          'UTF8'
        )), 'hex');

        UPDATE audit_logs
        SET integrity_hash = v_new_integrity, previous_log_hash = v_previous_hash
        WHERE id = v_log.id;
        
        v_previous_hash := v_new_integrity;
        v_count := v_count + 1;
      END LOOP;
      
      updated_count := v_count;
      tenant_id := v_current_tenant;
      RETURN NEXT;
    END LOOP;

    ALTER TABLE audit_logs ENABLE TRIGGER tr_prevent_audit_modification;
    ALTER TABLE audit_logs ENABLE TRIGGER trg_immutable_audit_logs;
  EXCEPTION WHEN OTHERS THEN
    ALTER TABLE audit_logs ENABLE TRIGGER tr_prevent_audit_modification;
    ALTER TABLE audit_logs ENABLE TRIGGER trg_immutable_audit_logs;
    RAISE;
  END;
  
  RETURN;
END;
$$;


--
-- Name: calculate_audit_log_hash(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_audit_log_hash() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_previous_hash TEXT;
BEGIN
  SELECT integrity_hash INTO v_previous_hash
  FROM audit_logs
  WHERE tenant_id = NEW.tenant_id
    AND id != NEW.id
  ORDER BY created_at DESC, id DESC
  LIMIT 1;
  
  NEW.previous_log_hash := COALESCE(v_previous_hash, 'GENESIS');
  
  NEW.integrity_hash := encode(sha256(
    convert_to(
      COALESCE(NEW.previous_log_hash, 'GENESIS') || 
      NEW.id::text || 
      COALESCE(NEW.action, '') || 
      COALESCE(NEW.resource_type, '') ||
      COALESCE(NEW.resource_id, '') ||
      COALESCE(NEW.state_before::text, '{}') ||
      COALESCE(NEW.state_after::text, '{}') ||
      COALESCE(NEW.created_at::text, ''),
      'UTF8'
    )
  ), 'hex');
  
  RETURN NEW;
END;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: audit_confidence_gaps; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.audit_confidence_gaps (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    audit_id uuid,
    red_team_id uuid,
    ana_score integer NOT NULL,
    red_score integer NOT NULL,
    confidence_gap integer NOT NULL,
    health_status text NOT NULL,
    previous_gap integer,
    gap_delta integer,
    alert_triggered boolean DEFAULT false,
    alert_reason text,
    dimension_gaps jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT audit_confidence_gaps_ana_score_check CHECK (((ana_score >= 0) AND (ana_score <= 100))),
    CONSTRAINT audit_confidence_gaps_health_status_check CHECK ((health_status = ANY (ARRAY['healthy'::text, 'attention'::text, 'critical'::text]))),
    CONSTRAINT audit_confidence_gaps_red_score_check CHECK (((red_score >= 0) AND (red_score <= 100)))
);


--
-- Name: TABLE audit_confidence_gaps; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.audit_confidence_gaps IS 'Lacunas de confiança identificadas em auditorias. Relacionada com tenants.';


--
-- Name: calculate_confidence_gap(uuid, uuid, uuid, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_confidence_gap(p_tenant_id uuid, p_audit_id uuid, p_red_team_id uuid, p_ana_score integer, p_red_score integer, p_dimension_gaps jsonb DEFAULT '{}'::jsonb) RETURNS public.audit_confidence_gaps
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_gap INTEGER;
  v_health TEXT;
  v_previous_gap INTEGER;
  v_gap_delta INTEGER;
  v_alert_triggered BOOLEAN := false;
  v_alert_reason TEXT;
  v_result public.audit_confidence_gaps;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  -- Calculate gap
  v_gap := p_ana_score - p_red_score;
  
  -- Determine health status
  IF v_gap > 40 THEN
    v_health := 'healthy';
  ELSIF v_gap >= 20 THEN
    v_health := 'attention';
  ELSE
    v_health := 'critical';
  END IF;
  
  -- Get previous gap for this tenant
  SELECT confidence_gap INTO v_previous_gap
  FROM public.audit_confidence_gaps
  WHERE tenant_id = p_tenant_id
  ORDER BY created_at DESC
  LIMIT 1;
  
  -- Calculate delta if we have previous data
  IF v_previous_gap IS NOT NULL THEN
    v_gap_delta := v_gap - v_previous_gap;
    
    -- Trigger alert if gap dropped more than 15 points
    IF v_gap_delta < -15 THEN
      v_alert_triggered := true;
      v_alert_reason := format('Confidence gap dropped %s points (from %s to %s)', 
        ABS(v_gap_delta), v_previous_gap, v_gap);
    END IF;
  END IF;
  
  -- Also alert on critical status
  IF v_health = 'critical' AND NOT v_alert_triggered THEN
    v_alert_triggered := true;
    v_alert_reason := format('Confidence gap entered critical zone: %s', v_gap);
  END IF;
  
  -- Insert the record
  INSERT INTO public.audit_confidence_gaps (
    tenant_id, audit_id, red_team_id,
    ana_score, red_score, confidence_gap,
    health_status, previous_gap, gap_delta,
    alert_triggered, alert_reason, dimension_gaps
  ) VALUES (
    p_tenant_id, p_audit_id, p_red_team_id,
    p_ana_score, p_red_score, v_gap,
    v_health, v_previous_gap, v_gap_delta,
    v_alert_triggered, v_alert_reason, p_dimension_gaps
  )
  RETURNING * INTO v_result;
  
  RETURN v_result;
END;
$$;


--
-- Name: calculate_event_risk(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_event_risk(p_event_type text, p_context jsonb) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_base NUMERIC;
  v_score NUMERIC;
BEGIN
  -- Buscar configuração do evento
  SELECT severity_base INTO v_base
  FROM event_risk_scoring
  WHERE event_type = p_event_type AND is_active = true;

  IF v_base IS NULL THEN
    RETURN 0.5; -- Default médio para eventos desconhecidos
  END IF;

  v_score := v_base;

  -- Multiplicador: repetição
  IF (p_context->>'repeat_count') IS NOT NULL THEN
    v_score := v_score + LEAST((p_context->>'repeat_count')::NUMERIC * 0.03, 0.2);
  END IF;

  -- Multiplicador: criticidade do agente
  IF p_context->>'agent_criticality' = 'high' THEN
    v_score := v_score + 0.1;
  ELSIF p_context->>'agent_criticality' = 'critical' THEN
    v_score := v_score + 0.15;
  END IF;

  -- Multiplicador: horário fora do expediente
  IF p_context->>'outside_business_hours' = 'true' THEN
    v_score := v_score + 0.05;
  END IF;

  -- Multiplicador: histórico de incidentes
  IF (p_context->>'previous_incidents')::INT > 0 THEN
    v_score := v_score + LEAST((p_context->>'previous_incidents')::NUMERIC * 0.02, 0.1);
  END IF;

  RETURN LEAST(v_score, 1.0);
END;
$$;


--
-- Name: calculate_evidence_log_hash(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_evidence_log_hash() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
