--
-- Name: can_hard_delete_agent(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_hard_delete_agent(p_agent_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant_id uuid;
  v_caller_tenant uuid;
  v_latest_evidence timestamptz;
BEGIN
  SELECT tenant_id INTO v_tenant_id FROM public.agents WHERE id = p_agent_id;
  IF v_tenant_id IS NULL THEN
    RETURN jsonb_build_object('can_delete', false, 'blocked_until', null);
  END IF;

  v_caller_tenant := public.get_active_tenant_id();
  IF v_caller_tenant IS NULL OR v_caller_tenant <> v_tenant_id THEN
    RETURN jsonb_build_object('can_delete', false, 'blocked_until', null);
  END IF;

  SELECT max(created_at) INTO v_latest_evidence
  FROM public.agent_evidence_logs
  WHERE agent_id = p_agent_id AND tenant_id = v_tenant_id;

  IF v_latest_evidence IS NOT NULL AND v_latest_evidence > now() - interval '30 days' THEN
    RETURN jsonb_build_object('can_delete', false, 'blocked_until', v_latest_evidence + interval '30 days');
  END IF;

  RETURN jsonb_build_object('can_delete', true, 'blocked_until', null);
END;
$$;


--
-- Name: cancel_jobs_on_agent_offline(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_jobs_on_agent_offline() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Se heartbeat está NULL ou muito antigo, cancelar jobs pendentes
  IF NEW.last_heartbeat IS NULL OR NEW.last_heartbeat < NOW() - INTERVAL '24 hours' THEN
    UPDATE public.jobs
    SET 
      status = 'cancelled',
      error_message = 'Auto-cancelled: agent offline >24h',
      completed_at = NOW()
    WHERE agent_id = NEW.id
      AND status IN ('queued', 'delivered');
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: capture_forensic_snapshot_full(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_forensic_snapshot_full(p_agent_id uuid, p_trigger_reason text, p_trigger_event_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
  v_snapshot_id UUID;
  v_config JSONB;
  v_process JSONB;
  v_network JSONB;
  v_liveness JSONB;
  v_caller_tenant UUID;
BEGIN
  SELECT tenant_id INTO v_tenant_id FROM agents WHERE id = p_agent_id;
  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'Agent not found'; END IF;
  
  -- V-14007 FIX: Validate caller has access to agent's tenant
  v_caller_tenant := get_active_tenant_id();
  IF v_caller_tenant IS NOT NULL AND v_caller_tenant != v_tenant_id AND NOT is_current_super_admin() THEN
    INSERT INTO security_logs (tenant_id, event_type, severity, details)
    VALUES (v_caller_tenant, 'cross_tenant_blocked', 'critical',
      jsonb_build_object('function', 'capture_forensic_snapshot_full', 'target_agent', p_agent_id, 'agent_tenant', v_tenant_id));
    RAISE EXCEPTION 'TENANT_MISMATCH: Caller cannot access agent in another tenant';
  END IF;
  
  SELECT jsonb_build_object('agent', to_jsonb(a.*)) INTO v_config
  FROM agents a WHERE a.id = p_agent_id;
  
  SELECT jsonb_build_object(
    'recent_jobs', (SELECT jsonb_agg(j.*) FROM (
      SELECT * FROM jobs WHERE agent_id = p_agent_id ORDER BY created_at DESC LIMIT 20
    ) j)
  ) INTO v_process;
  
  -- V-14007 FIX: Add tenant filter to network info query
  SELECT jsonb_agg(n.*) INTO v_network
  FROM agent_network_info n WHERE n.agent_id = p_agent_id AND n.tenant_id = v_tenant_id LIMIT 5;
  
  SELECT jsonb_agg(l.*) INTO v_liveness FROM system_liveness l;
  
  INSERT INTO forensic_snapshots (
    agent_id, tenant_id, trigger_reason, trigger_event_id,
    config_snapshot, process_snapshot, network_snapshot,
    system_liveness_snapshot, metadata
  ) VALUES (
    p_agent_id, v_tenant_id, p_trigger_reason, 
    COALESCE(p_trigger_event_id, gen_random_uuid()),
    COALESCE(v_config, '{}'), COALESCE(v_process, '{}'),
    COALESCE(v_network, '[]'), COALESCE(v_liveness, '[]'), p_metadata
  )
  ON CONFLICT (trigger_event_id, trigger_reason) DO NOTHING
  RETURNING id INTO v_snapshot_id;
  
  RETURN v_snapshot_id;
END;
$$;


--
-- Name: check_action_rate_limit(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_action_rate_limit(p_action_type text, p_tenant_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_max_executions INTEGER;
  v_today_executions INTEGER;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  -- Buscar limite configurado
  SELECT max_executions_per_day INTO v_max_executions
  FROM public.ai_action_configs
  WHERE action_type = p_action_type AND is_enabled = true;
  
  IF v_max_executions IS NULL THEN
    RETURN false; -- Ação não existe ou está desabilitada
  END IF;
  
  -- Contar execuções hoje
  SELECT COUNT(*) INTO v_today_executions
  FROM public.ai_action_executions ae
  JOIN public.ai_actions a ON ae.action_id = a.id
  WHERE a.action_type = p_action_type
    AND ae.tenant_id = p_tenant_id
    AND ae.execution_status = 'executed'
    AND ae.executed_at >= CURRENT_DATE;
  
  RETURN v_today_executions < v_max_executions;
END;
$$;


--
-- Name: FUNCTION check_action_rate_limit(p_action_type text, p_tenant_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_action_rate_limit(p_action_type text, p_tenant_id uuid) IS '🔒 Essencial - Rate limit de AI actions';


--
-- Name: check_agent_job_failure_rate(uuid, text, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_agent_job_failure_rate(p_agent_id uuid, p_job_type text, p_days_back integer DEFAULT 7, p_threshold numeric DEFAULT 50.0) RETURNS TABLE(total_jobs integer, failed_jobs integer, failure_rate numeric, should_skip boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH stats AS (
    SELECT
      COUNT(*) FILTER (WHERE status IN ('completed', 'failed')) AS total,
      COUNT(*) FILTER (WHERE status = 'failed') AS failed
    FROM jobs
    WHERE agent_id = p_agent_id
      AND type = p_job_type
      AND created_at > now() - make_interval(days => p_days_back)
  )
  SELECT
    s.total::INT AS total_jobs,
    s.failed::INT AS failed_jobs,
    CASE WHEN s.total > 0 THEN ROUND((s.failed::NUMERIC / s.total) * 100, 1) ELSE 0 END AS failure_rate,
    CASE WHEN s.total >= 3 AND (s.failed::NUMERIC / NULLIF(s.total, 0)) * 100 > p_threshold THEN TRUE ELSE FALSE END AS should_skip
  FROM stats s;
$$;


--
-- Name: check_ai_circuit_breaker(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_ai_circuit_breaker(p_action_type text, p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_config record;
  v_recent_failures integer;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  SELECT * INTO v_config FROM ai_action_configs WHERE action_type = p_action_type AND is_enabled = true;
  
  IF v_config IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'Action not configured');
  END IF;
  
  IF v_config.circuit_open_until IS NOT NULL AND v_config.circuit_open_until > NOW() THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'Circuit open', 'retry_after', v_config.circuit_open_until);
  END IF;
  
  SELECT COUNT(*) INTO v_recent_failures
  FROM ai_action_executions ae
  JOIN ai_actions a ON ae.action_id = a.id
  WHERE a.action_type = p_action_type AND ae.tenant_id = p_tenant_id
    AND ae.execution_status = 'failed'
    AND ae.executed_at > NOW() - (v_config.failure_window_minutes || ' minutes')::interval;
  
  IF v_recent_failures >= v_config.failure_threshold THEN
    UPDATE ai_action_configs SET circuit_open_until = NOW() + interval '15 minutes', current_failures = v_recent_failures
    WHERE action_type = p_action_type;
    RETURN jsonb_build_object('allowed', false, 'reason', 'Threshold exceeded', 'failures', v_recent_failures);
  END IF;
  
  RETURN jsonb_build_object('allowed', true, 'failures', v_recent_failures);
END;
$$;


--
-- Name: check_and_block_ip(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_and_block_ip(p_ip_address text, p_email text DEFAULT NULL::text) RETURNS TABLE(is_blocked boolean, blocked_until timestamp with time zone, attempt_count integer, block_level integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_attempt_count INTEGER;
  v_block_count INTEGER;
  v_blocked_until TIMESTAMP WITH TIME ZONE;
  v_new_block_duration INTERVAL;
BEGIN
  -- Verificar se IP está na blocklist
  SELECT ip.blocked_until INTO v_blocked_until
  FROM public.ip_blocklist ip
  WHERE ip.ip_address = p_ip_address
    AND ip.blocked_until > NOW();
  
  IF v_blocked_until IS NOT NULL THEN
    RETURN QUERY SELECT true, v_blocked_until, 0, 99;
    RETURN;
  END IF;
  
  -- Contar tentativas nos últimos 15 minutos
  SELECT COUNT(*), COALESCE(MAX(block_count), 0)
  INTO v_attempt_count, v_block_count
  FROM public.failed_login_attempts
  WHERE ip_address = p_ip_address
    AND created_at > NOW() - INTERVAL '15 minutes';
  
  -- Bloqueio progressivo: 5 tentativas = 5min, 10 = 15min, 15+ = 60min
  IF v_attempt_count >= 15 THEN
    v_new_block_duration := INTERVAL '60 minutes';
  ELSIF v_attempt_count >= 10 THEN
    v_new_block_duration := INTERVAL '15 minutes';
  ELSIF v_attempt_count >= 5 THEN
    v_new_block_duration := INTERVAL '5 minutes';
  ELSE
    -- Não bloquear ainda
    RETURN QUERY SELECT false, NULL::TIMESTAMP WITH TIME ZONE, v_attempt_count, 0;
    RETURN;
  END IF;
  
  -- Aplicar bloqueio
  v_blocked_until := NOW() + v_new_block_duration;
  
  INSERT INTO public.ip_blocklist (ip_address, blocked_until, reason)
  VALUES (p_ip_address, v_blocked_until, 'Bloqueio progressivo por tentativas de login')
  ON CONFLICT (ip_address) DO UPDATE SET 
    blocked_until = v_blocked_until,
    reason = 'Bloqueio progressivo por tentativas de login';
  
  -- Atualizar contador de bloqueios nas tentativas
  UPDATE public.failed_login_attempts
  SET block_count = v_block_count + 1,
      blocked_until = v_blocked_until
  WHERE ip_address = p_ip_address
    AND created_at > NOW() - INTERVAL '15 minutes';
  
  -- Log de segurança
  INSERT INTO public.security_logs (
    ip_address,
    endpoint,
    attack_type,
    severity,
    blocked,
    details,
    user_agent
  ) VALUES (
    p_ip_address,
    '/auth/login',
    'brute_force',
    CASE 
      WHEN v_attempt_count >= 15 THEN 'critical'
      WHEN v_attempt_count >= 10 THEN 'high'
      ELSE 'medium'
    END,
    true,
    jsonb_build_object(
      'email', p_email,
      'attempt_count', v_attempt_count,
      'block_duration_minutes', EXTRACT(EPOCH FROM v_new_block_duration) / 60,
      'blocked_until', v_blocked_until
    ),
    NULL
  );
  
  RETURN QUERY SELECT true, v_blocked_until, v_attempt_count, 
    CASE 
      WHEN v_attempt_count >= 15 THEN 3
      WHEN v_attempt_count >= 10 THEN 2
      ELSE 1
    END;
END;
$$;


--
-- Name: FUNCTION check_and_block_ip(p_ip_address text, p_email text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_and_block_ip(p_ip_address text, p_email text) IS '🔒 Essencial - Proteção contra brute force';


--
-- Name: check_and_update_circuit_breaker(uuid, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_and_update_circuit_breaker(p_rule_id uuid, p_threshold integer DEFAULT 10, p_window_minutes integer DEFAULT 5, p_recovery_minutes integer DEFAULT 15) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rule record;
  v_failure_count integer;
BEGIN
  SELECT circuit_state, circuit_opened_at, circuit_recovery_minutes INTO v_rule FROM automation_rules WHERE id = p_rule_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('allowed', true, 'reason', 'rule_not_found'); END IF;

  IF v_rule.circuit_state = 'open' THEN
    IF v_rule.circuit_opened_at + make_interval(mins => COALESCE(v_rule.circuit_recovery_minutes, p_recovery_minutes)) <= now() THEN
      UPDATE automation_rules SET circuit_state = 'half_open' WHERE id = p_rule_id;
      RETURN jsonb_build_object('allowed', true, 'state', 'half_open');
    ELSE
      RETURN jsonb_build_object('allowed', false, 'state', 'open',
        'recovery_at', v_rule.circuit_opened_at + make_interval(mins => COALESCE(v_rule.circuit_recovery_minutes, p_recovery_minutes)));
    END IF;
  END IF;

  SELECT count(*) INTO v_failure_count FROM automation_execution_log
  WHERE rule_id = p_rule_id AND success = false AND executed_at >= now() - make_interval(mins => p_window_minutes);

  IF v_failure_count >= p_threshold THEN
    UPDATE automation_rules SET circuit_state = 'open', circuit_opened_at = now() WHERE id = p_rule_id;
    INSERT INTO circuit_breaker_events (service, state, previous_state, reason, triggered_by, failure_count, tenant_id)
    SELECT 'rule_' || p_rule_id::text, 'open', COALESCE(v_rule.circuit_state, 'closed'),
      format('%s failures in %s min', v_failure_count, p_window_minutes), 'auto_breaker', v_failure_count, tenant_id
    FROM automation_rules WHERE id = p_rule_id;
    RETURN jsonb_build_object('allowed', false, 'state', 'open', 'failures', v_failure_count);
  END IF;

  RETURN jsonb_build_object('allowed', true, 'state', 'closed', 'failures', v_failure_count);
END;
$$;


--
-- Name: check_approval_complete(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_approval_complete(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_required integer; v_current integer;
BEGIN
  SELECT ac.min_approvers INTO v_required FROM approval_requests ar
  JOIN approval_chains ac ON ar.chain_id = ac.id WHERE ar.id = p_request_id;
  
  SELECT COUNT(DISTINCT approved_by) INTO v_current FROM approvals
  WHERE request_id = p_request_id AND decision = 'approved';
  
  RETURN jsonb_build_object('complete', v_current >= COALESCE(v_required, 1), 'required', COALESCE(v_required, 1), 'current', v_current);
END;
$$;


--
-- Name: check_execution_orphans(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_execution_orphans() RETURNS TABLE(orphan_count bigint, residual_execution_id_count bigint, null_payload_hash_count bigint, affected_job_ids uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH orphan_executions AS (
    SELECT DISTINCT je.job_id
    FROM job_executions je
    JOIN jobs j ON je.job_id = j.id
    WHERE j.status IN ('completed', 'failed', 'cancelled', 'done')
      AND je.status = 'claimed'
  ),
  residual_ids AS (
    SELECT id
    FROM jobs
    WHERE status IN ('completed', 'failed', 'cancelled', 'done')
      AND current_execution_id IS NOT NULL
  ),
  null_hashes AS (
    SELECT id
    FROM jobs
    WHERE payload_hash IS NULL
  )
  SELECT 
    (SELECT COUNT(*) FROM orphan_executions)::BIGINT,
    (SELECT COUNT(*) FROM residual_ids)::BIGINT,
    (SELECT COUNT(*) FROM null_hashes)::BIGINT,
    (
      SELECT ARRAY_AGG(DISTINCT job_id) 
      FROM (
        SELECT job_id FROM orphan_executions
        UNION
        SELECT id FROM residual_ids
        UNION
        SELECT id FROM null_hashes
      ) combined
    );
END;
$$;


--
-- Name: FUNCTION check_execution_orphans(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_execution_orphans() IS 'ARCH-NULL-ROOT Sentinel: Detecta violações de invariantes (orphan executions, residual execution_id, null payload_hash).
   Deve retornar 0,0,0,NULL em sistema saudável.';


