--
-- Name: check_expired_risks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_expired_risks() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  expired_task RECORD;
BEGIN
  -- V-14008 FIX: Require service_role or super_admin
  PERFORM _assert_service_role_or_super_admin();

  FOR expired_task IN
    SELECT * FROM public.tasks
    WHERE status = 'accepted_risk'
      AND risk_expiry_at IS NOT NULL
      AND risk_expiry_at <= now()
  LOOP
    INSERT INTO public.tasks (
      tenant_id, source_type, source_id, title, description, severity, 
      status, requires_human_review, auto_generated
    ) VALUES (
      expired_task.tenant_id,
      'manual',
      expired_task.id::text,
      'Reavaliação de Risco: ' || expired_task.title,
      'O risco aceito para "' || expired_task.title || '" expirou e precisa ser reavaliado.',
      expired_task.severity,
      'open',
      true,
      true
    );
    
    INSERT INTO public.task_events (task_id, tenant_id, actor_type, action, metadata)
    VALUES (
      expired_task.id, 
      expired_task.tenant_id, 
      'system', 
      'risk_expired', 
      jsonb_build_object('expiry_at', expired_task.risk_expiry_at)
    );
    
    UPDATE public.tasks 
    SET status = 'open', updated_at = now()
    WHERE id = expired_task.id;
  END LOOP;
END;
$$;


--
-- Name: check_global_circuit_breaker(uuid, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_global_circuit_breaker(p_tenant_id uuid, p_max_impact_percent numeric DEFAULT 30, p_window_minutes integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total_agents integer;
  v_impacted_agents integer;
  v_impact_percent numeric;
  v_is_open boolean := false;
  v_cooldown_until timestamptz;
BEGIN
  SELECT count(*) INTO v_total_agents FROM agents WHERE tenant_id = p_tenant_id AND archived_at IS NULL;
  IF v_total_agents = 0 THEN RETURN jsonb_build_object('allowed', true, 'reason', 'no_agents'); END IF;

  SELECT count(DISTINCT agent_id) INTO v_impacted_agents
  FROM automation_execution_log
  WHERE tenant_id = p_tenant_id AND executed_at >= now() - make_interval(mins => p_window_minutes);

  v_impact_percent := (v_impacted_agents::numeric / v_total_agents) * 100;

  SELECT cooldown_until INTO v_cooldown_until FROM tenant_automation_state WHERE tenant_id = p_tenant_id;
  IF v_cooldown_until IS NOT NULL AND v_cooldown_until > now() THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'tenant_cooldown_active', 'cooldown_until', v_cooldown_until, 'impact_percent', v_impact_percent);
  END IF;

  IF v_impact_percent >= p_max_impact_percent THEN
    v_is_open := true;
    INSERT INTO tenant_automation_state (tenant_id, cooldown_until, last_breaker_trip, trip_reason)
    VALUES (p_tenant_id, now() + interval '15 minutes', now(), format('Impact %s%% >= threshold %s%%', round(v_impact_percent, 1), p_max_impact_percent))
    ON CONFLICT (tenant_id) DO UPDATE SET cooldown_until = now() + interval '15 minutes', last_breaker_trip = now(),
      trip_reason = format('Impact %s%% >= threshold %s%%', round(v_impact_percent, 1), p_max_impact_percent);

    INSERT INTO circuit_breaker_events (service, state, previous_state, reason, triggered_by, failure_count, tenant_id)
    VALUES ('global_automation', 'open', 'closed',
      format('Fleet impact %s%% exceeds %s%%', round(v_impact_percent, 1), p_max_impact_percent),
      'auto_breaker', v_impacted_agents, p_tenant_id);
  END IF;

  RETURN jsonb_build_object('allowed', NOT v_is_open, 'impact_percent', round(v_impact_percent, 1),
    'impacted_agents', v_impacted_agents, 'total_agents', v_total_agents, 'threshold', p_max_impact_percent,
    'state', CASE WHEN v_is_open THEN 'open' ELSE 'closed' END);
END;
$$;


--
-- Name: check_honeypot_rate_limit_v2(text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_honeypot_rate_limit_v2(p_identifier_hash text, p_max_requests integer DEFAULT 5, p_bucket_seconds integer DEFAULT 60, p_block_seconds integer DEFAULT 900) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_blocked TIMESTAMPTZ;
  v_bucket TIMESTAMPTZ;
  v_count INT;
BEGIN
  -- 1. Check block table
  SELECT blocked_until INTO v_blocked
  FROM public.honeypot_blocks
  WHERE identifier_hash = p_identifier_hash
    AND blocked_until > now();

  IF v_blocked IS NOT NULL THEN
    RETURN FALSE;
  END IF;

  -- 2. Compute current bucket (truncate to bucket_seconds)
  v_bucket := date_trunc('minute', now());

  -- 3. Atomic upsert: increment or insert
  INSERT INTO public.honeypot_rate_buckets (identifier_hash, bucket_start, request_count)
  VALUES (p_identifier_hash, v_bucket, 1)
  ON CONFLICT (identifier_hash, bucket_start)
  DO UPDATE SET request_count = public.honeypot_rate_buckets.request_count + 1
  RETURNING request_count INTO v_count;

  -- 4. If over limit, block
  IF v_count > p_max_requests THEN
    INSERT INTO public.honeypot_blocks (identifier_hash, blocked_until, reason)
    VALUES (p_identifier_hash, now() + make_interval(secs := p_block_seconds), 'rate_limit_exceeded')
    ON CONFLICT (identifier_hash)
    DO UPDATE SET blocked_until = EXCLUDED.blocked_until, reason = EXCLUDED.reason;
    RETURN FALSE;
  END IF;

  RETURN TRUE;
END;
$$;


--
-- Name: check_incident_slo_task(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_incident_slo_task() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_slo RECORD;
  v_task_id uuid;
  v_count integer := 0;
  v_tenant_id uuid;
  v_title text;
  v_severity text;
  v_description text;
BEGIN
  FOR v_slo IN 
    SELECT 
      s.*,
      f.normalized_signature,
      f.severity_hint,
      f.failure_class
    FROM incident_slo_state s
    JOIN failure_fingerprints f ON f.id = s.fingerprint_id
    WHERE s.burn_rate_1h >= 2
      AND s.last_task_id IS NULL
  LOOP
    -- Check idempotency - no open task for this fingerprint
    IF NOT EXISTS (
      SELECT 1 FROM tasks 
      WHERE fingerprint_id = v_slo.fingerprint_id
        AND status IN ('open', 'in_progress')
    ) THEN
      -- Get tenant from recent occurrence
      SELECT tenant_id INTO v_tenant_id
      FROM failure_occurrences
      WHERE fingerprint_id = v_slo.fingerprint_id
      ORDER BY occurred_at DESC 
      LIMIT 1;

      IF v_tenant_id IS NOT NULL THEN
        v_severity := CASE 
          WHEN v_slo.burn_rate_1h >= 5 THEN 'critical'
          WHEN v_slo.burn_rate_1h >= 2 THEN 'high'
          ELSE 'medium' 
        END;

        v_title := 'Burn Rate Alto: ' || COALESCE(v_slo.failure_class, 'Incidente');

        -- CORREÇÃO: Usar concatenação em vez de format() com %.1f
        v_description := 'Burn Rate 1h: ' || ROUND(v_slo.burn_rate_1h::numeric, 1)::text || 'x | 6h: ' || 
                         ROUND(v_slo.burn_rate_6h::numeric, 1)::text || 'x | Budget: ' || 
                         ROUND(v_slo.budget_consumed::numeric, 0)::text || '% consumido';

        INSERT INTO tasks (
          tenant_id, source_type, fingerprint_id, title, description,
          severity, status, requires_human_review, auto_generated
        ) VALUES (
          v_tenant_id, 'incident_group', v_slo.fingerprint_id, v_title,
          v_description,
          v_severity, 'open', true, true
        ) RETURNING id INTO v_task_id;

        UPDATE incident_slo_state 
        SET last_task_id = v_task_id 
        WHERE fingerprint_id = v_slo.fingerprint_id;

        v_count := v_count + 1;
      END IF;
    END IF;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: FUNCTION check_incident_slo_task(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_incident_slo_task() IS '[NULLMANN-FIX] Corrigido bug de sintaxe: PostgreSQL format() não suporta %.1f';


--
-- Name: check_installation_failure_rate(uuid, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_installation_failure_rate(p_tenant_id uuid DEFAULT NULL::uuid, p_hours_back integer DEFAULT 1, p_threshold_pct numeric DEFAULT 30.0) RETURNS TABLE(tenant_id uuid, total_attempts bigint, failed_attempts bigint, failure_rate_pct numeric, exceeds_threshold boolean, period_start timestamp with time zone, period_end timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  RETURN QUERY
  WITH installation_stats AS (
    SELECT
      ia.tenant_id,
      COUNT(*) as total,
      COUNT(*) FILTER (WHERE ia.success = false) as failed,
      NOW() - (p_hours_back || ' hours')::INTERVAL as period_start,
      NOW() as period_end
    FROM public.installation_analytics ia
    WHERE ia.event_type IN ('post_installation', 'post_installation_unverified')
      AND ia.created_at > NOW() - (p_hours_back || ' hours')::INTERVAL
      AND (p_tenant_id IS NULL OR ia.tenant_id = p_tenant_id)
    GROUP BY ia.tenant_id
  )
  SELECT
    s.tenant_id,
    s.total::BIGINT as total_attempts,
    s.failed::BIGINT as failed_attempts,
    CASE 
      WHEN s.total > 0 THEN ROUND((s.failed::NUMERIC / s.total::NUMERIC) * 100, 1)
      ELSE 0
    END as failure_rate_pct,
    CASE 
      WHEN s.total > 0 AND (s.failed::NUMERIC / s.total::NUMERIC) * 100 > p_threshold_pct THEN true
      ELSE false
    END as exceeds_threshold,
    s.period_start,
    s.period_end
  FROM installation_stats s
  WHERE s.total >= 3; -- Minimum 3 attempts to trigger alert
END;
$$;


--
-- Name: FUNCTION check_installation_failure_rate(p_tenant_id uuid, p_hours_back integer, p_threshold_pct numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_installation_failure_rate(p_tenant_id uuid, p_hours_back integer, p_threshold_pct numeric) IS '🔒 Essencial - Monitoramento de falhas';


--
-- Name: check_job_health_anomalies_and_alert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_job_health_anomalies_and_alert() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_anomaly RECORD;
  v_alert_exists BOOLEAN;
BEGIN
  -- Check for critical anomalies in v_job_health_anomalies
  FOR v_anomaly IN 
    SELECT 
      anomaly_type,
      anomaly_count,
      severity,
      description
    FROM v_job_health_anomalies
    WHERE severity = 'critical' AND anomaly_count > 0
  LOOP
    -- Check if alert already exists for this anomaly type in last hour
    SELECT EXISTS(
      SELECT 1 FROM system_alerts
      WHERE alert_type = 'job_health_anomaly_' || v_anomaly.anomaly_type
        AND resolved = false
        AND created_at > NOW() - INTERVAL '1 hour'
    ) INTO v_alert_exists;
    
    IF NOT v_alert_exists THEN
      -- Create system alert for this anomaly
      INSERT INTO system_alerts (
        tenant_id,
        alert_type,
        severity,
        title,
        message,
        metadata,
        resolved
      ) VALUES (
        NULL, -- Global alert
        'job_health_anomaly_' || v_anomaly.anomaly_type,
        'critical',
        'Job Health Anomaly: ' || v_anomaly.anomaly_type,
        v_anomaly.description || ' (Count: ' || v_anomaly.anomaly_count || ')',
        jsonb_build_object(
          'anomaly_type', v_anomaly.anomaly_type,
          'count', v_anomaly.anomaly_count,
          'severity', v_anomaly.severity,
          'detected_at', NOW()
        ),
        false
      );
      
      RAISE NOTICE 'Created alert for job health anomaly: % (count: %)', 
        v_anomaly.anomaly_type, v_anomaly.anomaly_count;
    END IF;
  END LOOP;
END;
$$;


--
-- Name: check_job_quota(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_job_quota() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_max_queued INTEGER;
  v_current_queued INTEGER;
BEGIN
  -- Buscar limite customizado ou usar padrão
  SELECT COALESCE(tjq.max_queued_jobs, 100)
  INTO v_max_queued
  FROM tenant_job_quotas tjq
  WHERE tjq.tenant_id = NEW.tenant_id;
  
  IF v_max_queued IS NULL THEN
    v_max_queued := 100;
  END IF;
  
  -- Contar jobs queued/delivered atuais
  SELECT COUNT(*)
  INTO v_current_queued
  FROM jobs
  WHERE tenant_id = NEW.tenant_id
    AND status IN ('queued', 'delivered');
  
  -- Verificar quota
  IF v_current_queued >= v_max_queued THEN
    -- CORREÇÃO: Inserir com tenant_id EXPLÍCITO (usando o tenant_id do job)
    INSERT INTO security_logs (
      tenant_id,
      ip_address,
      endpoint,
      attack_type,
      severity,
      blocked,
      details
    ) VALUES (
      NEW.tenant_id,  -- IMPORTANTE: tenant_id explícito do job
      'system',
      'job_insert',
      'quota_exceeded',
      'high',
      true,
      jsonb_build_object(
        'current_queued', v_current_queued,
        'max_allowed', v_max_queued,
        'job_type', NEW.type,
        'agent_name', NEW.agent_name
      )
    );
    
    RAISE EXCEPTION 'JOB_QUOTA_EXCEEDED: Tenant has % queued jobs (limit: %). Wait for jobs to complete or contact admin.',
      v_current_queued, v_max_queued
      USING ERRCODE = '54001';
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION check_job_quota(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_job_quota() IS 'SSA-005: Limita quantidade de jobs queued/delivered por tenant para prevenir DoS. Default: 100 jobs.';


--
-- Name: check_offline_agents_for_playbook(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_offline_agents_for_playbook() RETURNS TABLE(agent_id uuid, tenant_id uuid, agent_name text, last_heartbeat timestamp with time zone, minutes_offline double precision, playbook_triggered boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    a.id,
    a.tenant_id,
    a.agent_name::TEXT,
    a.last_heartbeat,
    (EXTRACT(EPOCH FROM (NOW() - a.last_heartbeat)) / 60.0)::double precision,
    false
  FROM agents a
  WHERE a.status = 'active'
    AND a.last_heartbeat < NOW() - INTERVAL '15 minutes'
    AND a.archived_at IS NULL;
END;
$$;


--
-- Name: check_offline_agents_for_playbook(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_offline_agents_for_playbook(p_tenant_id uuid) RETURNS TABLE(agent_id uuid, agent_name text, last_heartbeat timestamp with time zone, minutes_offline double precision)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  RETURN QUERY
  SELECT 
    a.id,
    a.agent_name::TEXT,
    a.last_heartbeat,
    (EXTRACT(EPOCH FROM (NOW() - a.last_heartbeat)) / 60.0)::double precision
  FROM agents a
  WHERE a.tenant_id = p_tenant_id
    AND a.status = 'active'
    AND a.last_heartbeat < NOW() - INTERVAL '15 minutes'
    AND a.archived_at IS NULL;
END;
$$;


--
-- Name: check_quota_threshold(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_quota_threshold() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  usage_percentage numeric;
  tenant_name text;
BEGIN
  -- Calcular porcentagem de uso
  IF NEW.quota_limit IS NOT NULL AND NEW.quota_limit > 0 THEN
    usage_percentage := (NEW.quota_used::numeric / NEW.quota_limit::numeric) * 100;
    
    -- Se atingiu o threshold, enviar alerta
    IF usage_percentage >= COALESCE(NEW.quota_warning_threshold, 80) THEN
      -- Buscar nome do tenant
      SELECT name INTO tenant_name FROM tenants WHERE id = NEW.tenant_id;
      
      -- Log para monitoramento
      RAISE NOTICE 'Quota threshold exceeded: % for tenant % (% of %)', 
        NEW.feature_key, tenant_name, NEW.quota_used, NEW.quota_limit;
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION check_quota_threshold(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_quota_threshold() IS '🔒 Essencial - Trigger de quota';


--
-- Name: check_rate_limit_atomic(text, text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_rate_limit_atomic(p_identifier text, p_endpoint text, p_max_requests integer DEFAULT 60, p_window_minutes integer DEFAULT 1, p_block_minutes integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_now timestamptz := now();
    v_window_start timestamptz := v_now - (p_window_minutes || ' minutes')::interval;
    v_row record;
    v_new_count integer;
BEGIN
    -- Check if blocked
    SELECT * INTO v_row
    FROM rate_limits
    WHERE identifier = p_identifier AND endpoint = p_endpoint;

    IF FOUND AND v_row.blocked_until IS NOT NULL AND v_row.blocked_until > v_now THEN
        RETURN jsonb_build_object(
            'allowed', false,
            'reason', 'blocked',
            'reset_at', v_row.blocked_until
        );
    END IF;

    -- Window expired or no row: reset
    IF NOT FOUND OR v_row.window_start < v_window_start THEN
        INSERT INTO rate_limits (identifier, endpoint, request_count, window_start, last_request_at, blocked_until)
        VALUES (p_identifier, p_endpoint, 1, v_now, v_now, NULL)
        ON CONFLICT (identifier, endpoint)
        DO UPDATE SET
            request_count = 1,
            window_start = v_now,
            last_request_at = v_now,
            blocked_until = NULL;

        RETURN jsonb_build_object('allowed', true, 'remaining', p_max_requests - 1);
    END IF;

    -- Increment
    v_new_count := v_row.request_count + 1;

    IF v_new_count > p_max_requests THEN
        -- Block
        UPDATE rate_limits SET
            request_count = v_new_count,
            last_request_at = v_now,
            blocked_until = v_now + (p_block_minutes || ' minutes')::interval
        WHERE identifier = p_identifier AND endpoint = p_endpoint;

        RETURN jsonb_build_object(
            'allowed', false,
            'reason', 'rate_exceeded',
            'reset_at', v_now + (p_block_minutes || ' minutes')::interval
        );
    END IF;

    UPDATE rate_limits SET
        request_count = v_new_count,
        last_request_at = v_now
    WHERE identifier = p_identifier AND endpoint = p_endpoint;

    RETURN jsonb_build_object('allowed', true, 'remaining', p_max_requests - v_new_count);
END;
$$;


--
-- Name: check_rule_dependencies(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_rule_dependencies(p_rule_id uuid, p_tenant_id uuid) RETURNS TABLE(blocked boolean, blocking_rule_id uuid, blocking_rule_name text, relationship text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT 
    TRUE AS blocked,
    d.depends_on_rule_id AS blocking_rule_id,
    r.name AS blocking_rule_name,
    d.relationship_type AS relationship
  FROM automation_rule_dependencies d
  LEFT JOIN automation_rules r ON r.id = d.depends_on_rule_id
  WHERE d.rule_id = p_rule_id
    AND d.tenant_id = p_tenant_id
    AND d.relationship_type IN ('blocks', 'conflicts')
    AND r.is_active = true
    AND EXISTS (
      SELECT 1 FROM automation_execution_log el
      WHERE el.rule_id = d.depends_on_rule_id
        AND el.executed_at > now() - interval '1 hour'
        AND el.success = true
    );
$$;


--
-- Name: check_security_thresholds(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_security_thresholds() RETURNS TABLE(alert_type text, alert_severity text, message text, current_value integer, threshold integer, should_alert boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant_id uuid := get_active_tenant_id();
BEGIN
  -- Fail-closed for non-super-admin sessions that lack active tenant context.
  IF v_tenant_id IS NULL AND NOT is_current_super_admin() THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT 
    'rls_violation'::text,
    'critical'::text,
    'RLS test failures detected'::text,
    (
      SELECT count(*)::int
      FROM rls_test_results r
      WHERE NOT r.passed
        AND r.tested_at > now() - interval '1 hour'
        AND (is_current_super_admin() OR r.tenant_id = v_tenant_id)
    )::int,
    0,
    (
      SELECT count(*) > 0
      FROM rls_test_results r
      WHERE NOT r.passed
        AND r.tested_at > now() - interval '1 hour'
        AND (is_current_super_admin() OR r.tenant_id = v_tenant_id)
    )

  UNION ALL

  SELECT 
    'critical_event_spike'::text,
    'warning'::text,
    'Unusual critical security event volume'::text,
    (
      SELECT count(*)::int
      FROM security_logs sl
      WHERE sl.severity = 'critical'
        AND sl.created_at > now() - interval '10 minutes'
        AND (is_current_super_admin() OR sl.tenant_id = v_tenant_id)
    )::int,
    5,
    (
      SELECT count(*) > 5
      FROM security_logs sl
      WHERE sl.severity = 'critical'
        AND sl.created_at > now() - interval '10 minutes'
        AND (is_current_super_admin() OR sl.tenant_id = v_tenant_id)
    )

  UNION ALL

  SELECT
    'unresolved_alerts'::text,
    'warning'::text,
    'Multiple unresolved critical alerts'::text,
    (
      SELECT count(*)::int
      FROM system_alerts sa
      WHERE sa.resolved = false
        AND sa.severity = 'critical'
        AND (is_current_super_admin() OR sa.tenant_id = v_tenant_id)
    )::int,
    3,
    (
      SELECT count(*) > 3
      FROM system_alerts sa
      WHERE sa.resolved = false
        AND sa.severity = 'critical'
        AND (is_current_super_admin() OR sa.tenant_id = v_tenant_id)
    );
END;
$$;


--
-- Name: FUNCTION check_security_thresholds(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_security_thresholds() IS 'ADR-VELLUM V-303: Tenant-isolated SECURITY DEFINER. Non-super-admin without active tenant returns empty. Super-admin sees global.';


--
-- Name: check_segregation_rule(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_segregation_rule(_tenant_id uuid, _action_type text, _requester_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rule public.segregation_rules%ROWTYPE;
  v_requester_role text;
BEGIN
  SELECT * INTO v_rule
  FROM public.segregation_rules
  WHERE tenant_id = _tenant_id
    AND action_type = _action_type
    AND is_active = true;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'requires_approval', false,
      'min_approvers', 1
    );
  END IF;
  
  SELECT role::text INTO v_requester_role
  FROM public.user_roles
  WHERE user_id = _requester_id
    AND tenant_id = _tenant_id
  LIMIT 1;
  
  RETURN jsonb_build_object(
    'requires_approval', true,
    'min_approvers', v_rule.min_approvers,
    'required_roles', v_rule.required_roles,
    'exclude_requester', v_rule.exclude_requester,
    'requester_role', v_requester_role
  );
END;
$$;


--
-- Name: check_super_admin_ip_access(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_super_admin_ip_access(_user_id uuid, _ip_address text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _is_super_admin BOOLEAN;
  _ip_allowed BOOLEAN;
  _has_whitelist BOOLEAN;
BEGIN
  -- Verificar se é super_admin
  SELECT EXISTS(
    SELECT 1 FROM user_roles 
    WHERE user_id = _user_id AND role = 'super_admin'
  ) INTO _is_super_admin;

  -- Se não é super_admin, permite acesso normal
  IF NOT _is_super_admin THEN
    RETURN TRUE;
  END IF;

  -- Verificar se existe whitelist configurada
  SELECT EXISTS(
    SELECT 1 FROM admin_ip_whitelist WHERE is_active = true
  ) INTO _has_whitelist;

  -- Se não existe whitelist, permite acesso (para não bloquear durante setup)
  IF NOT _has_whitelist THEN
    RETURN TRUE;
  END IF;

  -- Verificar IP na whitelist (NULL tenant_id = global)
  SELECT EXISTS(
    SELECT 1 FROM admin_ip_whitelist
    WHERE is_active = true
      AND (expires_at IS NULL OR expires_at > now())
      AND _ip_address::inet <<= ip_address
  ) INTO _ip_allowed;

  RETURN _ip_allowed;
END;
$$;


--
-- Name: check_task_sla_breach(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_task_sla_breach() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  breach_count int;
BEGIN
  UPDATE tasks
  SET sla_breached_at = now(), updated_at = now()
  WHERE status IN ('open', 'in_progress')
    AND due_at < now()
    AND sla_breached_at IS NULL;
  
  GET DIAGNOSTICS breach_count = ROW_COUNT;
  RETURN breach_count;
END;
$$;


--
-- Name: check_tenant_automation_quota(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_tenant_automation_quota(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_state record;
  v_today_count integer;
  v_max integer;
BEGIN
  INSERT INTO tenant_automation_state (tenant_id) VALUES (p_tenant_id) ON CONFLICT (tenant_id) DO NOTHING;
  SELECT * INTO v_state FROM tenant_automation_state WHERE tenant_id = p_tenant_id;
  v_max := COALESCE(v_state.max_daily_executions, 500);
  IF v_state.daily_execution_reset_at < date_trunc('day', now()) THEN
    UPDATE tenant_automation_state SET daily_execution_count = 0, daily_execution_reset_at = now() WHERE tenant_id = p_tenant_id;
    v_today_count := 0;
  ELSE
    v_today_count := COALESCE(v_state.daily_execution_count, 0);
  END IF;
  RETURN jsonb_build_object('allowed', v_today_count < v_max, 'current', v_today_count, 'max', v_max, 'remaining', GREATEST(v_max - v_today_count, 0));
END;
$$;


--
-- Name: claim_event_buffer_batch(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_event_buffer_batch(p_batch_id uuid, p_limit integer DEFAULT 5000) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_claimed int;
BEGIN
  WITH claimed AS (
    UPDATE endpoint_event_buffer
    SET batch_id = p_batch_id
    WHERE id IN (
      SELECT id
      FROM endpoint_event_buffer
      WHERE processed_at IS NULL
        AND batch_id IS NULL
      ORDER BY received_at
      LIMIT p_limit
      FOR UPDATE SKIP LOCKED
    )
    RETURNING id
  )
  SELECT count(*) INTO v_claimed FROM claimed;
  
  RETURN v_claimed;
END;
$$;


--
-- Name: claim_jobs_for_agent(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_jobs_for_agent(p_agent_id uuid, p_limit integer DEFAULT 3) RETURNS TABLE(job_id uuid, job_type text, payload jsonb, payload_hash text, expires_at timestamp with time zone, execution_id uuid, nonce uuid, execution_index bigint, previous_execution_hash text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant_id uuid;
  v_caller_tenant_id uuid;
  v_agent_name text;
  v_agent_version text;
  v_job RECORD;
  v_execution_id uuid;
  v_nonce uuid;
  v_new_index bigint;
  v_new_hash text;
  v_chain RECORD;
  v_actual_max_index bigint;
  v_recovered_hash text;
BEGIN
  SELECT a.tenant_id, a.agent_name, a.agent_version
  INTO v_tenant_id, v_agent_name, v_agent_version
  FROM agents a
  WHERE a.id = p_agent_id;

  IF v_tenant_id IS NULL THEN
    RETURN;
  END IF;

  v_caller_tenant_id := get_active_tenant_id();
  IF v_caller_tenant_id IS NOT NULL AND v_caller_tenant_id != v_tenant_id THEN
    INSERT INTO security_logs (attack_type, severity, ip_address, endpoint, blocked, details, tenant_id, user_id)
    VALUES (
      'CROSS_TENANT_JOB_CLAIM_ATTEMPT',
      'high',
      COALESCE(current_setting('request.headers', true)::json->>'x-forwarded-for', 'unknown'),
      'rpc/claim_jobs_for_agent',
      true,
      jsonb_build_object(
        'target_agent_id', p_agent_id,
        'target_tenant_id', v_tenant_id,
        'caller_tenant_id', v_caller_tenant_id,
        'agent_name', v_agent_name
      ),
      v_caller_tenant_id,
      auth.uid()
    );
    RETURN;
  END IF;

  -- Ensure chain row exists (tenant_id is mandatory)
  INSERT INTO agent_execution_chain (
    agent_id,
    tenant_id,
    last_execution_hash,
    last_execution_index,
    updated_at
  )
  VALUES (
    p_agent_id,
    v_tenant_id,
    encode(sha256(('genesis_' || p_agent_id::text)::bytea), 'hex'),
    0,
    NOW()
  )
  ON CONFLICT (agent_id) DO NOTHING;

  -- Lock chain row
  SELECT last_execution_hash, last_execution_index
  INTO v_chain
  FROM agent_execution_chain
  WHERE agent_id = p_agent_id
  FOR UPDATE;

  -- SELF-HEALING: Always sync chain with actual max execution_index
  SELECT MAX(je.execution_index)
  INTO v_actual_max_index
  FROM job_executions je
  WHERE je.agent_id = p_agent_id
    AND je.execution_index IS NOT NULL;

  IF v_actual_max_index IS NOT NULL
     AND v_actual_max_index >= COALESCE(v_chain.last_execution_index, 0) THEN
    SELECT COALESCE(je.execution_hash, encode(sha256(('recovery_' || je.id::text)::bytea), 'hex'))
    INTO v_recovered_hash
    FROM job_executions je
    WHERE je.agent_id = p_agent_id
      AND je.execution_index = v_actual_max_index
    LIMIT 1;

    v_chain.last_execution_hash := COALESCE(
      v_recovered_hash,
      encode(sha256(('genesis_' || p_agent_id::text)::bytea), 'hex')
    );
    v_chain.last_execution_index := v_actual_max_index;

    UPDATE agent_execution_chain
    SET
      last_execution_hash = v_chain.last_execution_hash,
      last_execution_index = v_chain.last_execution_index,
      updated_at = NOW()
    WHERE agent_id = p_agent_id;
  END IF;

  FOR v_job IN
    WITH claimed AS (
      UPDATE jobs
      SET
        status = 'delivered',
        agent_id = p_agent_id,
        agent_name = v_agent_name,
        delivered_at = now(),
        delivery_attempts = delivery_attempts + 1
      WHERE jobs.id IN (
        SELECT j.id
        FROM jobs j
        WHERE j.status IN ('queued', 'pending')
          AND j.tenant_id = v_tenant_id
          AND j.agent_id = p_agent_id
          AND j.approved = true
          AND (j.scheduled_at IS NULL OR j.scheduled_at <= now())
          AND (j.expires_at IS NULL OR j.expires_at > now())
        ORDER BY j.priority DESC NULLS LAST, j.created_at ASC
        LIMIT p_limit
        FOR UPDATE SKIP LOCKED
      )
      RETURNING jobs.*
    )
    SELECT * FROM claimed
  LOOP
    BEGIN
      v_nonce := gen_random_uuid();
      v_new_index := COALESCE(v_chain.last_execution_index, 0) + 1;

      v_new_hash := encode(
        sha256(
          (
            COALESCE(v_chain.last_execution_hash, 'genesis') ||
            v_job.id::text ||
            v_nonce::text ||
            v_new_index::text
          )::bytea
        ),
        'hex'
      );

      INSERT INTO public.job_executions (
        job_id,
        agent_id,
        tenant_id,
        agent_version,
        agent_name,
        nonce,
        execution_index,
        previous_execution_hash,
        execution_hash,
        payload_hash,
        claimed_at,
        started_at,
        status
      ) VALUES (
        v_job.id,
        p_agent_id,
        v_tenant_id,
        COALESCE(v_agent_version, 'unknown'),
        v_agent_name,
        v_nonce,
        v_new_index,
        v_chain.last_execution_hash,
        v_new_hash,
        v_job.payload_hash,
        NOW(),
        NOW(),
        'running'
      )
      RETURNING id INTO v_execution_id;

      UPDATE jobs
      SET current_execution_id = v_execution_id
      WHERE id = v_job.id;

      v_chain.last_execution_hash := v_new_hash;
      v_chain.last_execution_index := v_new_index;

      UPDATE agent_execution_chain
      SET
        last_execution_hash = v_new_hash,
        last_execution_index = v_new_index,
        updated_at = NOW()
      WHERE agent_id = p_agent_id;

      job_id := v_job.id;
      job_type := v_job.type;
      payload := v_job.payload;
      payload_hash := v_job.payload_hash;
      expires_at := v_job.expires_at;
      execution_id := v_execution_id;
      nonce := v_nonce;
      execution_index := v_new_index;
      previous_execution_hash := v_chain.last_execution_hash;
      RETURN NEXT;
    EXCEPTION
      WHEN OTHERS THEN
        RAISE WARNING 'Failed to create execution for job %: %', v_job.id, SQLERRM;
        CONTINUE;
    END;
  END LOOP;
END;
$$;


--
-- Name: classify_dlq_job(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.classify_dlq_job() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Transient: network/timeout issues (retry-able)
  IF NEW.error_message ILIKE '%timeout%'
     OR NEW.error_message ILIKE '%connection%'
     OR NEW.error_message ILIKE '%network%'
     OR NEW.error_message ILIKE '%ECONNREFUSED%' THEN
    NEW.classification := 'transient';
    NEW.review_required := false;
  
  -- Suspicious: potential security or injection issues
  ELSIF NEW.error_message ILIKE '%syntax%'
     OR NEW.error_message ILIKE '%injection%'
     OR (NEW.payload IS NOT NULL AND NEW.payload::text ILIKE '%<script%')
     OR (NEW.payload IS NOT NULL AND NEW.payload::text ILIKE '%drop table%')
     OR (NEW.payload IS NOT NULL AND NEW.payload::text ILIKE '%delete from%') THEN
    NEW.classification := 'suspicious';
    NEW.review_required := true;
  
  -- Expected: normal operational failures
  ELSE
    NEW.classification := 'expected';
    NEW.review_required := false;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: classify_job_failure(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.classify_job_failure(p_error_message text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_error_message IS NULL THEN
    RETURN 'BUG';
  END IF;
  
  -- AGENT_OFFLINE: agente não busca jobs
  IF p_error_message ILIKE '%queued%hour%' 
     OR p_error_message ILIKE '%auto-cancel%offline%'
     OR p_error_message ILIKE '%agent offline%' THEN
    RETURN 'AGENT_OFFLINE';
  END IF;
  
  -- AGENT_STALLED: agente buscou mas não completou
  IF p_error_message ILIKE '%delivered state%'
     OR p_error_message ILIKE '%zombie%'
     OR p_error_message ILIKE '%delivered%timeout%'
     OR p_error_message ILIKE '%Job timeout%exceeded%' THEN
    RETURN 'AGENT_STALLED';
  END IF;
  
  -- AGENT_INCOMPATIBLE: versão antiga
  IF p_error_message ILIKE '%version%old%' THEN
    RETURN 'AGENT_INCOMPATIBLE';
  END IF;
  
  -- EXPECTED_DROP: limpeza de quota (não é erro)
  IF p_error_message ILIKE '%quota%cleanup%'
     OR p_error_message ILIKE '%obsoleto%' THEN
    RETURN 'EXPECTED_DROP';
  END IF;
  
  -- CASCADE_FAILURE: falha em cadeia
  IF p_error_message ILIKE '%parent job%'
     OR p_error_message ILIKE '%job pai%' THEN
    RETURN 'CASCADE_FAILURE';
  END IF;
  
  -- TRANSIENT: pode melhorar com retry
  IF p_error_message ILIKE '%timeout%'
     AND p_error_message NOT ILIKE '%hour%'
     AND p_error_message NOT ILIKE '%exceeded%' THEN
    RETURN 'TRANSIENT';
  END IF;
  
  -- POLICY: bloqueio por política
  IF p_error_message ILIKE '%safe mode%'
     OR p_error_message ILIKE '%SAFE_MODE%'
     OR p_error_message ILIKE '%policy%' THEN
    RETURN 'POLICY';
  END IF;
  
  -- Default: BUG (precisa investigar)
  RETURN 'BUG';
END;
$$;


--
-- Name: classify_software_risk(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.classify_software_risk() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_knowledge RECORD;
  v_risk TEXT := 'unknown';
  v_category TEXT;
BEGIN
  -- Skip if risk_level already set (manual override)
  IF NEW.risk_level IS NOT NULL AND NEW.risk_level != 'unknown' THEN
    RETURN NEW;
  END IF;

  -- Search knowledge base for matches
  FOR v_knowledge IN 
    SELECT * FROM software_knowledge_base 
    WHERE is_active = true
    ORDER BY 
      CASE match_type 
        WHEN 'exact' THEN 1 
        WHEN 'contains' THEN 2 
        WHEN 'regex' THEN 3 
      END
  LOOP
    IF v_knowledge.match_type = 'exact' AND LOWER(NEW.name) = LOWER(v_knowledge.software_pattern) THEN
      v_risk := v_knowledge.default_risk_level;
      v_category := v_knowledge.category;
      EXIT;
    ELSIF v_knowledge.match_type = 'contains' AND LOWER(NEW.name) LIKE '%' || LOWER(v_knowledge.software_pattern) || '%' THEN
      v_risk := v_knowledge.default_risk_level;
      v_category := v_knowledge.category;
      EXIT;
    ELSIF v_knowledge.match_type = 'regex' THEN
      BEGIN
        IF NEW.name ~ v_knowledge.software_pattern THEN
          v_risk := v_knowledge.default_risk_level;
          v_category := v_knowledge.category;
          EXIT;
        END IF;
      EXCEPTION WHEN OTHERS THEN
        -- Invalid regex, skip
        CONTINUE;
      END;
    END IF;
  END LOOP;
  
  NEW.risk_level := v_risk;
  RETURN NEW;
END;
$$;


--
-- Name: cleanup_all_problematic_agents(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_all_problematic_agents(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agent_record RECORD;
  v_results jsonb[] := '{}';
  v_total_cleaned INT := 0;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  -- Verificar permissão (apenas admin do tenant)
  IF NOT EXISTS (
    SELECT 1 FROM user_roles
    WHERE user_id = auth.uid()
      AND tenant_id = p_tenant_id
      AND role IN ('admin', 'super_admin')
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Unauthorized: Admin access required'
    );
  END IF;
  
  -- Limpar cada agente problemático
  FOR v_agent_record IN 
    SELECT id, agent_name 
    FROM v_problematic_agents
    WHERE tenant_id = p_tenant_id
  LOOP
    v_results := v_results || cleanup_problematic_agent(v_agent_record.id);
    v_total_cleaned := v_total_cleaned + 1;
  END LOOP;
  
  RETURN jsonb_build_object(
    'success', true,
    'total_cleaned', v_total_cleaned,
    'results', v_results
  );
END;
$$;


