--
-- Name: cleanup_expired_telemetry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_expired_telemetry() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_config RECORD;
  v_cutoff TIMESTAMPTZ;
  v_deleted INTEGER;
  v_results JSONB := '[]'::JSONB;
  v_table_name TEXT;
BEGIN
  FOR v_config IN
    SELECT * FROM telemetry_retention_config WHERE is_enabled = true
  LOOP
    v_cutoff := now() - (v_config.retention_days || ' days')::INTERVAL;

    CASE v_config.event_category
      WHEN 'process' THEN v_table_name := 'endpoint_process_events';
      WHEN 'file' THEN v_table_name := 'endpoint_file_events';
      WHEN 'network' THEN v_table_name := 'endpoint_network_events';
      WHEN 'registry' THEN v_table_name := 'endpoint_registry_events';
      WHEN 'detection' THEN v_table_name := 'endpoint_detection_events';
      ELSE CONTINUE;
    END CASE;

    EXECUTE format(
      'DELETE FROM %I WHERE tenant_id = $1 AND event_time < $2',
      v_table_name
    ) USING v_config.tenant_id, v_cutoff;

    GET DIAGNOSTICS v_deleted = ROW_COUNT;

    v_results := v_results || jsonb_build_object(
      'tenant_id', v_config.tenant_id,
      'category', v_config.event_category,
      'cutoff', v_cutoff,
      'deleted', v_deleted
    );
  END LOOP;

  RETURN jsonb_build_object('cleaned', v_results, 'run_at', now());
END;
$_$;


--
-- Name: cleanup_honeypot_old_data(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_honeypot_old_data(p_retention_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_interactions_deleted INT;
  v_buckets_deleted INT;
  v_blocks_deleted INT;
  v_hourly_deleted INT;
  v_cutoff TIMESTAMPTZ := now() - make_interval(days := p_retention_days);
BEGIN
  -- Delete old interactions
  DELETE FROM honeypot_interactions WHERE created_at < v_cutoff;
  GET DIAGNOSTICS v_interactions_deleted = ROW_COUNT;

  -- Delete old rate limit buckets (>1 hour old)
  DELETE FROM honeypot_rate_buckets WHERE bucket_start < now() - interval '1 hour';
  GET DIAGNOSTICS v_buckets_deleted = ROW_COUNT;

  -- Delete expired blocks
  DELETE FROM honeypot_blocks WHERE blocked_until < now();
  GET DIAGNOSTICS v_blocks_deleted = ROW_COUNT;

  -- Delete old hourly stats (keep 180 days)
  DELETE FROM honeypot_hourly_stats WHERE hour_start < now() - interval '180 days';
  GET DIAGNOSTICS v_hourly_deleted = ROW_COUNT;

  RETURN jsonb_build_object(
    'interactions_deleted', v_interactions_deleted,
    'buckets_deleted', v_buckets_deleted,
    'blocks_deleted', v_blocks_deleted,
    'hourly_deleted', v_hourly_deleted
  );
END;
$$;


--
-- Name: cleanup_honeypot_rate_data(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_honeypot_rate_data(p_older_than_minutes integer DEFAULT 10) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deleted INT := 0;
  v_tmp INT;
BEGIN
  DELETE FROM public.honeypot_rate_buckets
  WHERE bucket_start < now() - make_interval(mins := p_older_than_minutes);
  GET DIAGNOSTICS v_tmp = ROW_COUNT;
  v_deleted := v_deleted + v_tmp;

  DELETE FROM public.honeypot_blocks
  WHERE blocked_until < now();
  GET DIAGNOSTICS v_tmp = ROW_COUNT;
  v_deleted := v_deleted + v_tmp;

  RETURN v_deleted;
END;
$$;


--
-- Name: cleanup_jobs_for_offline_agents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_jobs_for_offline_agents() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  cancelled_count integer := 0;
  result jsonb;
BEGIN
  -- Cancel ALL pending/queued jobs for agents offline >2h
  -- No need to wait for TTL expiry - cancel immediately
  UPDATE jobs 
  SET 
    status = 'cancelled', 
    completed_at = NOW(),
    error_message = '[AUTO-CLEANUP] Job cancelled: Agent offline >2h',
    failure_class = 'AGENT_OFFLINE'
  WHERE status IN ('pending', 'queued')
    AND agent_id IN (
      SELECT id FROM agents 
      WHERE status = 'inactive' 
         OR (last_heartbeat IS NOT NULL AND last_heartbeat < NOW() - INTERVAL '2 hours')
         OR last_heartbeat IS NULL
    );
  GET DIAGNOSTICS cancelled_count = ROW_COUNT;
  
  result := jsonb_build_object(
    'success', true, 
    'jobs_cancelled', cancelled_count, 
    'executed_at', NOW()
  );
  
  INSERT INTO cron_health_checks (cron_name, last_success_at, consecutive_failures, updated_at, last_result)
  VALUES ('cleanup-jobs-offline-agents', NOW(), 0, NOW(), result)
  ON CONFLICT (cron_name) DO UPDATE SET
    last_success_at = NOW(), 
    consecutive_failures = 0, 
    last_error = NULL,
    updated_at = NOW(), 
    last_result = EXCLUDED.last_result;
  
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  INSERT INTO cron_health_checks (cron_name, last_failure_at, last_error, consecutive_failures, updated_at)
  VALUES ('cleanup-jobs-offline-agents', NOW(), SQLERRM, 1, NOW())
  ON CONFLICT (cron_name) DO UPDATE SET
    last_failure_at = NOW(), 
    last_error = SQLERRM,
    consecutive_failures = cron_health_checks.consecutive_failures + 1, 
    updated_at = NOW();
  RAISE;
END;
$$;


--
-- Name: FUNCTION cleanup_jobs_for_offline_agents(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cleanup_jobs_for_offline_agents() IS 'Cancela jobs pendentes para agentes offline';


--
-- Name: cleanup_offline_agents_jobs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_offline_agents_jobs() RETURNS TABLE(cleaned_count integer, agent_ids uuid[], job_ids uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cleaned_count INTEGER; v_agent_ids UUID[]; v_job_ids UUID[];
BEGIN
  PERFORM _assert_service_role_or_super_admin();
  
  WITH offline_agents AS (
    SELECT id FROM public.agents
    WHERE last_heartbeat IS NULL OR last_heartbeat < NOW() - INTERVAL '24 hours'
  ),
  cancelled_jobs AS (
    UPDATE public.jobs SET status = 'cancelled',
      error_message = 'Auto-cancelled: agent offline >24h (scheduled cleanup)', completed_at = NOW()
    WHERE status IN ('queued', 'delivered')
      AND agent_id IN (SELECT id FROM offline_agents)
    RETURNING id, agent_id
  )
  SELECT COUNT(*)::INTEGER, ARRAY_AGG(DISTINCT agent_id), ARRAY_AGG(id)
  INTO v_cleaned_count, v_agent_ids, v_job_ids FROM cancelled_jobs;
  
  RETURN QUERY SELECT COALESCE(v_cleaned_count, 0), COALESCE(v_agent_ids, ARRAY[]::UUID[]), COALESCE(v_job_ids, ARRAY[]::UUID[]);
END;
$$;


