--

CREATE FUNCTION public.cleanup_old_metrics_90days() RETURNS TABLE(deleted_count bigint, table_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_metrics_deleted BIGINT := 0;
  v_audit_deleted BIGINT := 0;
  v_cutoff_90days TIMESTAMP WITH TIME ZONE := NOW() - INTERVAL '90 days';
  v_cutoff_365days TIMESTAMP WITH TIME ZONE := NOW() - INTERVAL '365 days';
BEGIN
  -- Limpar métricas de sistema > 90 dias
  DELETE FROM public.agent_system_metrics_partitioned
  WHERE collected_at < v_cutoff_90days;
  GET DIAGNOSTICS v_metrics_deleted = ROW_COUNT;
  
  deleted_count := v_metrics_deleted;
  table_name := 'agent_system_metrics_partitioned';
  RETURN NEXT;
  
  -- Limpar audit logs > 365 dias
  DELETE FROM public.audit_logs
  WHERE created_at < v_cutoff_365days;
  GET DIAGNOSTICS v_audit_deleted = ROW_COUNT;
  
  deleted_count := v_audit_deleted;
  table_name := 'audit_logs';
  RETURN NEXT;
  
  RETURN;
END;
$$;


--
-- Name: FUNCTION cleanup_old_metrics_90days(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cleanup_old_metrics_90days() IS '🔒 Essencial - Política de retenção: métricas 90 dias, audit logs 365 dias';


--
-- Name: cleanup_old_metrics_aggressive(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_old_metrics_aggressive() RETURNS TABLE(deleted_count bigint, oldest_remaining timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deleted_count BIGINT;
  v_oldest_remaining TIMESTAMP WITH TIME ZONE;
BEGIN
  -- Deletar métricas com mais de 7 dias (em vez de 30)
  DELETE FROM public.agent_system_metrics
  WHERE collected_at < NOW() - INTERVAL '7 days';
  
  GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
  
  -- Buscar timestamp da métrica mais antiga restante
  SELECT MIN(collected_at) INTO v_oldest_remaining
  FROM public.agent_system_metrics;
  
  RAISE NOTICE 'Aggressive metrics cleanup: % rows deleted, oldest remaining: %', 
    v_deleted_count, v_oldest_remaining;
  
  RETURN QUERY SELECT v_deleted_count, v_oldest_remaining;
END;
$$;


--
-- Name: FUNCTION cleanup_old_metrics_aggressive(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cleanup_old_metrics_aggressive() IS 'Aggressive cleanup: removes metrics older than 7 days. Should be scheduled via pg_cron daily at 03:00 UTC.';


