--
-- Name: cleanup_problematic_agent(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_problematic_agent(p_agent_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agent_name TEXT;
  v_tenant_id UUID;
  v_caller_tenant_id UUID;
  v_tokens_invalidated INT;
  v_jobs_deleted INT;
BEGIN
  -- SECURITY: Get caller's tenant context
  v_caller_tenant_id := get_active_tenant_id();
  
  -- Allow super_admin to bypass tenant check
  IF v_caller_tenant_id IS NULL AND NOT is_current_super_admin() THEN
    INSERT INTO security_logs (
      attack_type, severity, ip_address, endpoint, blocked, details, tenant_id, user_id
    ) VALUES (
      'TENANT_VALIDATION_FAILED',
      'high',
      COALESCE(current_setting('request.headers', true)::json->>'x-forwarded-for', 'unknown'),
      'rpc/cleanup_problematic_agent',
      true,
      jsonb_build_object('agent_id', p_agent_id, 'reason', 'No tenant context'),
      NULL,
      auth.uid()
    );
    RETURN jsonb_build_object(
      'success', false,
      'error', 'INVALID_TENANT_CONTEXT'
    );
  END IF;

  -- Get agent info
  SELECT agent_name, tenant_id INTO v_agent_name, v_tenant_id
  FROM agents
  WHERE id = p_agent_id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Agent not found',
      'agent_id', p_agent_id
    );
  END IF;
  
  -- CRITICAL: Validate caller owns this agent (unless super_admin)
  IF NOT is_current_super_admin() AND v_caller_tenant_id != v_tenant_id THEN
    -- LOG ATTACK: Cross-tenant access attempt
    INSERT INTO security_logs (
      attack_type, severity, ip_address, endpoint, blocked, details, tenant_id, user_id
    ) VALUES (
      'CROSS_TENANT_ACCESS_ATTEMPT',
      'critical',
      COALESCE(current_setting('request.headers', true)::json->>'x-forwarded-for', 'unknown'),
      'rpc/cleanup_problematic_agent',
      true,
      jsonb_build_object(
        'target_agent_id', p_agent_id,
        'target_tenant_id', v_tenant_id,
        'caller_tenant_id', v_caller_tenant_id,
        'agent_name', v_agent_name
      ),
      v_caller_tenant_id,
      auth.uid()
    );

    RETURN jsonb_build_object(
      'success', false,
      'error', 'TENANT_MISMATCH'
    );
  END IF;
  
  -- Invalidate old tokens
  UPDATE agent_tokens 
  SET is_active = false 
  WHERE agent_id = p_agent_id;
  
  GET DIAGNOSTICS v_tokens_invalidated = ROW_COUNT;
  
  -- Remove pending jobs
  DELETE FROM jobs 
  WHERE agent_id = p_agent_id 
    AND status IN ('queued', 'delivered');
  
  GET DIAGNOSTICS v_jobs_deleted = ROW_COUNT;
  
  -- Reset agent status
  UPDATE agents 
  SET 
    status = 'pending',
    last_heartbeat = NULL
  WHERE id = p_agent_id;
  
  -- Audit log
  INSERT INTO audit_logs (
    tenant_id,
    user_id,
    action,
    resource_type,
    resource_id,
    success,
    details
  ) VALUES (
    v_tenant_id,
    auth.uid(),
    'cleanup_agent',
    'agent',
    p_agent_id::text,
    true,
    jsonb_build_object(
      'agent_name', v_agent_name,
      'tokens_invalidated', v_tokens_invalidated,
      'jobs_deleted', v_jobs_deleted
    )
  );
  
  RETURN jsonb_build_object(
    'success', true,
    'agent_id', p_agent_id,
    'agent_name', v_agent_name,
    'tokens_invalidated', v_tokens_invalidated,
    'jobs_deleted', v_jobs_deleted
  );
END;
$$;


--
-- Name: FUNCTION cleanup_problematic_agent(p_agent_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cleanup_problematic_agent(p_agent_id uuid) IS 'SECURITY HARDENED (V-101): Validates caller tenant ownership before cleanup.
Logs cross-tenant access attempts to security_logs with severity=critical.
Super admins can bypass tenant check.';


