--
-- Name: cleanup_stale_queued_jobs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_stale_queued_jobs(p_hours_threshold integer DEFAULT 24) RETURNS TABLE(cleaned_count integer, job_ids uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cutoff TIMESTAMP WITH TIME ZONE;
  v_cleaned_count INTEGER;
  v_job_ids UUID[];
BEGIN
  v_cutoff := NOW() - (p_hours_threshold || ' hours')::INTERVAL;
  
  -- Mark stale queued jobs as failed with explanation
  WITH updated_jobs AS (
    UPDATE jobs
    SET 
      status = 'failed',
      error_message = 'Job timeout: stuck in queued state for more than ' || p_hours_threshold || ' hours (auto-cleanup)',
      completed_at = NOW()
    WHERE status = 'queued'
      AND created_at < v_cutoff
    RETURNING id
  )
  SELECT 
    COUNT(*)::INTEGER,
    ARRAY_AGG(id)
  INTO v_cleaned_count, v_job_ids
  FROM updated_jobs;
  
  -- Log cleanup operation
  IF v_cleaned_count > 0 THEN
    RAISE NOTICE 'Cleanup completed: % stale queued jobs marked as failed', v_cleaned_count;
  END IF;
  
  RETURN QUERY SELECT 
    COALESCE(v_cleaned_count, 0),
    COALESCE(v_job_ids, ARRAY[]::UUID[]);
END;
$$;


--
-- Name: FUNCTION cleanup_stale_queued_jobs(p_hours_threshold integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cleanup_stale_queued_jobs(p_hours_threshold integer) IS 'P1 FIX: Cleans up jobs stuck in queued state. Should be called daily via cron or Edge Function scheduler. Default threshold: 24 hours.';


--
-- Name: cleanup_stale_tasks(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_stale_tasks(p_tenant_id uuid, p_days_old integer DEFAULT 30, p_batch_size integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cancelled INTEGER := 0;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  -- BLINDAGEM DE TENANT
  IF p_tenant_id IS DISTINCT FROM get_active_tenant_id()
     AND NOT is_current_super_admin() THEN
    RAISE EXCEPTION 'Tenant mismatch: access denied';
  END IF;

  WITH orphan_tasks AS (
    SELECT id FROM tasks
    WHERE tenant_id = p_tenant_id
      AND status = 'open'
      AND fingerprint_id IS NULL
      AND created_at < NOW() - (p_days_old || ' days')::INTERVAL
    LIMIT p_batch_size
  )
  UPDATE tasks t
  SET status = 'cancelled',
      closed_at = NOW(),
      closure_reason = 'Auto-cancelled: orphan task without fingerprint'
  FROM orphan_tasks o
  WHERE t.id = o.id;
  
  GET DIAGNOSTICS v_cancelled = ROW_COUNT;
  
  RETURN jsonb_build_object(
    'cancelled_orphans', v_cancelled,
    'tenant_id', p_tenant_id
  );
END;
$$;


--
-- Name: cleanup_stuck_builds(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_stuck_builds() RETURNS TABLE(cleaned_count integer, build_ids uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cleaned_count integer;
  v_build_ids uuid[];
BEGIN
  -- Atualizar builds travados (mais de 30 minutos em estado 'building')
  WITH updated_builds AS (
    UPDATE public.agent_builds
    SET 
      build_status = 'failed',
      build_completed_at = now(),
      error_message = 'Build timeout - exceeded 30 minutes (auto-cleanup)'
    WHERE 
      build_status = 'building'
      AND created_at < now() - interval '30 minutes'
    RETURNING id
  )
  SELECT 
    count(*)::integer,
    array_agg(id)
  INTO v_cleaned_count, v_build_ids
  FROM updated_builds;
  
  -- Log da operação
  RAISE NOTICE 'Cleanup completed: % builds marked as failed', COALESCE(v_cleaned_count, 0);
  
  RETURN QUERY SELECT 
    COALESCE(v_cleaned_count, 0),
    COALESCE(v_build_ids, ARRAY[]::uuid[]);
END;
$$;


