-- Name: FUNCTION cleanup_stuck_builds(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cleanup_stuck_builds() IS '🔒 Essencial - Recuperação de builds travados';


--
-- Name: cleanup_stuck_jobs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_stuck_jobs() RETURNS TABLE(cleaned_count integer, job_ids uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cleaned_count INTEGER;
  v_job_ids UUID[];
BEGIN
  -- Marcar jobs "delivered" há mais de 1 hora como "failed"
  WITH updated_jobs AS (
    UPDATE jobs
    SET 
      status = 'failed',
      error_message = 'Job timeout: exceeded 1 hour in delivered state (auto-cleanup)',
      completed_at = NOW()
    WHERE status = 'delivered'
      AND delivered_at < NOW() - INTERVAL '1 hour'
    RETURNING id
  )
  SELECT 
    COUNT(*)::INTEGER,
    ARRAY_AGG(id)
  INTO v_cleaned_count, v_job_ids
  FROM updated_jobs;
  
  -- Log da operação
  IF v_cleaned_count > 0 THEN
    RAISE NOTICE 'Cleanup concluído: % jobs marcados como failed', v_cleaned_count;
  END IF;
  
  RETURN QUERY SELECT 
    COALESCE(v_cleaned_count, 0),
    COALESCE(v_job_ids, ARRAY[]::UUID[]);
END;
$$;


