--
-- Name: cleanup_suspended_tenant_data(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_suspended_tenant_data(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant RECORD;
  v_deleted JSONB := '{}'::JSONB;
  v_count INTEGER;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  -- Only service_role can call this
  IF NOT (current_setting('request.jwt.claim.role', true) = 'service_role') THEN
    RAISE EXCEPTION 'Unauthorized: requires service_role';
  END IF;

  SELECT * INTO v_tenant FROM public.tenants WHERE id = p_tenant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tenant not found';
  END IF;

  IF v_tenant.suspension_status NOT IN ('suspended', 'pending_deletion') THEN
    RAISE EXCEPTION 'Tenant is not suspended';
  END IF;

  -- Log cleanup start
  INSERT INTO public.tenant_suspension_events (tenant_id, event_type, reason)
  VALUES (p_tenant_id, 'cleanup_started', 'Limpeza de dados obsoletos iniciada');

  -- Clean non-critical data (keep audit logs for compliance)
  -- 1. Agent disk metrics (older than 7 days)
  DELETE FROM public.agent_disk_metrics WHERE tenant_id = p_tenant_id AND created_at < now() - INTERVAL '7 days';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_deleted := v_deleted || jsonb_build_object('agent_disk_metrics', v_count);

  -- 2. Agent certificates
  DELETE FROM public.agent_certificates WHERE tenant_id = p_tenant_id AND collected_at < now() - INTERVAL '7 days';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_deleted := v_deleted || jsonb_build_object('agent_certificates', v_count);

  -- 3. File integrity records
  DELETE FROM public.agent_file_integrity WHERE tenant_id = p_tenant_id AND collected_at < now() - INTERVAL '7 days';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_deleted := v_deleted || jsonb_build_object('agent_file_integrity', v_count);

  -- 4. Old scheduled job runs
  DELETE FROM public.scheduled_job_runs WHERE tenant_id = p_tenant_id AND completed_at < now() - INTERVAL '7 days';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_deleted := v_deleted || jsonb_build_object('scheduled_job_runs', v_count);

  -- 5. AI insights (non-acknowledged)
  DELETE FROM public.ai_insights WHERE tenant_id = p_tenant_id AND acknowledged = false;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_deleted := v_deleted || jsonb_build_object('ai_insights', v_count);

  -- Log cleanup completion
  INSERT INTO public.tenant_suspension_events (tenant_id, event_type, reason, metadata)
  VALUES (p_tenant_id, 'cleanup_completed', 'Limpeza de dados concluída', v_deleted);

  RETURN jsonb_build_object(
    'status', 'completed',
    'tenant_id', p_tenant_id,
    'deleted', v_deleted
  );
END;
$$;


--
-- Name: cleanup_zombie_executions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_zombie_executions() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_orphaned integer := 0;
  v_stale integer := 0;
  v_completed_cleanup integer := 0;
BEGIN
  -- Part 1: Orphaned executions where parent job FAILED or CANCELLED
  -- These are genuine orphans that should be marked as failed
  WITH cleaned AS (
    UPDATE job_executions
    SET 
      status = 'failed',
      finished_at = now(),
      error_message = '[CLEANUP] Orphaned execution - parent job failed/cancelled'
    WHERE status = 'running'
      AND job_id IN (
        SELECT id FROM jobs WHERE status IN ('failed', 'cancelled')
      )
    RETURNING id
  )
  SELECT count(*) INTO v_orphaned FROM cleaned;

  -- Part 2: Stale executions for COMPLETED jobs
  -- The job succeeded but the execution record wasn't finalized (race condition).
  -- Mark as 'completed' (not 'failed') since the job itself succeeded.
  WITH completed_cleanup AS (
    UPDATE job_executions
    SET 
      status = 'completed',
      finished_at = COALESCE(finished_at, now()),
      error_message = '[CLEANUP] Execution record synced with completed parent job'
    WHERE status = 'running'
      AND job_id IN (
        SELECT id FROM jobs WHERE status = 'completed'
      )
    RETURNING id
  )
  SELECT count(*) INTO v_completed_cleanup FROM completed_cleanup;

  -- Part 3: Executions running > 4h without result (genuinely stale)
  WITH stale AS (
    UPDATE job_executions
    SET 
      status = 'failed',
      finished_at = now(),
      error_message = '[CLEANUP] Execution running > 4h without result'
    WHERE status = 'running'
      AND started_at < now() - interval '4 hours'
    RETURNING id
  )
  SELECT count(*) INTO v_stale FROM stale;

  RETURN jsonb_build_object(
    'orphaned_cleaned', v_orphaned,
    'completed_synced', v_completed_cleanup,
    'stale_cleaned', v_stale,
    'total', v_orphaned + v_completed_cleanup + v_stale,
    'cleaned_at', now()
  );
END;
$$;


--
-- Name: FUNCTION cleanup_zombie_executions(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cleanup_zombie_executions() IS 'Limpa job_executions órfãs (running cujo job já finalizou) e stale (running > 4h)';


--
-- Name: collect_soc2_evidence_all_tenants(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.collect_soc2_evidence_all_tenants() RETURNS TABLE(tenant_id uuid, evidence_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant RECORD;
  v_count INTEGER;
BEGIN
  FOR v_tenant IN SELECT t.id FROM tenants t WHERE t.state = 'active' OR t.state IS NULL ORDER BY t.id
  LOOP
    v_count := collect_soc2_evidence_for_tenant(v_tenant.id);
    tenant_id := v_tenant.id;
    evidence_count := v_count;
    RETURN NEXT;
  END LOOP;
  RETURN;
END;
$$;


--
-- Name: collect_soc2_evidence_for_tenant(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.collect_soc2_evidence_for_tenant(p_tenant_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count INTEGER := 0;
  v_roles_count INTEGER;
  v_audit_count INTEGER;
  v_agents_total INTEGER;
  v_agents_active INTEGER;
  v_detection_rules_count INTEGER;
  v_enrollment_active INTEGER;
  v_enrollment_total INTEGER;
  v_policies_count INTEGER;
  v_policies_approved INTEGER;
  v_controls_total INTEGER;
  v_controls_implemented INTEGER;
  v_backup_count INTEGER;
  v_rotation_count INTEGER;
  v_unique_roles TEXT[];
BEGIN
  SELECT COUNT(*), ARRAY_AGG(DISTINCT role::text)
  INTO v_roles_count, v_unique_roles
  FROM user_roles WHERE tenant_id = p_tenant_id;

  SELECT COUNT(*) INTO v_audit_count
  FROM audit_logs WHERE tenant_id = p_tenant_id AND created_at > NOW() - INTERVAL '30 days';

  SELECT COUNT(*), COUNT(*) FILTER (WHERE status IN ('active','online'))
  INTO v_agents_total, v_agents_active
  FROM agents WHERE tenant_id = p_tenant_id;

  SELECT COUNT(*) INTO v_detection_rules_count
  FROM detection_rules WHERE tenant_id = p_tenant_id OR tenant_id IS NULL;

  SELECT COUNT(*), COUNT(*) FILTER (WHERE is_active = true)
  INTO v_enrollment_total, v_enrollment_active
  FROM enrollment_keys WHERE tenant_id = p_tenant_id;

  SELECT COUNT(*), COUNT(*) FILTER (WHERE status = 'approved')
  INTO v_policies_count, v_policies_approved
  FROM compliance_policies WHERE tenant_id = p_tenant_id;

  SELECT COUNT(*), COUNT(*) FILTER (WHERE status IN ('implemented','verified'))
  INTO v_controls_total, v_controls_implemented
  FROM soc2_controls WHERE tenant_id = p_tenant_id;

  SELECT COUNT(*) INTO v_backup_count
  FROM backup_verifications WHERE tenant_id = p_tenant_id;

  SELECT COUNT(*) INTO v_rotation_count
  FROM secret_rotation_log WHERE tenant_id = p_tenant_id AND rotated_at > NOW() - INTERVAL '90 days';

  IF v_policies_count > 0 THEN
    INSERT INTO soc2_evidence (tenant_id, control_id, evidence_type, reference, description, metadata, status, valid_from)
    VALUES (p_tenant_id, 'CC1.1', 'policy', 'compliance_policies',
      v_policies_count || ' política(s) documentada(s)',
      jsonb_build_object('count', v_policies_count, 'approved', v_policies_approved), 'active', NOW());
    v_count := v_count + 1;
  END IF;

  IF v_detection_rules_count > 0 THEN
    INSERT INTO soc2_evidence (tenant_id, control_id, evidence_type, reference, description, metadata, status, valid_from)
    VALUES (p_tenant_id, 'CC1.2', 'config', 'detection_rules',
      v_detection_rules_count || ' regra(s) de detecção',
      jsonb_build_object('count', v_detection_rules_count), 'active', NOW());
    v_count := v_count + 1;
  END IF;

  IF v_roles_count > 0 THEN
    INSERT INTO soc2_evidence (tenant_id, control_id, evidence_type, reference, description, metadata, status, valid_from)
    VALUES (p_tenant_id, 'CC1.3', 'config', 'user_roles',
      'RBAC com ' || COALESCE(array_length(v_unique_roles, 1), 0) || ' papel(is)',
      jsonb_build_object('totalAssignments', v_roles_count, 'roles', to_jsonb(v_unique_roles)), 'active', NOW());
    v_count := v_count + 1;
  END IF;

  IF v_audit_count > 0 THEN
    INSERT INTO soc2_evidence (tenant_id, control_id, evidence_type, reference, description, metadata, status, valid_from)
    VALUES (p_tenant_id, 'CC1.5', 'log', 'audit_logs',
      v_audit_count || ' registros de auditoria (30d)',
      jsonb_build_object('count_30d', v_audit_count), 'active', NOW());
    v_count := v_count + 1;
  END IF;

  IF v_policies_approved > 0 THEN
    INSERT INTO soc2_evidence (tenant_id, control_id, evidence_type, reference, description, metadata, status, valid_from)
    VALUES (p_tenant_id, 'CC2.1', 'policy', 'compliance_policies',
      v_policies_approved || ' política(s) aprovada(s)',
      jsonb_build_object('approved', v_policies_approved, 'total', v_policies_count), 'active', NOW());
    v_count := v_count + 1;
  END IF;

  IF v_detection_rules_count > 0 THEN
    INSERT INTO soc2_evidence (tenant_id, control_id, evidence_type, reference, description, metadata, status, valid_from)
    VALUES (p_tenant_id, 'CC3.1', 'config', 'detection_rules',
      v_detection_rules_count || ' regra(s) de monitoramento',
      jsonb_build_object('count', v_detection_rules_count), 'active', NOW());
    v_count := v_count + 1;
  END IF;

  IF v_roles_count > 0 THEN
    INSERT INTO soc2_evidence (tenant_id, control_id, evidence_type, reference, description, metadata, status, valid_from)
    VALUES (p_tenant_id, 'CC6.1', 'config', 'user_roles + RLS',
      'RBAC (' || v_roles_count || ' atribuições) + RLS',
      jsonb_build_object('roleAssignments', v_roles_count), 'active', NOW());
    v_count := v_count + 1;
  END IF;

  IF v_agents_total > 0 THEN
    INSERT INTO soc2_evidence (tenant_id, control_id, evidence_type, reference, description, metadata, status, valid_from)
    VALUES (p_tenant_id, 'CC6.2', 'config', 'agents',
      v_agents_active || '/' || v_agents_total || ' agente(s) HMAC+JWT',
      jsonb_build_object('active', v_agents_active, 'total', v_agents_total), 'active', NOW());
    v_count := v_count + 1;
  END IF;

  IF v_enrollment_total > 0 THEN
    INSERT INTO soc2_evidence (tenant_id, control_id, evidence_type, reference, description, metadata, status, valid_from)
    VALUES (p_tenant_id, 'CC6.3', 'config', 'enrollment_keys',
      v_enrollment_active || '/' || v_enrollment_total || ' chave(s)',
      jsonb_build_object('active', v_enrollment_active, 'total', v_enrollment_total), 'active', NOW());
    v_count := v_count + 1;
  END IF;

  IF v_audit_count > 0 THEN
    INSERT INTO soc2_evidence (tenant_id, control_id, evidence_type, reference, description, metadata, status, valid_from)
    VALUES (p_tenant_id, 'CC7.1', 'log', 'audit_logs',
      'Monitoramento com ' || v_audit_count || ' logs (30d)',
      jsonb_build_object('count_30d', v_audit_count), 'active', NOW());
    v_count := v_count + 1;
  END IF;

  IF v_detection_rules_count > 0 OR v_agents_total > 0 THEN
    INSERT INTO soc2_evidence (tenant_id, control_id, evidence_type, reference, description, metadata, status, valid_from)
    VALUES (p_tenant_id, 'CC7.2', 'config', 'detection_rules + agents',
      v_detection_rules_count || ' regra(s) + ' || v_agents_total || ' agente(s)',
      jsonb_build_object('rules', v_detection_rules_count, 'agents', v_agents_total), 'active', NOW());
    v_count := v_count + 1;
  END IF;

  IF v_controls_total > 0 THEN
    INSERT INTO soc2_evidence (tenant_id, control_id, evidence_type, reference, description, metadata, status, valid_from)
    VALUES (p_tenant_id, 'CC8.1', 'config', 'soc2_controls',
      v_controls_implemented || '/' || v_controls_total || ' controles implementados',
      jsonb_build_object('implemented', v_controls_implemented, 'total', v_controls_total), 'active', NOW());
    v_count := v_count + 1;
  END IF;

  INSERT INTO soc2_evidence (tenant_id, control_id, evidence_type, reference, description, metadata, status, valid_from)
  VALUES (p_tenant_id, 'A1.2', 'log', 'backup_verifications + secret_rotation_log',
    v_backup_count || ' restore(s), ' || v_rotation_count || ' rotação(ões) (90d)',
    jsonb_build_object('backups', v_backup_count, 'rotations_90d', v_rotation_count), 'active', NOW());
  v_count := v_count + 1;

  RETURN v_count;
END;
$$;


--
-- Name: collect_task_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.collect_task_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_source_data jsonb;
BEGIN
  -- Apenas coleta snapshot em INSERT com source_id presente
  IF TG_OP = 'INSERT' AND NEW.source_id IS NOT NULL THEN
    
    CASE NEW.source_type
      WHEN 'job' THEN
        SELECT jsonb_build_object(
          'id', j.id,
          'type', j.type,
          'status', j.status,
          'priority', j.priority,
          'created_at', j.created_at,
          'completed_at', j.completed_at
        ) INTO v_source_data 
        FROM jobs j WHERE j.id = NEW.source_id;
        
      WHEN 'system_alert' THEN
        SELECT jsonb_build_object(
          'id', sa.id,
          'alert_type', sa.alert_type,
          'severity', sa.severity,
          'message', sa.message,
          'resolved', sa.resolved,
          'created_at', sa.created_at
        ) INTO v_source_data 
        FROM system_alerts sa WHERE sa.id = NEW.source_id;
        
      WHEN 'ai_insight' THEN
        SELECT jsonb_build_object(
          'id', i.id,
          'insight_type', i.insight_type,
          'severity', i.severity,
          'title', i.title,
          'status', i.status,
          'created_at', i.created_at
        ) INTO v_source_data 
        FROM ai_insights i WHERE i.id = NEW.source_id;
        
      WHEN 'dlq' THEN
        -- DLQ table may not exist - store minimal metadata
        v_source_data := jsonb_build_object(
          'source_type', 'dlq',
          'source_id', NEW.source_id,
          'note', 'DLQ source - table not available'
        );
        
      ELSE
        v_source_data := NULL;
    END CASE;
    
    -- Armazena snapshot em closure_evidence
    IF v_source_data IS NOT NULL THEN
      NEW.closure_evidence := COALESCE(NEW.closure_evidence, '{}'::jsonb) || 
                             jsonb_build_object('source_snapshot', v_source_data);
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION collect_task_evidence(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.collect_task_evidence() IS 'Trigger function to collect source evidence on task creation. Handles job, system_alert, ai_insight, and dlq source types. DLQ handled gracefully if table does not exist.';


--
-- Name: collect_task_evidence(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.collect_task_evidence(p_agent_id uuid, p_task_type text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_evidence jsonb := '{}'::jsonb;
  v_related_alerts jsonb;
  v_related_insights jsonb;
  v_agent_metrics jsonb;
BEGIN
  -- Coletar alertas relacionados
  SELECT jsonb_agg(jsonb_build_object(
    'id', a.id,
    'alert_type', a.alert_type,
    'severity', a.severity,
    'message', a.message,
    'resolved', a.resolved,
    'created_at', a.created_at
  ))
  INTO v_related_alerts
  FROM system_alerts a
  WHERE a.agent_id = p_agent_id
    AND a.created_at > NOW() - INTERVAL '24 hours'
  LIMIT 10;

  -- Coletar insights relacionados
  SELECT jsonb_agg(jsonb_build_object(
    'id', i.id,
    'insight_type', i.insight_type,
    'severity', i.severity,
    'title', i.title,
    'acknowledged', i.acknowledged,
    'created_at', i.created_at
  ))
  INTO v_related_insights
  FROM ai_insights i
  WHERE i.agent_id = p_agent_id
    AND i.created_at > NOW() - INTERVAL '24 hours'
  LIMIT 10;

  -- Coletar métricas recentes do agente
  SELECT jsonb_build_object(
    'cpu_usage_percent', m.cpu_usage_percent,
    'memory_usage_percent', m.memory_usage_percent,
    'disk_usage_percent', m.disk_usage_percent,
    'collected_at', m.collected_at
  )
  INTO v_agent_metrics
  FROM agent_system_metrics m
  WHERE m.agent_id = p_agent_id
  ORDER BY m.collected_at DESC
  LIMIT 1;

  -- Montar evidência completa
  v_evidence := jsonb_build_object(
    'task_type', p_task_type,
    'agent_id', p_agent_id,
    'collected_at', NOW(),
    'related_alerts', COALESCE(v_related_alerts, '[]'::jsonb),
    'related_insights', COALESCE(v_related_insights, '[]'::jsonb),
    'agent_metrics', COALESCE(v_agent_metrics, '{}'::jsonb)
  );

  RETURN v_evidence;
END;
$$;


--
-- Name: collect_weekly_governance_metrics(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.collect_weekly_governance_metrics(tenant_uuid uuid, week_start date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  start_date date := COALESCE(week_start, date_trunc('week', now())::date);
  end_date date := start_date + interval '7 days';
  result jsonb;
  tasks_opened integer;
  tasks_resolved integer;
  tasks_ignored integer;
  tasks_risk_accepted integer;
  sla_breached integer;
  human_decisions integer;
  avg_resolution_hours numeric;
  critical_open integer;
BEGIN
  SELECT count(*) INTO tasks_opened
  FROM public.tasks WHERE tenant_id = tenant_uuid
    AND created_at >= start_date AND created_at < end_date;
  
  SELECT count(*) INTO tasks_resolved
  FROM public.tasks WHERE tenant_id = tenant_uuid
    AND status = 'resolved'
    AND closed_at >= start_date AND closed_at < end_date;
  
  SELECT count(*) INTO tasks_ignored
  FROM public.tasks WHERE tenant_id = tenant_uuid
    AND status = 'ignored'
    AND closed_at >= start_date AND closed_at < end_date;
  
  SELECT count(*) INTO tasks_risk_accepted
  FROM public.tasks WHERE tenant_id = tenant_uuid
    AND status = 'accepted_risk'
    AND risk_accepted_at >= start_date AND risk_accepted_at < end_date;
  
  SELECT count(*) INTO sla_breached
  FROM public.tasks WHERE tenant_id = tenant_uuid
    AND sla_breached_at >= start_date AND sla_breached_at < end_date;
  
  SELECT count(*) INTO human_decisions
  FROM public.task_events WHERE tenant_id = tenant_uuid
    AND actor_type = 'user'
    AND event_at >= start_date AND event_at < end_date;
  
  SELECT AVG(EXTRACT(EPOCH FROM (closed_at - created_at))/3600)::numeric INTO avg_resolution_hours
  FROM public.tasks WHERE tenant_id = tenant_uuid
    AND status = 'resolved'
    AND closed_at >= start_date AND closed_at < end_date;
  
  SELECT count(*) INTO critical_open
  FROM public.tasks WHERE tenant_id = tenant_uuid
    AND severity = 'critical'
    AND status IN ('open', 'in_progress');
  
  result := jsonb_build_object(
    'period_start', start_date,
    'period_end', end_date,
    'tasks_opened', tasks_opened,
    'tasks_resolved', tasks_resolved,
    'tasks_ignored', tasks_ignored,
    'tasks_risk_accepted', tasks_risk_accepted,
    'sla_breached', sla_breached,
    'human_decisions', human_decisions,
    'avg_resolution_hours', ROUND(COALESCE(avg_resolution_hours, 0), 2),
    'critical_open', critical_open,
    'net_tasks', tasks_opened - tasks_resolved - tasks_ignored
  );
  
  RETURN result;
END;
$$;


--
-- Name: count_policies_for_table(text); Type: FUNCTION; Schema: public; Owner: -
