--
-- Name: create_approval_request(text, jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_approval_request(p_action_type text, p_action_payload jsonb, p_target_agent_id uuid DEFAULT NULL::uuid, p_playbook_execution_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_tenant_id UUID;
  v_chain RECORD;
  v_request_id UUID;
  v_timeout_hours INTEGER := 24;
  v_min_approvers INTEGER := 2;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
  END IF;
  
  -- Buscar tenant do usuário
  SELECT tenant_id INTO v_tenant_id FROM user_roles 
  WHERE user_id = v_user_id AND role IN ('admin', 'super_admin', 'operator')
  LIMIT 1;
  
  IF v_tenant_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Forbidden');
  END IF;
  
  -- Buscar chain aplicável
  SELECT * INTO v_chain FROM approval_chains 
  WHERE tenant_id = v_tenant_id 
    AND is_active = true 
    AND p_action_type = ANY(applies_to_actions)
  ORDER BY min_approvers DESC
  LIMIT 1;
  
  IF v_chain IS NOT NULL THEN
    v_timeout_hours := v_chain.timeout_hours;
    v_min_approvers := v_chain.min_approvers;
  END IF;
  
  -- Criar request
  INSERT INTO approval_requests (
    tenant_id, chain_id, playbook_execution_id, action_type, action_payload,
    target_agent_id, requested_by, required_approvers, expires_at
  ) VALUES (
    v_tenant_id, v_chain.id, p_playbook_execution_id, p_action_type, p_action_payload,
    p_target_agent_id, v_user_id, v_min_approvers, NOW() + (v_timeout_hours || ' hours')::interval
  )
  RETURNING id INTO v_request_id;
  
  -- Log
  INSERT INTO risk_decision_log (tenant_id, decision_type, trigger_source, trigger_id, decision, reasoning, metadata)
  VALUES (v_tenant_id, 'approval_requested', 'two_man_rule', v_request_id::text, 'pending',
          'Approval request created for ' || p_action_type,
          jsonb_build_object('requested_by', v_user_id, 'action_type', p_action_type, 'required_approvers', v_min_approvers));
  
  RETURN jsonb_build_object(
    'success', true, 
    'request_id', v_request_id,
    'required_approvers', v_min_approvers,
    'expires_at', NOW() + (v_timeout_hours || ' hours')::interval
  );
END;
$$;


--
-- Name: create_decision_event_from_ai_action(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_decision_event_from_ai_action() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_insight_record RECORD;
  v_agent_name TEXT;
BEGIN
  -- Buscar informações do insight associado
  SELECT 
    agent_id,
    insight_type
  INTO v_insight_record
  FROM ai_insights
  WHERE id = NEW.insight_id;

  -- Buscar agent_name da tabela agents
  SELECT name INTO v_agent_name
  FROM agents
  WHERE id = v_insight_record.agent_id;

  INSERT INTO decision_events (
    tenant_id,
    rule_code,
    agent_id,
    agent_name,
    action,
    evidence,
    actions_executed,
    decision_source,
    decision_type,
    created_at
  ) VALUES (
    NEW.tenant_id,
    COALESCE(v_insight_record.insight_type, 'AI_ACTION'),
    v_insight_record.agent_id,
    COALESCE(v_agent_name, 'unknown'),
    NEW.action_type,
    jsonb_build_object(
      'ai_action_id', NEW.id,
      'insight_id', NEW.insight_id,
      'status', NEW.status,
      'risk', NEW.risk_level,
      'human_reviewed', COALESCE(NEW.human_reviewed, false),
      'ai_validation', NEW.ai_validation_status
    ),
    jsonb_build_array(
      jsonb_build_object(
        'type', NEW.action_type,
        'success', NEW.status = 'executed'
      )
    ),
    CASE WHEN COALESCE(NEW.human_reviewed, false) THEN 'human' ELSE 'ai' END,
    CASE NEW.status 
      WHEN 'executed' THEN 'approval' 
      WHEN 'failed' THEN 'rejection' 
      ELSE 'system' 
    END,
    NOW()
  );
  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'create_decision_event_from_ai_action failed: %', SQLERRM;
    RETURN NEW;
END;
$$;


--
-- Name: create_decision_event_from_alert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_decision_event_from_alert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Só criar evento se o alerta foi resolvido
  IF NEW.resolved = true AND (OLD.resolved = false OR OLD.resolved IS NULL) THEN
    INSERT INTO decision_events (
      tenant_id,
      decision_type,
      decision_source,
      actor_type,
      actor_id,
      rule_code,
      action,
      evidence,
      justification,
      human_reviewed,
      created_at
    ) VALUES (
      NEW.tenant_id,
      'alert_resolution',
      CASE 
        WHEN NEW.resolved_by IS NOT NULL THEN 'human'
        ELSE 'system'
      END,
      CASE 
        WHEN NEW.resolved_by IS NOT NULL THEN 'user'
        ELSE 'system'
      END,
      COALESCE(NEW.resolved_by, '00000000-0000-0000-0000-000000000000'),
      'ALERT_RESOLVED',
      'resolve_alert',
      jsonb_build_object(
        'alert_id', NEW.id,
        'alert_type', NEW.alert_type,
        'severity', NEW.severity,
        'message', NEW.message,
        'resolved_at', NEW.resolved_at,
        'trigger_source', 'database_trigger'
      ),
      COALESCE(NEW.resolution_notes, 'Alert resolved'),
      NEW.resolved_by IS NOT NULL,
      COALESCE(NEW.resolved_at, now())
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: create_decision_event_from_playbook(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_decision_event_from_playbook() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
