--
-- Name: create_default_subscription(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_default_subscription() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  free_plan_id UUID;
BEGIN
  -- Buscar plano free
  SELECT id INTO free_plan_id
  FROM public.subscription_plans
  WHERE name = 'free'
  LIMIT 1;

  -- Se não existe plano free, não fazer nada (fail silently, handle_new_user cuidará)
  IF free_plan_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- INSERT com ON CONFLICT DO NOTHING (dupla proteção)
  INSERT INTO public.tenant_subscriptions (tenant_id, plan_id)
  VALUES (NEW.id, free_plan_id)
  ON CONFLICT (tenant_id) DO NOTHING;

  RETURN NEW;
END;
$$;


