-- Name: FUNCTION create_default_subscription(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_default_subscription() IS 'ADR-024: Trigger hardened com ON CONFLICT DO NOTHING. 
Cria subscription básica; handle_new_user faz UPSERT para trial de 14 dias.';


--
-- Name: create_dlq_decision_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_dlq_decision_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant_id uuid;
  v_decision_source text;
  v_event_id uuid;
BEGIN
  -- Só processa quando status muda para 'resolved' ou 'failed'
  IF (TG_OP = 'UPDATE' AND NEW.status IN ('resolved', 'failed') AND OLD.status = 'pending') THEN
    v_tenant_id := NEW.tenant_id;
    
    -- Mapear resolution_source para decision_source válido
    v_decision_source := CASE 
      WHEN NEW.resolution_source = 'auto_cleanup' THEN 'system'
      WHEN NEW.resolution_source = 'human' THEN 'human'
      WHEN NEW.resolution_source = 'ai' THEN 'ai'
      WHEN NEW.resolution_source = 'policy' THEN 'policy'
      WHEN NEW.resolution_source = 'resilience_engine' THEN 'resilience_engine'
      WHEN NEW.resolved_by IS NOT NULL THEN 'human'
      ELSE 'system'
    END;
    
    -- V-610 FIX: Usar RETURNING para capturar o ID gerado
    INSERT INTO public.decision_events (
      tenant_id, 
      rule_code, 
      action, 
      evidence, 
      decision_source, 
      decision_type
    ) VALUES (
      v_tenant_id,
      'DLQ_RESOLUTION',
      'resolve_dlq_item',
      jsonb_build_object(
        'dlq_item_id', NEW.id,
        'original_job_id', NEW.original_job_id,
        'job_type', NEW.job_type,
        'error_message', NEW.error_message,
        'resolution_notes', NEW.resolution_notes,
        'resolution_source_original', NEW.resolution_source,
        'resolved_by', NEW.resolved_by
      ),
      v_decision_source,
      'system'
    ) RETURNING id INTO v_event_id;
    
    -- V-610 FIX: Atribuir o ID ao registro DLQ
    NEW.decision_event_id := v_event_id;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION create_dlq_decision_event(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_dlq_decision_event() IS 'ADR-026/V-603/V-610: Trigger com search_path fixo e RETURNING para atribuir decision_event_id.';


--
-- Name: create_job_if_not_exists(uuid, uuid, text, jsonb, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_job_if_not_exists(p_agent_id uuid, p_tenant_id uuid, p_type text, p_payload jsonb DEFAULT '{}'::jsonb, p_priority integer DEFAULT 5, p_ttl_hours integer DEFAULT 4) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing_id uuid;
  v_new_id uuid;
  v_agent_name text;
  v_agent_status text;
  v_scheduling_paused boolean;
  v_last_heartbeat timestamptz;
  v_minutes_since_heartbeat integer;
  v_effective_ttl_hours integer;
  v_is_recovery_job boolean;
BEGIN
  -- Determine if this is a recovery job (always allowed)
  v_is_recovery_job := p_type IN ('update_agent', 'reinstall_agent');

  -- Check if an active job of the same type already exists for this agent
  SELECT id INTO v_existing_id
  FROM jobs
  WHERE agent_id = p_agent_id
    AND type = p_type
    AND status IN ('pending', 'queued', 'delivered')
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RETURN NULL;
  END IF;

  -- Lookup agent info
  SELECT agent_name, status, scheduling_paused, last_heartbeat
  INTO v_agent_name, v_agent_status, v_scheduling_paused, v_last_heartbeat
  FROM agents
  WHERE id = p_agent_id;

  IF v_agent_name IS NULL THEN
    RETURN NULL; -- Agent not found
  END IF;

  -- Block scheduling if paused (except recovery jobs)
  IF v_scheduling_paused = true AND NOT v_is_recovery_job THEN
    RETURN NULL;
  END IF;

  -- Block if agent is inactive/archived (except recovery jobs)
  IF v_agent_status IN ('inactive', 'archived', 'deleted') AND NOT v_is_recovery_job THEN
    RETURN NULL;
  END IF;

  -- V-OFFLINE: Block agents with no heartbeat or offline > 2h (except recovery jobs)
  IF NOT v_is_recovery_job THEN
    IF v_last_heartbeat IS NULL THEN
      RETURN NULL; -- Never seen online
    END IF;
    
    v_minutes_since_heartbeat := EXTRACT(EPOCH FROM (now() - v_last_heartbeat))::integer / 60;
    
    IF v_minutes_since_heartbeat > 120 THEN
      RETURN NULL; -- Offline > 2 hours
    END IF;
  END IF;

  -- Adaptive TTL based on heartbeat recency
  v_effective_ttl_hours := p_ttl_hours;
  
  IF v_last_heartbeat IS NOT NULL THEN
    v_minutes_since_heartbeat := COALESCE(v_minutes_since_heartbeat, 
      EXTRACT(EPOCH FROM (now() - v_last_heartbeat))::integer / 60);
    
    -- Agent heartbeat > 30min: reduce TTL to 2h
    IF v_minutes_since_heartbeat > 30 AND v_effective_ttl_hours > 2 THEN
      v_effective_ttl_hours := 2;
    END IF;
  END IF;

  -- Safe to insert
  INSERT INTO jobs (
    agent_id, tenant_id, type, payload, priority,
    status, approved, expires_at, created_at, agent_name
  ) VALUES (
    p_agent_id, p_tenant_id, p_type, p_payload, p_priority,
    'pending', true, now() + (v_effective_ttl_hours || ' hours')::interval, now(), v_agent_name
  )
  RETURNING id INTO v_new_id;

  RETURN v_new_id;
EXCEPTION WHEN unique_violation THEN
  RETURN NULL;
END;
$$;


--
-- Name: create_job_if_not_exists(uuid, text, uuid, integer, jsonb, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_job_if_not_exists(p_agent_id uuid, p_job_type text, p_tenant_id uuid, p_priority integer DEFAULT 5, p_payload jsonb DEFAULT '{}'::jsonb, p_max_retries integer DEFAULT 3, p_timeout_seconds integer DEFAULT 300, p_idempotency_key text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing_id uuid;
  v_new_id uuid;
  v_agent_name text;
  v_agent_status text;
  v_scheduling_paused boolean;
  v_last_heartbeat timestamptz;
  v_minutes_since_heartbeat integer;
  v_effective_timeout integer;
  v_caller_tenant uuid;
BEGIN
  -- PSIA: tenant guard
  v_caller_tenant := get_active_tenant_id();
  IF v_caller_tenant IS NOT NULL AND p_tenant_id != v_caller_tenant AND NOT is_current_super_admin() THEN
    INSERT INTO security_logs (tenant_id, event_type, severity, details)
    VALUES (v_caller_tenant, 'cross_tenant_blocked', 'critical',
      jsonb_build_object('function', 'create_job_if_not_exists', 'target_tenant', p_tenant_id));
    RAISE EXCEPTION 'TENANT_MISMATCH';
  END IF;

  -- Verify agent belongs to tenant
  SELECT agent_name, status, scheduling_paused, last_heartbeat 
  INTO v_agent_name, v_agent_status, v_scheduling_paused, v_last_heartbeat
  FROM agents WHERE id = p_agent_id AND tenant_id = p_tenant_id;
  
  IF v_agent_name IS NULL THEN
    RAISE EXCEPTION 'AGENT_NOT_FOUND_OR_TENANT_MISMATCH';
  END IF;
  
  IF v_scheduling_paused THEN RETURN NULL; END IF;
  IF v_agent_status NOT IN ('online', 'idle', 'warning') THEN RETURN NULL; END IF;
  
  v_minutes_since_heartbeat := EXTRACT(EPOCH FROM (now() - v_last_heartbeat)) / 60;
  IF v_minutes_since_heartbeat > 30 THEN RETURN NULL; END IF;
  
  -- Check existing
  SELECT id INTO v_existing_id FROM jobs
  WHERE agent_id = p_agent_id AND job_type = p_job_type AND tenant_id = p_tenant_id
    AND status IN ('pending', 'queued', 'assigned', 'delivered', 'in_progress')
  LIMIT 1;
  
  IF v_existing_id IS NOT NULL THEN RETURN v_existing_id; END IF;
  
  v_effective_timeout := LEAST(p_timeout_seconds, 600);
  
  INSERT INTO jobs (agent_id, job_type, tenant_id, priority, payload, max_retries, timeout_seconds, status, created_at)
  VALUES (p_agent_id, p_job_type, p_tenant_id, p_priority, p_payload, p_max_retries, v_effective_timeout, 'pending', now())
  RETURNING id INTO v_new_id;
  
  RETURN v_new_id;
END;
$$;


--
-- Name: create_jobs_for_all_agents(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_jobs_for_all_agents(p_tenant_id uuid, p_job_type text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count integer := 0;
  v_agent RECORD;
  v_new_id uuid;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  IF p_tenant_id IS NULL THEN
    RAISE EXCEPTION 'tenant_id is required';
  END IF;
  
  FOR v_agent IN
    SELECT id, agent_name 
    FROM agents 
    WHERE tenant_id = p_tenant_id 
      AND archived_at IS NULL
      AND status = 'active'
      AND last_heartbeat > NOW() - INTERVAL '5 minutes'
  LOOP
    -- Use dedup guard instead of raw INSERT
    SELECT create_job_if_not_exists(
      v_agent.id, p_tenant_id, p_job_type, p_payload, 5, 1
    ) INTO v_new_id;
    
    IF v_new_id IS NOT NULL THEN
      v_count := v_count + 1;
    END IF;
  END LOOP;
  
  RETURN v_count;
END;
$$;


--
-- Name: create_metrics_partition_if_needed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_metrics_partition_if_needed() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  partition_name TEXT;
  start_date DATE;
  end_date DATE;
  -- OTIMIZAÇÃO: Apenas mês atual (0) + próximo mês (1)
  -- Evita criação prematura de partições vazias
  check_months INTEGER[] := ARRAY[0, 1];
  m INTEGER;
BEGIN
  FOREACH m IN ARRAY check_months LOOP
    start_date := date_trunc('month', CURRENT_DATE + (m || ' months')::INTERVAL)::DATE;
    end_date := (start_date + INTERVAL '1 month')::DATE;
    partition_name := 'agent_system_metrics_' || to_char(start_date, 'YYYY_MM');
    
    -- Verificar se partição existe
    IF NOT EXISTS (
      SELECT 1 FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE c.relname = partition_name AND n.nspname = 'public'
    ) THEN
      BEGIN
        EXECUTE format(
          'CREATE TABLE IF NOT EXISTS public.%I PARTITION OF public.agent_system_metrics_partitioned FOR VALUES FROM (%L) TO (%L)',
          partition_name, start_date, end_date
        );
        RAISE NOTICE 'Partição criada: %', partition_name;
      EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Erro ao criar partição %: %', partition_name, SQLERRM;
      END;
    END IF;
  END LOOP;
END;
$$;


--
-- Name: FUNCTION create_metrics_partition_if_needed(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_metrics_partition_if_needed() IS 'Cria particoes futuras automaticamente. Execute periodicamente via cron ou Edge Function.';


--
-- Name: create_monthly_partitions(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_monthly_partitions(p_table_name text, p_partition_column text, p_months_ahead integer DEFAULT 3) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_start DATE;
  v_end DATE;
  v_partition_name TEXT;
  v_created INTEGER := 0;
BEGIN
  FOR i IN 0..p_months_ahead LOOP
    v_start := date_trunc('month', now()) + (i || ' months')::interval;
    v_end := v_start + '1 month'::interval;
    v_partition_name := p_table_name || '_' || to_char(v_start, 'YYYY_MM');
    
    -- Check if partition already exists
    IF NOT EXISTS (
      SELECT 1 FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public' AND c.relname = v_partition_name
    ) THEN
      EXECUTE format(
        'CREATE TABLE public.%I PARTITION OF public.%I FOR VALUES FROM (%L) TO (%L)',
        v_partition_name, p_table_name, v_start, v_end
      );
      v_created := v_created + 1;
    END IF;
  END LOOP;
  
  RETURN v_created;
END;
$$;


--
-- Name: create_recurring_jobs_for_agent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_recurring_jobs_for_agent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  job_types TEXT[] := ARRAY['software_inventory_collect', 'light_vuln_scan', 'collect_antivirus_status', 'collect_web_activity'];
  job_type TEXT;
BEGIN
  -- Create 4 recurring jobs for the new agent
  FOREACH job_type IN ARRAY job_types
  LOOP
    INSERT INTO public.jobs (
      agent_name,
      agent_id,
      tenant_id,
      type,
      status,
      approved,
      is_recurring,
      recurrence_pattern,
      next_run_at,
      payload
    ) VALUES (
      NEW.agent_name,
      NEW.id,
      NEW.tenant_id,
      job_type,
      'queued',
      true,
      true,
      'daily',
      (CURRENT_DATE + INTERVAL '1 day' + INTERVAL '19 hours')::timestamptz, -- 16h Brasília = 19h UTC
      jsonb_build_object('auto_created', true, 'created_for_agent', NEW.agent_name)
    );
  END LOOP;
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION create_recurring_jobs_for_agent(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_recurring_jobs_for_agent() IS 'Automatically creates 4 recurring security jobs (software inventory, vulnerability scan, antivirus status, web activity) when a new agent is enrolled';


--
-- Name: create_retroactive_execution(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_retroactive_execution(p_job_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_execution_id UUID;
  v_job RECORD;
BEGIN
  -- SSA-SEC: Only service_role can create retroactive executions
  PERFORM _assert_service_role_or_super_admin();
  
  IF EXISTS (SELECT 1 FROM job_executions WHERE job_id = p_job_id) THEN
    RAISE NOTICE 'Job % already has execution - skipping', p_job_id;
    RETURN NULL;
  END IF;
  
  SELECT * INTO v_job FROM jobs WHERE id = p_job_id AND status IN ('done', 'completed', 'failed');
  
  IF NOT FOUND THEN
    RAISE NOTICE 'Job % not found or not completed', p_job_id;
    RETURN NULL;
  END IF;
  
  INSERT INTO job_executions (
    job_id, agent_id, tenant_id, agent_name, agent_version, payload_hash,
    status, legacy, claimed_at, started_at, finished_at, error_message
  ) VALUES (
    v_job.id, v_job.agent_id, v_job.tenant_id,
    COALESCE(v_job.agent_name, 'legacy-agent'), 'pre-execution-model',
    COALESCE(v_job.payload_hash, 'legacy-no-hash'),
    CASE v_job.status WHEN 'done' THEN 'completed' ELSE v_job.status END,
    true, v_job.created_at,
    COALESCE(v_job.started_at, v_job.delivered_at, v_job.created_at),
    COALESCE(v_job.finished_at, v_job.completed_at)
  )
  RETURNING id INTO v_execution_id;
  
  RETURN v_execution_id;
END;
$$;


--
-- Name: FUNCTION create_retroactive_execution(p_job_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_retroactive_execution(p_job_id uuid) IS 'Cria uma execution retroativa para jobs v1 que não têm trilha de auditoria.
Usado para migração histórica, relatórios e auditoria.
NUNCA usar no fluxo normal de jobs - apenas para compatibilidade.';


--
-- Name: create_security_event_from_alert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_security_event_from_alert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.severity = 'critical' AND NOT NEW.resolved THEN
    INSERT INTO security_events (tenant_id, agent_id, severity, title, description, status, data)
    VALUES (
      NEW.tenant_id,
      NEW.agent_id,
      'high',
      NEW.alert_type,
      NEW.message,
      'open',
      jsonb_build_object(
        'source', 'system_alerts',
        'alert_id', NEW.id,
        'alert_type', NEW.alert_type
      )
    );
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: create_task_from_critical_insight(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_task_from_critical_insight() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  sla_hours int;
BEGIN
  -- Only create task for critical/high severity unacknowledged insights
  IF NEW.severity IN ('critical', 'high') AND NEW.acknowledged = false THEN
    -- Set SLA based on severity
    sla_hours := CASE NEW.severity WHEN 'critical' THEN 4 ELSE 24 END;
    
    INSERT INTO tasks (
      tenant_id, 
      source_type, 
      source_id, 
      title, 
      description, 
      severity, 
      requires_human_review,
      due_at
    )
    VALUES (
      NEW.tenant_id,
      'ai_insight',
      NEW.id,
      COALESCE(NEW.title, 'AI Insight: ' || NEW.insight_type),
      NEW.description,
      NEW.severity,
      NEW.severity = 'critical',
      now() + (sla_hours || ' hours')::interval
    )
    ON CONFLICT (source_type, source_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: create_task_from_dlq_item(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_task_from_dlq_item() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Criar task para TODA falha não-transient (CORRIGIDO)
  IF COALESCE(NEW.failure_class, 'UNKNOWN') NOT IN ('TRANSIENT', 'EXPECTED_DROP') THEN
    INSERT INTO public.tasks (
      tenant_id, source_type, source_id, title, description, severity, 
      status, requires_human_review, auto_generated, due_at, created_at, updated_at
    )
    VALUES (
      NEW.tenant_id,
      'dlq',
      NEW.id,
      '[DLQ] ' || COALESCE(NEW.job_type, 'unknown') || ': ' || COALESCE(NEW.failure_class, 'UNKNOWN'),
      'Item na Dead Letter Queue requer revisão.' ||
      E'\n\nClasse de Falha: ' || COALESCE(NEW.failure_class, 'UNKNOWN') ||
      E'\nErro: ' || COALESCE(NEW.error_message, 'Sem mensagem') ||
      E'\nAgente: ' || COALESCE(NEW.agent_name, 'N/A') ||
      E'\nRetry Count: ' || COALESCE(NEW.retry_count, 0)::text,
      CASE NEW.failure_class
        WHEN 'BUG' THEN 'critical'
        WHEN 'CASCADE_FAILURE' THEN 'high'
        WHEN 'AGENT_STALLED' THEN 'medium'
        WHEN 'AGENT_OFFLINE' THEN 'medium'
        WHEN 'DISPATCH_FAILURE' THEN 'medium'
        ELSE 'low'
      END,
      'open',
      NEW.failure_class IN ('BUG', 'CASCADE_FAILURE'),
      true,
      NOW() + CASE 
        WHEN NEW.failure_class = 'BUG' THEN interval '4 hours'
        WHEN NEW.failure_class = 'CASCADE_FAILURE' THEN interval '24 hours'
        WHEN NEW.failure_class IN ('AGENT_STALLED', 'AGENT_OFFLINE') THEN interval '48 hours'
        ELSE interval '72 hours'
      END,
      NOW(),
      NOW()
    )
    ON CONFLICT (source_type, source_id) WHERE source_type IS NOT NULL AND source_id IS NOT NULL
    DO UPDATE SET 
      updated_at = NOW(),
      description = EXCLUDED.description;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION create_task_from_dlq_item(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_task_from_dlq_item() IS 'AUDIT 2026-01-10: Corrigido para criar task para TODA falha não-transient. Antes só criava para flagged_suspicious=true OU retry_count>=3.';


--
-- Name: create_task_from_failed_job(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_task_from_failed_job() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  sla_hours int;
  severity_level text;
  task_title text;
BEGIN
  -- Só atuar quando job transita PARA failed
  IF OLD.status IS DISTINCT FROM 'failed' AND NEW.status = 'failed' THEN
    
    -- Mapear failure_class para severity
    severity_level := CASE NEW.failure_class
      WHEN 'BUG' THEN 'critical'
      WHEN 'AGENT_STALLED' THEN 'high'
      WHEN 'AGENT_OFFLINE' THEN 'medium'
      WHEN 'CASCADE_FAILURE' THEN 'high'
      WHEN 'TIMEOUT' THEN 'medium'
      ELSE 'low'
    END;
    
    -- SLA baseado em severity
    sla_hours := CASE severity_level
      WHEN 'critical' THEN 4
      WHEN 'high' THEN 24
      WHEN 'medium' THEN 48
      ELSE 72
    END;
    
    -- Título descritivo
    task_title := '[Job Falho] ' || COALESCE(NEW.type, 'unknown') || ': ' || COALESCE(NEW.failure_class, 'UNKNOWN');
    
    -- Criar task apenas para falhas não-esperadas
    IF COALESCE(NEW.failure_class, '') NOT IN ('EXPECTED_DROP', 'TRANSIENT') THEN
      INSERT INTO public.tasks (
        tenant_id, 
        source_type, 
        source_id, 
        title, 
        description, 
        severity, 
        status, 
        requires_human_review, 
        auto_generated, 
        due_at,
        created_at,
        updated_at
      )
      VALUES (
        NEW.tenant_id,
        'job',
        NEW.id,  -- Já é UUID, não precisa de cast
        task_title,
        'Job falhou: ' || COALESCE(NEW.error_message, 'Sem mensagem de erro') || 
        E'\n\nAgente: ' || COALESCE(NEW.agent_name, 'N/A') ||
        E'\nTipo: ' || COALESCE(NEW.type, 'N/A') ||
        E'\nClasse de Falha: ' || COALESCE(NEW.failure_class, 'N/A'),
        severity_level,
        'open',
        NEW.failure_class IN ('BUG', 'CASCADE_FAILURE'),
        true,
        NOW() + (sla_hours || ' hours')::interval,
        NOW(),
        NOW()
      )
      ON CONFLICT (source_type, source_id) WHERE source_type IS NOT NULL AND source_id IS NOT NULL
      DO UPDATE SET
        updated_at = NOW(),
        description = EXCLUDED.description;
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION create_task_from_failed_job(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_task_from_failed_job() IS 'ADR-031: Cria task automaticamente quando job falha';


--
-- Name: create_task_from_system_alert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_task_from_system_alert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  sla_hours int;
BEGIN
  IF NEW.severity IN ('critical', 'high') AND NEW.resolved = false THEN
    sla_hours := CASE NEW.severity WHEN 'critical' THEN 4 ELSE 24 END;
    
    INSERT INTO tasks (
      tenant_id, 
      source_type, 
      source_id, 
      title, 
      description, 
      severity, 
      requires_human_review,
      due_at
    )
    VALUES (
      NEW.tenant_id,
      'system_alert',
      NEW.id,
      NEW.title,
      NEW.message,
      NEW.severity,
      COALESCE(NEW.requires_human_decision, false),
      now() + (sla_hours || ' hours')::interval
    )
    ON CONFLICT (source_type, source_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: create_telemetry_partitions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_telemetry_partitions() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_month date;
  v_next date;
  v_suffix text;
  v_part_name text;
  v_tables text[] := ARRAY[
    'endpoint_event_buffer_partitioned',
    'endpoint_process_events_partitioned', 
    'endpoint_network_events_partitioned'
  ];
  v_table text;
  v_part_col text;
BEGIN
  -- Create partitions for the next 3 months
  FOR i IN 0..2 LOOP
    v_month := date_trunc('month', NOW() + (i || ' months')::interval)::date;
    v_next := (v_month + interval '1 month')::date;
    v_suffix := to_char(v_month, 'YYYY_MM');
    
    FOREACH v_table IN ARRAY v_tables LOOP
      v_part_name := v_table || '_' || v_suffix;
      
      -- Skip if partition already exists
      IF NOT EXISTS (SELECT 1 FROM pg_class WHERE relname = v_part_name AND relnamespace = 'public'::regnamespace) THEN
        -- Determine partition column
        IF v_table = 'endpoint_event_buffer_partitioned' THEN
          v_part_col := 'received_at';
        ELSE
          v_part_col := 'created_at';
        END IF;
        
        EXECUTE format(
          'CREATE TABLE public.%I PARTITION OF public.%I FOR VALUES FROM (%L) TO (%L)',
          v_part_name, v_table, v_month, v_next
        );
        
        -- Enable RLS
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', v_part_name);
        
        -- Add RLS policies
        EXECUTE format(
          'CREATE POLICY "authenticated_select_tenant" ON public.%I FOR SELECT TO authenticated USING (tenant_id::text = (get_active_tenant_id())::text)',
          v_part_name
        );
        EXECUTE format(
          'CREATE POLICY "service_role_full_access" ON public.%I TO service_role USING (true) WITH CHECK (true)',
          v_part_name
        );
        
        RAISE NOTICE 'Created partition: %', v_part_name;
      END IF;
    END LOOP;
  END LOOP;
END;
$$;


