--
-- Name: deduplicate_system_alert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deduplicate_system_alert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  existing_id uuid;
BEGIN
  SELECT id INTO existing_id 
  FROM system_alerts 
  WHERE tenant_id = NEW.tenant_id 
    AND title = NEW.title 
    AND alert_type = NEW.alert_type 
    AND resolved = false
  LIMIT 1;
  
  IF existing_id IS NOT NULL THEN
    UPDATE system_alerts 
    SET details = NEW.details,
        message = NEW.message
    WHERE id = existing_id;
    RETURN NULL;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: derive_agent_state_if_null(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.derive_agent_state_if_null() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.agent_state IS NULL THEN
    NEW.agent_state := CASE 
      WHEN NEW.archived_at IS NOT NULL THEN 'archived'
      WHEN NEW.last_heartbeat IS NULL THEN 'pending'
      WHEN NEW.last_heartbeat < NOW() - INTERVAL '5 minutes' THEN 'offline'
      ELSE 'healthy'
    END;
    NEW.agent_state_reason := 'Auto-derived by system trigger';
    NEW.agent_state_changed_at := NOW();
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: derive_agent_state_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.derive_agent_state_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  old_state text;
  new_state text;
  minutes_since_heartbeat numeric;
BEGIN
  old_state := OLD.agent_state;
  
  -- Calculate minutes since last heartbeat
  IF NEW.last_heartbeat IS NOT NULL THEN
    minutes_since_heartbeat := EXTRACT(EPOCH FROM (now() - NEW.last_heartbeat)) / 60;
  ELSE
    minutes_since_heartbeat := NULL;
  END IF;

  -- Derive state with priority order (security first)
  IF NEW.is_isolated = true THEN
    new_state := 'isolated';
  ELSIF NEW.safe_mode_reason IS NOT NULL AND NEW.safe_mode_entered_at IS NOT NULL THEN
    new_state := 'safe_mode';
  ELSIF minutes_since_heartbeat IS NOT NULL AND minutes_since_heartbeat > 10 THEN
    new_state := 'offline';
  ELSIF NEW.status = 'pending' AND NEW.last_heartbeat IS NULL THEN
    new_state := 'offline';
  ELSIF NEW.force_update_version IS NOT NULL AND NEW.force_update_at IS NOT NULL 
        AND EXTRACT(EPOCH FROM (now() - NEW.force_update_at)) / 60 < 30 THEN
    new_state := 'updating';
  ELSIF NEW.is_throttled = true THEN
    new_state := 'degraded';
  ELSIF NEW.status = 'active' THEN
    new_state := 'healthy';
  ELSE
    new_state := 'offline';
  END IF;

  NEW.agent_state := new_state;
  
  -- Update timestamp only if state actually changed
  IF old_state IS DISTINCT FROM new_state THEN
    NEW.agent_state_changed_at := now();
    
    -- Set reason based on new state
    CASE new_state
      WHEN 'isolated' THEN
        NEW.agent_state_reason := COALESCE(NEW.isolation_reason, 'Isolado por segurança');
      WHEN 'safe_mode' THEN
        NEW.agent_state_reason := COALESCE(NEW.safe_mode_reason, 'Modo de proteção ativo');
      WHEN 'degraded' THEN
        NEW.agent_state_reason := COALESCE(NEW.throttle_reason, 'Comunicação restrita');
      WHEN 'updating' THEN
        NEW.agent_state_reason := 'Atualizando para versão ' || COALESCE(NEW.force_update_version, 'desconhecida');
      WHEN 'offline' THEN
        NEW.agent_state_reason := 'Sem contato';
      WHEN 'healthy' THEN
        NEW.agent_state_reason := NULL;
      ELSE
        NEW.agent_state_reason := NULL;
    END CASE;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: describe_table(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.describe_table(p_table_name text) RETURNS TABLE(column_name text, data_type text, is_nullable text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    c.column_name::text,
    c.data_type::text,
    c.is_nullable::text
  FROM information_schema.columns c
  WHERE c.table_schema = 'public'
    AND c.table_name = p_table_name
  ORDER BY c.ordinal_position;
$$;


--
-- Name: detect_agent_offline_reason(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_agent_offline_reason() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- If heartbeat becomes stale (>5 min gap), set offline reason
  IF OLD.last_heartbeat IS NOT NULL AND NEW.last_heartbeat = OLD.last_heartbeat THEN
    -- Heartbeat not updated, check if we need to set offline reason
    IF NEW.offline_reason IS NULL AND OLD.last_heartbeat < NOW() - INTERVAL '5 minutes' THEN
      NEW.offline_reason := 'network_unreachable';
      NEW.offline_detected_at := NOW();
    END IF;
  END IF;
  
  -- If heartbeat was just updated, clear offline reason
  IF NEW.last_heartbeat IS DISTINCT FROM OLD.last_heartbeat AND NEW.last_heartbeat IS NOT NULL THEN
    NEW.offline_reason := NULL;
    NEW.offline_detected_at := NULL;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: detect_blocked_access_attempts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_blocked_access_attempts() RETURNS TABLE(inserted_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count INTEGER := 0;
BEGIN
  WITH inserted AS (
    INSERT INTO blocked_access_attempts (
      tenant_id,
      agent_id,
      agent_name,
      domain,
      policy_id,
      attempted_at,
      blocked_by,
      source,
      created_at
    )
    SELECT
      awa.tenant_id,
      awa.agent_id,
      a.agent_name,
      awa.domain,
      bw.id,
      awa.visited_at,
      'hosts_file',
      awa.source,
      now()
    FROM agent_web_activity awa
    JOIN agents a ON a.id = awa.agent_id
    JOIN blocked_websites bw
      ON bw.tenant_id = awa.tenant_id
     AND bw.is_active = true
     AND (
          awa.domain = bw.domain_pattern
       OR awa.domain = 'www.' || bw.domain_pattern
       OR (
            bw.domain_pattern LIKE '*.%'
        AND (
              awa.domain = SUBSTRING(bw.domain_pattern FROM 3)
           OR awa.domain LIKE '%.' || SUBSTRING(bw.domain_pattern FROM 3)
        )
       )
     )
    WHERE awa.is_blocked = true
      AND awa.source != 'dns_cache'  -- CRITICAL: exclude DNS cache noise
      AND awa.visited_at >= bw.created_at
      AND NOT EXISTS (
        SELECT 1
        FROM blocked_access_attempts baa
        WHERE baa.agent_id = awa.agent_id
          AND baa.domain = awa.domain
          AND baa.attempted_at = awa.visited_at
      )
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_count FROM inserted;

  RETURN QUERY SELECT v_count;
END;
$$;


--
-- Name: detect_blocked_attempts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_blocked_attempts() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count integer := 0;
BEGIN
  WITH blocked AS (
    SELECT tenant_id, COUNT(*) as attempt_count
    FROM security_logs
    WHERE created_at > now() - interval '5 minutes'
      AND blocked = true
    GROUP BY tenant_id
    HAVING COUNT(*) >= 5
  )
  INSERT INTO tasks (tenant_id, source_type, title, description, severity, status, auto_generated)
  SELECT 
    b.tenant_id,
    'system_alert',
    '🚨 Blocked access attempts detected - ' || b.attempt_count || ' in 5min',
    'Multiple blocked access attempts detected. Investigate potential brute force or unauthorized access.',
    CASE WHEN b.attempt_count >= 20 THEN 'critical' ELSE 'high' END,
    'open',
    true
  FROM blocked b
  WHERE NOT EXISTS (
    SELECT 1 FROM tasks t 
    WHERE t.tenant_id = b.tenant_id 
      AND t.source_type = 'system_alert'
      AND t.title LIKE '%Blocked access%'
      AND t.status = 'open'
      AND t.created_at > now() - interval '1 hour'
  );
  GET DIAGNOSTICS v_count = ROW_COUNT;
  
  RETURN jsonb_build_object('alerts_created', v_count, 'executed_at', now());
END;
$$;


--
-- Name: detect_chain_breaks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_chain_breaks() RETURNS TABLE(break_count bigint, affected_agents uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    COUNT(*)::BIGINT,
    ARRAY_AGG(DISTINCT e1.agent_id)
  FROM job_executions e1
  JOIN job_executions e2
    ON e2.agent_id = e1.agent_id
   AND e2.execution_index = e1.execution_index + 1
  WHERE e2.previous_execution_hash IS NOT NULL
    AND e1.execution_hash IS NOT NULL
    AND e2.previous_execution_hash != e1.execution_hash;
END;
$$;


--
-- Name: detect_critical_failure_pattern(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_critical_failure_pattern(p_window_minutes integer DEFAULT 30, p_min_failures integer DEFAULT 3) RETURNS TABLE(tenant_id uuid, agent_id uuid, agent_name text, failure_type text, failure_count bigint, first_seen timestamp with time zone, last_seen timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH recent_failures AS (
    SELECT
      je.tenant_id,
      je.agent_id,
      je.agent_name,
      COALESCE(je.exit_code::text, je.error_message, 'unknown') AS fail_type,
      je.created_at AS event_time
    FROM job_executions je
    WHERE je.status = 'error'
      AND je.created_at > NOW() - (p_window_minutes || ' minutes')::interval

    UNION ALL

    SELECT
      j.tenant_id,
      j.agent_id,
      j.agent_name,
      j.type AS fail_type,
      j.completed_at AS event_time
    FROM jobs j
    WHERE j.status = 'failed'
      AND j.completed_at > NOW() - (p_window_minutes || ' minutes')::interval
  )
  SELECT
    rf.tenant_id,
    rf.agent_id,
    rf.agent_name,
    rf.fail_type AS failure_type,
    COUNT(*)::bigint AS failure_count,
    MIN(rf.event_time) AS first_seen,
    MAX(rf.event_time) AS last_seen
  FROM recent_failures rf
  GROUP BY rf.tenant_id, rf.agent_id, rf.agent_name, rf.fail_type
  HAVING COUNT(*) >= p_min_failures;
END;
$$;


--
-- Name: FUNCTION detect_critical_failure_pattern(p_window_minutes integer, p_min_failures integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.detect_critical_failure_pattern(p_window_minutes integer, p_min_failures integer) IS 'Fixed: uses exit_code instead of error_code';


--
-- Name: detect_duplicate_executions(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_duplicate_executions(p_hours_back integer DEFAULT 24) RETURNS TABLE(job_id uuid, execution_count bigint, agent_name text, tenant_id uuid, first_claimed_at timestamp with time zone, last_claimed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    je.job_id,
    COUNT(*) as execution_count,
    je.agent_name,
    je.tenant_id,
    MIN(je.claimed_at) as first_claimed_at,
    MAX(je.claimed_at) as last_claimed_at
  FROM job_executions je
  WHERE je.created_at > NOW() - (p_hours_back || ' hours')::INTERVAL
  GROUP BY je.job_id, je.agent_name, je.tenant_id
  HAVING COUNT(*) > 1
  ORDER BY COUNT(*) DESC;
END;
$$;


--
-- Name: detect_improdutive_agents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_improdutive_agents() RETURNS TABLE(agent_id uuid, agent_name text, tenant_id uuid, health_status text, minutes_since_heartbeat integer, minutes_since_execution integer, stale_queued_jobs bigint, pending_jobs bigint)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    v.agent_id,
    v.agent_name,
    v.tenant_id,
    v.health_status,
    v.minutes_since_heartbeat::integer,
    v.minutes_since_execution::integer,
    v.stale_queued_jobs::bigint,
    v.pending_jobs::bigint
  FROM v_agent_execution_health v
  JOIN active_agents a ON a.id = v.agent_id
  WHERE v.health_status IN ('not_polling_jobs', 'not_executing_jobs', 'execution_stale')
    AND v.minutes_since_heartbeat < 30
    AND COALESCE(a.is_throttled, false) = false
    AND NOT EXISTS (
      SELECT 1 FROM decision_events de
      WHERE de.agent_id = v.agent_id
        AND de.rule_code = 'AGENT_IMPRODUTIVE_005'
        AND de.created_at > NOW() - INTERVAL '2 hours'
    )
    AND v.health_status != 'safe_mode'
    AND (
      v.stale_queued_jobs >= 3
      OR v.minutes_since_execution > 120
    );
END;
$$;


--
-- Name: FUNCTION detect_improdutive_agents(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.detect_improdutive_agents() IS 'Detects agents that are online but not processing jobs. Returns integer types for minutes columns to match v_agent_execution_health view.';


--
-- Name: detect_isolation_candidates(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_isolation_candidates(p_suspicious_events_count integer DEFAULT 5, p_time_window_minutes integer DEFAULT 10) RETURNS TABLE(agent_id uuid, agent_name text, tenant_id uuid, event_count bigint, event_types text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    se.agent_id,
    COALESCE(se.agent_name, a.agent_name) AS agent_name,
    se.tenant_id,
    COUNT(*) AS event_count,
    ARRAY_AGG(DISTINCT se.event_type) AS event_types
  FROM security_events se
  JOIN agents a ON se.agent_id = a.id
  WHERE se.created_at > NOW() - (p_time_window_minutes || ' minutes')::INTERVAL
    AND a.is_isolated = false
    AND se.severity IN ('high', 'critical')
  GROUP BY se.agent_id, COALESCE(se.agent_name, a.agent_name), se.tenant_id
  HAVING COUNT(*) >= p_suspicious_events_count
  ORDER BY event_count DESC;
END;
$$;


--
-- Name: detect_rule_dependency_loops(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_rule_dependency_loops(p_tenant_id uuid) RETURNS TABLE(loop_path uuid[], loop_length integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH RECURSIVE dep_chain AS (
    SELECT 
      rule_id,
      depends_on_rule_id,
      ARRAY[rule_id, depends_on_rule_id] AS path,
      1 AS depth,
      (rule_id = depends_on_rule_id) AS is_cycle
    FROM automation_rule_dependencies
    WHERE tenant_id = p_tenant_id
    
    UNION ALL
    
    SELECT
      dc.rule_id,
      d.depends_on_rule_id,
      dc.path || d.depends_on_rule_id,
      dc.depth + 1,
      d.depends_on_rule_id = ANY(dc.path)
    FROM dep_chain dc
    JOIN automation_rule_dependencies d 
      ON dc.depends_on_rule_id = d.rule_id 
      AND d.tenant_id = p_tenant_id
    WHERE NOT dc.is_cycle AND dc.depth < 10
  )
  SELECT path AS loop_path, depth AS loop_length
  FROM dep_chain
  WHERE is_cycle;
$$;


--
-- Name: detect_silent_job_failures(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_silent_job_failures() RETURNS TABLE(job_id uuid, tenant_id uuid, agent_id uuid, job_name text, job_type text, last_status text, last_execution_at timestamp with time zone, hours_since_execution double precision, violation_type text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    j.id,
    j.tenant_id,
    j.agent_id,
    COALESCE(j.agent_name, j.type)::TEXT,
    j.type::TEXT,
    j.status::TEXT,
    j.completed_at,
    (EXTRACT(EPOCH FROM (NOW() - j.completed_at)) / 3600)::double precision,
    'silent_failure'::TEXT
  FROM jobs j
  WHERE j.status = 'completed'
    AND j.completed_at > NOW() - INTERVAL '24 hours'
    AND (j.output IS NULL OR j.output = '{}'::jsonb OR j.output = 'null'::jsonb)
    AND j.type NOT IN ('heartbeat', 'ping', 'status_check')
    AND NOT EXISTS (
      SELECT 1 FROM system_alerts sa
      WHERE sa.tenant_id = j.tenant_id
        AND sa.alert_type = 'silent_job_failure'
        AND sa.details->>'job_id' = j.id::text
        AND sa.created_at > NOW() - INTERVAL '4 hours'
    );
END;
$$;


--
-- Name: detect_throttle_candidates(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_throttle_candidates(p_requests_per_minute integer DEFAULT 60, p_time_window_minutes integer DEFAULT 5) RETURNS TABLE(agent_id uuid, agent_name text, tenant_id uuid, request_count bigint, error_count bigint, error_rate numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    j.agent_id,
    j.agent_name,
    j.tenant_id,
    COUNT(*) AS request_count,
    COUNT(*) FILTER (WHERE j.status = 'failed') AS error_count,
    ROUND(
      (COUNT(*) FILTER (WHERE j.status = 'failed')::NUMERIC / 
       NULLIF(COUNT(*)::NUMERIC, 0)) * 100, 2
    ) AS error_rate
  FROM jobs j
  JOIN agents a ON j.agent_id = a.id
  WHERE j.created_at > NOW() - (p_time_window_minutes || ' minutes')::INTERVAL
    AND a.is_throttled = false
  GROUP BY j.agent_id, j.agent_name, j.tenant_id
  HAVING COUNT(*) > (p_requests_per_minute * p_time_window_minutes)
     OR (COUNT(*) FILTER (WHERE j.status = 'failed')::NUMERIC / NULLIF(COUNT(*)::NUMERIC, 0)) > 0.5
  ORDER BY request_count DESC;
END;
$$;


--
-- Name: detect_throttle_revert_candidates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_throttle_revert_candidates() RETURNS TABLE(agent_id uuid, agent_name text, tenant_id uuid, throttled_at timestamp with time zone, minutes_since_execution double precision, pending_jobs integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    a.id,
    a.agent_name::TEXT,
    a.tenant_id,
    a.throttled_at,
    v.minutes_since_execution::double precision,
    v.pending_jobs::INTEGER
  FROM agents a
  JOIN v_agent_execution_health v ON v.agent_id = a.id
  WHERE a.is_throttled = true
    AND a.throttled_at < NOW() - INTERVAL '2 hours'
    AND v.minutes_since_execution < 15
    AND v.pending_jobs < 5
    AND NOT EXISTS (
      SELECT 1 FROM decision_events de
      WHERE de.agent_id = a.id
        AND de.rule_code = 'AGENT_IMPRODUTIVE_005'
        AND de.created_at > NOW() - INTERVAL '2 hours'
    )
    AND v.health_status != 'safe_mode';
END;
$$;


--
-- Name: detect_version_block_candidates(numeric, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_version_block_candidates(p_failure_rate_percent numeric DEFAULT 30, p_affected_agents_count integer DEFAULT 3, p_time_window_hours integer DEFAULT 24) RETURNS TABLE(version text, platform text, version_id uuid, total_agents bigint, failed_agents bigint, failure_rate numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    a.agent_version AS version,
    COALESCE(a.os_type, 'unknown') AS platform,
    av.id AS version_id,
    COUNT(DISTINCT a.id) AS total_agents,
    COUNT(DISTINCT a.id) FILTER (
      WHERE EXISTS (
        SELECT 1 FROM jobs j 
        WHERE j.agent_id = a.id 
          AND j.status = 'failed'
          AND j.created_at > NOW() - (p_time_window_hours || ' hours')::INTERVAL
      )
    ) AS failed_agents,
    ROUND(
      COUNT(DISTINCT a.id) FILTER (
        WHERE EXISTS (
          SELECT 1 FROM jobs j 
          WHERE j.agent_id = a.id 
            AND j.status = 'failed'
            AND j.created_at > NOW() - (p_time_window_hours || ' hours')::INTERVAL
        )
      )::NUMERIC / NULLIF(COUNT(DISTINCT a.id)::NUMERIC, 0) * 100, 2
    ) AS failure_rate
  FROM agents a
  LEFT JOIN agent_versions av ON a.agent_version = av.version AND a.os_type = av.platform
  WHERE a.agent_version IS NOT NULL
    AND a.enrolled_at > NOW() - (p_time_window_hours || ' hours')::INTERVAL
    AND (av.is_blocked IS NULL OR av.is_blocked = false)
  GROUP BY a.agent_version, a.os_type, av.id
  HAVING 
    COUNT(DISTINCT a.id) >= p_affected_agents_count
    AND (
      COUNT(DISTINCT a.id) FILTER (
        WHERE EXISTS (
          SELECT 1 FROM jobs j 
          WHERE j.agent_id = a.id 
            AND j.status = 'failed'
            AND j.created_at > NOW() - (p_time_window_hours || ' hours')::INTERVAL
        )
      )::NUMERIC / NULLIF(COUNT(DISTINCT a.id)::NUMERIC, 0) * 100
    ) >= p_failure_rate_percent
  ORDER BY failure_rate DESC;
END;
$$;


--
-- Name: diagnose_agent(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.diagnose_agent(p_agent_name text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agent RECORD;
  v_token_info RECORD;
  v_jobs_info RECORD;
  v_issues jsonb[] := '{}';
  v_user_tenant_id uuid;
BEGIN
  SELECT tenant_id INTO v_user_tenant_id 
  FROM user_roles 
  WHERE user_id = auth.uid() 
  LIMIT 1;
  
  IF v_user_tenant_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'User not authenticated or no tenant assigned'
    );
  END IF;

  SELECT * INTO v_agent
  FROM agents
  WHERE agent_name = p_agent_name
    AND tenant_id = v_user_tenant_id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Agent not found in your tenant',
      'agent_name', p_agent_name
    );
  END IF;
  
  SELECT 
    COUNT(*) as total_tokens,
    COUNT(*) FILTER (WHERE is_active = true) as active_tokens,
    MAX(created_at) as last_token_created
  INTO v_token_info
  FROM agent_tokens
  WHERE agent_id = v_agent.id;
  
  IF v_token_info.active_tokens = 0 THEN
    v_issues := v_issues || jsonb_build_object(
      'type', 'no_active_token',
      'severity', 'critical',
      'message', 'No active tokens found for this agent'
    );
  END IF;
  
  IF v_agent.last_heartbeat IS NULL THEN
    v_issues := v_issues || jsonb_build_object(
      'type', 'never_connected',
      'severity', 'critical',
      'message', 'Agent never sent a heartbeat',
      'enrolled_at', v_agent.enrolled_at
    );
  ELSIF v_agent.last_heartbeat < NOW() - INTERVAL '10 minutes' THEN
    v_issues := v_issues || jsonb_build_object(
      'type', 'stale_heartbeat',
      'severity', 'high',
      'message', 'Last heartbeat was more than 10 minutes ago',
      'last_heartbeat', v_agent.last_heartbeat,
      'minutes_ago', EXTRACT(EPOCH FROM (NOW() - v_agent.last_heartbeat)) / 60
    );
  END IF;
  
  SELECT 
    COUNT(*) as total_jobs,
    COUNT(*) FILTER (WHERE status = 'queued') as queued_jobs,
    COUNT(*) FILTER (WHERE status = 'delivered') as delivered_jobs,
    COUNT(*) FILTER (WHERE status = 'failed') as failed_jobs
  INTO v_jobs_info
  FROM jobs
  WHERE agent_id = v_agent.id;
  
  IF v_jobs_info.delivered_jobs > 0 THEN
    v_issues := v_issues || jsonb_build_object(
      'type', 'stuck_jobs',
      'severity', 'medium',
      'message', format('%s jobs stuck in delivered state', v_jobs_info.delivered_jobs)
    );
  END IF;
  
  RETURN jsonb_build_object(
    'success', true,
    'agent', jsonb_build_object(
      'id', v_agent.id,
      'name', v_agent.agent_name,
      'status', v_agent.status,
      'enrolled_at', v_agent.enrolled_at,
      'last_heartbeat', v_agent.last_heartbeat,
      'os_type', v_agent.os_type
    ),
    'tokens', v_token_info,
    'jobs', v_jobs_info,
    'issues', v_issues,
    'is_healthy', array_length(v_issues, 1) IS NULL
  );
END;
$$;


--
-- Name: FUNCTION diagnose_agent(p_agent_name text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.diagnose_agent(p_agent_name text) IS 'Diagnóstico completo de um agente específico';


--
-- Name: diagnose_agent_issues(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.diagnose_agent_issues(p_agent_name text, p_tenant_id uuid) RETURNS TABLE(issue_type text, severity text, message text, details jsonb, detected_at timestamp with time zone, origin text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agent record;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  SELECT a.id, a.status, a.agent_version, a.last_heartbeat, a.os_type,
         a.force_update_version, a.scheduling_paused, a.scheduling_paused_reason,
         a.archived_at,
         EXTRACT(EPOCH FROM (now() - a.last_heartbeat))/60 as minutes_offline
  INTO v_agent
  FROM agents a
  WHERE a.agent_name = p_agent_name AND a.tenant_id = p_tenant_id;
  
  IF v_agent IS NULL THEN
    RETURN QUERY SELECT 'agent_not_found'::text, 'critical'::text,
      'Agente não encontrado no sistema'::text,
      jsonb_build_object('agent_name', p_agent_name), now(), 'system'::text;
    RETURN;
  END IF;
  
  IF v_agent.archived_at IS NOT NULL THEN
    RETURN QUERY SELECT 'agent_archived'::text, 'info'::text,
      'Agente está arquivado'::text,
      jsonb_build_object('agent_id', v_agent.id), now(), 'system'::text;
    RETURN;
  END IF;

  IF v_agent.minutes_offline > 10 THEN
    RETURN QUERY SELECT
      'agent_offline'::text,
      CASE WHEN v_agent.minutes_offline > 1440 THEN 'critical' 
           WHEN v_agent.minutes_offline > 120 THEN 'high' ELSE 'medium' END,
      'Sem comunicação há ' || 
        CASE WHEN v_agent.minutes_offline > 1440 THEN round(v_agent.minutes_offline / 1440) || ' dia(s)'
          WHEN v_agent.minutes_offline > 60 THEN round(v_agent.minutes_offline / 60) || ' hora(s)'
          ELSE round(v_agent.minutes_offline) || ' minutos' END,
      jsonb_build_object('last_heartbeat', v_agent.last_heartbeat, 'minutes_offline', round(v_agent.minutes_offline)),
      v_agent.last_heartbeat, 'system'::text;
  END IF;

  IF v_agent.agent_version IS NOT NULL THEN
    DECLARE v_latest_version text;
    BEGIN
      SELECT ar.version INTO v_latest_version
      FROM agent_releases ar
      WHERE ar.platform = COALESCE(v_agent.os_type, 'windows') AND ar.is_active = true
      ORDER BY ar.created_at DESC LIMIT 1;
      IF v_latest_version IS NOT NULL AND v_agent.agent_version != v_latest_version THEN
        RETURN QUERY SELECT
          'outdated_version'::text,
          CASE WHEN v_agent.force_update_version IS NOT NULL THEN 'medium' ELSE 'high' END,
          'Versão ' || v_agent.agent_version || ' desatualizada (atual: ' || v_latest_version || ')' ||
            CASE WHEN v_agent.force_update_version IS NOT NULL THEN ' — atualização pendente' ELSE '' END,
          jsonb_build_object('current_version', v_agent.agent_version, 'latest_version', v_latest_version),
          now(), 'system'::text;
      END IF;
    END;
  END IF;

  IF v_agent.scheduling_paused = true THEN
    RETURN QUERY SELECT
      'scheduling_paused'::text, 'info'::text,
      'Agendamento de jobs pausado' || COALESCE(': ' || v_agent.scheduling_paused_reason, ''),
      jsonb_build_object('reason', v_agent.scheduling_paused_reason), now(), 'system'::text;
  END IF;

  -- Jobs falhados recentes (últimas 24h, agrupados)
  -- EXCLUI falhas operacionais esperadas: TTL expirado e agente offline
  RETURN QUERY
  SELECT
    'failed_job'::text,
    CASE WHEN jg.fail_count > 3 THEN 'high' ELSE 'medium' END,
    jg.jtype || ' falhou ' || jg.fail_count || 'x nas últimas 24h' ||
      COALESCE(' — ' || jg.last_error, ''),
    jsonb_build_object('job_type', jg.jtype, 'fail_count', jg.fail_count, 'last_failure', jg.last_failure),
    jg.last_failure, 'jobs'::text
  FROM (
    SELECT j.type as jtype, COUNT(*) as fail_count,
      MAX(j.created_at) as last_failure,
      (array_agg(j.error_message ORDER BY j.created_at DESC))[1] as last_error
    FROM jobs j
    WHERE j.agent_id = v_agent.id
      AND j.status IN ('failed', 'dlq', 'exhausted')
      AND j.created_at > now() - interval '24 hours'
      -- Exclude expected operational failures (TTL expired, agent offline)
      AND COALESCE(j.failure_class, '') NOT IN ('EXPIRED_TTL', 'AGENT_OFFLINE', 'AGENT_STALLED')
      AND j.error_message NOT LIKE '[DLQ:EXPIRED_TTL]%'
      AND j.error_message NOT LIKE '[DLQ:AGENT_OFFLINE]%'
      AND j.error_message NOT LIKE '[DLQ:AGENT_STALLED]%'
    GROUP BY j.type HAVING COUNT(*) >= 2
  ) jg;

  -- Eventos de segurança críticos (últimas 48h, deduplicados)
  RETURN QUERY
  SELECT DISTINCT ON (e.event_type, e.event_data->>'component')
    e.event_type, e.severity,
    CASE e.event_type
      WHEN 'security_event' THEN 'Evento de segurança: ' || COALESCE(e.event_data->>'component', 'sistema')
      WHEN 'service_stopped' THEN 'Serviço ' || COALESCE(e.event_data->>'service_name', 'desconhecido') || ' parado'
      ELSE COALESCE(e.event_data->>'message', 'Evento: ' || replace(e.event_type, '_', ' '))
    END,
    e.event_data, e.created_at, 'evidence_logs'::text
  FROM agent_evidence_logs e
  WHERE e.agent_id = v_agent.id
    AND e.severity IN ('critical', 'error')
    AND e.created_at > now() - interval '48 hours'
    AND e.event_type NOT IN ('heartbeat', 'state_change', 'policy_drift', 'policy_sync')
  ORDER BY e.event_type, e.event_data->>'component', e.created_at DESC;
END;
$$;


--
-- Name: FUNCTION diagnose_agent_issues(p_agent_name text, p_tenant_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.diagnose_agent_issues(p_agent_name text, p_tenant_id uuid) IS '🔒 Essencial - Diagnóstico de agentes com mensagens descritivas';


--
-- Name: diagnose_chain_health(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.diagnose_chain_health(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_audit_breaks INT;
  v_exec_agents_with_gaps INT;
  v_exec_total_gaps INT;
  v_audit_details JSONB;
  v_exec_details JSONB;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  -- Only service_role or super_admin
  IF NOT (
    current_setting('role', true) = 'service_role' 
    OR is_current_super_admin()
  ) THEN
    RAISE EXCEPTION 'ACCESS_DENIED: requires service_role or super_admin';
  END IF;

  -- === AUDIT LOG CHAIN ===
  SELECT COUNT(*), jsonb_agg(jsonb_build_object(
    'id', sub.id, 
    'created_at', sub.created_at,
    'previous_log_hash', sub.previous_log_hash
  ))
  INTO v_audit_breaks, v_audit_details
  FROM (
    SELECT a.id, a.created_at, a.previous_log_hash
    FROM audit_logs a
    WHERE (p_tenant_id IS NULL OR a.tenant_id = p_tenant_id)
      AND a.previous_log_hash IS NOT NULL
      AND a.previous_log_hash != 'GENESIS'
      AND NOT EXISTS (
        SELECT 1 FROM audit_logs b 
        WHERE b.integrity_hash = a.previous_log_hash
        AND b.tenant_id = a.tenant_id
      )
    ORDER BY a.created_at ASC
    LIMIT 50
  ) sub;

  -- === EXECUTION HASH CHAIN ===
  SELECT COUNT(*), COALESCE(SUM(gaps), 0), 
    jsonb_agg(jsonb_build_object(
      'agent_id', agent_id,
      'min_idx', min_idx,
      'max_idx', max_idx,
      'expected', expected,
      'actual', actual,
      'gaps', gaps
    ))
  INTO v_exec_agents_with_gaps, v_exec_total_gaps, v_exec_details
  FROM (
    SELECT 
      je.agent_id,
      MIN(je.execution_index) as min_idx,
      MAX(je.execution_index) as max_idx,
      (MAX(je.execution_index) - MIN(je.execution_index) + 1) as expected,
      COUNT(*) as actual,
      (MAX(je.execution_index) - MIN(je.execution_index) + 1 - COUNT(*)) as gaps
    FROM job_executions je
    JOIN agents ag ON ag.id = je.agent_id
    WHERE je.execution_index IS NOT NULL 
      AND je.execution_hash IS NOT NULL
      AND (p_tenant_id IS NULL OR je.tenant_id = p_tenant_id)
    GROUP BY je.agent_id
    HAVING COUNT(*) != (MAX(je.execution_index) - MIN(je.execution_index) + 1)
  ) sub;

  RETURN jsonb_build_object(
    'audit_chain', jsonb_build_object(
      'breaks_found', COALESCE(v_audit_breaks, 0),
      'details', COALESCE(v_audit_details, '[]'::jsonb)
    ),
    'execution_chain', jsonb_build_object(
      'agents_with_gaps', COALESCE(v_exec_agents_with_gaps, 0),
      'total_gaps', COALESCE(v_exec_total_gaps, 0),
      'details', COALESCE(v_exec_details, '[]'::jsonb)
    ),
    'diagnosed_at', now(),
    'diagnosed_by', auth.uid()
  );
END;
$$;


--
-- Name: drop_old_metrics_partitions(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.drop_old_metrics_partitions(retention_months integer DEFAULT 3) RETURNS TABLE(partition_dropped text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  partition_rec RECORD;
  cutoff_date DATE;
  partition_date DATE;
BEGIN
  cutoff_date := date_trunc('month', CURRENT_DATE - (retention_months || ' months')::INTERVAL)::DATE;
  
  FOR partition_rec IN
    SELECT c.relname
    FROM pg_class c
    JOIN pg_inherits i ON c.oid = i.inhrelid
    JOIN pg_namespace n ON c.relnamespace = n.oid
    WHERE i.inhparent = 'public.agent_system_metrics_partitioned'::regclass
      AND n.nspname = 'public'
      AND c.relname ~ '^agent_system_metrics_\d{4}_\d{2}$'
  LOOP
    -- Extrair data da particao
    BEGIN
      partition_date := to_date(substring(partition_rec.relname from 'agent_system_metrics_(\d{4}_\d{2})'), 'YYYY_MM');
      
      IF partition_date < cutoff_date THEN
        EXECUTE format('DROP TABLE IF EXISTS public.%I', partition_rec.relname);
        partition_dropped := partition_rec.relname;
        RETURN NEXT;
        RAISE NOTICE 'Particao removida: %', partition_rec.relname;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'Erro ao processar particao %: %', partition_rec.relname, SQLERRM;
    END;
  END LOOP;
  
  RETURN;
END;
$_$;


--
-- Name: FUNCTION drop_old_metrics_partitions(retention_months integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.drop_old_metrics_partitions(retention_months integer) IS '🔒 Essencial - Manutenção de partições';


--
-- Name: drop_old_partitions(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.drop_old_partitions(p_table_name text, p_retention_months integer DEFAULT 3) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_partition RECORD;
    v_dropped INTEGER := 0;
    v_cutoff DATE;
BEGIN
    v_cutoff := date_trunc('month', now()) - (p_retention_months || ' months')::interval;
    
    FOR v_partition IN
        SELECT c.relname AS partition_name
        FROM pg_inherits i
        JOIN pg_class c ON c.oid = i.inhrelid
        JOIN pg_class p ON p.oid = i.inhparent
        WHERE p.relname = p_table_name
        ORDER BY c.relname
    LOOP
        -- Extract YYYY_MM from partition name and check if older than cutoff
        DECLARE
            v_date_part TEXT;
            v_partition_date DATE;
        BEGIN
            v_date_part := substring(v_partition.partition_name FROM '_(\d{4}_\d{2})$');
            IF v_date_part IS NOT NULL THEN
                v_partition_date := to_date(v_date_part, 'YYYY_MM');
                IF v_partition_date < v_cutoff THEN
                    EXECUTE format('DROP TABLE IF EXISTS public.%I', v_partition.partition_name);
                    v_dropped := v_dropped + 1;
                END IF;
            END IF;
        END;
    END LOOP;
    
    RETURN v_dropped;
END;
$_$;


--
-- Name: drop_old_telemetry_partitions(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.drop_old_telemetry_partitions(retention_days integer DEFAULT 30) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
  partition_record RECORD;
  cutoff_date DATE;
  partition_date DATE;
BEGIN
  cutoff_date := CURRENT_DATE - (retention_days || ' days')::INTERVAL;
  
  FOR partition_record IN
    SELECT c.relname AS partition_name
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'r'
      AND (
        c.relname ~ '^endpoint_event_buffer_partitioned_\d{4}_\d{2}$'
        OR c.relname ~ '^endpoint_process_events_partitioned_\d{4}_\d{2}$'
        OR c.relname ~ '^endpoint_network_events_partitioned_\d{4}_\d{2}$'
        OR c.relname ~ '^agent_system_metrics_\d{4}_\d{2}$'
        OR c.relname ~ '^hmac_signatures_\d{4}_\d{2}$'
      )
    ORDER BY c.relname
  LOOP
    BEGIN
      partition_date := TO_DATE(
        REGEXP_REPLACE(partition_record.partition_name, '.*_(\d{4})_(\d{2})$', '\1-\2-01'),
        'YYYY-MM-DD'
      );
      
      IF partition_date < cutoff_date THEN
        EXECUTE FORMAT('DROP TABLE IF EXISTS public.%I', partition_record.partition_name);
        RAISE NOTICE 'Dropped old partition: %', partition_record.partition_name;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Failed to process partition %: %', partition_record.partition_name, SQLERRM;
    END;
  END LOOP;
END;
$_$;


--
-- Name: emit_agent_status_domain_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.emit_agent_status_domain_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    INSERT INTO domain_events (
      event_type, aggregate_type, aggregate_id, tenant_id, payload, created_at
    ) VALUES (
      'agent.status_changed', 'agent', NEW.id, NEW.tenant_id,
      jsonb_build_object(
        'agent_id', NEW.id, 'agent_name', NEW.agent_name,
        'old_status', OLD.status, 'new_status', NEW.status
      ), now()
    );
  END IF;
  RETURN NEW;
END;
$$;


