-- Name: emit_job_domain_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.emit_job_domain_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status IN ('completed', 'failed', 'cancelled') AND OLD.status IS DISTINCT FROM NEW.status THEN
    INSERT INTO domain_events (
      event_type, aggregate_type, aggregate_id, tenant_id, payload, created_at
    ) VALUES (
      'job.' || NEW.status, 'job', NEW.id, NEW.tenant_id,
      jsonb_build_object(
        'job_id', NEW.id, 'job_type', NEW.type,
        'agent_id', NEW.agent_id, 'status', NEW.status
      ), now()
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_ai_action_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_ai_action_approval() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.review_decision = 'approved' THEN
    NEW.approved_at := COALESCE(NEW.approved_at, now());
    NEW.approved_by := COALESCE(NEW.approved_by, NEW.executed_by);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_critical_alert_human_review(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_critical_alert_human_review() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.resolved = true AND (OLD.resolved IS NULL OR OLD.resolved = false) THEN
    IF NEW.severity = 'critical' AND NEW.resolved_by IS NULL THEN
      RAISE EXCEPTION 'Critical alerts require human resolution (resolved_by must be set)';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


