--
-- Name: enforce_failed_job_requires_error(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_failed_job_requires_error() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.status IS DISTINCT FROM 'failed'
     AND NEW.status = 'failed' THEN

    IF NEW.error_message IS NULL
       OR LENGTH(TRIM(NEW.error_message)) = 0 THEN

      RAISE EXCEPTION
        'JOB_INTEGRITY_VIOLATION: failed job requires error_message (job_id=%, type=%)',
        NEW.id, NEW.type
        USING ERRCODE = '23514';

    END IF;

  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION enforce_failed_job_requires_error(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enforce_failed_job_requires_error() IS 'Zero Trust: Impede jobs marcados como failed sem error_message explicativo. ERRCODE 23514.';


--
-- Name: enforce_forensic_snapshot_immutability(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_forensic_snapshot_immutability() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RAISE EXCEPTION 'IMMUTABLE_RECORD: forensic snapshots cannot be modified or deleted'
    USING ERRCODE = '23514';
END;
$$;


--
-- Name: enforce_insight_resolution_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_insight_resolution_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- If transitioning to resolved/acknowledged without decision_event, block it
  IF NEW.acknowledged = true 
     AND OLD.acknowledged = false 
     AND NEW.resolved_by_decision_event IS NULL 
     AND NEW.resolution_method IS NULL THEN
    -- Allow but mark as requiring governance attention
    NEW.resolution_method := 'manual_dismiss';
  END IF;
  
  -- Track when resolution happened
  IF NEW.acknowledged = true AND OLD.acknowledged = false THEN
    NEW.acknowledged_at := COALESCE(NEW.acknowledged_at, NOW());
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: enforce_job_side_effects(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_job_side_effects() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.status IS DISTINCT FROM 'completed'
     AND NEW.status = 'completed' THEN

    -- collect_web_activity: RELAXED - empty web activity is valid
    -- (endpoint may have no browser/DNS data)

    -- collect_system_metrics must have metrics data
    IF NEW.type = 'collect_system_metrics' THEN
      IF NOT EXISTS (
        SELECT 1
        FROM agent_system_metrics asm
        WHERE asm.agent_id = NEW.agent_id
          AND asm.created_at >= NEW.created_at
      ) THEN
        RAISE EXCEPTION
          'JOB_INTEGRITY_VIOLATION: collect_system_metrics completed without metrics data (job_id=%, agent_id=%)',
          NEW.id, NEW.agent_id
          USING ERRCODE = '23514';
      END IF;
    END IF;

  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_job_state_transitions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_job_state_transitions() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_valid_transitions jsonb := '{
    "pending": ["queued", "delivered", "cancelled", "failed", "expired"],
    "queued": ["delivered", "failed", "cancelled", "expired"],
    "delivered": ["completed", "failed", "cancelled", "expired"],
    "running": ["completed", "failed", "cancelled", "timeout", "expired"],
    "completed": ["archived"],
    "failed": ["archived"],
    "cancelled": ["archived"],
    "timeout": ["archived"],
    "expired": ["archived"]
  }'::jsonb;
  v_allowed_states jsonb;
BEGIN
  IF OLD.status = NEW.status THEN
    RETURN NEW;
  END IF;
  
  v_allowed_states := v_valid_transitions->OLD.status;
  
  IF v_allowed_states IS NULL OR NOT v_allowed_states ? NEW.status THEN
    RAISE EXCEPTION 'ILLEGAL_STATE_TRANSITION: Cannot transition from % to %. Allowed: %',
      OLD.status, NEW.status, COALESCE(v_allowed_states, '[]'::jsonb)
    USING ERRCODE = '23514';
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION enforce_job_state_transitions(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enforce_job_state_transitions() IS 'Enforce valid state machine transitions for jobs. States: pending -> queued -> delivered -> completed. Terminal states (failed, cancelled, completed) can transition to archived.';


--
-- Name: enforce_kill_switch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_kill_switch() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  ks RECORD;
BEGIN
  SELECT * INTO ks
  FROM public.system_kill_switch
  WHERE tenant_id = NEW.tenant_id
    AND enabled = true;

  IF ks.enabled THEN
    -- Block high-risk only if scope is 'high_risk_only'
    IF ks.scope = 'high_risk_only' AND NEW.risk_level != 'high' THEN
      RETURN NEW;
    END IF;
    
    NEW.status := 'blocked';
    NEW.block_reason := 'kill_switch_active';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_no_auto_destructive_actions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_no_auto_destructive_actions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM playbook_actions
    WHERE playbook_id = NEW.id
    AND action_type IN ('isolate','kill_process','stop_service','disable_service','revoke_token','quarantine','network_isolate')
  ) THEN
    NEW.require_approval := true;
  END IF;
  RETURN NEW;
END;
$$;


