-- Name: FUNCTION ensure_tenant_features(p_tenant_id uuid, p_plan_name text, p_device_quantity integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ensure_tenant_features(p_tenant_id uuid, p_plan_name text, p_device_quantity integer) IS '🔒 Essencial - Provisionamento de features';


--
-- Name: enter_autonomous_safe_mode(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enter_autonomous_safe_mode(p_agent_id uuid, p_reason text DEFAULT 'autonomous_detection'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agent_name TEXT; v_tenant_id UUID; v_agent_version TEXT; v_caller_tenant uuid;
BEGIN
  v_caller_tenant := get_active_tenant_id();
  SELECT agent_name, tenant_id, agent_version INTO v_agent_name, v_tenant_id, v_agent_version
  FROM agents WHERE id = p_agent_id;
  IF v_agent_name IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Agent not found'); END IF;
  IF v_caller_tenant IS NOT NULL AND v_tenant_id != v_caller_tenant AND NOT is_current_super_admin() THEN
    INSERT INTO security_logs (tenant_id, event_type, severity, details)
    VALUES (v_caller_tenant, 'cross_tenant_blocked', 'critical',
      jsonb_build_object('function', 'enter_autonomous_safe_mode', 'target_agent', p_agent_id));
    RETURN jsonb_build_object('success', false, 'error', 'TENANT_MISMATCH');
  END IF;
  UPDATE agents SET agent_mode = 'SAFE_MODE', safe_mode_entered_at = now(), safe_mode_reason = p_reason
  WHERE id = p_agent_id;
  INSERT INTO agent_evidence_logs (agent_id, agent_name, tenant_id, event_type, event_data, evidence_hash, severity)
  VALUES (p_agent_id, v_agent_name, v_tenant_id, 'safe_mode_entry',
    jsonb_build_object('reason', p_reason, 'agent_version', v_agent_version, 'timestamp', now()),
    encode(digest(p_agent_id::text || 'safe_mode' || now()::text, 'sha256'), 'hex'), 'high');
  RETURN jsonb_build_object('success', true, 'agent', v_agent_name, 'mode', 'SAFE_MODE');
END;
$$;


--
-- Name: enter_autonomous_safe_mode(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enter_autonomous_safe_mode(p_agent_id uuid, p_reason text, p_failure_type text, p_failure_count integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agent_name TEXT; v_tenant_id UUID; v_agent_version TEXT; v_event_id UUID; v_caller_tenant uuid;
BEGIN
  v_caller_tenant := get_active_tenant_id();
  SELECT agent_name, tenant_id, agent_version INTO v_agent_name, v_tenant_id, v_agent_version
  FROM agents WHERE id = p_agent_id;
  IF v_agent_name IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Agent not found'); END IF;
  IF v_caller_tenant IS NOT NULL AND v_tenant_id != v_caller_tenant AND NOT is_current_super_admin() THEN
    INSERT INTO security_logs (tenant_id, event_type, severity, details)
    VALUES (v_caller_tenant, 'cross_tenant_blocked', 'critical',
      jsonb_build_object('function', 'enter_autonomous_safe_mode_v2', 'target_agent', p_agent_id));
    RETURN jsonb_build_object('success', false, 'error', 'TENANT_MISMATCH');
  END IF;
  UPDATE agents SET agent_mode = 'SAFE_MODE', safe_mode_entered_at = NOW(), safe_mode_reason = p_reason WHERE id = p_agent_id;
  INSERT INTO agent_safe_mode_events (agent_id, tenant_id, entered_at, reason, agent_version, failure_count)
  VALUES (p_agent_id, v_tenant_id, NOW(), p_reason, v_agent_version, p_failure_count) RETURNING id INTO v_event_id;
  INSERT INTO system_alerts (tenant_id, agent_id, alert_type, severity, message, source, details)
  VALUES (v_tenant_id, p_agent_id, 'autonomous_safe_mode', 'high',
    format('Agente %s entrou automaticamente em SAFE_MODE: %s', v_agent_name, p_reason),
    'autonomous_safe_mode_system',
    jsonb_build_object('agent_id', p_agent_id, 'agent_name', v_agent_name, 'failure_type', p_failure_type,
      'failure_count', p_failure_count, 'safe_mode_event_id', v_event_id, 'triggered_at', NOW()));
  INSERT INTO ai_insights (tenant_id, agent_id, insight_type, severity, title, description, recommended_action, data)
  VALUES (v_tenant_id, p_agent_id, 'anomaly', 'high',
    format('SAFE_MODE Autônomo: %s', v_agent_name),
    format('Agente entrou em modo seguro automaticamente após %s falhas (%s)', p_failure_count, p_failure_type),
    'Investigar causa raiz e resetar modo seguro quando estável',
    jsonb_build_object('safe_mode_event_id', v_event_id, 'failure_type', p_failure_type, 'failure_count', p_failure_count));
  RETURN jsonb_build_object('success', true, 'agent', v_agent_name, 'mode', 'SAFE_MODE', 'event_id', v_event_id);
END;
$$;


--
-- Name: FUNCTION enter_autonomous_safe_mode(p_agent_id uuid, p_reason text, p_failure_type text, p_failure_count integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enter_autonomous_safe_mode(p_agent_id uuid, p_reason text, p_failure_type text, p_failure_count integer) IS 'Coloca um agente em SAFE_MODE autonomamente, com registro e alertas';


--
-- Name: escalate_breached_sla_tasks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.escalate_breached_sla_tasks() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Mark tasks with breached SLA
  UPDATE tasks
  SET 
    sla_breached_at = now(),
    updated_at = now()
  WHERE due_at < now()
    AND sla_breached_at IS NULL
    AND status IN ('open', 'in_progress');
END;
$$;


--
-- Name: evaluate_decision_rules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.evaluate_decision_rules() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rules_evaluated int := 0;
  v_events_created int := 0;
  v_rule RECORD;
  v_agent RECORD;
  v_definition jsonb;
  v_conditions jsonb;
  v_event_id uuid;
BEGIN
  -- Avalia cada regra ativa
  FOR v_rule IN
    SELECT * FROM decision_rules WHERE is_enabled = true
  LOOP
    v_rules_evaluated := v_rules_evaluated + 1;
    v_definition := v_rule.definition;
    v_conditions := v_definition->'conditions';
    
    -- Regra SILENT_FAILURE_007: Agente improdutivo
    IF v_rule.code = 'SILENT_FAILURE_007' THEN
      FOR v_agent IN
        SELECT a.*, 
               COALESCE(
                 (SELECT MAX(finished_at) FROM jobs j WHERE j.agent_id = a.id AND j.status = 'completed'),
                 a.enrolled_at
               ) as last_execution
        FROM agents a
        WHERE a.status = 'online'
          AND a.last_heartbeat > NOW() - INTERVAL '5 minutes'
          AND NOT EXISTS (
            SELECT 1 FROM decision_events de 
            WHERE de.agent_id = a.id 
              AND de.rule_code = 'SILENT_FAILURE_007'
              AND de.created_at > NOW() - INTERVAL '60 minutes'
          )
          AND EXISTS (
            SELECT 1 FROM jobs j 
            WHERE j.agent_id = a.id 
              AND j.status = 'queued'
              AND j.created_at < NOW() - INTERVAL '30 minutes'
          )
      LOOP
        -- Verifica se não executou jobs recentemente
        IF v_agent.last_execution < NOW() - INTERVAL '60 minutes' THEN
          -- Cria evento de decisão
          INSERT INTO decision_events (
            tenant_id, rule_code, agent_id, agent_name, action,
            evidence, executed_actions
          ) VALUES (
            v_agent.tenant_id,
            'SILENT_FAILURE_007',
            v_agent.id,
            v_agent.agent_name,
            'detect_silent_failure',
            jsonb_build_object(
              'last_heartbeat', v_agent.last_heartbeat,
              'last_execution', v_agent.last_execution,
              'agent_status', v_agent.status
            ),
            ARRAY['CREATE_AI_INSIGHT']
          ) RETURNING id INTO v_event_id;
          
          -- Cria insight
          INSERT INTO ai_insights (
            tenant_id, severity, insight_type, title, description
          ) VALUES (
            v_agent.tenant_id,
            'high',
            'agent_health',
            'Agente improdutivo: ' || v_agent.agent_name,
            'O agente ' || v_agent.agent_name || ' está online mas não executou jobs nas últimas horas. Última execução: ' || 
            COALESCE(v_agent.last_execution::text, 'nunca')
          );
          
          v_events_created := v_events_created + 1;
        END IF;
      END LOOP;
    END IF;
    
    -- Regra INSIGHT_IGNORED_009: Insights críticos ignorados
    IF v_rule.code = 'INSIGHT_IGNORED_009' THEN
      -- Escala insights ignorados há mais de 72h
      UPDATE ai_insights
      SET 
        severity = 'critical',
        title = '[ESCALADO] ' || title
      WHERE severity IN ('critical', 'high')
        AND acknowledged = false
        AND created_at < NOW() - INTERVAL '72 hours'
        AND title NOT LIKE '[ESCALADO]%';
        
      -- Registra evento se houve escalações
      IF FOUND THEN
        INSERT INTO decision_events (
          tenant_id, rule_code, action, evidence, executed_actions
        ) 
        SELECT DISTINCT 
          tenant_id,
          'INSIGHT_IGNORED_009',
          'escalate_insight',
          jsonb_build_object('escalated_at', NOW()),
          ARRAY['ESCALATE_INSIGHT']
        FROM ai_insights
        WHERE title LIKE '[ESCALADO]%';
          
        v_events_created := v_events_created + 1;
      END IF;
    END IF;
  END LOOP;
  
  -- Gera AI Actions para insights não processados
  PERFORM generate_ai_actions_from_insights();
  
  RETURN jsonb_build_object(
    'success', true,
    'rules_evaluated', v_rules_evaluated,
    'events_created', v_events_created,
    'evaluated_at', NOW()
  );
END;
$$;


--
-- Name: evaluate_decision_rules(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.evaluate_decision_rules(p_tenant_id uuid, p_context jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_tenant uuid;
  v_results jsonb;
BEGIN
  v_caller_tenant := get_active_tenant_id();
  IF v_caller_tenant IS NOT NULL AND v_caller_tenant != p_tenant_id AND NOT is_current_super_admin() THEN
    PERFORM log_security_violation(p_tenant_id, auth.uid(), 'internal', 'evaluate_decision_rules', 'cross_tenant_rule_evaluation', 'high',
      jsonb_build_object('caller_tenant', v_caller_tenant, 'target_tenant', p_tenant_id));
    RETURN jsonb_build_object('success', false, 'error', 'TENANT_MISMATCH');
  END IF;

  SELECT jsonb_agg(jsonb_build_object('rule_id', id, 'name', name, 'action', action_type))
  INTO v_results
  FROM automation_rules WHERE tenant_id = p_tenant_id AND is_active = true AND mode = 'active';

  RETURN jsonb_build_object('success', true, 'rules_evaluated', COALESCE(v_results, '[]'::jsonb));
END;
$$;


--
-- Name: evaluate_job_slo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.evaluate_job_slo() RETURNS TABLE(out_tenant_id uuid, out_time_window text, out_burn_rate numeric, out_error_rate numeric, out_severity text, out_task_created boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    t.id as out_tenant_id,
    '24h' as out_time_window,
    COALESCE(
      (SELECT COUNT(*)::numeric / NULLIF(COUNT(*) FILTER (WHERE status = 'completed'), 0)
       FROM scheduled_job_runs 
       WHERE tenant_id = t.id 
         AND started_at > now() - interval '24 hours'),
      0
    ) as out_burn_rate,
    COALESCE(
      (SELECT COUNT(*) FILTER (WHERE status = 'failed')::numeric / NULLIF(COUNT(*), 0)
       FROM scheduled_job_runs 
       WHERE tenant_id = t.id 
         AND started_at > now() - interval '24 hours'),
      0
    ) as out_error_rate,
    CASE 
      WHEN (SELECT COUNT(*) FILTER (WHERE status = 'failed') 
            FROM scheduled_job_runs 
            WHERE tenant_id = t.id 
              AND started_at > now() - interval '24 hours') > 10 
      THEN 'critical'
      WHEN (SELECT COUNT(*) FILTER (WHERE status = 'failed') 
            FROM scheduled_job_runs 
            WHERE tenant_id = t.id 
              AND started_at > now() - interval '24 hours') > 5 
      THEN 'warning'
      ELSE 'ok'
    END as out_severity,
    false as out_task_created
  FROM tenants t
  WHERE t.is_active = true;
END;
$$;


--
-- Name: evaluate_playbook_trigger(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.evaluate_playbook_trigger(p_tenant_id uuid, p_trigger_type text, p_agent_id uuid DEFAULT NULL::uuid, p_trigger_context jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_playbook RECORD;
  v_execution_id UUID;
  v_last_execution TIMESTAMPTZ;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  -- Buscar playbook ativo que match o trigger
  SELECT * INTO v_playbook
  FROM public.playbooks
  WHERE trigger_type = p_trigger_type
    AND is_enabled = true
    AND (tenant_id = p_tenant_id OR is_system = true)
  ORDER BY is_system ASC, created_at DESC
  LIMIT 1;
  
  IF v_playbook.id IS NULL THEN
    RETURN NULL;
  END IF;
  
  -- Verificar cooldown
  SELECT MAX(triggered_at) INTO v_last_execution
  FROM public.playbook_executions
  WHERE playbook_id = v_playbook.id
    AND tenant_id = p_tenant_id
    AND agent_id IS NOT DISTINCT FROM p_agent_id
    AND status NOT IN ('cancelled', 'ignored');
  
  IF v_last_execution IS NOT NULL AND 
     v_last_execution > NOW() - (v_playbook.cooldown_minutes || ' minutes')::INTERVAL THEN
    RETURN NULL; -- Dentro do cooldown
  END IF;
  
  -- Criar execução pendente
  INSERT INTO public.playbook_executions (
    playbook_id,
    tenant_id,
    agent_id,
    trigger_source,
    trigger_context,
    status
  ) VALUES (
    v_playbook.id,
    p_tenant_id,
    p_agent_id,
    p_trigger_type,
    p_trigger_context,
    CASE WHEN v_playbook.require_approval THEN 'pending' ELSE 'in_progress' END
  )
  RETURNING id INTO v_execution_id;
  
  RETURN v_execution_id;
END;
$$;


--
-- Name: evaluate_software_risk(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.evaluate_software_risk(p_agent_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- No-op: risk evaluation placeholder
  -- Agent risk is tracked through software_inventory and vuln scans, not agent metadata
  PERFORM 1 FROM agents WHERE id = p_agent_id AND archived_at IS NULL;
END;
$$;


--
-- Name: evaluate_software_risk_all_agents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.evaluate_software_risk_all_agents() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agent RECORD;
  v_count integer := 0;
  v_errors integer := 0;
BEGIN
  FOR v_agent IN 
    SELECT id, tenant_id, hostname
    FROM agents 
    WHERE archived_at IS NULL AND status = 'active'
    ORDER BY last_heartbeat DESC
  LOOP
    BEGIN
      -- Evaluate risk for each active agent
      PERFORM evaluate_software_risk(v_agent.id);
      v_count := v_count + 1;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
      RAISE WARNING 'Failed to evaluate risk for agent %: %', v_agent.id, SQLERRM;
    END;
  END LOOP;
  
  RETURN jsonb_build_object(
    'agents_evaluated', v_count,
    'errors', v_errors,
    'executed_at', now()
  );
END;
$$;


--
-- Name: evaluate_software_risk_with_reporting(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.evaluate_software_risk_with_reporting() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  agents_processed integer := 0;
  high_risk_count integer := 0;
  result jsonb;
BEGIN
  -- Contar agentes ativos
  SELECT COUNT(*) INTO agents_processed 
  FROM agents 
  WHERE archived_at IS NULL;
  
  -- Contar agentes de alto risco (versão antiga ou offline)
  SELECT COUNT(*) INTO high_risk_count
  FROM agents
  WHERE archived_at IS NULL
    AND (
      agent_version < 'v5.0.0'
      OR last_heartbeat < NOW() - INTERVAL '24 hours'
    );
  
  result := jsonb_build_object(
    'success', true,
    'agents_evaluated', agents_processed,
    'high_risk_agents', high_risk_count,
    'risk_percentage', CASE WHEN agents_processed > 0 
      THEN ROUND(100.0 * high_risk_count / agents_processed, 2) 
      ELSE 0 END,
    'executed_at', NOW()
  );
  
  -- Reportar SUCESSO para cron_health_checks
  INSERT INTO cron_health_checks (cron_name, last_success_at, consecutive_failures, updated_at, last_result)
  VALUES ('evaluate-software-risk-daily', NOW(), 0, NOW(), result)
  ON CONFLICT (cron_name) DO UPDATE SET
    last_success_at = NOW(),
    consecutive_failures = 0,
    last_error = NULL,
    updated_at = NOW(),
    last_result = EXCLUDED.last_result;
  
  RETURN result;
  
EXCEPTION WHEN OTHERS THEN
  INSERT INTO cron_health_checks (cron_name, last_failure_at, last_error, consecutive_failures, updated_at)
  VALUES ('evaluate-software-risk-daily', NOW(), SQLERRM, 1, NOW())
  ON CONFLICT (cron_name) DO UPDATE SET
    last_failure_at = NOW(),
    last_error = SQLERRM,
    consecutive_failures = cron_health_checks.consecutive_failures + 1,
    updated_at = NOW();
  RAISE;
END;
$$;


--
-- Name: FUNCTION evaluate_software_risk_with_reporting(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.evaluate_software_risk_with_reporting() IS 'Avalia risco de software e reporta para cron_health_checks';


--
-- Name: execute_ai_action_rollback(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execute_ai_action_rollback(p_ai_action_id uuid, p_success boolean, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  act RECORD;
BEGIN
  SELECT * INTO act
  FROM public.ai_actions
  WHERE id = p_ai_action_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'AI action not found');
  END IF;

  IF act.rollback_status != 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'No pending rollback');
  END IF;

  UPDATE public.ai_actions
  SET rollback_status = CASE WHEN p_success THEN 'executed' ELSE 'failed' END
  WHERE id = p_ai_action_id;

  INSERT INTO public.decision_events (
    tenant_id,
    rule_code,
    agent_id,
    agent_name,
    action,
    decision_source,
    decision_type,
    evidence,
    created_at
  ) VALUES (
    act.tenant_id,
    'ROLLBACK_EXECUTION',
    act.agent_id,
    act.agent_name,
    'rollback_executed',
    'system',
    'compensating_action',
    jsonb_build_object(
      'ai_action_id', act.id,
      'success', p_success,
      'notes', p_notes
    ),
    NOW()
  );

  RETURN jsonb_build_object('success', true, 'executed', p_success);
END;
$$;


--
-- Name: execute_playbook_actions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execute_playbook_actions(p_execution_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '5min'
    AS $$
DECLARE
  v_execution RECORD;
  v_playbook RECORD;
  v_action RECORD;
  v_result JSONB := '[]'::JSONB;
  v_action_result JSONB;
  v_error_message TEXT;
BEGIN
  -- Buscar execução
  SELECT * INTO v_execution
  FROM playbook_executions
  WHERE id = p_execution_id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Execution not found');
  END IF;
  
  -- Verificar se já está em execução ou finalizada
  IF v_execution.status NOT IN ('pending', 'in_progress') THEN
    RETURN jsonb_build_object('error', 'Execution already processed', 'status', v_execution.status);
  END IF;
  
  -- Marcar como em progresso
  UPDATE playbook_executions
  SET status = 'in_progress', started_at = COALESCE(started_at, NOW())
  WHERE id = p_execution_id;
  
  -- Buscar playbook
  SELECT * INTO v_playbook
  FROM playbooks
  WHERE id = v_execution.playbook_id;
  
  IF NOT FOUND THEN
    UPDATE playbook_executions
    SET status = 'failed', completed_at = NOW(), notes = 'Playbook not found'
    WHERE id = p_execution_id;
    RETURN jsonb_build_object('error', 'Playbook not found');
  END IF;
  
  -- Processar cada ação do playbook
  FOR v_action IN 
    SELECT * FROM playbook_actions 
    WHERE playbook_id = v_playbook.id AND is_enabled = true
    ORDER BY execution_order
  LOOP
    BEGIN
      v_action_result := jsonb_build_object(
        'action_id', v_action.id,
        'action_type', v_action.action_type,
        'status', 'completed',
        'executed_at', NOW()
      );
      
      v_result := v_result || v_action_result;
      
    EXCEPTION WHEN OTHERS THEN
      v_error_message := SQLERRM;
      v_action_result := jsonb_build_object(
        'action_id', v_action.id,
        'action_type', v_action.action_type,
        'status', 'failed',
        'error', v_error_message,
        'executed_at', NOW()
      );
      v_result := v_result || v_action_result;
    END;
  END LOOP;
  
  -- Marcar como concluído
  UPDATE playbook_executions
  SET 
    status = 'completed',
    completed_at = NOW(),
    actions_taken = v_result
  WHERE id = p_execution_id;
  
  RETURN v_result;
  
EXCEPTION WHEN OTHERS THEN
  UPDATE playbook_executions
  SET 
    status = 'failed',
    completed_at = NOW(),
    notes = COALESCE(notes || ' | ', '') || 'Erro: ' || SQLERRM
  WHERE id = p_execution_id;
  
  RETURN jsonb_build_object('error', SQLERRM);
END;
$$;


--
-- Name: execute_rollback_test(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execute_rollback_test(p_tenant_id uuid, p_agent_id uuid DEFAULT NULL::uuid, p_dry_run boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_test_id uuid;
  v_agent record;
  v_steps jsonb := '[]'::jsonb;
  v_step_count int := 0;
  v_total_steps int := 5;
  v_start_time timestamptz := clock_timestamp();
  v_status text := 'passed';
  v_error text;
  v_from_version text;
  v_to_version text;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  -- Auth check
  IF NOT (
    EXISTS (SELECT 1 FROM user_roles WHERE user_id = auth.uid() AND role IN ('admin', 'super_admin') AND tenant_id = p_tenant_id)
    OR EXISTS (SELECT 1 FROM user_roles WHERE user_id = auth.uid() AND role = 'super_admin')
  ) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  -- Get agent info
  IF p_agent_id IS NOT NULL THEN
    SELECT * INTO v_agent FROM agents WHERE id = p_agent_id AND tenant_id = p_tenant_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Agent not found';
    END IF;
    v_from_version := v_agent.agent_version;
  ELSE
    -- Pick first online agent for test
    SELECT * INTO v_agent FROM agents WHERE tenant_id = p_tenant_id AND status = 'healthy' LIMIT 1;
    v_from_version := COALESCE(v_agent.agent_version, 'unknown');
  END IF;

  -- Determine rollback target version
  SELECT to_version INTO v_to_version
  FROM agent_rollback_events
  WHERE tenant_id = p_tenant_id
  ORDER BY created_at DESC LIMIT 1;
  
  v_to_version := COALESCE(v_to_version, 'previous');

  -- Create test record
  INSERT INTO rollback_test_results (tenant_id, agent_id, dry_run, from_version, to_version, test_status, steps_total, initiated_by)
  VALUES (p_tenant_id, p_agent_id, p_dry_run, v_from_version, v_to_version, 'running', v_total_steps, auth.uid())
  RETURNING id INTO v_test_id;

  -- Step 1: Verify agent build cache exists
  v_step_count := v_step_count + 1;
  IF EXISTS (SELECT 1 FROM agent_builds WHERE agent_id = COALESCE(p_agent_id, v_agent.id) AND build_status = 'completed') THEN
    v_steps := v_steps || jsonb_build_object('step', v_step_count, 'name', 'build_cache_check', 'status', 'passed', 'detail', 'Previous build found in cache');
  ELSE
    v_steps := v_steps || jsonb_build_object('step', v_step_count, 'name', 'build_cache_check', 'status', 'warning', 'detail', 'No previous build in cache - rebuild required');
  END IF;

  -- Step 2: Verify rollback state machine allows transition
  v_step_count := v_step_count + 1;
  IF v_agent.status IS NOT NULL AND v_agent.status IN ('healthy', 'degraded', 'updating', 'safe_mode') THEN
    v_steps := v_steps || jsonb_build_object('step', v_step_count, 'name', 'state_machine_check', 'status', 'passed', 'detail', format('Agent state %s allows rollback transition', v_agent.status));
  ELSE
    v_steps := v_steps || jsonb_build_object('step', v_step_count, 'name', 'state_machine_check', 'status', 'failed', 'detail', format('Agent state %s does not allow rollback', COALESCE(v_agent.status, 'unknown')));
    v_status := 'failed';
    v_error := 'Agent state does not allow rollback';
  END IF;

  -- Step 3: Verify file integrity baseline exists
  v_step_count := v_step_count + 1;
  IF EXISTS (SELECT 1 FROM agent_file_integrity WHERE agent_id = COALESCE(p_agent_id, v_agent.id) LIMIT 1) THEN
    v_steps := v_steps || jsonb_build_object('step', v_step_count, 'name', 'integrity_baseline', 'status', 'passed', 'detail', 'File integrity baseline exists for comparison');
  ELSE
    v_steps := v_steps || jsonb_build_object('step', v_step_count, 'name', 'integrity_baseline', 'status', 'warning', 'detail', 'No integrity baseline - post-rollback verification limited');
  END IF;

  -- Step 4: Verify execution chain continuity
  v_step_count := v_step_count + 1;
  IF EXISTS (SELECT 1 FROM agent_execution_chain WHERE agent_id = COALESCE(p_agent_id, v_agent.id)) THEN
    v_steps := v_steps || jsonb_build_object('step', v_step_count, 'name', 'execution_chain', 'status', 'passed', 'detail', 'Execution chain intact - audit trail preserved');
  ELSE
    v_steps := v_steps || jsonb_build_object('step', v_step_count, 'name', 'execution_chain', 'status', 'warning', 'detail', 'No execution chain - rollback audit may be incomplete');
  END IF;

  -- Step 5: Simulate rollback event creation (dry-run only logs, real creates event)
  v_step_count := v_step_count + 1;
  IF p_dry_run THEN
    v_steps := v_steps || jsonb_build_object('step', v_step_count, 'name', 'rollback_simulation', 'status', 'passed', 'detail', format('DRY RUN: Would rollback %s → %s', v_from_version, v_to_version));
  ELSE
    -- Real rollback: create rollback event
    INSERT INTO agent_rollback_events (agent_id, tenant_id, from_version, to_version, reason, status)
    VALUES (COALESCE(p_agent_id, v_agent.id), p_tenant_id, v_from_version, v_to_version, 'Manual rollback test', 'initiated');
    v_steps := v_steps || jsonb_build_object('step', v_step_count, 'name', 'rollback_execution', 'status', 'passed', 'detail', format('Rollback event created: %s → %s', v_from_version, v_to_version));
  END IF;

  -- Finalize test result
  UPDATE rollback_test_results
  SET test_status = v_status,
      steps_executed = v_steps,
      error_message = v_error,
      duration_ms = EXTRACT(MILLISECOND FROM clock_timestamp() - v_start_time)::int,
      completed_at = now()
  WHERE id = v_test_id;

  RETURN jsonb_build_object(
    'test_id', v_test_id,
    'status', v_status,
    'dry_run', p_dry_run,
    'from_version', v_from_version,
    'to_version', v_to_version,
    'steps', v_steps,
    'duration_ms', EXTRACT(MILLISECOND FROM clock_timestamp() - v_start_time)::int
  );
END;
$$;


--
-- Name: execute_with_timeout(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execute_with_timeout(p_sql text, p_timeout_ms integer DEFAULT 30000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result JSONB;
  v_old_timeout TEXT;
BEGIN
  SELECT current_setting('statement_timeout') INTO v_old_timeout;
  EXECUTE format('SET LOCAL statement_timeout = %L', p_timeout_ms || 'ms');
  EXECUTE p_sql INTO v_result;
  EXECUTE format('SET LOCAL statement_timeout = %L', v_old_timeout);
  RETURN v_result;
EXCEPTION WHEN OTHERS THEN
  EXECUTE format('SET LOCAL statement_timeout = %L', v_old_timeout);
  RAISE;
END;
$$;


--
-- Name: finalize_job_execution(uuid, uuid, text, integer, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_job_execution(p_execution_id uuid, p_agent_id uuid, p_status text, p_exit_code integer DEFAULT NULL::integer, p_output jsonb DEFAULT NULL::jsonb, p_error_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_execution job_executions%ROWTYPE;
  v_caller_tenant uuid; v_agent_tenant uuid;
BEGIN
  v_caller_tenant := get_active_tenant_id();
  SELECT tenant_id INTO v_agent_tenant FROM agents WHERE id = p_agent_id;
  IF v_caller_tenant IS NOT NULL AND v_agent_tenant IS NOT NULL AND v_agent_tenant != v_caller_tenant AND NOT is_current_super_admin() THEN
    INSERT INTO security_logs (tenant_id, event_type, severity, details)
    VALUES (v_caller_tenant, 'cross_tenant_blocked', 'critical',
      jsonb_build_object('function', 'finalize_job_execution', 'target_agent', p_agent_id));
    RETURN jsonb_build_object('success', false, 'error', 'TENANT_MISMATCH');
  END IF;
  SELECT * INTO v_execution FROM job_executions WHERE id = p_execution_id AND agent_id = p_agent_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'EXECUTION_NOT_FOUND'; END IF;
  IF v_execution.status IN ('completed', 'failed', 'cancelled', 'done') THEN
    RETURN jsonb_build_object('success', true, 'message', 'Already finalized', 'status', v_execution.status);
  END IF;
  UPDATE job_executions SET status = p_status, exit_code = p_exit_code,
    finished_at = now(), completed_at = now() WHERE id = p_execution_id;
  UPDATE jobs SET status = CASE WHEN p_status = 'completed' THEN 'completed' ELSE 'failed' END,
    completed_at = now() WHERE id = v_execution.job_id AND status NOT IN ('completed', 'failed', 'cancelled');
  RETURN jsonb_build_object('success', true, 'status', p_status);
END;
$$;


