--
-- Name: finalize_job_execution(uuid, uuid, uuid, text, timestamp with time zone, timestamp with time zone, text, text, numeric, text, boolean, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_job_execution(p_execution_id uuid, p_agent_id uuid, p_job_id uuid, p_status text, p_started_at timestamp with time zone, p_finished_at timestamp with time zone, p_output_hash text DEFAULT NULL::text, p_error_message text DEFAULT NULL::text, p_execution_time_seconds numeric DEFAULT NULL::numeric, p_result_signature text DEFAULT NULL::text, p_signature_verified boolean DEFAULT NULL::boolean, p_execution_hash text DEFAULT NULL::text, p_previous_execution_hash text DEFAULT NULL::text, p_execution_index bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_execution job_executions%ROWTYPE;
  v_caller_tenant uuid; v_agent_tenant uuid;
BEGIN
  v_caller_tenant := get_active_tenant_id();
  SELECT tenant_id INTO v_agent_tenant FROM agents WHERE id = p_agent_id;
  IF v_caller_tenant IS NOT NULL AND v_agent_tenant IS NOT NULL AND v_agent_tenant != v_caller_tenant AND NOT is_current_super_admin() THEN
    INSERT INTO security_logs (tenant_id, event_type, severity, details)
    VALUES (v_caller_tenant, 'cross_tenant_blocked', 'critical',
      jsonb_build_object('function', 'finalize_job_execution_full', 'target_agent', p_agent_id));
    RETURN jsonb_build_object('success', false, 'error', 'TENANT_MISMATCH');
  END IF;

  SELECT * INTO v_execution FROM job_executions WHERE id = p_execution_id AND agent_id = p_agent_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'EXECUTION_NOT_FOUND'; END IF;
  IF v_execution.status IN ('completed', 'failed', 'cancelled', 'done') THEN
    RETURN jsonb_build_object('success', true, 'message', 'Already finalized', 'status', v_execution.status);
  END IF;

  UPDATE job_executions SET
    status = p_status, started_at = p_started_at, completed_at = p_finished_at,
    output_hash = p_output_hash, error_message = p_error_message,
    execution_time_seconds = p_execution_time_seconds, result_signature = p_result_signature,
    signature_verified = p_signature_verified, execution_hash = p_execution_hash,
    previous_execution_hash = p_previous_execution_hash, execution_index = p_execution_index
  WHERE id = p_execution_id;

  UPDATE jobs SET status = CASE WHEN p_status = 'completed' THEN 'completed' ELSE 'failed' END,
    completed_at = now() WHERE id = p_job_id AND status NOT IN ('completed', 'failed', 'cancelled');

  RETURN jsonb_build_object('success', true, 'status', p_status);
END;
$$;


--
-- Name: find_unsafe_definer_functions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_unsafe_definer_functions() RETURNS TABLE(proname text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.proname::text
  FROM pg_proc p
  JOIN pg_namespace n ON p.pronamespace = n.oid
  WHERE p.prosecdef = true
    AND n.nspname = 'public'
    AND (p.proconfig IS NULL 
         OR NOT p.proconfig @> ARRAY['search_path=public']);
$$;


--
-- Name: flag_critical_alerts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flag_critical_alerts() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.severity = 'critical' THEN
    NEW.requires_human_decision := true;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_agent_reentry_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_agent_reentry_check() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Se agente está voltando de offline para online
  IF OLD.status = 'offline' AND NEW.status = 'online' THEN
    -- Se ficou offline por mais de 7 dias
    IF OLD.offline_detected_at IS NOT NULL 
       AND OLD.offline_detected_at < NOW() - INTERVAL '7 days' THEN
      NEW.requires_revalidation := true;
      NEW.revalidation_reason := 'Offline por mais de 7 dias - requer validação antes de processar jobs críticos';
      NEW.revalidation_required_at := NOW();
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_alert_agent_reentry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_alert_agent_reentry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.requires_revalidation = true AND (OLD.requires_revalidation IS NULL OR OLD.requires_revalidation = false) THEN
    INSERT INTO system_alerts (
      tenant_id, severity, type, title, message, agent_id, created_at
    ) VALUES (
      NEW.tenant_id, 
      'medium', 
      'agent_reentry_validation',
      'Agente requer revalidação',
      format('O agente %s ficou offline por período prolongado e requer validação antes de processar jobs críticos.', NEW.agent_name),
      NEW.id,
      NOW()
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: force_review_unreviewed_dlq(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.force_review_unreviewed_dlq(p_reviewer_id uuid, p_max_items integer DEFAULT 100) RETURNS TABLE(reviewed_count integer, flagged_suspicious integer, items_processed uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reviewed int := 0;
  v_flagged int := 0;
  v_items uuid[];
BEGIN
  -- Marcar itens antigos como requiring review
  WITH updated AS (
    UPDATE public.failed_jobs_dlq
    SET 
      review_required = true,
      flagged_suspicious = CASE 
        WHEN failure_class IN ('security', 'critical', 'auth_failure') THEN true
        WHEN retry_count > 5 THEN true
        ELSE false
      END,
      auto_flagged_reason = CASE 
        WHEN failure_class IN ('security', 'critical', 'auth_failure') THEN 'security_pattern'
        WHEN retry_count > 5 THEN 'excessive_retries'
        ELSE NULL
      END
    WHERE status != 'resolved'
      AND resolved_by IS NULL
      AND created_at < now() - interval '24 hours'
    RETURNING id, flagged_suspicious
  )
  SELECT 
    COUNT(*)::int,
    COUNT(*) FILTER (WHERE flagged_suspicious)::int,
    array_agg(id)
  INTO v_reviewed, v_flagged, v_items
  FROM updated;

  RETURN QUERY SELECT v_reviewed, v_flagged, v_items;
END;
$$;


--
-- Name: generate_ai_actions_from_insights(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_ai_actions_from_insights() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_insights_processed int := 0;
  v_actions_created int := 0;
  v_insight RECORD;
  v_action_type text;
  v_action_payload jsonb;
BEGIN
  -- Processa insights críticos não reconhecidos sem ação associada
  FOR v_insight IN
    SELECT i.*
    FROM ai_insights i
    LEFT JOIN ai_actions a ON a.insight_id = i.id
    WHERE i.severity IN ('critical', 'high')
      AND i.acknowledged = false
      AND a.id IS NULL
      AND i.created_at > NOW() - INTERVAL '7 days'
    ORDER BY 
      CASE i.severity 
        WHEN 'critical' THEN 1 
        WHEN 'high' THEN 2 
        ELSE 3 
      END,
      i.created_at DESC
    LIMIT 20
  LOOP
    v_insights_processed := v_insights_processed + 1;
    
    -- Determina tipo de ação baseado na categoria do insight
    CASE 
      WHEN v_insight.insight_type ILIKE '%agent%' OR v_insight.insight_type ILIKE '%health%' THEN
        v_action_type := 'suggest_agent_restart';
        v_action_payload := jsonb_build_object(
          'insight_id', v_insight.id,
          'insight_title', v_insight.title,
          'insight_type', v_insight.insight_type,
          'suggested_action', 'Reiniciar agente ou verificar conectividade'
        );
      WHEN v_insight.insight_type ILIKE '%security%' OR v_insight.insight_type ILIKE '%threat%' THEN
        v_action_type := 'create_system_alert';
        v_action_payload := jsonb_build_object(
          'insight_id', v_insight.id,
          'title', 'Alerta de Segurança: ' || v_insight.title,
          'message', v_insight.description,
          'severity', v_insight.severity,
          'category', 'security'
        );
      WHEN v_insight.insight_type ILIKE '%job%' OR v_insight.insight_type ILIKE '%execution%' THEN
        v_action_type := 'suggest_job_cleanup';
        v_action_payload := jsonb_build_object(
          'insight_id', v_insight.id,
          'insight_title', v_insight.title,
          'suggested_action', 'Limpar jobs travados ou cancelar jobs problemáticos'
        );
      WHEN v_insight.insight_type ILIKE '%config%' OR v_insight.insight_type ILIKE '%policy%' THEN
        v_action_type := 'suggest_config_change';
        v_action_payload := jsonb_build_object(
          'insight_id', v_insight.id,
          'insight_title', v_insight.title,
          'suggested_action', 'Revisar configuração do sistema'
        );
      ELSE
        v_action_type := 'create_system_alert';
        v_action_payload := jsonb_build_object(
          'insight_id', v_insight.id,
          'title', v_insight.title,
          'message', v_insight.description,
          'severity', v_insight.severity
        );
    END CASE;
    
    -- Cria a ação
    INSERT INTO ai_actions (
      tenant_id,
      insight_id,
      action_type,
      action_payload,
      status
    ) VALUES (
      v_insight.tenant_id,
      v_insight.id,
      v_action_type,
      v_action_payload,
      'pending'
    );
    
    v_actions_created := v_actions_created + 1;
  END LOOP;
  
  RETURN jsonb_build_object(
    'success', true,
    'insights_processed', v_insights_processed,
    'actions_created', v_actions_created,
    'processed_at', NOW()
  );
END;
$$;


--
-- Name: generate_audit_reason_tree(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_audit_reason_tree(p_tenant_id uuid, p_score integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  reasons jsonb := '[]'::jsonb;
  v_ai_total integer;
  v_human_reviewed integer;
  v_shadow_validated integer;
  v_decision_events integer;
  v_dlq_suspicious integer;
  v_kill_switch boolean;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  -- Count AI actions
  SELECT 
    COUNT(*),
    COUNT(*) FILTER (WHERE human_reviewed = true),
    COUNT(*) FILTER (WHERE ai_validation_status IS NOT NULL)
  INTO v_ai_total, v_human_reviewed, v_shadow_validated
  FROM public.ai_actions
  WHERE tenant_id = p_tenant_id;

  -- Count decision events
  SELECT COUNT(DISTINCT (evidence->>'ai_action_id')::uuid)
  INTO v_decision_events
  FROM public.decision_events
  WHERE tenant_id = p_tenant_id;

  -- Count suspicious DLQ
  SELECT COUNT(*)
  INTO v_dlq_suspicious
  FROM public.failed_jobs_dlq
  WHERE tenant_id = p_tenant_id
    AND classification = 'suspicious'
    AND review_required = true;

  -- Check kill switch
  SELECT EXISTS (
    SELECT 1 FROM public.system_kill_switch
    WHERE tenant_id = p_tenant_id
  ) INTO v_kill_switch;

  -- Build reason tree
  
  -- Governance: no human review
  IF v_ai_total > 0 AND v_human_reviewed = 0 THEN
    reasons := reasons || jsonb_build_array(
      jsonb_build_object(
        'dimension', 'governance',
        'impact', -20,
        'signal', 'no_human_review',
        'evidence', jsonb_build_object(
          'ai_actions_total', v_ai_total,
          'human_reviewed', v_human_reviewed
        )
      )
    );
  ELSIF v_ai_total > 0 AND v_human_reviewed > 0 THEN
    reasons := reasons || jsonb_build_array(
      jsonb_build_object(
        'dimension', 'governance',
        'impact', 10,
        'signal', 'human_review_present',
        'evidence', jsonb_build_object(
          'ai_actions_total', v_ai_total,
          'human_reviewed', v_human_reviewed,
          'rate', ROUND((v_human_reviewed::numeric / v_ai_total) * 100, 1)
        )
      )
    );
  END IF;

  -- Safety: shadow validation
  IF v_shadow_validated > 0 THEN
    reasons := reasons || jsonb_build_array(
      jsonb_build_object(
        'dimension', 'safety',
        'impact', 15,
        'signal', 'shadow_validation_active',
        'evidence', jsonb_build_object(
          'validated_count', v_shadow_validated,
          'rate', CASE WHEN v_ai_total > 0 
            THEN ROUND((v_shadow_validated::numeric / v_ai_total) * 100, 1)
            ELSE 0 END
        )
      )
    );
  END IF;

  -- Traceability: decision events
  IF v_ai_total > 0 AND v_decision_events > 0 THEN
    reasons := reasons || jsonb_build_array(
      jsonb_build_object(
        'dimension', 'traceability',
        'impact', 15,
        'signal', 'decision_events_linked',
        'evidence', jsonb_build_object(
          'decision_events', v_decision_events,
          'coverage', ROUND((v_decision_events::numeric / v_ai_total) * 100, 1)
        )
      )
    );
  END IF;

  -- Resilience: kill switch configured
  IF v_kill_switch THEN
    reasons := reasons || jsonb_build_array(
      jsonb_build_object(
        'dimension', 'resilience',
        'impact', 10,
        'signal', 'kill_switch_configured'
      )
    );
  END IF;

  -- Risk: suspicious DLQ
  IF v_dlq_suspicious > 0 THEN
    reasons := reasons || jsonb_build_array(
      jsonb_build_object(
        'dimension', 'risk',
        'impact', -25,
        'signal', 'dlq_suspicious_unreviewed',
        'evidence', jsonb_build_object(
          'suspicious_count', v_dlq_suspicious
        )
      )
    );
  END IF;

  RETURN reasons;
END;
$$;


--
-- Name: generate_enforcement_decision_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_enforcement_decision_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO decision_events (
    tenant_id, rule_code, action,
    agent_ids, severity, evidence,
    actions_executed
  ) VALUES (
    NEW.tenant_id,
    'POLICY_ENFORCED',
    NEW.action_taken,
    CASE WHEN NEW.agent_id IS NOT NULL THEN ARRAY[NEW.agent_id] ELSE ARRAY[]::uuid[] END,
    CASE WHEN NEW.blocked THEN 'medium' ELSE 'low' END,
    jsonb_build_object(
      'source', 'policy_enforcement_trigger',
      'policy_id', NEW.policy_id,
      'rule_type', NEW.rule_type,
      'target', NEW.target
    ),
    ARRAY[NEW.action_taken]::text[]
  );
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$;


