--
-- Name: generate_telemetry_hash(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_telemetry_hash() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.telemetry_hash := encode(
    extensions.digest(
      convert_to(
        COALESCE(NEW.agent_id::text, '') ||
        COALESCE(NEW.agent_name, 'unknown') ||
        COALESCE(NEW.event_type, '') ||
        date_trunc('minute', COALESCE(NEW.created_at, now()))::text ||
        COALESCE(NEW.platform, 'unknown'),
        'UTF8'
      ),
      'sha256'::text
    ),
    'hex'
  );
  RETURN NEW;
END;
$$;


--
-- Name: get_action_center_feed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_action_center_feed(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
  urgent_items jsonb;
  recommended_items jsonb;
  informational_items jsonb;
  healthy_count integer;
  v_user_tenant_id uuid;
BEGIN
  -- Validate user has access to this tenant
  SELECT tenant_id INTO v_user_tenant_id
  FROM user_roles
  WHERE user_id = auth.uid()
    AND tenant_id = p_tenant_id
  LIMIT 1;

  IF v_user_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Access denied to tenant %', p_tenant_id;
  END IF;

  -- Urgent: critical/high severity or priority_score >= 70
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'item_id', item_id,
      'source_type', source_type,
      'agent_id', agent_id,
      'agent_name', agent_name,
      'hostname', hostname,
      'title', title,
      'description', description,
      'severity', severity,
      'risk_score', risk_score,
      'context', context,
      'created_at', created_at,
      'trigger_type', trigger_type,
      'playbook_id', playbook_id,
      'priority_score', priority_score
    ) ORDER BY priority_score DESC
  ), '[]'::jsonb)
  INTO urgent_items
  FROM v_action_center
  WHERE tenant_id = p_tenant_id
    AND (severity IN ('critical', 'high') OR priority_score >= 70);

  -- Recommended: medium severity or priority_score between 30-70
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'item_id', item_id,
      'source_type', source_type,
      'agent_id', agent_id,
      'agent_name', agent_name,
      'hostname', hostname,
      'title', title,
      'description', description,
      'severity', severity,
      'risk_score', risk_score,
      'context', context,
      'created_at', created_at,
      'trigger_type', trigger_type,
      'playbook_id', playbook_id,
      'priority_score', priority_score
    ) ORDER BY priority_score DESC
  ), '[]'::jsonb)
  INTO recommended_items
  FROM v_action_center
  WHERE tenant_id = p_tenant_id
    AND severity NOT IN ('critical', 'high')
    AND priority_score >= 30
    AND priority_score < 70;

  -- Informational: low priority items
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'item_id', item_id,
      'source_type', source_type,
      'agent_id', agent_id,
      'agent_name', agent_name,
      'hostname', hostname,
      'title', title,
      'description', description,
      'severity', severity,
      'risk_score', risk_score,
      'context', context,
      'created_at', created_at,
      'trigger_type', trigger_type,
      'playbook_id', playbook_id,
      'priority_score', priority_score
    ) ORDER BY priority_score DESC
  ), '[]'::jsonb)
  INTO informational_items
  FROM v_action_center
  WHERE tenant_id = p_tenant_id
    AND priority_score < 30;

  -- Count healthy agents (online, no issues)
  SELECT COUNT(*)
  INTO healthy_count
  FROM agents
  WHERE tenant_id = p_tenant_id
    AND status = 'online'
    AND agent_state = 'healthy';

  -- Build final result
  result := jsonb_build_object(
    'urgent', urgent_items,
    'recommended', recommended_items,
    'informational', informational_items,
    'healthy_count', healthy_count,
    'generated_at', now()
  );

  RETURN result;
END;
$$;


--
-- Name: get_active_tenant_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_tenant_id() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_claim text;
BEGIN
  v_claim := current_setting('request.jwt.claims', true)::json->'app_metadata'->>'active_tenant_id';
  
  IF v_claim IS NOT NULL AND v_claim != '' THEN
    RETURN v_claim::uuid;
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: FUNCTION get_active_tenant_id(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_active_tenant_id() IS 'ADR-028 P3-01: Returns active tenant from JWT with sampled logging for NULL claims';


--
-- Name: get_adaptive_blast_radius(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_adaptive_blast_radius(p_tenant_id uuid, p_action_type text, p_severity text DEFAULT 'medium'::text) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_max_percent numeric;
  v_config record;
  v_is_bh boolean;
BEGIN
  SELECT * INTO v_config FROM adaptive_blast_radius_config
  WHERE tenant_id = p_tenant_id AND action_type = p_action_type AND severity = p_severity LIMIT 1;

  IF FOUND THEN
    v_is_bh := (extract(dow FROM now()) = ANY(v_config.business_days)
      AND now()::time BETWEEN v_config.business_hours_start::time AND v_config.business_hours_end::time);
    v_max_percent := CASE WHEN v_is_bh THEN v_config.business_hours_max_percent ELSE v_config.off_hours_max_percent END;
  ELSE
    v_max_percent := CASE p_severity WHEN 'critical' THEN 80 WHEN 'high' THEN 50 WHEN 'medium' THEN 30 WHEN 'low' THEN 15 ELSE 30 END;
    IF p_action_type IN ('delete', 'quarantine_file', 'kill_process') THEN v_max_percent := v_max_percent * 0.5; END IF;
  END IF;
  RETURN v_max_percent;
END;
$$;


--
-- Name: get_agent_disk_details(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_agent_disk_details(p_agent_id uuid) RETURNS TABLE(drive_letter text, drive_label text, drive_type text, total_gb numeric, used_gb numeric, free_gb numeric, usage_percent numeric, is_system_drive boolean, collected_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_tenant uuid; v_agent_tenant uuid;
BEGIN
  v_caller_tenant := get_active_tenant_id();
  SELECT tenant_id INTO v_agent_tenant FROM agents WHERE id = p_agent_id;
  IF v_caller_tenant IS NOT NULL AND v_agent_tenant IS NOT NULL AND v_agent_tenant != v_caller_tenant AND NOT is_current_super_admin() THEN
    INSERT INTO security_logs (tenant_id, event_type, severity, details)
    VALUES (v_caller_tenant, 'cross_tenant_blocked', 'critical',
      jsonb_build_object('function', 'get_agent_disk_details', 'target_agent', p_agent_id));
    RETURN;
  END IF;
  RETURN QUERY
  SELECT DISTINCT ON (dm.drive_letter) dm.drive_letter, dm.drive_label, dm.drive_type,
    dm.total_gb, dm.used_gb, dm.free_gb, dm.usage_percent, dm.is_system_drive, dm.collected_at
  FROM agent_disk_metrics dm WHERE dm.agent_id = p_agent_id ORDER BY dm.drive_letter, dm.collected_at DESC;
END;
$$;


--
-- Name: get_agent_health_metrics(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_agent_health_metrics(p_tenant_id uuid) RETURNS TABLE(id uuid, agent_name text, hostname text, os_type text, os_version text, agent_version text, status text, last_heartbeat timestamp with time zone, enrolled_at timestamp with time zone, health_status text, seconds_since_heartbeat integer, is_throttled boolean, throttle_reason text, is_isolated boolean, isolation_reason text, is_in_safe_mode boolean, safe_mode_reason text, has_critical_alerts boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);

  RETURN QUERY
  SELECT
    a.id,
    a.agent_name,
    a.hostname,
    a.os_type,
    a.os_version,
    a.agent_version,
    a.status,
    a.last_heartbeat,
    a.enrolled_at,
    CASE
      WHEN a.last_heartbeat IS NULL THEN 'never_connected'::text
      WHEN a.last_heartbeat < NOW() - INTERVAL '30 minutes' THEN 'offline'::text
      WHEN a.last_heartbeat < NOW() - INTERVAL '12 minutes' THEN 'warning'::text
      ELSE 'healthy'::text
    END AS health_status,
    EXTRACT(EPOCH FROM (NOW() - a.last_heartbeat))::integer AS seconds_since_heartbeat,
    COALESCE(a.is_throttled, false) AS is_throttled,
    a.throttle_reason,
    COALESCE(a.is_isolated, false) AS is_isolated,
    a.isolation_reason,
    (a.safe_mode_entered_at IS NOT NULL) AS is_in_safe_mode,
    a.safe_mode_reason,
    EXISTS (
      SELECT 1
      FROM system_alerts sa
      WHERE sa.agent_id = a.id
        AND sa.resolved = false
        AND sa.severity IN ('critical', 'high')
    ) AS has_critical_alerts
  FROM agents a
  WHERE a.tenant_id = p_tenant_id
    AND a.archived_at IS NULL
    AND a.status != 'archived'
  ORDER BY a.agent_name;
END;
$$;


--
-- Name: FUNCTION get_agent_health_metrics(p_tenant_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_agent_health_metrics(p_tenant_id uuid) IS 'Retorna métricas de saúde dos agentes. Thresholds: healthy < 2min, warning 2-10min, offline > 10min.';


