--
-- Name: get_agent_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_agent_snapshot(p_agent_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'agent_id', a.id,
    'tenant_id', a.tenant_id,
    'hostname', a.hostname,
    'os_type', a.os_type,
    'version', a.agent_version,
    'last_heartbeat', a.last_heartbeat,
    'online', a.last_heartbeat > (now() - interval '2 minutes'),
    'latency_ms', EXTRACT(epoch FROM now() - a.last_heartbeat) * 1000::numeric,
    'agent_state', a.agent_state,
    'safe_mode', COALESCE(a.safe_mode_entered_at IS NOT NULL, false),
    'safe_mode_reason', a.safe_mode_reason,
    'is_isolated', COALESCE(a.is_isolated, false),
    'is_throttled', COALESCE(a.is_throttled, false),
    'active_issues', COALESCE((SELECT count(*) FROM system_alerts sa WHERE sa.agent_id = a.id AND sa.resolved_at IS NULL), 0),
    'unresolved_insights', COALESCE((SELECT count(*) FROM ai_insights ai WHERE ai.agent_id = a.id AND ai.status = 'open'), 0)
  )
  FROM agents a
  WHERE a.id = p_agent_id
    AND a.archived_at IS NULL
    AND (
      -- Tenant isolation: check JWT claim first
      a.tenant_id = get_active_tenant_id()
      OR
      -- Fallback: check user_roles when JWT claim not set
      (get_active_tenant_id() IS NULL AND auth.uid() IS NOT NULL AND EXISTS (
        SELECT 1 FROM user_roles ur 
        WHERE ur.user_id = auth.uid() 
          AND ur.tenant_id = a.tenant_id
      ))
      OR
      -- Super admin bypass
      is_current_super_admin()
      OR
      -- Service role bypass (edge functions)
      (auth.uid() IS NULL AND current_setting('role', true) = 'service_role')
    );
$$;


--
-- Name: get_agents_list(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_agents_list(p_tenant_id uuid, p_include_archived boolean DEFAULT false) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT is_current_super_admin() 
     AND (get_active_tenant_id() IS NULL OR p_tenant_id IS DISTINCT FROM get_active_tenant_id()) THEN
    RAISE EXCEPTION 'TENANT_MISMATCH: Caller does not belong to requested tenant (INV-001)';
  END IF;
  RETURN QUERY
  SELECT jsonb_build_object(
    'id', id, 'tenant_id', tenant_id, 'agent_name', agent_name,
    'hostname', hostname, 'status', status, 'os_type', os_type,
    'os_version', os_version, 'agent_version', agent_version,
    'agent_version_code', agent_version_code, 'display_name', display_name,
    'enrolled_at', enrolled_at, 'last_heartbeat', last_heartbeat,
    'last_block_sync_at', last_block_sync_at, 'agent_state', agent_state,
    'is_throttled', is_throttled, 'is_isolated', is_isolated,
    'skip_firewall_remediation', COALESCE(skip_firewall_remediation, false),
    'archived_at', archived_at
  )
  FROM agents
  WHERE tenant_id = p_tenant_id
    AND (p_include_archived OR archived_at IS NULL);
END;
$$;


--
-- Name: FUNCTION get_agents_list(p_tenant_id uuid, p_include_archived boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_agents_list(p_tenant_id uuid, p_include_archived boolean) IS 'RPC SECURITY DEFINER para lista de agentes com parâmetro tenant_id explícito. Não depende de JWT claims.';


--
-- Name: get_agents_snapshots_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_agents_snapshots_list(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_effective_tenant_id uuid;
BEGIN
  v_effective_tenant_id := COALESCE(p_tenant_id, get_active_tenant_id());
  
  IF v_effective_tenant_id IS NOT NULL AND NOT is_current_super_admin() THEN
    PERFORM public._assert_caller_tenant(v_effective_tenant_id);
  END IF;
  
  RETURN QUERY
  SELECT jsonb_build_object(
    'agent_id', a.id, 'tenant_id', a.tenant_id, 'hostname', a.hostname,
    'os_type', a.os_type, 'version', a.agent_version, 'last_heartbeat', a.last_heartbeat,
    'online', a.last_heartbeat > (now() - interval '15 minutes'),
    'latency_ms', EXTRACT(epoch FROM now() - a.last_heartbeat) * 1000::numeric,
    'agent_state', a.agent_state,
    'safe_mode', COALESCE(a.safe_mode_entered_at IS NOT NULL, false),
    'safe_mode_reason', a.safe_mode_reason,
    'is_isolated', COALESCE(a.is_isolated, false),
    'is_throttled', COALESCE(a.is_throttled, false),
    'active_issues', 0::bigint,
    'unresolved_insights', (SELECT count(*) FROM ai_insights ai WHERE ai.agent_id = a.id AND ai.status = 'open'),
    'snapshot_at', now()
  )
  FROM agents a
  WHERE a.archived_at IS NULL AND a.status = 'active'
    AND a.tenant_id = v_effective_tenant_id;
END;
$$;


--
-- Name: FUNCTION get_agents_snapshots_list(p_tenant_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_agents_snapshots_list(p_tenant_id uuid) IS 'RPC SECURITY DEFINER para lista de snapshots de agentes. Prioriza p_tenant_id explícito, depois JWT, depois user_roles como fallback.';


--
-- Name: get_ai_provider_scores(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ai_provider_scores() RETURNS TABLE(provider text, avg_latency_ms numeric, success_rate numeric, requests_count bigint, score numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH recent_stats AS (
    SELECT 
      COALESCE(provider, 'unknown') as provider,
      AVG(latency_ms) as avg_latency,
      AVG(CASE WHEN success THEN 1.0 ELSE 0.0 END) as success_rate,
      COUNT(*) as requests
    FROM ai_inference_metrics
    WHERE created_at > NOW() - INTERVAL '1 hour'
    GROUP BY COALESCE(provider, 'unknown')
  )
  SELECT 
    provider,
    ROUND(avg_latency) as avg_latency_ms,
    ROUND(success_rate * 100, 1) as success_rate,
    requests as requests_count,
    -- Score: lower is better (latency * 0.5 + error_penalty * 0.5)
    ROUND(
      avg_latency * 0.5 + 
      (1 - success_rate) * 10000 * 0.5
    , 2) as score
  FROM recent_stats
  ORDER BY score ASC;
$$;


--
-- Name: FUNCTION get_ai_provider_scores(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_ai_provider_scores() IS 'Returns AI provider scores for intelligent routing (lower score = better)';


--
-- Name: get_alert_decision_chain(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_alert_decision_chain(p_alert_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
  v_caller_tenant uuid;
  v_alert_tenant uuid;
BEGIN
  -- SSA-SEC: Tenant isolation guard
  v_caller_tenant := get_active_tenant_id();
  IF v_caller_tenant IS NULL THEN
    RAISE EXCEPTION 'TENANT_REQUIRED: No active tenant';
  END IF;
  
  -- Verify alert belongs to caller's tenant
  SELECT sa.tenant_id INTO v_alert_tenant
  FROM system_alerts sa WHERE sa.id = p_alert_id;
  
  IF v_alert_tenant IS NULL THEN
    RETURN NULL;
  END IF;
  
  IF v_alert_tenant != v_caller_tenant THEN
    -- Log cross-tenant attempt
    INSERT INTO security_logs (event_type, severity, details, tenant_id)
    VALUES ('cross_tenant_attempt', 'high', 
      jsonb_build_object('function', 'get_alert_decision_chain', 'target_alert', p_alert_id, 'caller_tenant', v_caller_tenant, 'target_tenant', v_alert_tenant),
      v_caller_tenant);
    RAISE EXCEPTION 'TENANT_MISMATCH: Alert does not belong to caller tenant';
  END IF;

  SELECT jsonb_build_object(
    'alert_id', p_alert_id,
    'current_state', CASE WHEN sa.resolved THEN 'resolved' ELSE 'open' END,
    'reason_tree', (
      SELECT jsonb_agg(
        jsonb_build_object(
          'at', e.created_at,
          'event_type', e.event_type,
          'source', e.source,
          'reason', e.reason,
          'evidence', e.evidence
        ) ORDER BY e.created_at
      )
      FROM (
        SELECT sa2.created_at, 'alert_created' AS event_type, 'system' AS source,
          sa2.title AS reason,
          jsonb_build_object('severity', sa2.severity, 'alert_type', sa2.alert_type, 'message', sa2.message) AS evidence
        FROM system_alerts sa2 WHERE sa2.id = p_alert_id
        UNION ALL
        SELECT de.created_at, de.decision_type AS event_type, de.decision_source AS source,
          de.action AS reason, de.evidence
        FROM decision_events de WHERE de.evidence->>'alert_id' = p_alert_id::text
      ) e
    )
  )
  INTO result
  FROM system_alerts sa
  WHERE sa.id = p_alert_id;

  RETURN result;
END;
$$;


--
-- Name: FUNCTION get_alert_decision_chain(p_alert_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_alert_decision_chain(p_alert_id uuid) IS 'Returns the causal decision chain for a specific alert.
Distinct from generate_audit_reason_tree() which explains the overall ANA score.
- get_alert_decision_chain: "Why was THIS alert resolved?"
- generate_audit_reason_tree: "Why is the ANA score X/100?"
Created as part of ANA shock plan consolidation.';


--
-- Name: get_audit_raw_metrics(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_audit_raw_metrics(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
  rls_total int;
  rls_enabled int;
  ai_total int;
  ai_reviewed int;
  ai_approved int;
  ai_pending int;
  evidence_count bigint;
  security_log_count bigint;
  exec_chain_count int;
  trigger_count int;
  immutable_trigger_count int;
  view_count int;
  rpc_count int;
  rls_tests_total int;
  rls_tests_passed int;
  policy_total int;
  policy_active int;
  hitl_enabled boolean;
  alert_total int;
  alert_critical int;
  alert_resolved int;
  decision_total bigint;
  decision_human bigint;
  decision_system bigint;
  cert_count int;
  integrity_count int;
  baseline_count int;
  dlq_pending int;
  dlq_total int;
  rollback_total int;
  rollback_30d int;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  -- RLS Coverage (global)
  SELECT COUNT(*), COUNT(*) FILTER (WHERE c.relrowsecurity = true)
  INTO rls_total, rls_enabled
  FROM pg_tables t
  JOIN pg_class c ON c.relname = t.tablename 
    AND c.relnamespace = (SELECT oid FROM pg_namespace WHERE nspname = 'public')
  WHERE t.schemaname = 'public';

  -- AI Actions
  SELECT 
    COUNT(*),
    COUNT(*) FILTER (WHERE human_reviewed = true),
    COUNT(*) FILTER (WHERE review_decision = 'approved'),
    COUNT(*) FILTER (WHERE review_decision IS NULL)
  INTO ai_total, ai_reviewed, ai_approved, ai_pending
  FROM ai_actions WHERE tenant_id = p_tenant_id;

  -- Evidence & Audit Trail
  SELECT COUNT(*) INTO evidence_count FROM agent_evidence_logs WHERE tenant_id = p_tenant_id;
  SELECT COUNT(*) INTO security_log_count FROM security_logs WHERE tenant_id = p_tenant_id;
  SELECT COUNT(*) INTO exec_chain_count FROM agent_execution_chain 
    WHERE agent_id IN (SELECT id FROM agents WHERE tenant_id = p_tenant_id);

  -- Database hardening metrics (global)
  SELECT COUNT(*) INTO trigger_count 
  FROM pg_trigger t JOIN pg_class c ON t.tgrelid = c.oid 
  WHERE c.relnamespace = (SELECT oid FROM pg_namespace WHERE nspname = 'public');
  
  SELECT COUNT(*) INTO immutable_trigger_count 
  FROM pg_trigger t JOIN pg_class c ON t.tgrelid = c.oid 
  WHERE c.relnamespace = (SELECT oid FROM pg_namespace WHERE nspname = 'public') 
    AND t.tgname LIKE '%immut%';

  SELECT COUNT(*) INTO view_count FROM pg_views WHERE schemaname = 'public' AND viewname LIKE 'v_%';
  
  SELECT COUNT(*) INTO rpc_count FROM pg_proc 
  WHERE pronamespace = (SELECT oid FROM pg_namespace WHERE nspname = 'public');

  -- RLS Test Results (global - no tenant_id column)
  SELECT COUNT(*), COUNT(*) FILTER (WHERE passed = true)
  INTO rls_tests_total, rls_tests_passed
  FROM rls_test_results;

  -- Security Policies
  SELECT COUNT(*), COUNT(*) FILTER (WHERE is_active = true)
  INTO policy_total, policy_active
  FROM security_policies WHERE tenant_id = p_tenant_id;

  -- HITL (Human-in-the-Loop) config
  SELECT COALESCE(force_human_review_critical, false) INTO hitl_enabled
  FROM tenant_settings WHERE tenant_id = p_tenant_id;

  -- Alerts
  SELECT 
    COUNT(*) FILTER (WHERE resolved = false),
    COUNT(*) FILTER (WHERE resolved = false AND severity = 'critical'),
    COUNT(*) FILTER (WHERE resolved = true)
  INTO alert_total, alert_critical, alert_resolved
  FROM system_alerts WHERE tenant_id = p_tenant_id;

  -- Decision Events
  SELECT 
    COUNT(*),
    COUNT(*) FILTER (WHERE actor_type = 'human'),
    COUNT(*) FILTER (WHERE actor_type = 'system')
  INTO decision_total, decision_human, decision_system
  FROM decision_events WHERE tenant_id = p_tenant_id;

  -- Agent security features
  SELECT COUNT(*) INTO cert_count FROM agent_certificates WHERE tenant_id = p_tenant_id;
  SELECT COUNT(*) INTO integrity_count FROM agent_file_integrity WHERE tenant_id = p_tenant_id;
  SELECT COUNT(*) INTO baseline_count FROM agent_behavioral_baseline WHERE tenant_id = p_tenant_id;

  -- DLQ
  SELECT 
    COUNT(*) FILTER (WHERE status = 'pending'),
    COUNT(*)
  INTO dlq_pending, dlq_total
  FROM failed_jobs_dlq WHERE tenant_id = p_tenant_id;

  -- Rollbacks
  SELECT 
    COUNT(*),
    COUNT(*) FILTER (WHERE created_at > NOW() - INTERVAL '30 days')
  INTO rollback_total, rollback_30d
  FROM agent_rollback_events WHERE tenant_id = p_tenant_id;

  SELECT jsonb_build_object(
    'agents', jsonb_build_object(
      'total', (SELECT COUNT(*) FROM agents WHERE tenant_id = p_tenant_id AND archived_at IS NULL),
      'online', (SELECT COUNT(*) FROM agents WHERE tenant_id = p_tenant_id AND archived_at IS NULL AND status = 'active'),
      'offline', (SELECT COUNT(*) FROM agents WHERE tenant_id = p_tenant_id AND archived_at IS NULL AND status != 'active'),
      'in_safe_mode', (SELECT COUNT(*) FROM agent_safe_mode_events WHERE tenant_id = p_tenant_id AND resolved_at IS NULL)
    ),
    'decision_events', jsonb_build_object(
      'total', decision_total,
      'by_human', decision_human,
      'by_system', decision_system,
      'governance_active', decision_total > 0
    ),
    'ai_actions', jsonb_build_object(
      'total', ai_total,
      'human_reviewed', ai_reviewed,
      'approved', ai_approved,
      'pending', ai_pending,
      'review_rate', CASE WHEN ai_total > 0 THEN ROUND((ai_reviewed::numeric / ai_total) * 100, 1) ELSE 0 END,
      'approval_rate', CASE WHEN ai_total > 0 THEN ROUND((ai_approved::numeric / ai_total) * 100, 1) ELSE 0 END
    ),
    'human_oversight', jsonb_build_object(
      'hitl_enabled', COALESCE(hitl_enabled, false),
      'force_human_review_critical', COALESCE(hitl_enabled, false),
      'kill_switch_available', true,
      'ai_actions_total', ai_total,
      'ai_actions_reviewed', ai_reviewed,
      'review_rate', CASE WHEN ai_total > 0 THEN ROUND((ai_reviewed::numeric / ai_total) * 100, 1) ELSE 0 END,
      'dry_run_mode_available', true
    ),
    'tenant_isolation', jsonb_build_object(
      'rls_enabled_tables', rls_enabled,
      'rls_total_tables', rls_total,
      'rls_coverage_percent', CASE WHEN rls_total > 0 THEN ROUND((rls_enabled::numeric / rls_total) * 100, 1) ELSE 0 END,
      'rls_tests_total', rls_tests_total,
      'rls_tests_passed', rls_tests_passed,
      'rls_tests_pass_rate', CASE WHEN rls_tests_total > 0 THEN ROUND((rls_tests_passed::numeric / rls_tests_total) * 100, 1) ELSE 0 END,
      'multi_tenant_architecture', true
    ),
    'evidence_trail', jsonb_build_object(
      'evidence_logs', evidence_count,
      'security_logs', security_log_count,
      'execution_chains', exec_chain_count,
      'cryptographic_hash_chains', exec_chain_count > 0,
      'immutable_audit_trail', true,
      'agent_certificates', cert_count,
      'file_integrity_scans', integrity_count,
      'behavioral_baselines', baseline_count
    ),
    'database_hardening', jsonb_build_object(
      'total_triggers', trigger_count,
      'immutability_triggers', immutable_trigger_count,
      'governance_views', view_count,
      'rpc_functions', rpc_count,
      'security_definer_views', true,
      'security_barrier_views', true
    ),
    'enforcement', jsonb_build_object(
      'policies_total', policy_total,
      'policies_active', policy_active,
      'compliance_frameworks', jsonb_build_array('ISO27001', 'SOC2', 'LGPD', 'NIST'),
      'automated_enforcement', true
    ),
    'dlq', jsonb_build_object(
      'current', dlq_pending,
      'total', dlq_total
    ),
    'rollbacks', jsonb_build_object(
      'total', rollback_total,
      'last_30d', rollback_30d
    ),
    'alerts', jsonb_build_object(
      'open', alert_total,
      'critical_open', alert_critical,
      'resolved', alert_resolved,
      'decision_coverage_percent', CASE 
        WHEN (alert_total + alert_resolved) > 0 
        THEN ROUND((alert_resolved::numeric / (alert_total + alert_resolved)) * 100, 1)
        ELSE 100 
      END
    ),
    'system_capabilities', jsonb_build_object(
      'endpoint_monitoring', true,
      'vulnerability_detection', true,
      'certificate_management', cert_count > 0,
      'file_integrity_monitoring', integrity_count > 0,
      'behavioral_anomaly_detection', true,
      'network_anomaly_detection', true,
      'ai_powered_analysis', true,
      'multi_provider_ai_routing', true,
      'automated_remediation', true,
      'compliance_dashboard', true,
      'action_center', true,
      'predictive_failure_analysis', true,
      'hmac_authentication', true,
      'execution_hash_chains', exec_chain_count > 0,
      'job_orchestration', true,
      'safe_mode_protection', true,
      'agent_build_pipeline', true,
      'dns_filtering', true
    ),
    'users', jsonb_build_object(
      'count', COALESCE((SELECT COUNT(DISTINCT user_id) FROM user_roles WHERE tenant_id = p_tenant_id), 0)
    ),
    'policies', jsonb_build_object(
      'total', policy_total,
      'active', policy_active
    ),
    'tenant_stats', jsonb_build_object(
      'agent_count', (SELECT COUNT(*) FROM agents WHERE tenant_id = p_tenant_id AND archived_at IS NULL),
      'job_count', COALESCE((SELECT COUNT(*) FROM jobs WHERE tenant_id = p_tenant_id), 0),
      'user_count', COALESCE((SELECT COUNT(DISTINCT user_id) FROM user_roles WHERE tenant_id = p_tenant_id), 0)
    ),
    'collected_at', NOW(),
    'version', '4.0.0'
  ) INTO result;

  RETURN result;
END;
$$;


--
-- Name: get_autonomy_metrics(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_autonomy_metrics(p_tenant_id uuid, p_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
  since timestamptz := now() - (p_days || ' days')::interval;
BEGIN
  SELECT jsonb_build_object(
    'total_decisions', COALESCE((SELECT count(*) FROM decision_events WHERE tenant_id = p_tenant_id AND created_at >= since), 0),
    'total_actions_created', COALESCE((SELECT count(*) FROM ai_actions WHERE tenant_id = p_tenant_id AND created_at >= since), 0),
    'actions_auto_executed', COALESCE((SELECT count(*) FROM ai_actions WHERE tenant_id = p_tenant_id AND created_at >= since AND status = 'executed'), 0),
    'actions_pending', COALESCE((SELECT count(*) FROM ai_actions WHERE tenant_id = p_tenant_id AND created_at >= since AND status = 'pending'), 0),
    'actions_approved', COALESCE((SELECT count(*) FROM ai_actions WHERE tenant_id = p_tenant_id AND created_at >= since AND status = 'approved'), 0),
    'actions_rejected', COALESCE((SELECT count(*) FROM ai_actions WHERE tenant_id = p_tenant_id AND created_at >= since AND status = 'rejected'), 0),
    'alerts_generated', COALESCE((SELECT count(*) FROM ai_actions WHERE tenant_id = p_tenant_id AND created_at >= since AND action_type = 'alert'), 0),
    'execution_success_rate', COALESCE(
      (SELECT round(count(*) FILTER (WHERE status IN ('executed','completed','approved'))::numeric * 100.0 / NULLIF(count(*) FILTER (WHERE status NOT IN ('pending')), 0), 1)
       FROM ai_actions WHERE tenant_id = p_tenant_id AND created_at >= since), 0),
    'job_success_rate_corrected', COALESCE(
      (SELECT round(count(*) FILTER (WHERE status IN ('completed','executed'))::numeric * 100.0 / NULLIF(count(*), 0), 1)
       FROM jobs WHERE tenant_id = p_tenant_id AND created_at >= since AND status != 'cancelled_timeout'), 99),
    'decisions_by_rule', COALESCE(
      (SELECT jsonb_agg(jsonb_build_object('rule_code', rule_code, 'count', cnt))
       FROM (SELECT rule_code, count(*) as cnt FROM decision_events WHERE tenant_id = p_tenant_id AND created_at >= since GROUP BY rule_code ORDER BY cnt DESC LIMIT 20) sub), '[]'::jsonb),
    'actions_by_type', COALESCE(
      (SELECT jsonb_agg(jsonb_build_object('action_type', action_type, 'count', cnt))
       FROM (SELECT action_type, count(*) as cnt FROM ai_actions WHERE tenant_id = p_tenant_id AND created_at >= since GROUP BY action_type ORDER BY cnt DESC LIMIT 20) sub), '[]'::jsonb)
  ) INTO result;
  RETURN result;
END;
$$;


--
-- Name: get_balanced_pending_actions(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_balanced_pending_actions(p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, tenant_id uuid, action_type text, action_payload jsonb, insight_id uuid, ai_insights jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- SSA-SEC: This returns cross-tenant data by design (for system processing)
  -- Must be restricted to service_role only
  PERFORM _assert_service_role_or_super_admin();

  RETURN QUERY
  WITH ranked_actions AS (
    SELECT 
      a.id, a.tenant_id, a.action_type, a.action_payload, a.insight_id, a.created_at,
      ROW_NUMBER() OVER (PARTITION BY a.tenant_id ORDER BY a.created_at ASC) as tenant_rank
    FROM ai_actions a
    WHERE a.status = 'pending'
  ),
  balanced_actions AS (
    SELECT ra.id, ra.tenant_id, ra.action_type, ra.action_payload, ra.insight_id, ra.created_at
    FROM ranked_actions ra
    ORDER BY ra.tenant_rank ASC, ra.created_at ASC
    LIMIT p_limit
  )
  SELECT 
    ba.id, ba.tenant_id, ba.action_type, ba.action_payload, ba.insight_id,
    (SELECT jsonb_build_object('id', i.id, 'confidence_score', i.confidence_score, 'insight_type', i.insight_type, 'status', i.status)
     FROM ai_insights i WHERE i.id = ba.insight_id
    ) as ai_insights
  FROM balanced_actions ba;
END;
$$;


--
-- Name: FUNCTION get_balanced_pending_actions(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_balanced_pending_actions(p_limit integer) IS 'Anti-starvation RPC: distribui ações pendentes de forma justa entre todos os tenants, 
evitando que um tenant com rate limit excedido bloqueie outros. 
Implementa round-robin por tenant_rank para garantir que todos processem igualmente.';


--
-- Name: get_cached_value(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cached_value(p_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    cached_value JSONB;
BEGIN
    SELECT value INTO cached_value
    FROM kv_cache
    WHERE key = p_key AND expires_at > NOW();
    
    RETURN cached_value;
END;
$$;


--
-- Name: get_critical_insights_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_critical_insights_count(p_tenant_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  RETURN (
    SELECT COUNT(*)::INTEGER
    FROM public.ai_insights
    WHERE tenant_id = p_tenant_id
      AND acknowledged = false
      AND severity IN ('critical', 'high')
  );
END;
$$;


--
-- Name: get_decision_timeline(uuid, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_decision_timeline(p_tenant_id uuid, p_limit integer DEFAULT 50, p_rule_code text DEFAULT NULL::text, p_agent_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(row_data ORDER BY (row_data->>'created_at') DESC), '[]'::jsonb)
  INTO result
  FROM (
    SELECT jsonb_build_object(
      'id', d.id, 'rule_code', d.rule_code, 'action', d.action,
      'evidence', COALESCE(d.evidence, '{}'::jsonb),
      'executed_actions', COALESCE(d.actions_executed, ARRAY[]::text[]),
      'created_at', d.created_at, 'agent_id', d.agent_id, 'agent_name', d.agent_name,
      'rule_name', COALESCE(r.description, d.rule_code),
      'rule_severity', (r.definition->>'severity'),
      'risk_level', (r.definition->>'risk_level'),
      'related_actions', COALESCE(
        (SELECT jsonb_agg(jsonb_build_object('id', a.id, 'action_type', a.action_type, 'status', a.status, 'executed_at', a.executed_at))
        FROM ai_actions a WHERE a.decision_event_id = d.id), '[]'::jsonb)
    ) as row_data
    FROM decision_events d
    LEFT JOIN decision_rules r ON r.code = d.rule_code
    WHERE d.tenant_id = p_tenant_id
      AND (p_rule_code IS NULL OR d.rule_code = p_rule_code)
      AND (p_agent_id IS NULL OR d.agent_id = p_agent_id)
    ORDER BY d.created_at DESC
    LIMIT p_limit
  ) sub;
  RETURN result;
END;
$$;


--
-- Name: get_enrollment_key_full(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_enrollment_key_full(p_key_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_key TEXT;
BEGIN
  -- SSA-SEC: MUST be service_role only - this exposes plaintext keys
  PERFORM _assert_service_role_or_super_admin();
  
  SELECT key INTO v_key
  FROM public.enrollment_keys
  WHERE id = p_key_id
    AND is_active = true
    AND expires_at > NOW();
  
  RETURN v_key;
END;
$$;


