Não deve ser chamada diretamente pelo frontend.';


--
-- Name: get_evidence_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_evidence_summary(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH real_events AS (
    SELECT 
      event_type,
      severity,
      agent_name,
      COALESCE(event_data->>'alert_type', 'unknown') AS alert_type
    FROM agent_evidence_logs
    WHERE tenant_id = p_tenant_id
      AND created_at >= now() - interval '30 days'
      AND severity NOT IN ('info', 'debug')
      AND event_data IS DISTINCT FROM '{}'::jsonb
      AND jsonb_typeof(event_data) = 'object'
      AND (SELECT count(*) FROM jsonb_object_keys(event_data)) > 0
  ),
  -- Deduplicate ALL event types: 1 per (agent_name, alert_type, severity_bucket)
  deduped AS (
    SELECT DISTINCT ON (event_type, agent_name, alert_type, 
      CASE 
        WHEN severity = 'critical' THEN 'critical'
        WHEN severity IN ('high', 'error') THEN 'high'
        WHEN severity = 'warning' THEN 'warning'
        ELSE 'other'
      END
    )
      event_type,
      agent_name,
      alert_type,
      CASE 
        WHEN severity = 'critical' THEN 'critical'
        WHEN severity IN ('high', 'error') THEN 'high'
        WHEN severity = 'warning' THEN 'warning'
        ELSE 'other'
      END AS severity_bucket
    FROM real_events
  ),
  counts AS (
    SELECT
      (SELECT count(*) FROM deduped WHERE event_type = 'auto_repair') AS auto_repairs,
      (SELECT count(*) FROM deduped WHERE event_type = 'auto_recovery') AS auto_recoveries,
      (SELECT count(*) FROM deduped WHERE event_type = 'policy_drift') AS policy_drifts,
      (SELECT count(*) FROM deduped WHERE event_type = 'security_event' AND severity_bucket = 'critical') AS critical_prevented,
      (SELECT count(*) FROM deduped WHERE event_type = 'security_event' AND severity_bucket = 'high') AS high_prevented,
      (SELECT count(*) FROM deduped WHERE event_type = 'security_event' AND severity_bucket = 'warning') AS medium_prevented
  )
  SELECT jsonb_build_object(
    'auto_repairs', auto_repairs,
    'auto_recoveries', auto_recoveries,
    'policy_drifts', policy_drifts,
    'critical_prevented', critical_prevented,
    'high_prevented', high_prevented,
    'medium_prevented', medium_prevented,
    'incidents_contained', critical_prevented + high_prevented + medium_prevented
  )
  FROM counts;
$$;


--
-- Name: get_governance_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_governance_snapshot() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_decision_events jsonb;
  v_ai_actions jsonb;
  v_policies jsonb;
  v_tenant_isolation jsonb;
  v_rbac jsonb;
BEGIN
  -- Decision Events metrics
  SELECT jsonb_build_object(
    'total', COUNT(*),
    'by_human', COUNT(*) FILTER (WHERE decision_source = 'human'),
    'by_system', COUNT(*) FILTER (WHERE decision_source IN ('system', 'ai')),
    'rollbacks', COUNT(*) FILTER (WHERE decision_type = 'rollback'),
    'alert_resolutions', COUNT(*) FILTER (WHERE decision_type = 'alert_resolution'),
    'last_24h', COUNT(*) FILTER (WHERE created_at > NOW() - INTERVAL '24 hours')
  ) INTO v_decision_events
  FROM public.decision_events;

  -- AI Actions metrics
  SELECT jsonb_build_object(
    'total', COUNT(*),
    'approved', COUNT(*) FILTER (WHERE status = 'approved'),
    'rejected', COUNT(*) FILTER (WHERE status = 'rejected'),
    'pending', COUNT(*) FILTER (WHERE status = 'pending'),
    'human_reviewed', COUNT(*) FILTER (WHERE human_reviewed = true),
    'with_formal_approval', COUNT(*) FILTER (WHERE approved_at IS NOT NULL AND approved_by IS NOT NULL),
    'high_risk_with_approval', COUNT(*) FILTER (WHERE risk_level IN ('high', 'critical') AND approved_at IS NOT NULL)
  ) INTO v_ai_actions
  FROM public.ai_actions;

  -- Policies metrics
  SELECT jsonb_build_object(
    'total', COUNT(*),
    'enabled', COUNT(*) FILTER (WHERE enabled = true),
    'with_assignments', (
      SELECT COUNT(DISTINCT policy_id) FROM public.agent_group_policies
    )
  ) INTO v_policies
  FROM public.security_policies;

  -- Tenant Isolation metrics
  SELECT jsonb_build_object(
    'total_tables', total_tables,
    'tables_with_rls', tables_with_rls,
    'tables_with_tenant_id', tables_with_tenant_id,
    'tables_with_valid_isolation', tables_with_valid_isolation,
    'rls_coverage_pct', rls_coverage_pct,
    'isolation_coverage_pct', isolation_coverage_pct,
    'rls_status', rls_status,
    'isolation_status', isolation_status
  ) INTO v_tenant_isolation
  FROM public.v_tenant_isolation_metrics;

  -- RBAC metrics
  SELECT jsonb_build_object(
    'total_tenants', total_tenants,
    'total_role_assignments', total_role_assignments,
    'users_with_roles', users_with_roles,
    'distinct_roles', distinct_roles,
    'admin_count', admin_count,
    'super_admin_count', super_admin_count,
    'operator_count', operator_count,
    'viewer_count', viewer_count,
    'rbac_status', rbac_status,
    'security_functions_present', 
      has_tenant_id_function AND has_role_function AND has_super_admin_function AND has_tenant_access_function
  ) INTO v_rbac
  FROM public.v_rbac_metrics;

  -- Build complete snapshot
  v_result := jsonb_build_object(
    'decision_events', COALESCE(v_decision_events, '{}'::jsonb),
    'ai_actions', COALESCE(v_ai_actions, '{}'::jsonb),
    'policies', COALESCE(v_policies, '{}'::jsonb),
    'tenant_isolation', COALESCE(v_tenant_isolation, '{}'::jsonb),
    'rbac', COALESCE(v_rbac, '{}'::jsonb),
    'snapshot_at', NOW()
  );

  RETURN v_result;
END;
$$;


--
-- Name: get_governance_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_governance_snapshot(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  SELECT jsonb_build_object(
    'timestamp', now(),
    'tenant_id', p_tenant_id,
    
    -- AI Governance metrics
    'ai_governance', (
      SELECT jsonb_build_object(
        'total_actions', COUNT(*),
        'pending_review', COUNT(*) FILTER (WHERE human_reviewed = false),
        'approved', COUNT(*) FILTER (WHERE review_decision = 'approved'),
        'rejected', COUNT(*) FILTER (WHERE review_decision = 'rejected'),
        'high_risk_pending', COUNT(*) FILTER (WHERE risk_level IN ('high', 'critical') AND human_reviewed = false)
      )
      FROM ai_actions
      WHERE (p_tenant_id IS NULL OR tenant_id = p_tenant_id)
    ),
    
    -- Human approval metrics
    'human_approval', (
      SELECT jsonb_build_object(
        'total_requests', COUNT(*),
        'pending', COUNT(*) FILTER (WHERE status = 'pending'),
        'approved', COUNT(*) FILTER (WHERE status = 'approved'),
        'rejected', COUNT(*) FILTER (WHERE status = 'rejected'),
        'expired', COUNT(*) FILTER (WHERE status = 'expired'),
        'avg_resolution_hours', ROUND(EXTRACT(EPOCH FROM AVG(
          CASE WHEN resolved_at IS NOT NULL THEN resolved_at - created_at END
        ))/3600, 2)
      )
      FROM approval_requests
      WHERE (p_tenant_id IS NULL OR tenant_id = p_tenant_id)
    ),
    
    -- DLQ metrics
    'dlq', (
      SELECT jsonb_build_object(
        'total_entries', COUNT(*),
        'pending', COUNT(*) FILTER (WHERE status = 'pending'),
        'resolved', COUNT(*) FILTER (WHERE status = 'resolved'),
        'escalated', COUNT(*) FILTER (WHERE status = 'escalated'),
        'oldest_pending_hours', ROUND(EXTRACT(EPOCH FROM (now() - MIN(
          CASE WHEN status = 'pending' THEN created_at END
        )))/3600, 2)
      )
      FROM failed_jobs_dlq
      WHERE (p_tenant_id IS NULL OR tenant_id = p_tenant_id)
    ),
    
    -- Rollback metrics
    'rollback', (
      SELECT jsonb_build_object(
        'total_events', COUNT(*),
        'safe_mode_triggered', COUNT(*) FILTER (WHERE safe_mode_triggered = true),
        'last_24h', COUNT(*) FILTER (WHERE created_at > now() - interval '24 hours')
      )
      FROM agent_rollback_events
      WHERE (p_tenant_id IS NULL OR tenant_id = p_tenant_id)
    ),
    
    -- Decision events metrics
    'decisions', (
      SELECT jsonb_build_object(
        'total_events', COUNT(*),
        'by_type', jsonb_object_agg(COALESCE(decision_type, 'unknown'), cnt)
      )
      FROM (
        SELECT decision_type, COUNT(*) as cnt
        FROM decision_events
        WHERE (p_tenant_id IS NULL OR tenant_id = p_tenant_id)
        GROUP BY decision_type
      ) sub
    ),
    
    -- Tenant isolation metrics
    'tenant_isolation', (
      SELECT jsonb_build_object(
        'total_tables', total_tables,
        'tables_with_rls', tables_with_rls,
        'rls_coverage_pct', rls_coverage_pct,
        'tables_with_isolation', tables_with_isolation,
        'isolation_coverage_pct', isolation_coverage_pct,
        'isolation_status', isolation_status
      )
      FROM v_tenant_isolation_metrics
    ),
    
    -- RBAC metrics
    'rbac', (
      SELECT jsonb_build_object(
        'total_tenants', total_tenants,
        'total_role_assignments', total_role_assignments,
        'users_with_roles', users_with_roles,
        'admin_count', admin_count,
        'super_admin_count', super_admin_count,
        'distinct_roles', distinct_roles,
        'security_functions_present', security_functions_present,
        'rbac_status', rbac_status
      )
      FROM v_rbac_metrics
    ),
    
    -- Enforcement compliance metrics (NEW)
    'enforcement', (
      SELECT jsonb_build_object(
        'active_since', enforcement_active_since,
        'ai_actions', jsonb_build_object(
          'total_high_critical', ai_actions_high_critical,
          'with_approval', ai_actions_with_approval,
          'compliance_pct', ai_actions_compliance_pct
        ),
        'critical_alerts', jsonb_build_object(
          'total', critical_alerts_total,
          'resolved', critical_alerts_resolved,
          'human_resolved', critical_alerts_human_resolved,
          'with_decision', critical_alerts_with_decision,
          'compliance_pct', critical_alerts_compliance_pct
        ),
        'dlq', jsonb_build_object(
          'total_resolved', dlq_resolved_total,
          'with_decision_event', dlq_with_decision_event,
          'compliance_pct', dlq_compliance_pct
        ),
        'legacy_data', jsonb_build_object(
          'critical_alerts_before_enforcement', legacy_critical_alerts,
          'dlq_resolved_before_enforcement', legacy_dlq_resolved
        ),
        'status', enforcement_status
      )
      FROM v_enforcement_compliance
    )
    
  ) INTO result;
  
  RETURN result;
END;
$$;


--
-- Name: get_honeypot_stats(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_honeypot_stats(p_tenant_id uuid DEFAULT NULL::uuid, p_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result JSONB;
  v_cutoff TIMESTAMPTZ := now() - make_interval(hours := p_hours);
BEGIN
  SELECT jsonb_build_object(
    'total_interactions', COALESCE(count(*), 0),
    'unique_ip_hashes', COALESCE(count(DISTINCT source_ip_hash), 0),
    'classifications', COALESCE(
      jsonb_object_agg(cls, cnt) FILTER (WHERE cls IS NOT NULL),
      '{}'::jsonb
    ),
    'modes', COALESCE(
      jsonb_object_agg(m, mcnt) FILTER (WHERE m IS NOT NULL),
      '{}'::jsonb
    )
  ) INTO v_result
  FROM (
    SELECT classification AS cls, count(*) AS cnt, NULL::text AS m, NULL::bigint AS mcnt
    FROM honeypot_interactions
    WHERE created_at >= v_cutoff
      AND (p_tenant_id IS NULL OR tenant_id = p_tenant_id)
    GROUP BY classification
    UNION ALL
    SELECT NULL, NULL, mode AS m, count(*) AS mcnt
    FROM honeypot_interactions
    WHERE created_at >= v_cutoff
      AND (p_tenant_id IS NULL OR tenant_id = p_tenant_id)
    GROUP BY mode
  ) sub;

  RETURN COALESCE(v_result, '{"total_interactions":0,"unique_ip_hashes":0,"classifications":{},"modes":{}}'::jsonb);
END;
$$;


--
-- Name: get_installation_health_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_installation_health_status(p_tenant_id uuid) RETURNS TABLE(status text, failure_rate_pct numeric, total_attempts bigint, threshold numeric)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Validate user has access to this tenant
  IF NOT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = auth.uid() AND tenant_id = p_tenant_id
  ) THEN
    RAISE EXCEPTION 'Unauthorized: No access to tenant'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
  SELECT 
    CASE 
      WHEN COUNT(*) = 0 THEN 'no_data'
      WHEN (COUNT(*) FILTER (WHERE success = false)::numeric / COUNT(*)::numeric) > 0.30 THEN 'unhealthy'
      ELSE 'healthy'
    END as status,
    CASE 
      WHEN COUNT(*) > 0 THEN 
        ROUND((COUNT(*) FILTER (WHERE success = false)::numeric / COUNT(*)::numeric) * 100, 1)
      ELSE 0
    END as failure_rate_pct,
    COUNT(*) as total_attempts,
    30.0 as threshold
  FROM public.installation_analytics
  WHERE tenant_id = p_tenant_id
    AND created_at > NOW() - INTERVAL '24 hours'
    AND event_type IN ('post_installation', 'post_installation_unverified');
END;
$$;


--
-- Name: FUNCTION get_installation_health_status(p_tenant_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_installation_health_status(p_tenant_id uuid) IS '🔒 Essencial - Status de instalação';


--
-- Name: get_job_failure_stats(uuid, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_job_failure_stats(p_tenant_id uuid, p_days_back integer DEFAULT 30, p_group_by_agent boolean DEFAULT false) RETURNS TABLE(job_type text, agent_name text, agent_id uuid, total_jobs bigint, completed_jobs bigint, failed_jobs bigint, failure_rate numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    j.type AS job_type,
    CASE WHEN p_group_by_agent THEN j.agent_name ELSE NULL END AS agent_name,
    CASE WHEN p_group_by_agent THEN j.agent_id ELSE NULL END AS agent_id,
    COUNT(*) FILTER (WHERE j.status IN ('completed', 'failed')) AS total_jobs,
    COUNT(*) FILTER (WHERE j.status = 'completed') AS completed_jobs,
    COUNT(*) FILTER (WHERE j.status = 'failed') AS failed_jobs,
    CASE 
      WHEN COUNT(*) FILTER (WHERE j.status IN ('completed', 'failed')) > 0 
      THEN ROUND(
        COUNT(*) FILTER (WHERE j.status = 'failed')::NUMERIC / 
        COUNT(*) FILTER (WHERE j.status IN ('completed', 'failed')) * 100, 1
      )
      ELSE 0 
    END AS failure_rate
  FROM jobs j
  WHERE j.tenant_id = p_tenant_id
    AND j.created_at > now() - make_interval(days => p_days_back)
  GROUP BY j.type,
    CASE WHEN p_group_by_agent THEN j.agent_name ELSE NULL END,
    CASE WHEN p_group_by_agent THEN j.agent_id ELSE NULL END
  ORDER BY failure_rate DESC, total_jobs DESC;
$$;


