--
-- Name: get_playbook_execution_breakdown(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_playbook_execution_breakdown(p_tenant_id uuid, p_days_back integer DEFAULT 30) RETURNS TABLE(playbook_id uuid, playbook_name text, severity text, total_triggers bigint, completed_count bigint, ignored_count bigint, failed_count bigint, avg_response_minutes numeric, last_triggered_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  RETURN QUERY
  SELECT
    p.id as playbook_id,
    p.name as playbook_name,
    p.severity,
    COUNT(pe.id)::BIGINT as total_triggers,
    COUNT(pe.id) FILTER (WHERE pe.status = 'completed')::BIGINT as completed_count,
    COUNT(pe.id) FILTER (WHERE pe.status = 'ignored')::BIGINT as ignored_count,
    COUNT(pe.id) FILTER (WHERE pe.status = 'failed')::BIGINT as failed_count,
    ROUND(
      AVG(EXTRACT(EPOCH FROM (pe.completed_at - pe.triggered_at)) / 60) 
      FILTER (WHERE pe.completed_at IS NOT NULL)::NUMERIC, 
      2
    ) as avg_response_minutes,
    MAX(pe.triggered_at) as last_triggered_at
  FROM playbooks p
  LEFT JOIN playbook_executions pe ON p.id = pe.playbook_id 
    AND pe.tenant_id = p_tenant_id
    AND pe.triggered_at >= NOW() - (p_days_back || ' days')::INTERVAL
  WHERE p.tenant_id = p_tenant_id OR p.is_system = true
  GROUP BY p.id, p.name, p.severity
  ORDER BY total_triggers DESC NULLS LAST, p.name;
END;
$$;


--
-- Name: FUNCTION get_playbook_execution_breakdown(p_tenant_id uuid, p_days_back integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_playbook_execution_breakdown(p_tenant_id uuid, p_days_back integer) IS 'Retorna breakdown de execuções por playbook individual com estatísticas detalhadas';


--
-- Name: get_playbook_metrics(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_playbook_metrics(p_tenant_id uuid, p_days_back integer DEFAULT 30) RETURNS TABLE(total_executions bigint, total_completed bigint, total_ignored bigint, total_failed bigint, execution_rate_pct numeric, ignore_rate_pct numeric, avg_response_time_minutes numeric, min_response_time_minutes numeric, max_response_time_minutes numeric, most_triggered_playbook_id uuid, most_triggered_playbook_name text, most_triggered_count bigint, period_start timestamp with time zone, period_end timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cutoff TIMESTAMP WITH TIME ZONE;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  v_cutoff := NOW() - (p_days_back || ' days')::INTERVAL;
  
  RETURN QUERY
  WITH execution_stats AS (
    SELECT
      COUNT(*) as total,
      COUNT(*) FILTER (WHERE pe.status = 'completed') as completed,
      COUNT(*) FILTER (WHERE pe.status = 'ignored') as ignored,
      COUNT(*) FILTER (WHERE pe.status = 'failed') as failed,
      AVG(
        EXTRACT(EPOCH FROM (pe.completed_at - pe.triggered_at)) / 60
      ) FILTER (WHERE pe.completed_at IS NOT NULL) as avg_response_min,
      MIN(
        EXTRACT(EPOCH FROM (pe.completed_at - pe.triggered_at)) / 60
      ) FILTER (WHERE pe.completed_at IS NOT NULL) as min_response_min,
      MAX(
        EXTRACT(EPOCH FROM (pe.completed_at - pe.triggered_at)) / 60
      ) FILTER (WHERE pe.completed_at IS NOT NULL) as max_response_min
    FROM playbook_executions pe
    WHERE pe.tenant_id = p_tenant_id
      AND pe.triggered_at >= v_cutoff
  ),
  top_playbook AS (
    SELECT 
      pe.playbook_id,
      p.name as playbook_name,
      COUNT(*) as trigger_count
    FROM playbook_executions pe
    LEFT JOIN playbooks p ON pe.playbook_id = p.id
    WHERE pe.tenant_id = p_tenant_id
      AND pe.triggered_at >= v_cutoff
      AND pe.playbook_id IS NOT NULL
    GROUP BY pe.playbook_id, p.name
    ORDER BY trigger_count DESC
    LIMIT 1
  )
  SELECT
    COALESCE(es.total, 0)::BIGINT,
    COALESCE(es.completed, 0)::BIGINT,
    COALESCE(es.ignored, 0)::BIGINT,
    COALESCE(es.failed, 0)::BIGINT,
    CASE WHEN es.total > 0 
      THEN ROUND((es.completed::NUMERIC / es.total::NUMERIC) * 100, 1)
      ELSE 0
    END,
    CASE WHEN es.total > 0 
      THEN ROUND((es.ignored::NUMERIC / es.total::NUMERIC) * 100, 1)
      ELSE 0
    END,
    ROUND(COALESCE(es.avg_response_min, 0)::NUMERIC, 2),
    ROUND(COALESCE(es.min_response_min, 0)::NUMERIC, 2),
    ROUND(COALESCE(es.max_response_min, 0)::NUMERIC, 2),
    tp.playbook_id,
    tp.playbook_name,
    COALESCE(tp.trigger_count, 0)::BIGINT,
    v_cutoff,
    NOW()
  FROM execution_stats es
  CROSS JOIN (SELECT * FROM top_playbook LIMIT 1) tp;
END;
$$;


--
-- Name: FUNCTION get_playbook_metrics(p_tenant_id uuid, p_days_back integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_playbook_metrics(p_tenant_id uuid, p_days_back integer) IS 'Retorna métricas agregadas de execuções de playbooks: taxas, tempos de resposta, playbook mais acionado';


--
-- Name: get_previous_audit_score(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_previous_audit_score(p_tenant_id uuid) RETURNS TABLE(previous_score integer, previous_official_score integer, avg_last_3 numeric, avg_last_7 numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  RETURN QUERY
  WITH recent_audits AS (
    SELECT 
      overall_score,
      official_score,
      created_at,
      ROW_NUMBER() OVER (ORDER BY created_at DESC) as rn
    FROM system_audits
    WHERE tenant_id = p_tenant_id
    ORDER BY created_at DESC
    LIMIT 7
  ),
  averages AS (
    SELECT 
      AVG(overall_score) FILTER (WHERE rn <= 3) as avg_3,
      AVG(overall_score) FILTER (WHERE rn <= 7) as avg_7
    FROM recent_audits
  )
  SELECT 
    ra.overall_score::INTEGER as previous_score,
    ra.official_score::INTEGER as previous_official_score,
    COALESCE(a.avg_3, ra.overall_score::NUMERIC) as avg_last_3,
    COALESCE(a.avg_7, ra.overall_score::NUMERIC) as avg_last_7
  FROM recent_audits ra
  CROSS JOIN averages a
  WHERE ra.rn = 1
  LIMIT 1;
END;
$$;


--
-- Name: get_problematic_agents(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_problematic_agents(p_tenant_id uuid) RETURNS TABLE(id uuid, agent_name text, status text, created_at timestamp with time zone, minutes_since_creation numeric, installation_success boolean, network_connectivity boolean, metadata jsonb)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM user_roles 
    WHERE user_id = auth.uid() 
      AND tenant_id = p_tenant_id
  ) THEN
    RAISE EXCEPTION 'Access denied: user does not belong to tenant %', p_tenant_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
  SELECT 
    a.id,
    a.agent_name,
    a.status,
    a.enrolled_at AS created_at,
    EXTRACT(EPOCH FROM (NOW() - a.enrolled_at))::numeric / 60 AS minutes_since_creation,
    ia.success AS installation_success,
    ia.network_connectivity,
    ia.metadata
  FROM active_agents a
  LEFT JOIN LATERAL (
    SELECT success, network_connectivity, metadata
    FROM installation_analytics
    WHERE agent_id = a.id
      AND event_type = 'post_installation'
    ORDER BY created_at DESC
    LIMIT 1
  ) ia ON true
  WHERE a.status = 'pending'
    AND a.last_heartbeat IS NULL
    AND a.enrolled_at < NOW() - INTERVAL '5 minutes'
    AND a.tenant_id = p_tenant_id
  ORDER BY a.enrolled_at DESC;
END;
$$;


--
-- Name: get_rate_limit_summary(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_rate_limit_summary(p_hours_back integer DEFAULT 24) RETURNS TABLE(endpoint text, total_requests bigint, unique_identifiers bigint, blocked_count bigint, avg_requests_per_identifier numeric)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    rl.endpoint,
    SUM(rl.request_count)::BIGINT as total_requests,
    COUNT(DISTINCT rl.identifier)::BIGINT as unique_identifiers,
    COUNT(*) FILTER (WHERE rl.blocked_until > NOW())::BIGINT as blocked_count,
    ROUND(AVG(rl.request_count), 2) as avg_requests_per_identifier
  FROM public.rate_limits rl
  WHERE rl.window_start > NOW() - (p_hours_back || ' hours')::INTERVAL
  GROUP BY rl.endpoint
  ORDER BY total_requests DESC;
END;
$$;


--
-- Name: jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    agent_name text NOT NULL,
    type text NOT NULL,
    payload jsonb,
    approved boolean DEFAULT true NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    delivered_at timestamp with time zone,
    completed_at timestamp with time zone,
    tenant_id uuid NOT NULL,
    scheduled_at timestamp with time zone,
    is_recurring boolean DEFAULT false,
    recurrence_pattern text,
    parent_job_id uuid,
    last_run_at timestamp with time zone,
    next_run_at timestamp with time zone,
    output jsonb,
    error_message text,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    execution_time_seconds integer,
    agent_id uuid,
    priority smallint DEFAULT 2,
    delivery_attempts integer DEFAULT 0 NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '04:00:00'::interval),
    current_execution_id uuid,
    payload_hash text NOT NULL,
    retry_count integer DEFAULT 0,
    failure_class text,
    CONSTRAINT check_recurring_has_pattern CHECK (((is_recurring = false) OR ((is_recurring = true) AND (recurrence_pattern IS NOT NULL)))),
    CONSTRAINT jobs_failure_class_check CHECK ((failure_class = ANY (ARRAY['AGENT_OFFLINE'::text, 'AGENT_STALLED'::text, 'AGENT_INCOMPATIBLE'::text, 'EXPECTED_DROP'::text, 'CASCADE_FAILURE'::text, 'TRANSIENT'::text, 'BUG'::text, 'POLICY'::text, 'SECURITY'::text, 'EXPIRED'::text, 'STUCK'::text])))
);

ALTER TABLE ONLY public.jobs REPLICA IDENTITY FULL;


--
-- Name: TABLE jobs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.jobs IS 'Jobs (tarefas remotas) enviados para execução nos agentes. Utilizada no módulo de operações. Relacionada com agents e tenants.';


--
-- Name: COLUMN jobs.id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.jobs.id IS 'Identificador único do job. UUID.';


--
-- Name: COLUMN jobs.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.jobs.status IS 'Status: queued (aguardando), delivered (em execução), done (concluído), failed (falhou)';


--
-- Name: COLUMN jobs.created_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.jobs.created_at IS 'Data/hora de criação.';


--
-- Name: COLUMN jobs.tenant_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.jobs.tenant_id IS 'FK para tenants. Multi-tenant.';


--
-- Name: COLUMN jobs.scheduled_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.jobs.scheduled_at IS 'When the job should be executed (one-time scheduled jobs)';


--
-- Name: COLUMN jobs.is_recurring; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.jobs.is_recurring IS 'Whether this job should repeat on a schedule';


--
-- Name: COLUMN jobs.recurrence_pattern; Type: COMMENT; Schema: public; Owner: -
