COMMENT ON COLUMN public.jobs.recurrence_pattern IS 'Cron-like pattern for recurring jobs (e.g., "0 * * * *" for hourly)';


--
-- Name: COLUMN jobs.parent_job_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.jobs.parent_job_id IS 'Reference to the original job if this is a recurring instance';


--
-- Name: COLUMN jobs.last_run_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.jobs.last_run_at IS 'Last time this recurring job was executed';


--
-- Name: COLUMN jobs.next_run_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.jobs.next_run_at IS 'Next scheduled execution time for recurring jobs';


--
-- Name: COLUMN jobs.output; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.jobs.output IS 'JSON estruturado do resultado (v3)';


--
-- Name: COLUMN jobs.error_message; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.jobs.error_message IS 'Jobs v3: Mensagem de erro se status=failed';


--
-- Name: COLUMN jobs.started_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.jobs.started_at IS 'Timestamp de início da execução (v3)';


--
-- Name: COLUMN jobs.finished_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.jobs.finished_at IS 'Timestamp de conclusão (v3, substitui completed_at)';


--
-- Name: COLUMN jobs.execution_time_seconds; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.jobs.execution_time_seconds IS 'Duração da execução em segundos (v3)';


--
-- Name: COLUMN jobs.agent_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.jobs.agent_id IS 'FK para agents.id com ON DELETE CASCADE para evitar jobs órfãos quando um agente é deletado.';


--
-- Name: COLUMN jobs.priority; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.jobs.priority IS 'Job priority: 1=critical (immediate), 2=standard, 3=heavy (can wait)';


