-- Name: COLUMN jobs.delivery_attempts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.jobs.delivery_attempts IS 'Number of times job was delivered but not completed. Max 5 before auto-fail.';


