-- Name: COLUMN jobs.expires_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.jobs.expires_at IS 'Job expiration time. Jobs past this time are auto-failed. Default: created_at + 7 days.';


