-- Name: COLUMN jobs.payload_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.jobs.payload_hash IS 'SHA256 hash of canonical payload JSON. Immutable after creation. Used for integrity verification.';


--
-- Name: get_recent_jobs(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_recent_jobs(p_tenant_id uuid, p_limit integer DEFAULT 50) RETURNS SETOF public.jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  RETURN QUERY
  SELECT *
  FROM jobs
  WHERE tenant_id = p_tenant_id
  ORDER BY created_at DESC
  LIMIT p_limit;
END;
$$;


--
-- Name: get_replay_attempts(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_replay_attempts(hours_back integer DEFAULT 1) RETURNS TABLE(signature text, attempt_count bigint, first_attempt timestamp with time zone, last_attempt timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT 
    signature,
    COUNT(*) as attempt_count,
    MIN(used_at) as first_attempt,
    MAX(used_at) as last_attempt
  FROM public.hmac_signatures
  WHERE used_at > now() - (hours_back || ' hours')::interval
  GROUP BY signature
  HAVING COUNT(*) > 1
  ORDER BY attempt_count DESC
  LIMIT 100;
$$;


--
-- Name: get_report_frequency_days(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_report_frequency_days(p_plan_name text) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN CASE p_plan_name
    WHEN 'free' THEN NULL -- Trial: single report only
    WHEN 'starter' THEN 30 -- Monthly
    WHEN 'pro' THEN 14 -- Bi-weekly
    WHEN 'business' THEN 14 -- Bi-weekly
    WHEN 'scale' THEN 7 -- Weekly
    WHEN 'enterprise' THEN 7 -- Weekly
    ELSE 30 -- Default monthly for residential plans
  END;
END;
$$;


--
-- Name: get_session_timeout_minutes(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_session_timeout_minutes(_role text) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _timeout INTEGER;
BEGIN
  SELECT COALESCE(
    (SELECT (t.session_timeout_minutes->>_role)::INTEGER
     FROM tenants t
     WHERE t.id = (
       SELECT ((auth.jwt()->'app_metadata')::jsonb->>'active_tenant_id')::UUID
     )),
    CASE _role
      WHEN 'super_admin' THEN 15
      WHEN 'admin' THEN 60
      ELSE 480
    END
  ) INTO _timeout;
  
  RETURN _timeout;
END;
$$;


--
-- Name: get_slo_target_for_severity(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_slo_target_for_severity(p_severity text) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN CASE p_severity
    WHEN 'critical' THEN 99.9
    WHEN 'high' THEN 99.5
    WHEN 'medium' THEN 99.0
    WHEN 'low' THEN 98.0
    ELSE 99.0
  END;
END;
$$;


--
-- Name: get_smart_notifications(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_smart_notifications(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant_id uuid;
  result jsonb := '[]'::jsonb;
  v_offline_count integer;
  v_critical_alerts integer;
  v_pending_jobs integer;
  v_last_scan timestamptz;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  -- Get tenant context
  v_tenant_id := COALESCE(p_tenant_id, get_active_tenant_id());
  
  IF v_tenant_id IS NULL THEN
    RETURN result;
  END IF;

  -- Check offline agents
  SELECT COUNT(*) INTO v_offline_count
  FROM agents 
  WHERE tenant_id = v_tenant_id 
    AND archived_at IS NULL
    AND (last_heartbeat IS NULL OR last_heartbeat < NOW() - INTERVAL '10 minutes');

  IF v_offline_count > 0 THEN
    result := result || jsonb_build_object(
      'type', 'agents_offline',
      'title', format('%s computador%s desconectado%s', 
        v_offline_count, 
        CASE WHEN v_offline_count > 1 THEN 'es' ELSE '' END,
        CASE WHEN v_offline_count > 1 THEN 's' ELSE '' END
      ),
      'message', 'Verifique se estão ligados e conectados à internet',
      'urgency', CASE WHEN v_offline_count > 5 THEN 'high' ELSE 'medium' END,
      'action', 'Ver computadores',
      'actionHref', '/admin/agent-health'
    );
  END IF;

  -- Check critical alerts
  SELECT COUNT(*) INTO v_critical_alerts
  FROM system_alerts 
  WHERE tenant_id = v_tenant_id 
    AND severity IN ('critical', 'high')
    AND resolved = false;

  IF v_critical_alerts > 0 THEN
    result := result || jsonb_build_object(
      'type', 'critical_alerts',
      'title', format('%s alerta%s de segurança', 
        v_critical_alerts,
        CASE WHEN v_critical_alerts > 1 THEN 's' ELSE '' END
      ),
      'message', 'Ameaças detectadas que precisam de atenção',
      'urgency', 'high',
      'action', 'Ver alertas',
      'actionHref', '/admin/security-monitoring'
    );
  END IF;

  -- Check pending jobs
  SELECT COUNT(*) INTO v_pending_jobs
  FROM jobs 
  WHERE tenant_id = v_tenant_id 
    AND status IN ('queued', 'pending')
    AND created_at < NOW() - INTERVAL '1 hour';

  IF v_pending_jobs > 3 THEN
    result := result || jsonb_build_object(
      'type', 'pending_jobs',
      'title', 'Tarefas pendentes',
      'message', format('%s tarefas aguardando execução há mais de 1 hora', v_pending_jobs),
      'urgency', 'medium',
      'action', 'Ver tarefas',
      'actionHref', '/admin/job-orchestration'
    );
  END IF;

  -- All good notification
  IF jsonb_array_length(result) = 0 THEN
    result := result || jsonb_build_object(
      'type', 'all_good',
      'title', 'Tudo em ordem!',
      'message', 'Seus computadores estão protegidos e funcionando normalmente',
      'urgency', 'low'
    );
  END IF;

  RETURN result;
END;
$$;


--
-- Name: FUNCTION get_smart_notifications(p_tenant_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_smart_notifications(p_tenant_id uuid) IS 'Returns notifications in simple business language for the Simple Mode dashboard.
Designed for non-technical users (business owners).';


--
-- Name: get_software_risk_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_software_risk_summary(p_tenant_id uuid) RETURNS TABLE(risk_level text, count bigint, category_breakdown jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  -- Validate tenant access
  IF NOT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = auth.uid() AND tenant_id = p_tenant_id
  ) THEN
    RAISE EXCEPTION 'Unauthorized: No access to tenant'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
  WITH categorized AS (
    SELECT 
      si.risk_level,
      COALESCE(skb.category, 'uncategorized') as category,
      COUNT(*) as cnt
    FROM software_inventory si
    LEFT JOIN software_knowledge_base skb ON (
      skb.is_active = true AND (
        (skb.match_type = 'exact' AND LOWER(si.name) = LOWER(skb.software_pattern))
        OR (skb.match_type = 'contains' AND LOWER(si.name) LIKE '%' || LOWER(skb.software_pattern) || '%')
      )
    )
    WHERE si.tenant_id = p_tenant_id
    GROUP BY si.risk_level, COALESCE(skb.category, 'uncategorized')
  )
  SELECT 
    c.risk_level,
    SUM(c.cnt)::BIGINT as count,
    jsonb_object_agg(c.category, c.cnt) as category_breakdown
  FROM categorized c
  GROUP BY c.risk_level
  ORDER BY 
    CASE c.risk_level 
      WHEN 'critical' THEN 1 
      WHEN 'high' THEN 2 
      WHEN 'medium' THEN 3 
      WHEN 'low' THEN 4 
      ELSE 5 
    END;
END;
$$;


--
-- Name: get_stale_agents(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_stale_agents(p_tenant_id uuid, p_threshold_minutes integer DEFAULT 30) RETURNS TABLE(agent_id uuid, agent_name text, display_name text, hostname text, last_heartbeat timestamp with time zone, minutes_since_heartbeat numeric, agent_version text, status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  RETURN QUERY
  SELECT 
    a.id, a.agent_name, a.display_name, a.hostname, a.last_heartbeat,
    ROUND(EXTRACT(EPOCH FROM (NOW() - a.last_heartbeat))/60, 1),
    a.agent_version, a.status
  FROM agents a
  WHERE a.tenant_id = p_tenant_id
    AND a.archived_at IS NULL AND a.status = 'active'
    AND a.last_heartbeat IS NOT NULL
    AND a.last_heartbeat < NOW() - (p_threshold_minutes || ' minutes')::interval
  ORDER BY a.last_heartbeat ASC;
END;
$$;


--
-- Name: FUNCTION get_stale_agents(p_tenant_id uuid, p_threshold_minutes integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_stale_agents(p_tenant_id uuid, p_threshold_minutes integer) IS 'Retorna agentes cujo heartbeat está atrasado além do threshold especificado (padrão 30 min). Útil para monitoramento e detecção de agentes offline.';


--
-- Name: get_system_mode(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_system_mode() RETURNS public.system_operational_mode
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  current_mode system_operational_mode;
BEGIN
  SELECT mode INTO current_mode FROM system_global_state LIMIT 1;
  RETURN COALESCE(current_mode, 'normal'::system_operational_mode);
END;
