--
-- Name: get_system_mode_safe(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_system_mode_safe() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  current_mode text;
BEGIN
  SELECT mode::text INTO current_mode FROM system_global_state LIMIT 1;
