--
-- Name: get_user_tenant_id_safe(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_tenant_id_safe(p_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
  v_check_user_id UUID;
BEGIN
  v_check_user_id := COALESCE(p_user_id, auth.uid());
  
  IF v_check_user_id IS NULL THEN
    RETURN NULL;
  END IF;
  
  SELECT tenant_id INTO v_tenant_id
  FROM profiles
  WHERE user_id = v_check_user_id
  LIMIT 1;
  
  IF v_tenant_id IS NOT NULL THEN
    RETURN v_tenant_id;
  END IF;
  
  SELECT tenant_id INTO v_tenant_id
  FROM tenant_users
  WHERE user_id = v_check_user_id
  LIMIT 1;
  
  RETURN v_tenant_id;
END;
$$;


--
-- Name: get_valid_agent_signing_key(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_valid_agent_signing_key(p_agent_id uuid, p_fingerprint text) RETURNS TABLE(key_id uuid, public_key text, version integer, algorithm text, is_current boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_max_version INT;
BEGIN
  -- Buscar versão máxima ativa do agente
  SELECT COALESCE(MAX(ask.version), 0) INTO v_max_version
  FROM agent_signing_keys ask
  WHERE ask.agent_id = p_agent_id 
    AND ask.revoked_at IS NULL;
  
  RETURN QUERY
  SELECT 
    ask.id as key_id,
    ask.public_key,
    ask.version,
    ask.algorithm,
    (ask.version = v_max_version) as is_current
  FROM agent_signing_keys ask
  WHERE ask.agent_id = p_agent_id
    AND ask.key_fingerprint = p_fingerprint
    AND ask.revoked_at IS NULL
    -- Aceitar N (atual) e N-1 (anterior) para rotação sem downtime
    AND ask.version >= GREATEST(v_max_version - 1, 1)
  ORDER BY ask.version DESC
  LIMIT 1;
END;
$$;


--
-- Name: get_valid_agent_signing_key_by_agent(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_valid_agent_signing_key_by_agent(p_agent_id uuid) RETURNS TABLE(key_id uuid, public_key text, version integer, algorithm text, is_current boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_max_version INT;
BEGIN
  -- Buscar versão máxima não-revogada do agente
  SELECT COALESCE(MAX(ask.version), 0) INTO v_max_version
  FROM agent_signing_keys ask
  WHERE ask.agent_id = p_agent_id 
    AND ask.revoked_at IS NULL;
  
  -- Retornar chaves N e N-1 (para suportar rotação)
  RETURN QUERY
  SELECT 
    ask.id as key_id,
    ask.public_key,
    ask.version,
    ask.algorithm,
    (ask.version = v_max_version) as is_current
  FROM agent_signing_keys ask
  WHERE ask.agent_id = p_agent_id
    AND ask.revoked_at IS NULL
    -- Aceitar N (atual) e N-1 (anterior) para rotação sem downtime
    AND ask.version >= GREATEST(v_max_version - 1, 1)
  ORDER BY ask.version DESC;
END;
$$;


--
-- Name: FUNCTION get_valid_agent_signing_key_by_agent(p_agent_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_valid_agent_signing_key_by_agent(p_agent_id uuid) IS 'Returns all valid signing keys (N and N-1) for an agent to support key rotation without downtime';


