--

CREATE FUNCTION public.get_vulnerability_counts(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'total', (SELECT count(*) FROM vuln_findings WHERE tenant_id = p_tenant_id),
    'critical', (SELECT count(*) FROM vuln_findings WHERE tenant_id = p_tenant_id AND severity IN ('critical', 'high'))
  );
$$;


--
-- Name: get_zombie_threshold_minutes(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_zombie_threshold_minutes(p_job_type text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_job_type LIKE 'collect_%' THEN 30
    WHEN p_job_type = 'light_vuln_scan' THEN 30
    WHEN p_job_type = 'integration_test_v3' THEN 30
    WHEN p_job_type = 'health_check' THEN 15
    WHEN p_job_type = 'config' THEN 15
    WHEN p_job_type = 'software_inventory_collect' THEN 60
    WHEN p_job_type = 'disk_cleanup' THEN 60
    WHEN p_job_type = 'update_agent' THEN 120
    WHEN p_job_type = 'apply_security_patch' THEN 120
    WHEN p_job_type = 'reinstall_agent' THEN 120
    ELSE 45
  END;
$$;


--
-- Name: guard_role_self_promotion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_role_self_promotion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Block self-promotion: user cannot assign admin role to themselves
  -- unless they are already an admin or super_admin for this tenant
  IF NEW.user_id = auth.uid() AND NEW.role = 'admin' THEN
    -- Check if caller is already admin or super_admin
    IF NOT EXISTS (
      SELECT 1 FROM public.user_roles
      WHERE user_id = auth.uid()
        AND tenant_id = NEW.tenant_id
        AND role IN ('admin', 'super_admin')
    ) THEN
      RAISE EXCEPTION 'SECURITY: Cannot self-promote to admin (INV-006)';
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: handle_archived_agent_heartbeat(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_archived_agent_heartbeat(p_agent_id uuid, p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agent RECORD;
  v_days_archived integer;
  v_action text;
  v_alert_severity text;
  v_alert_title text;
  v_alert_message text;
  v_requires_decision boolean;
BEGIN
  SELECT id, agent_name, hostname, agent_state, archived_at, tenant_id
  INTO v_agent
  FROM public.agents
  WHERE id = p_agent_id
    AND tenant_id = p_tenant_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('action', 'ignored', 'reason', 'agent_not_found');
  END IF;

  IF COALESCE(v_agent.archived_at IS NOT NULL, false) = false THEN
    RETURN jsonb_build_object('action', 'ignored', 'reason', 'agent_not_archived');
  END IF;

  v_days_archived := FLOOR(EXTRACT(EPOCH FROM (now() - v_agent.archived_at)) / 86400)::integer;

  IF v_days_archived < 15 THEN
    UPDATE public.agents
    SET agent_state = 'healthy',
        status = 'active',
        archived_at = NULL,
        archived_reason = NULL,
        agent_state_reason = 'Auto-reativado via heartbeat após ' || v_days_archived || ' dias arquivado',
        agent_state_changed_at = now(),
        last_heartbeat = now()
    WHERE id = p_agent_id
      AND tenant_id = p_tenant_id;

    v_action := 'reactivated';
    v_alert_severity := 'medium';
    v_alert_title := 'Agente reativado automaticamente';
    v_alert_message := format(
      'O agente "%s" (%s) foi reativado automaticamente após enviar heartbeat. Estava arquivado há %s dias.',
      v_agent.agent_name,
      COALESCE(v_agent.hostname, 'N/A'),
      v_days_archived
    );
    v_requires_decision := false;
  ELSE
    v_action := 'alert_only';
    v_alert_severity := 'high';
    v_alert_title := 'Heartbeat de agente arquivado requer aprovação';
    v_alert_message := format(
      'O agente "%s" (%s) enviou heartbeat, mas está arquivado há %s dias. Reativação requer aprovação manual.',
      v_agent.agent_name,
      COALESCE(v_agent.hostname, 'N/A'),
      v_days_archived
    );
    v_requires_decision := true;
  END IF;

  INSERT INTO public.system_alerts (
    tenant_id,
    agent_id,
    alert_type,
    severity,
    title,
    message,
    details,
    requires_human_decision,
    source,
    status,
    resolved
  ) VALUES (
    p_tenant_id,
    p_agent_id,
    'automation_alert',
    v_alert_severity,
    v_alert_title,
    v_alert_message,
    jsonb_build_object(
      'category', 'archived_agent_heartbeat',
      'days_archived', v_days_archived,
      'action_taken', v_action,
      'agent_name', v_agent.agent_name,
      'hostname', v_agent.hostname
    ),
    v_requires_decision,
    'heartbeat_monitor',
    'active',
    false
  );

  RETURN jsonb_build_object(
    'action', v_action,
    'days_archived', v_days_archived,
    'agent_name', v_agent.agent_name
  );
END;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  full_name TEXT;
  user_email TEXT;
  tenant_slug TEXT;
  new_tenant_id UUID;
  free_plan_id UUID;
  device_qty INTEGER := 1;
  device_count_str TEXT;
  has_pending_invite BOOLEAN := FALSE;
  admin_provisioned BOOLEAN := FALSE;
  trial_end_date TIMESTAMPTZ;
BEGIN
  -- Extrair dados do usuário
  full_name := COALESCE(
    NEW.raw_user_meta_data->>'full_name',
    NEW.raw_user_meta_data->>'name',
    split_part(NEW.email, '@', 1)
  );
  user_email := COALESCE(NEW.email, '');

  -- 1) UPSERT em profiles (idempotente)
  INSERT INTO public.profiles (user_id, full_name, username, updated_at)
  VALUES (NEW.id, full_name, NULL, NOW())
  ON CONFLICT (user_id) DO UPDATE SET
    full_name = COALESCE(EXCLUDED.full_name, profiles.full_name),
    updated_at = NOW();

  -- 2) Verificar se foi provisionado por admin
  admin_provisioned := COALESCE((NEW.raw_user_meta_data->>'admin_provisioned')::BOOLEAN, FALSE);
  IF admin_provisioned THEN
    RETURN NEW;
  END IF;

  -- 3) Verificar convite pendente
  SELECT EXISTS (
    SELECT 1 FROM public.invites 
    WHERE email = user_email 
      AND status = 'pending'
  ) INTO has_pending_invite;
  
  IF has_pending_invite THEN
    RETURN NEW;
  END IF;

  -- 4) Gerar slug único para tenant
  tenant_slug := lower(regexp_replace(
    COALESCE(full_name, split_part(user_email, '@', 1)),
    '[^a-zA-Z0-9]+', '-', 'g'
  )) || '-' || substring(NEW.id::text FROM 1 FOR 8);

  -- 5) Criar tenant com schema correto
  INSERT INTO public.tenants (name, slug, owner_user_id)
  VALUES (
    COALESCE(full_name, 'Minha Empresa'),
    tenant_slug,
    NEW.id
  )
  RETURNING id INTO new_tenant_id;

  -- 6) Criar role 'admin' para o usuário no tenant
  INSERT INTO public.user_roles (user_id, role, tenant_id)
  VALUES (NEW.id, 'admin', new_tenant_id);

  -- 7) Mapear device_count para device_qty
  device_count_str := NEW.raw_user_meta_data->>'device_count';
  device_qty := CASE device_count_str
    WHEN '1-3' THEN 3
    WHEN '4-10' THEN 10
    WHEN '11-30' THEN 30
    WHEN '31-100' THEN 100
    WHEN '100+' THEN 100
    ELSE 1
  END;

  -- 8) Buscar plano 'free'
  SELECT id INTO free_plan_id
  FROM public.subscription_plans
  WHERE name = 'free'
  LIMIT 1;

  IF free_plan_id IS NULL THEN
    RAISE EXCEPTION 'Plano "free" não encontrado em subscription_plans';
  END IF;

  -- 9) Calcular data de trial (14 dias)
  trial_end_date := NOW() + INTERVAL '14 days';

  -- 10) UPSERT em tenant_subscriptions (idempotente com create_default_subscription)
  INSERT INTO public.tenant_subscriptions (
    tenant_id,
    plan_id,
    status,
    trial_end,
    current_period_end,
    device_quantity,
    created_at,
    updated_at
  )
  VALUES (
    new_tenant_id,
    free_plan_id,
    'trialing',
    trial_end_date,
    trial_end_date,
    device_qty,
    NOW(),
    NOW()
  )
  ON CONFLICT (tenant_id) DO UPDATE SET
    status = 'trialing',
    trial_end = trial_end_date,
    current_period_end = trial_end_date,
    device_quantity = device_qty,
    updated_at = NOW();

  -- 11) Provisionar features do plano free
  PERFORM public.ensure_tenant_features(new_tenant_id, 'free', device_qty);

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION handle_new_user(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.handle_new_user() IS 'ADR-024: Trigger de onboarding corrigido. Usa schema correto (slug, owner_user_id, admin role). 
UPSERT em tenant_subscriptions para idempotência com create_default_subscription. 
Trial de 14 dias automático. Respeita admin_provisioned e pending_invite.';


