--
-- Name: hmac_check_and_record(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hmac_check_and_record(p_signature text, p_agent_name text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_inserted boolean;
BEGIN
    -- Try to insert the signature. If it exists, it's a replay.
    INSERT INTO public.agent_hmac_signatures (signature, agent_name, created_at)
    VALUES (p_signature, p_agent_name, now())
    ON CONFLICT (signature) DO NOTHING;
    
    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    
    -- If ROW_COUNT is 1, it was a new signature and we recorded it.
    -- If ROW_COUNT is 0, it was already present (replay).
    RETURN v_inserted > 0;
END;
$$;


--
-- Name: hmac_signatures_delete_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hmac_signatures_delete_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Delete from all partitions
  DELETE FROM public.hmac_signatures_2025_12 WHERE id = OLD.id OR (signature = OLD.signature AND agent_name = OLD.agent_name);
  DELETE FROM public.hmac_signatures_2026_01 WHERE id = OLD.id OR (signature = OLD.signature AND agent_name = OLD.agent_name);
  RETURN OLD;
END;
$$;


--
-- Name: hmac_signatures_insert_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hmac_signatures_insert_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  partition_name TEXT;
  partition_start DATE;
  partition_end DATE;
BEGIN
  partition_start := date_trunc('month', COALESCE(NEW.used_at, NOW()))::DATE;
  partition_end := (partition_start + INTERVAL '1 month')::DATE;
  partition_name := 'hmac_signatures_' || to_char(partition_start, 'YYYY_MM');
  
  -- Create partition if not exists
  IF NOT EXISTS (
    SELECT 1 FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE c.relname = partition_name AND n.nspname = 'public'
  ) THEN
    EXECUTE format(
      'CREATE TABLE IF NOT EXISTS public.%I (
        id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
        signature TEXT NOT NULL,
        agent_name TEXT NOT NULL,
        used_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
      )', partition_name
    );
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_signature ON public.%I(signature)', partition_name, partition_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_used_at ON public.%I(used_at)', partition_name, partition_name);
  END IF;
  
  -- Insert into correct partition
  EXECUTE format(
    'INSERT INTO public.%I (id, signature, agent_name, used_at) VALUES ($1, $2, $3, $4)',
    partition_name
  ) USING COALESCE(NEW.id, gen_random_uuid()), NEW.signature, NEW.agent_name, COALESCE(NEW.used_at, NOW());
  
  RETURN NEW;
END;
$_$;


