--

CREATE FUNCTION public.increment_incident_event_count() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE correlated_incidents
  SET event_count = event_count + 1
  WHERE id = NEW.incident_id;
  RETURN NEW;
END;
$$;


--
-- Name: increment_playbook_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_playbook_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Incrementar versão quando playbook é modificado (exceto updated_at)
  IF (NEW.name IS DISTINCT FROM OLD.name) OR
     (NEW.description IS DISTINCT FROM OLD.description) OR
     (NEW.trigger_type IS DISTINCT FROM OLD.trigger_type) OR
     (NEW.trigger_conditions IS DISTINCT FROM OLD.trigger_conditions) OR
     (NEW.severity IS DISTINCT FROM OLD.severity) OR
     (NEW.require_approval IS DISTINCT FROM OLD.require_approval) THEN
    NEW.version := OLD.version + 1;
    NEW.updated_at := now();
  END IF;
  
  RETURN NEW;
END;
$$;


