--
-- Name: installation_health_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.installation_health_summary() RETURNS TABLE(os_type text, total_events bigint, successful_events bigint, failed_events bigint, success_rate numeric, window_interval text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT 
    ia.platform AS os_type,
    COUNT(*) AS total_events,
    COUNT(*) FILTER (WHERE ia.success = true) AS successful_events,
    COUNT(*) FILTER (WHERE ia.success = false) AS failed_events,
    ROUND(
      (COUNT(*) FILTER (WHERE ia.success = true)::NUMERIC / 
       NULLIF(COUNT(*)::NUMERIC, 0)) * 100, 
      1
    ) AS success_rate,
    'all_time' AS window_interval
  FROM installation_analytics ia
  WHERE ia.event_type = 'post_installation'
    AND ia.tenant_id IN (
      SELECT ur.tenant_id 
      FROM user_roles ur 
      WHERE ur.user_id = auth.uid()
    )
  GROUP BY ia.platform
  ORDER BY 
    CASE ia.platform
      WHEN 'macos' THEN 0
      WHEN 'windows' THEN 1
      WHEN 'linux' THEN 2
      ELSE 3
    END;
$$;


--
-- Name: FUNCTION installation_health_summary(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.installation_health_summary() IS 'Retorna metricas de instalacao por OS (ultimos 7 dias). Usado pelo InstallationHealthCard. Respeita RLS filtrando por tenant_id do usuario autenticado.';


--
-- Name: invalidate_cache_prefix(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_cache_prefix(p_prefix text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM kv_cache WHERE key LIKE (p_prefix || '%');
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$;


--
-- Name: invalidate_old_agent_tokens(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_old_agent_tokens() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing_agent_id UUID;
BEGIN
  -- Verificar se já existe agente com mesmo nome no tenant
  SELECT id INTO v_existing_agent_id
  FROM public.agents
  WHERE agent_name = NEW.agent_name
    AND tenant_id = NEW.tenant_id
    AND id != NEW.id
    AND status IN ('pending', 'active')
  LIMIT 1;
  
  IF v_existing_agent_id IS NOT NULL THEN
    -- Invalidar todos os tokens do agente antigo
    UPDATE public.agent_tokens
    SET is_active = false
    WHERE agent_id = v_existing_agent_id;
    
    -- Marcar agente antigo como inactive
    UPDATE public.agents
    SET status = 'inactive'
    WHERE id = v_existing_agent_id;
    
    RAISE NOTICE 'Invalidated old agent % and its tokens', v_existing_agent_id;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION invalidate_old_agent_tokens(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.invalidate_old_agent_tokens() IS 'Invalida tokens e marca como inactive agentes anteriores com mesmo nome no tenant (previne conflitos de instalação)';


