--
-- Name: log_circuit_breaker_to_decisions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_circuit_breaker_to_decisions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Only log state changes (not initial inserts to closed state)
  IF NEW.state != 'closed' OR NEW.previous_state IS NOT NULL THEN
    INSERT INTO public.decision_events (
      tenant_id,
      decision_type,
      decision_source,
      rule_code,
      severity,
      action,
      evidence,
      created_at
    ) VALUES (
      NEW.tenant_id,
      'system',
      'resilience_engine',
      'CIRCUIT_BREAKER_' || UPPER(NEW.state),
      CASE NEW.state 
        WHEN 'open' THEN 'high'
        WHEN 'half_open' THEN 'medium'
        ELSE 'low'
      END,
      'circuit_breaker_' || NEW.state,
      jsonb_build_object(
        'service', NEW.service,
        'state', NEW.state,
        'previous_state', NEW.previous_state,
        'reason', NEW.reason,
        'triggered_by', NEW.triggered_by,
        'failure_count', NEW.failure_count
      ),
      NOW()
    );
  END IF;
  
  RETURN NEW;
END;
$$;


