        'max_uses', NEW.max_uses
      )
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: log_scheduled_job_run(text, boolean, integer, text, jsonb, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_scheduled_job_run(p_job_key text, p_success boolean, p_duration_ms integer DEFAULT NULL::integer, p_error text DEFAULT NULL::text, p_result jsonb DEFAULT NULL::jsonb, p_processed_count integer DEFAULT 0, p_job_source text DEFAULT 'cron'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO public.scheduled_job_runs (
    job_key,
    job_source,
    ran_at,
    success,
    duration_ms,
    error,
    result,
    processed_count
  ) VALUES (
    p_job_key,
    COALESCE(p_job_source, 'cron'),
    NOW(),
    p_success,
    p_duration_ms,
    p_error,
    p_result,
    p_processed_count
  )
  RETURNING id INTO v_id;

  -- Keep scheduled_jobs metadata fresh only for successful runs
  IF p_success THEN
    UPDATE public.scheduled_jobs sj
    SET
      last_run_at = NOW(),
      next_run_at = CASE
        WHEN sj.cron_expr IS NOT NULL THEN public.calculate_next_run(sj.cron_expr, NOW())
        ELSE sj.next_run_at
      END,
      updated_at = NOW()
    WHERE
      lower(replace(sj.job_key, '_', '-')) = lower(replace(p_job_key, '_', '-'))
      OR lower(replace(COALESCE(sj.job_type, ''), '_', '-')) = lower(replace(p_job_key, '_', '-'))
      OR lower(replace(COALESCE(sj.payload->>'function_name', ''), '_', '-')) = lower(replace(p_job_key, '_', '-'));
  END IF;

  RETURN v_id;
END;
$$;


