--
-- Name: log_session_start(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_session_start(_ip_address text, _user_agent text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _session_id UUID;
  _user_id UUID;
  _is_super_admin BOOLEAN;
  _timeout_minutes INTEGER;
BEGIN
  _user_id := auth.uid();
  
  IF _user_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Verificar se é super_admin
  SELECT EXISTS(
    SELECT 1 FROM user_roles 
    WHERE user_id = _user_id AND role = 'super_admin'
  ) INTO _is_super_admin;

  -- Calcular timeout
  _timeout_minutes := CASE WHEN _is_super_admin THEN 15 ELSE 480 END;

  -- Limpar sessões antigas do mesmo usuário
  DELETE FROM active_sessions 
  WHERE user_id = _user_id 
    AND (expires_at < now() OR last_activity_at < now() - interval '1 day');

  -- Inserir nova sessão
  INSERT INTO active_sessions (
    user_id, 
    tenant_id,
    ip_address, 
    user_agent, 
    expires_at, 
    is_super_admin
  ) VALUES (
    _user_id,
    ((auth.jwt()->'app_metadata')::jsonb->>'active_tenant_id')::UUID,
    _ip_address,
    _user_agent,
    now() + (_timeout_minutes || ' minutes')::interval,
    _is_super_admin
  ) RETURNING id INTO _session_id;

  RETURN _session_id;
END;
$$;


