--
-- Name: log_task_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_task_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO task_events (task_id, tenant_id, actor_type, action, metadata)
    VALUES (
      NEW.id, 
      NEW.tenant_id, 
      'system', 
      'created', 
      jsonb_build_object(
        'severity', NEW.severity,
        'source_type', NEW.source_type,
        'source_id', NEW.source_id,
        'auto_generated', NEW.auto_generated,
        'title', NEW.title
      )
    );
  ELSIF TG_OP = 'UPDATE' THEN
    -- Log status changes
    IF OLD.status IS DISTINCT FROM NEW.status THEN
      INSERT INTO task_events (task_id, tenant_id, actor_type, actor_id, action, metadata)
      VALUES (
        NEW.id, 
        NEW.tenant_id, 
        CASE WHEN NEW.closed_by IS NOT NULL THEN 'human' ELSE 'system' END,
        COALESCE(NEW.closed_by, NEW.assigned_to),
        'status_changed', 
        jsonb_build_object(
          'from', OLD.status, 
          'to', NEW.status, 
          'reason', NEW.closure_reason
        )
      );
    END IF;
    
    -- Log assignment changes
    IF OLD.assigned_to IS DISTINCT FROM NEW.assigned_to AND NEW.assigned_to IS NOT NULL THEN
      INSERT INTO task_events (task_id, tenant_id, actor_type, action, metadata)
      VALUES (
        NEW.id, 
        NEW.tenant_id, 
        'human', 
        'assigned', 
        jsonb_build_object(
          'previous_owner', OLD.assigned_to,
          'new_owner', NEW.assigned_to
        )
      );
    END IF;
    
    -- Log SLA breach
    IF OLD.sla_breached_at IS NULL AND NEW.sla_breached_at IS NOT NULL THEN
      INSERT INTO task_events (task_id, tenant_id, actor_type, action, metadata)
      VALUES (
        NEW.id, 
        NEW.tenant_id, 
        'system', 
        'sla_breached', 
        jsonb_build_object(
          'due_at', NEW.due_at,
          'breached_at', NEW.sla_breached_at
        )
      );
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


