--
-- Name: normalize_job_failure(public.jobs); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_job_failure(job_record public.jobs) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  error_code text;
  agent_version_major text;
  signature jsonb;
BEGIN
  error_code := CASE
    WHEN job_record.error_message ~* 'ECONNRESET|timeout|ETIMEDOUT|timed out' THEN 'NETWORK_TIMEOUT'
    WHEN job_record.error_message ~* 'permission denied|403|unauthorized|401' THEN 'AUTH_ERROR'
    WHEN job_record.error_message ~* 'null|undefined|NaN|nil' THEN 'NULL_REFERENCE'
    WHEN job_record.error_message ~* 'out of memory|heap|stack overflow' THEN 'MEMORY_ERROR'
    WHEN job_record.error_message ~* 'disk full|no space|ENOSPC' THEN 'DISK_ERROR'
    WHEN job_record.error_message ~* 'connection refused|ECONNREFUSED' THEN 'CONNECTION_REFUSED'
    WHEN job_record.error_message ~* 'DNS|resolve|ENOTFOUND' THEN 'DNS_ERROR'
    WHEN job_record.error_message ~* 'certificate|SSL|TLS' THEN 'SSL_ERROR'
    WHEN job_record.error_message IS NULL THEN 'NO_MESSAGE'
    ELSE 'UNKNOWN'
  END;
  
  SELECT COALESCE(
    CASE 
      WHEN a.agent_version ~ '^1\.' THEN 'v1'
      WHEN a.agent_version ~ '^2\.' THEN 'v2'
      WHEN a.agent_version ~ '^3\.' THEN 'v3'
      ELSE 'unknown'
    END,
    'unknown'
  ) INTO agent_version_major
  FROM public.agents a WHERE a.id = job_record.agent_id;
  
  signature := jsonb_build_object(
    'source_type', 'job',
    'job_type', COALESCE(job_record.type, 'unknown'),
    'failure_class', COALESCE(job_record.failure_class, 'UNKNOWN'),
    'error_code', error_code,
    'agent_version_major', COALESCE(agent_version_major, 'unknown')
  );
  
  RETURN signature;
END;
$$;


--
-- Name: FUNCTION normalize_job_failure(job_record public.jobs); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.normalize_job_failure(job_record public.jobs) IS 'ADR-033: Extracts deterministic signature from job failure';


--
-- Name: notify_ai_insight_dispatcher(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_ai_insight_dispatcher() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  service_key TEXT;
BEGIN
  -- Only process if auto_action_mode is not 'none'
  IF NEW.auto_action_mode IS NOT NULL AND NEW.auto_action_mode != 'none' THEN
    service_key := current_setting('app.settings.service_role_key', true);
    
    -- Use pg_net to call the dispatcher asynchronously
    -- FIXED: Send complete insight object with all required fields
    PERFORM net.http_post(
      url := 'https://iavbnmduxpxhwubqrzzn.supabase.co/functions/v1/ai-insight-dispatcher',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || service_key
      ),
      body := jsonb_build_object(
        'insight', jsonb_build_object(
          'id', NEW.id,
          'tenant_id', NEW.tenant_id,
          'agent_id', NEW.agent_id,
          'insight_type', NEW.insight_type,
          'severity', NEW.severity,
          'title', NEW.title,
          'description', NEW.description,
          'evidence', COALESCE(NEW.evidence, '{}'::jsonb),
          'recommendation', NEW.recommendation,
          'confidence_score', NEW.confidence_score,
          'auto_action_mode', NEW.auto_action_mode,
          'category', NEW.category,
          'recommended_actions', COALESCE(NEW.recommended_actions, '[]'::jsonb)
        ),
        'source', 'trigger'
      )
    );
    
    RAISE LOG '[notify_ai_insight_dispatcher] Dispatched insight % with mode %', NEW.id, NEW.auto_action_mode;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: parse_version_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.parse_version_code(version_text text) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  clean_version TEXT;
  parts TEXT[];
  major INT;
  minor INT;
  patch INT;
BEGIN
  IF version_text IS NULL THEN RETURN NULL; END IF;
  
  -- Remove 'v' prefix se existir
  clean_version := REGEXP_REPLACE(version_text, '^v', '', 'i');
  
  -- Split por '.'
  parts := STRING_TO_ARRAY(clean_version, '.');
  
  -- Parse cada parte (com fallback para 0)
  major := COALESCE(NULLIF(parts[1], '')::INT, 0);
  minor := COALESCE(NULLIF(parts[2], '')::INT, 0);
  patch := COALESCE(NULLIF(parts[3], '')::INT, 0);
  
  RETURN (major * 10000) + (minor * 100) + patch;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$$;


--
-- Name: persist_chain_breaks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.persist_chain_breaks() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hash_count INTEGER := 0;
  v_gap_count INTEGER := 0;
BEGIN
  -- Insert hash mismatch breaks (where consecutive executions don't chain properly)
  WITH inserted AS (
    INSERT INTO poe_chain_breaks (agent_id, tenant_id, break_type, context)
    SELECT 
      e1.agent_id,
      a.tenant_id,
      'hash_mismatch',
      jsonb_build_object(
        'execution_1_id', e1.id,
        'execution_1_index', e1.execution_index,
        'execution_1_hash', e1.execution_hash,
        'execution_2_id', e2.id,
        'execution_2_index', e2.execution_index,
        'execution_2_previous_hash', e2.previous_execution_hash
      )
    FROM job_executions e1
    JOIN job_executions e2
      ON e2.agent_id = e1.agent_id
     AND e2.execution_index = e1.execution_index + 1
    JOIN agents a ON a.id = e1.agent_id
    WHERE e2.previous_execution_hash IS NOT NULL
      AND e1.execution_hash IS NOT NULL
      AND e2.previous_execution_hash != e1.execution_hash
      AND NOT EXISTS (
        SELECT 1 FROM poe_chain_breaks pcb
        WHERE pcb.agent_id = e1.agent_id
          AND pcb.break_type = 'hash_mismatch'
          AND pcb.context->>'execution_1_id' = e1.id::text
      )
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_hash_count FROM inserted;
  
  -- Insert index gap breaks (missing execution indices)
  WITH inserted AS (
    INSERT INTO poe_chain_breaks (agent_id, tenant_id, break_type, context)
    SELECT 
      e1.agent_id,
      a.tenant_id,
      'index_gap',
      jsonb_build_object(
        'execution_id', e1.id,
        'current_index', e1.execution_index,
        'expected_next', e1.execution_index + 1,
        'actual_next', (
          SELECT MIN(e2.execution_index) 
          FROM job_executions e2 
          WHERE e2.agent_id = e1.agent_id 
            AND e2.execution_index > e1.execution_index
        )
      )
    FROM job_executions e1
    JOIN agents a ON a.id = e1.agent_id
    WHERE NOT EXISTS (
      SELECT 1 FROM job_executions e2 
      WHERE e2.agent_id = e1.agent_id 
        AND e2.execution_index = e1.execution_index + 1
    )
    AND EXISTS (
      SELECT 1 FROM job_executions e3 
      WHERE e3.agent_id = e1.agent_id 
        AND e3.execution_index > e1.execution_index + 1
    )
    AND NOT EXISTS (
      SELECT 1 FROM poe_chain_breaks pcb
      WHERE pcb.agent_id = e1.agent_id
        AND pcb.break_type = 'index_gap'
        AND pcb.context->>'execution_id' = e1.id::text
    )
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_gap_count FROM inserted;
  
  RETURN v_hash_count + v_gap_count;
END;
$$;


--
-- Name: poll_jobs_v2(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.poll_jobs_v2(p_token_hash text, p_max_jobs integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_agent_id uuid;
    v_agent_name text;
    v_tenant_id uuid;
    v_jobs jsonb;
BEGIN
    -- 1. Validate token
    SELECT a.id, a.agent_name, a.tenant_id
    INTO v_agent_id, v_agent_name, v_tenant_id
    FROM agent_tokens t
    JOIN agents a ON t.agent_id = a.id
    WHERE t.token_hash = p_token_hash
      AND t.is_active = true
      AND a.status = 'active';

    IF v_agent_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_token');
    END IF;

    -- 2. Claim + return jobs in one CTE
    WITH claimed AS (
        UPDATE jobs SET
            status = 'delivered',
            delivered_at = now(),
            delivery_attempts = COALESCE(delivery_attempts, 0) + 1
        WHERE id IN (
            SELECT id FROM jobs
            WHERE agent_id = v_agent_id
              AND status IN ('pending', 'queued')
              AND (expires_at IS NULL OR expires_at > now())
            ORDER BY priority DESC NULLS LAST, created_at ASC
            LIMIT p_max_jobs
            FOR UPDATE SKIP LOCKED
        )
        RETURNING id, type, payload, priority, created_at
    )
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', id, 'type', type, 'payload', payload,
            'priority', priority, 'created_at', created_at
        ) ORDER BY priority DESC NULLS LAST, created_at ASC
    ), '[]'::jsonb)
    INTO v_jobs
    FROM claimed;

    RETURN jsonb_build_object(
        'success', true,
        'agent_id', v_agent_id,
        'agent_name', v_agent_name,
        'jobs', v_jobs
    );
END;
$$;


