--
-- Name: prevent_execution_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_execution_deletion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Permitir deleção de registros arquivados há mais de 30 dias
  IF OLD.archived_at IS NOT NULL 
     AND OLD.archived_at < NOW() - INTERVAL '30 days' THEN
    RETURN OLD;
  END IF;
  
  -- Bloquear deleção de registros não arquivados ou recentes
  RAISE EXCEPTION 'Cannot delete job execution records. Archive first, then wait 30 days.'
    USING ERRCODE = '23514';
END;
$$;


--
-- Name: FUNCTION prevent_execution_deletion(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.prevent_execution_deletion() IS 'Security trigger: Blocks deletion of job_executions for audit compliance.
Exception: service_role can delete records older than 30 days for cleanup operations.';


--
-- Name: prevent_execution_modification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_execution_modification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.status IN ('completed', 'failed') THEN
    -- Only archived_at change is allowed on finalized executions
    IF (NEW.status = OLD.status
        AND NEW.error_message IS NOT DISTINCT FROM OLD.error_message
        AND NEW.finished_at IS NOT DISTINCT FROM OLD.finished_at
        AND NEW.exit_code IS NOT DISTINCT FROM OLD.exit_code
        AND NEW.archived_at IS DISTINCT FROM OLD.archived_at) THEN
      RETURN NEW;
    END IF;
    
    RAISE EXCEPTION 'IMMUTABLE_VIOLATION: Finalized executions cannot be modified. Execution: %', OLD.id
      USING ERRCODE = '23514';
  END IF;
  
  IF NEW.job_id != OLD.job_id 
     OR NEW.agent_id != OLD.agent_id 
     OR NEW.tenant_id != OLD.tenant_id
     OR NEW.payload_hash != OLD.payload_hash
     OR NEW.nonce != OLD.nonce
     OR NEW.claimed_at != OLD.claimed_at THEN
    RAISE EXCEPTION 'IMMUTABLE_VIOLATION: Cannot modify immutable fields on execution: %', OLD.id
      USING ERRCODE = '23514';
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: prevent_job_payload_modification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_job_payload_modification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Block any modification to payload or payload_hash after job creation
  IF OLD.payload IS DISTINCT FROM NEW.payload THEN
    RAISE EXCEPTION 'IMMUTABLE_VIOLATION: Job payload cannot be modified after creation. Job ID: %', OLD.id
      USING ERRCODE = '23514';
  END IF;
  
  IF OLD.payload_hash IS NOT NULL AND OLD.payload_hash IS DISTINCT FROM NEW.payload_hash THEN
    RAISE EXCEPTION 'IMMUTABLE_VIOLATION: Job payload_hash cannot be modified after creation. Job ID: %', OLD.id
      USING ERRCODE = '23514';
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: prevent_jobs_on_safe_mode(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_jobs_on_safe_mode() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_mode TEXT;
BEGIN
  SELECT agent_mode INTO v_mode
  FROM public.agents WHERE id = NEW.agent_id;

  IF v_mode = 'SAFE_MODE' 
     AND NEW.type NOT IN ('recovery_check', 'health_report', 'heartbeat') THEN
    RAISE EXCEPTION 'SAFE_MODE_ACTIVE: job blocked for agent %', NEW.agent_id
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: prevent_orphan_tokens(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_orphan_tokens() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'archived' AND OLD.status != 'archived' THEN
    UPDATE public.agent_tokens 
    SET is_active = false
    WHERE agent_id = NEW.id AND is_active = true;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION prevent_orphan_tokens(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.prevent_orphan_tokens() IS 'SSA-SEC: Auto-deactivates agent tokens when agent is archived to prevent orphan tokens (Token Integrity Invariant)';


