-- Name: prevent_plaintext_agent_token(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_plaintext_agent_token() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
