--
-- Name: prevent_playbook_execution_modification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_playbook_execution_modification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Impedir alteração após conclusão/cancelamento/falha
  IF OLD.status IN ('completed', 'cancelled', 'failed', 'ignored') THEN
    RAISE EXCEPTION 'IMMUTABLE_VIOLATION: Playbook execution is immutable after completion. Status: %', OLD.status
      USING ERRCODE = '23514';
  END IF;
  
  -- Impedir alteração de snapshots após criação
  IF OLD.playbook_snapshot IS NOT NULL AND NEW.playbook_snapshot IS DISTINCT FROM OLD.playbook_snapshot THEN
    RAISE EXCEPTION 'IMMUTABLE_VIOLATION: playbook_snapshot cannot be modified after creation'
      USING ERRCODE = '23514';
  END IF;
  
  IF OLD.actions_snapshot IS NOT NULL AND NEW.actions_snapshot IS DISTINCT FROM OLD.actions_snapshot THEN
    RAISE EXCEPTION 'IMMUTABLE_VIOLATION: actions_snapshot cannot be modified after creation'
      USING ERRCODE = '23514';
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: prevent_self_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_self_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_requested_by uuid;
  v_chain record;
BEGIN
  SELECT requested_by INTO v_requested_by FROM approval_requests WHERE id = NEW.request_id;
  
  IF NEW.approved_by = v_requested_by THEN
    RAISE EXCEPTION 'SEGREGATION_VIOLATION: Cannot approve your own request.' USING ERRCODE = '23514';
  END IF;
  
  SELECT ac.* INTO v_chain FROM approval_chains ac
  JOIN approval_requests ar ON ar.chain_id = ac.id WHERE ar.id = NEW.request_id;
  
  IF v_chain IS NOT NULL AND v_chain.require_different_approvers THEN
    IF EXISTS (SELECT 1 FROM approvals WHERE request_id = NEW.request_id AND approved_by = NEW.approved_by AND id != NEW.id) THEN
      RAISE EXCEPTION 'DUPLICATE_APPROVAL: Each approver can only approve once.' USING ERRCODE = '23514';
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


