--
-- Name: prevent_signing_key_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_signing_key_deletion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RAISE EXCEPTION 'IMMUTABLE_VIOLATION: Signing keys cannot be deleted, only revoked. Key: %', OLD.id
    USING ERRCODE = '23514';
END;
$$;


--
-- Name: prevent_signing_key_modification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_signing_key_modification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Permitir apenas setar revoked_at e revoked_reason
  IF OLD.public_key != NEW.public_key 
     OR OLD.key_fingerprint != NEW.key_fingerprint
     OR OLD.agent_id != NEW.agent_id
     OR OLD.version != NEW.version
     OR OLD.algorithm != NEW.algorithm
     OR OLD.valid_from != NEW.valid_from THEN
    RAISE EXCEPTION 'IMMUTABLE_VIOLATION: Signing key fields cannot be modified. Key: %', OLD.id
      USING ERRCODE = '23514';
  END IF;
  
  -- Não permitir "des-revogar" uma chave
  IF OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS NULL THEN
    RAISE EXCEPTION 'IMMUTABLE_VIOLATION: Cannot unrevoke a signing key. Key: %', OLD.id
      USING ERRCODE = '23514';
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: prevent_super_admin_self_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_super_admin_self_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Block INSERT of super_admin by non-super_admin
  IF NEW.role = 'super_admin' AND NOT is_current_super_admin() THEN
    RAISE EXCEPTION 'PRIVILEGE_ESCALATION: Only super_admin can assign super_admin role'
      USING ERRCODE = '42501';
  END IF;
  
  -- Block UPDATE to super_admin by non-super_admin
  IF TG_OP = 'UPDATE' AND NEW.role = 'super_admin' 
     AND OLD.role != 'super_admin' AND NOT is_current_super_admin() THEN
    RAISE EXCEPTION 'PRIVILEGE_ESCALATION: Only super_admin can modify roles to super_admin'
      USING ERRCODE = '42501';
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: prevent_truncate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_truncate() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_obj record;
  v_protected_tables text[] := ARRAY[
    'audit_logs', 'security_logs', 'agent_evidence_logs', 
    'poe_chain_breaks', 'domain_events', 'job_executions'
  ];
BEGIN
  FOR v_obj IN SELECT * FROM pg_event_trigger_ddl_commands() LOOP
    IF v_obj.command_tag = 'TRUNCATE' THEN
      -- Note: event triggers can't prevent TRUNCATE directly,
      -- but REVOKE TRUNCATE above is the real protection.
      -- This logs any attempt that somehow bypasses REVOKE.
      RAISE WARNING 'TRUNCATE attempted on protected table - this should be blocked by REVOKE';
    END IF;
  END LOOP;
END;
$$;


--
-- Name: preview_automation_impact(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_automation_impact(p_rule_id uuid, p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rule record;
  v_total_agents integer;
  v_matching_agents integer;
  v_recent_executions integer;
  v_agent_list jsonb;
BEGIN
  SELECT * INTO v_rule FROM automation_rules WHERE id = p_rule_id AND tenant_id = p_tenant_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Rule not found'); END IF;

  SELECT count(*) INTO v_total_agents FROM agents WHERE tenant_id = p_tenant_id AND archived_at IS NULL;

  IF v_rule.target_scope = 'all_agents' THEN
    v_matching_agents := v_total_agents;
    SELECT jsonb_agg(jsonb_build_object('id', id, 'name', agent_name, 'status', status))
    INTO v_agent_list FROM agents WHERE tenant_id = p_tenant_id AND archived_at IS NULL;
  ELSE
    SELECT count(*), jsonb_agg(jsonb_build_object('id', id, 'name', agent_name, 'status', status))
    INTO v_matching_agents, v_agent_list FROM agents WHERE tenant_id = p_tenant_id AND archived_at IS NULL AND id = ANY(v_rule.target_ids);
  END IF;

  SELECT count(*) INTO v_recent_executions FROM automation_execution_log
  WHERE rule_id = p_rule_id AND tenant_id = p_tenant_id AND executed_at >= now() - interval '24 hours';

  RETURN jsonb_build_object('rule_name', v_rule.name, 'action_type', v_rule.action_type, 'mode', v_rule.mode,
    'dry_run', v_rule.dry_run, 'total_agents', v_total_agents, 'matching_agents', v_matching_agents,
    'impact_percent', CASE WHEN v_total_agents > 0 THEN round((v_matching_agents::numeric / v_total_agents) * 100, 1) ELSE 0 END,
    'recent_executions_24h', v_recent_executions, 'rate_limit', v_rule.max_executions_per_hour,
    'cooldown_minutes', v_rule.cooldown_minutes, 'circuit_state', v_rule.circuit_state,
    'affected_agents', COALESCE(v_agent_list, '[]'::jsonb));
END;
$$;


--
-- Name: process_antivirus_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_antivirus_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_av_data JSONB;
  v_av_name TEXT;
  v_av_status TEXT;
  v_definitions_status TEXT;
  v_scan_status TEXT;
BEGIN
  -- Só processar evidências de antivirus
  IF NEW.event_type NOT IN ('antivirus_status', 'collect_antivirus_status') THEN
    RETURN NEW;
  END IF;
  
  -- Extrair dados do antivirus
  v_av_data := NEW.event_data;
  
  -- Extrair campos do JSON
  v_av_name := COALESCE(
    v_av_data->>'displayName',
    v_av_data->>'productName',
    v_av_data->>'name',
    'Unknown'
  );
  
  v_av_status := COALESCE(
    v_av_data->>'productState',
    v_av_data->>'status',
    'Unknown'
  );
  
  v_definitions_status := COALESCE(
    v_av_data->>'definitionStatus',
    CASE 
      WHEN (v_av_data->>'isUpToDate')::boolean = true THEN 'Up to Date'
      WHEN (v_av_data->>'isUpToDate')::boolean = false THEN 'Outdated'
      ELSE 'Unknown'
    END
  );
  
  v_scan_status := COALESCE(
    v_av_data->>'scanStatus',
    v_av_data->>'lastScanResult',
    'Unknown'
  );
  
  -- Inserir ou atualizar status de antivirus (usando UPSERT simples)
  INSERT INTO antivirus_status (
    agent_id,
    tenant_id,
    antivirus_name,
    antivirus_status,
    definitions_status,
    scan_status,
    collected_at,
    raw_data
  ) VALUES (
    NEW.agent_id,
    NEW.tenant_id,
    v_av_name,
    v_av_status,
    v_definitions_status,
    v_scan_status,
    NEW.created_at,
    v_av_data
  );
  
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Log error but don't fail the trigger
  RAISE WARNING 'Error processing antivirus evidence: %', SQLERRM;
  RETURN NEW;
END;
$$;


--
-- Name: process_autonomous_safe_mode(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_autonomous_safe_mode() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agent RECORD;
  v_results JSONB := '[]'::JSONB;
  v_result JSONB;
  v_processed INTEGER := 0;
BEGIN
  -- Processar cada agente com padrão de falha detectado
  FOR v_agent IN 
    SELECT * FROM detect_critical_failure_pattern(10, 3)
    WHERE heartbeat_active = TRUE  -- Só agentes que ainda respondem
  LOOP
    -- Entrar em SAFE_MODE
    v_result := enter_autonomous_safe_mode(
      v_agent.agent_id,
      format('Detecção automática: %s falhas do tipo "%s" em 10 minutos', 
        v_agent.failure_count, v_agent.failure_type),
      v_agent.failure_type,
      v_agent.failure_count::INTEGER
    );
    
    v_results := v_results || v_result;
    v_processed := v_processed + 1;
  END LOOP;
  
  RETURN jsonb_build_object(
    'success', true,
    'processed_count', v_processed,
    'agents', v_results,
    'executed_at', NOW()
  );
END;
$$;


--
-- Name: FUNCTION process_autonomous_safe_mode(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.process_autonomous_safe_mode() IS 'Função principal que processa entrada autônoma em SAFE_MODE';


--
-- Name: process_dlq_batch(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_dlq_batch(p_tenant_id uuid, p_batch_size integer DEFAULT 50, p_action text DEFAULT 'resolve'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_processed INTEGER := 0;
  v_retried INTEGER := 0;
  v_resolved INTEGER := 0;
  v_item RECORD;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  -- BLINDAGEM DE TENANT
  IF p_tenant_id IS DISTINCT FROM get_active_tenant_id()
     AND NOT is_current_super_admin() THEN
    RAISE EXCEPTION 'Tenant mismatch: access denied';
  END IF;

  FOR v_item IN
    SELECT d.id, d.original_job_id, d.retry_count
    FROM failed_jobs_dlq d
    WHERE d.tenant_id = p_tenant_id
      AND d.resolved_at IS NULL
    ORDER BY d.last_failure_at ASC
    LIMIT p_batch_size
  LOOP
    v_processed := v_processed + 1;
    
    IF p_action = 'retry' AND v_item.retry_count < 3 THEN
      UPDATE jobs 
      SET status = 'queued', updated_at = NOW()
      WHERE id = v_item.original_job_id;
      
      UPDATE failed_jobs_dlq 
      SET retry_count = retry_count + 1, next_retry_at = NOW()
      WHERE id = v_item.id;
      
      v_retried := v_retried + 1;
    ELSE
      UPDATE failed_jobs_dlq 
      SET resolved_at = NOW(), 
          resolution_notes = 'Resolved via batch cleanup',
          status = 'resolved'
      WHERE id = v_item.id;
      
      v_resolved := v_resolved + 1;
    END IF;
  END LOOP;
  
  RETURN jsonb_build_object(
    'processed', v_processed,
    'retried', v_retried,
    'resolved', v_resolved,
    'tenant_id', p_tenant_id
  );
END;
$$;


--
-- Name: process_endpoint_event_buffer(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_endpoint_event_buffer(batch_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  rec record;
  processed_count int := 0;
  error_count int := 0;
  stats jsonb;
  v_payload jsonb;
BEGIN
  FOR rec IN
    SELECT id, agent_id, tenant_id, event_category, payload
    FROM endpoint_event_buffer
    WHERE processed_at IS NULL
    ORDER BY received_at ASC
    LIMIT batch_limit
    FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      v_payload := rec.payload::jsonb;
      
      CASE rec.event_category
        WHEN 'process' THEN
          INSERT INTO endpoint_process_events (
            agent_id, tenant_id, event_type, pid, parent_pid, process_name,
            command_line, executable_path, user_name, sha256_hash,
            parent_process_name, parent_command_line, mitre_technique_id,
            mitre_tactic, is_suspicious, detection_tags, event_time
          ) VALUES (
            rec.agent_id, rec.tenant_id,
            COALESCE(v_payload->>'event_type', 'process_start'),
            COALESCE((v_payload->>'pid')::int, 0),
            (v_payload->>'parent_pid')::int,
            COALESCE(v_payload->>'process_name', 'unknown'),
            v_payload->>'command_line',
            v_payload->>'executable_path',
            v_payload->>'user_name',
            v_payload->>'sha256_hash',
            v_payload->>'parent_process_name',
            v_payload->>'parent_command_line',
            v_payload->>'mitre_technique_id',
            v_payload->>'mitre_tactic',
            COALESCE((v_payload->>'is_suspicious')::boolean, false),
            COALESCE(ARRAY(SELECT jsonb_array_elements_text(v_payload->'detection_tags')), ARRAY[]::text[]),
            COALESCE((v_payload->>'event_time')::timestamptz, now())
          );
          
        WHEN 'file' THEN
          INSERT INTO endpoint_file_events (
            agent_id, tenant_id, event_type, file_path, file_name,
            file_extension, file_size, sha256_hash, old_path,
            process_name, process_pid, is_suspicious, detection_tags, event_time
          ) VALUES (
            rec.agent_id, rec.tenant_id,
            COALESCE(v_payload->>'event_type', 'file_create'),
            COALESCE(v_payload->>'file_path', 'unknown'),
            v_payload->>'file_name',
            v_payload->>'file_extension',
            (v_payload->>'file_size')::bigint,
            v_payload->>'sha256_hash',
            v_payload->>'old_path',
            v_payload->>'process_name',
            (v_payload->>'process_pid')::int,
            COALESCE((v_payload->>'is_suspicious')::boolean, false),
            COALESCE(ARRAY(SELECT jsonb_array_elements_text(v_payload->'detection_tags')), ARRAY[]::text[]),
            COALESCE((v_payload->>'event_time')::timestamptz, now())
          );
          
        WHEN 'network' THEN
          INSERT INTO endpoint_network_events (
            agent_id, tenant_id, event_type, protocol, local_address,
            local_port, remote_address, remote_port, direction,
            process_name, process_pid, bytes_sent, bytes_received,
            domain, dns_query_type, dns_response, is_suspicious,
            detection_tags, geo_country, event_time
          ) VALUES (
            rec.agent_id, rec.tenant_id,
            COALESCE(v_payload->>'event_type', 'connection'),
            v_payload->>'protocol',
            v_payload->>'local_address',
            (v_payload->>'local_port')::int,
            v_payload->>'remote_address',
            (v_payload->>'remote_port')::int,
            v_payload->>'direction',
            v_payload->>'process_name',
            (v_payload->>'process_pid')::int,
            (v_payload->>'bytes_sent')::bigint,
            (v_payload->>'bytes_received')::bigint,
            v_payload->>'domain',
            v_payload->>'dns_query_type',
            v_payload->>'dns_response',
            COALESCE((v_payload->>'is_suspicious')::boolean, false),
            COALESCE(ARRAY(SELECT jsonb_array_elements_text(v_payload->'detection_tags')), ARRAY[]::text[]),
            v_payload->>'geo_country',
            COALESCE((v_payload->>'event_time')::timestamptz, now())
          );
          
        WHEN 'registry' THEN
          INSERT INTO endpoint_registry_events (
            agent_id, tenant_id, event_type, key_path, value_name,
            value_data, value_type, old_value_data, process_name,
            process_pid, is_suspicious, detection_tags, mitre_technique_id, event_time
          ) VALUES (
            rec.agent_id, rec.tenant_id,
            COALESCE(v_payload->>'event_type', 'registry_set'),
            COALESCE(v_payload->>'key_path', 'unknown'),
            v_payload->>'value_name',
            v_payload->>'value_data',
            v_payload->>'value_type',
            v_payload->>'old_value_data',
            v_payload->>'process_name',
            (v_payload->>'process_pid')::int,
            COALESCE((v_payload->>'is_suspicious')::boolean, false),
            COALESCE(ARRAY(SELECT jsonb_array_elements_text(v_payload->'detection_tags')), ARRAY[]::text[]),
            v_payload->>'mitre_technique_id',
            COALESCE((v_payload->>'event_time')::timestamptz, now())
          );
          
        ELSE
          -- Unknown category: skip but mark as processed to avoid infinite loop
          NULL;
      END CASE;
      
      -- Mark as processed
      UPDATE endpoint_event_buffer SET processed_at = now() WHERE id = rec.id;
      processed_count := processed_count + 1;
      
    EXCEPTION WHEN OTHERS THEN
      error_count := error_count + 1;
      RAISE WARNING 'Buffer process error for id=%: %', rec.id, SQLERRM;
    END;
  END LOOP;
  
  stats := jsonb_build_object(
    'processed', processed_count,
    'errors', error_count,
    'timestamp', now()
  );
  
  RETURN stats;
END;
$$;


--
-- Name: process_heartbeat_v2(text, text, text, text, text, numeric, numeric, numeric, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_heartbeat_v2(p_token_hash text, p_agent_version text DEFAULT NULL::text, p_hostname text DEFAULT NULL::text, p_os_type text DEFAULT NULL::text, p_os_version text DEFAULT NULL::text, p_cpu_usage numeric DEFAULT NULL::numeric, p_memory_usage numeric DEFAULT NULL::numeric, p_disk_usage numeric DEFAULT NULL::numeric, p_uptime_seconds bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_now timestamptz := now();
    v_agent record;
    v_rate jsonb;
    v_force_update boolean := false;
    v_light_mode record;
BEGIN
    -- 1. Single query: validate token + get agent data
    SELECT a.id, a.agent_name, a.tenant_id, a.status, a.hmac_secret,
           a.force_update_version, a.force_update_at, a.agent_version,
           a.poll_interval_seconds, a.is_throttled, a.agent_mode
    INTO v_agent
    FROM agent_tokens t
    JOIN agents a ON t.agent_id = a.id
    WHERE t.token_hash = p_token_hash
      AND t.is_active = true;

    IF v_agent IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_token');
    END IF;

    IF v_agent.status != 'active' THEN
        RETURN jsonb_build_object('success', false, 'error', 'agent_inactive', 'status', v_agent.status);
    END IF;

    -- 2. Atomic rate limit check (replaces 2-3 separate queries)
    v_rate := check_rate_limit_atomic(v_agent.id::text, 'heartbeat', 60, 1, 5);
    IF NOT (v_rate->>'allowed')::boolean THEN
        RETURN jsonb_build_object('success', false, 'error', 'rate_limited', 'details', v_rate);
    END IF;

    -- 3. Check force update
    IF v_agent.force_update_version IS NOT NULL
       AND v_agent.force_update_version != COALESCE(p_agent_version, v_agent.agent_version)
       AND v_agent.force_update_at IS NOT NULL
       AND v_agent.force_update_at > v_now - interval '7 days' THEN
        v_force_update := true;
    END IF;

    -- 4. Single UPDATE: heartbeat + metadata
    UPDATE agents SET
        last_heartbeat = v_now,
        agent_version = COALESCE(p_agent_version, agent_version),
        hostname = COALESCE(p_hostname, hostname),
        os_type = COALESCE(p_os_type, os_type),
        os_version = COALESCE(p_os_version, os_version)
    WHERE id = v_agent.id;

    -- 5. Update token last_used_at
    UPDATE agent_tokens SET last_used_at = v_now
    WHERE token_hash = p_token_hash;

    -- 6. Persist system metrics if provided
    IF p_cpu_usage IS NOT NULL THEN
        INSERT INTO agent_system_metrics (
            agent_id, tenant_id, collected_at,
            cpu_usage_percent, memory_usage_percent,
            disk_usage_percent, uptime_seconds
        ) VALUES (
            v_agent.id, v_agent.tenant_id, v_now,
            p_cpu_usage, p_memory_usage,
            p_disk_usage, p_uptime_seconds
        );
    END IF;

    -- 7. Check light mode
    SELECT is_active, reduced_interval_seconds
    INTO v_light_mode
    FROM agent_light_mode_configs
    WHERE agent_id = v_agent.id AND is_active = true
    LIMIT 1;

    -- 8. Build response
    RETURN jsonb_build_object(
        'success', true,
        'agent_id', v_agent.id,
        'agent_name', v_agent.agent_name,
        'tenant_id', v_agent.tenant_id,
        'hmac_secret', v_agent.hmac_secret,
        'force_update', v_force_update,
        'force_update_version', v_agent.force_update_version,
        'poll_interval', COALESCE(
            v_light_mode.reduced_interval_seconds,
            v_agent.poll_interval_seconds,
            60
        ),
        'light_mode', COALESCE(v_light_mode.is_active, false),
        'is_throttled', v_agent.is_throttled,
        'agent_mode', v_agent.agent_mode
    );
END;
$$;


--
-- Name: process_safe_mode_entry(uuid, text, timestamp with time zone, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_safe_mode_entry(p_agent_id uuid, p_reason text, p_entered_at timestamp with time zone, p_failure_count integer DEFAULT 0, p_agent_version text DEFAULT NULL::text, p_execution_hash text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
  v_event_id UUID;
BEGIN
  SELECT tenant_id INTO v_tenant_id FROM agents WHERE id = p_agent_id;
  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'Agent not found'; END IF;
  
  UPDATE agents SET
    agent_mode = 'SAFE_MODE',
    safe_mode_reason = p_reason,
    safe_mode_entered_at = p_entered_at
  WHERE id = p_agent_id;
  
  INSERT INTO agent_safe_mode_events (
    agent_id, tenant_id, entered_at, reason,
    failure_count, agent_version, execution_hash
  ) VALUES (
    p_agent_id, v_tenant_id, p_entered_at, p_reason,
    p_failure_count, p_agent_version, p_execution_hash
  ) RETURNING id INTO v_event_id;
  
  PERFORM capture_forensic_snapshot_full(p_agent_id, 'safe_mode', v_event_id);
  
  INSERT INTO system_alerts (tenant_id, agent_id, alert_type, severity, message, data)
  VALUES (v_tenant_id, p_agent_id, 'safe_mode_activated', 'critical',
    format('Agent entered SAFE_MODE: %s', p_reason),
    jsonb_build_object('event_id', v_event_id, 'reason', p_reason));
  
  RETURN v_event_id;
END;
$$;


--
-- Name: process_tenant_suspensions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_tenant_suspensions() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_config RECORD;
  v_warned INTEGER := 0;
  v_suspended INTEGER := 0;
  v_scheduled INTEGER := 0;
  v_tenant RECORD;
BEGIN
  -- Only service_role can call this
  IF NOT (current_setting('request.jwt.claim.role', true) = 'service_role') THEN
    RAISE EXCEPTION 'Unauthorized: requires service_role';
  END IF;

  -- Get config
  SELECT * INTO v_config FROM public.tenant_suspension_config WHERE is_enabled = true LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'disabled', 'message', 'Suspension system is disabled');
  END IF;

  -- PHASE 1: Send warnings (active tenants inactive for warning_days)
  FOR v_tenant IN
    SELECT id, name, last_activity_at 
    FROM public.tenants
    WHERE suspension_status = 'active'
      AND last_activity_at < now() - (v_config.warning_days || ' days')::INTERVAL
      AND (suspension_warning_sent_at IS NULL OR suspension_warning_sent_at < now() - INTERVAL '7 days')
      AND NOT (id = ANY(v_config.exempt_tenant_ids))
    LIMIT v_config.cleanup_batch_size
  LOOP
    UPDATE public.tenants 
    SET suspension_status = 'warned',
        suspension_warning_sent_at = now()
    WHERE id = v_tenant.id;

    INSERT INTO public.tenant_suspension_events (tenant_id, event_type, previous_status, new_status, reason)
    VALUES (v_tenant.id, 'warning_sent', 'active', 'warned', 
            'Inativo por ' || v_config.warning_days || '+ dias. Última atividade: ' || v_tenant.last_activity_at);

    v_warned := v_warned + 1;
  END LOOP;

  -- PHASE 2: Suspend (warned tenants inactive for suspension_days)
  FOR v_tenant IN
    SELECT id, name, last_activity_at
    FROM public.tenants
    WHERE suspension_status = 'warned'
      AND last_activity_at < now() - (v_config.suspension_days || ' days')::INTERVAL
      AND NOT (id = ANY(v_config.exempt_tenant_ids))
    LIMIT v_config.cleanup_batch_size
  LOOP
    UPDATE public.tenants
    SET suspension_status = 'suspended',
        suspended_at = now(),
        suspension_reason = 'Inatividade automática (' || v_config.suspension_days || ' dias)'
    WHERE id = v_tenant.id;

    INSERT INTO public.tenant_suspension_events (tenant_id, event_type, previous_status, new_status, reason)
    VALUES (v_tenant.id, 'suspended', 'warned', 'suspended',
            'Suspenso por inatividade de ' || v_config.suspension_days || '+ dias');

    v_suspended := v_suspended + 1;
  END LOOP;

  -- PHASE 3: Schedule deletion (suspended for deletion_days - suspension_days)
  FOR v_tenant IN
    SELECT id, name, suspended_at
    FROM public.tenants
    WHERE suspension_status = 'suspended'
      AND suspended_at < now() - ((v_config.deletion_days - v_config.suspension_days) || ' days')::INTERVAL
      AND NOT (id = ANY(v_config.exempt_tenant_ids))
    LIMIT v_config.cleanup_batch_size
  LOOP
    UPDATE public.tenants
    SET suspension_status = 'pending_deletion',
        deletion_scheduled_at = now() + INTERVAL '30 days'
    WHERE id = v_tenant.id;

    INSERT INTO public.tenant_suspension_events (tenant_id, event_type, previous_status, new_status, reason)
    VALUES (v_tenant.id, 'deletion_scheduled', 'suspended', 'pending_deletion',
            'Deleção agendada para ' || (now() + INTERVAL '30 days')::TEXT);

    v_scheduled := v_scheduled + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'status', 'completed',
    'warned', v_warned,
    'suspended', v_suspended,
    'deletion_scheduled', v_scheduled,
    'processed_at', now()
  );
END;
$$;


