--
-- Name: purge_expired_hmac_signatures(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_expired_hmac_signatures() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  total_deleted integer := 0;
  batch_deleted integer;
  cutoff timestamptz := now() - interval '7 days';
  v_alert_threshold integer := 100000;
BEGIN
  LOOP
    DELETE FROM public.hmac_signatures
    WHERE id IN (
      SELECT id FROM public.hmac_signatures
      WHERE used_at < cutoff
      LIMIT 1000
    );
    GET DIAGNOSTICS batch_deleted = ROW_COUNT;
    total_deleted := total_deleted + batch_deleted;
    EXIT WHEN batch_deleted < 1000;
  END LOOP;

  RAISE NOTICE '[purge_expired_hmac_signatures] Deleted % rows (cutoff: %)', total_deleted, cutoff;

  -- Alert on anomalous purge volume
  IF total_deleted > v_alert_threshold THEN
    INSERT INTO public.system_alerts (
      alert_type, severity, title, description, metadata, resolved
    ) VALUES (
      'hmac_purge_anomaly',
      'warning',
      'HMAC purge deleted anomalous volume',
      format('purge_expired_hmac_signatures deleted %s rows (threshold: %s). Investigate potential abuse or replay storm.', total_deleted, v_alert_threshold),
      jsonb_build_object(
        'total_deleted', total_deleted,
        'threshold', v_alert_threshold,
        'cutoff', cutoff,
        'executed_at', now()
      ),
      false
    );
    RAISE WARNING '[purge_expired_hmac_signatures] ANOMALY: Deleted % rows exceeds threshold %', total_deleted, v_alert_threshold;
  END IF;

  RETURN total_deleted;
END;
$$;


--
-- Name: reactivate_tenant(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reactivate_tenant(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  IF NOT is_current_super_admin() THEN
    PERFORM log_security_violation(p_tenant_id, auth.uid(), 'internal', 'reactivate_tenant', 'unauthorized_tenant_reactivation', 'critical',
      jsonb_build_object('target_tenant', p_tenant_id));
    RAISE EXCEPTION 'Only super_admin can reactivate tenants';
  END IF;

  UPDATE tenants SET status = 'active', suspended_at = NULL, suspension_reason = NULL
  WHERE id = p_tenant_id AND status = 'suspended';

  RETURN jsonb_build_object('success', true, 'tenant_id', p_tenant_id);
END;
$$;


--
-- Name: reanchor_audit_log_chain(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reanchor_audit_log_chain(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_log RECORD;
  v_prev_hash TEXT := NULL;
  v_fixed INT := 0;
  v_total INT := 0;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  -- Only service_role or super_admin  
  IF NOT (
    current_setting('role', true) = 'service_role' 
    OR is_current_super_admin()
  ) THEN
    RAISE EXCEPTION 'ACCESS_DENIED: requires service_role or super_admin';
  END IF;

  -- Temporarily disable the immutability trigger for this repair
  ALTER TABLE audit_logs DISABLE TRIGGER tr_prevent_audit_modification;

  BEGIN
    -- Walk the chain chronologically and fix broken links
    FOR v_log IN 
      SELECT id, integrity_hash, previous_log_hash, created_at
      FROM audit_logs
      WHERE tenant_id = p_tenant_id
      ORDER BY created_at ASC
    LOOP
      v_total := v_total + 1;
      
      IF v_total = 1 THEN
        -- First log should have GENESIS
        IF v_log.previous_log_hash IS DISTINCT FROM 'GENESIS' THEN
          UPDATE audit_logs SET previous_log_hash = 'GENESIS' WHERE id = v_log.id;
          v_fixed := v_fixed + 1;
        END IF;
      ELSE
        -- Subsequent logs should reference the previous log's integrity_hash
        IF v_log.previous_log_hash IS DISTINCT FROM v_prev_hash THEN
          UPDATE audit_logs SET previous_log_hash = v_prev_hash WHERE id = v_log.id;
          v_fixed := v_fixed + 1;
        END IF;
      END IF;
      
      v_prev_hash := v_log.integrity_hash;
    END LOOP;

    -- Re-enable the immutability trigger
    ALTER TABLE audit_logs ENABLE TRIGGER tr_prevent_audit_modification;
    
  EXCEPTION WHEN OTHERS THEN
    -- Ensure trigger is re-enabled even on error
    ALTER TABLE audit_logs ENABLE TRIGGER tr_prevent_audit_modification;
    RAISE;
  END;

  -- Log the repair event
  IF v_fixed > 0 THEN
    -- Temporarily disable trigger again for this security log insert
    INSERT INTO security_logs (
      tenant_id, event_type, severity, source, details
    ) VALUES (
      p_tenant_id,
      'AUDIT_CHAIN_REANCHOR',
      'warning',
      'ADR-036',
      jsonb_build_object(
        'total_logs', v_total,
        'links_repaired', v_fixed,
        'initiated_by', auth.uid(),
        'repaired_at', now()
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'total_logs_scanned', v_total,
    'links_repaired', v_fixed,
    'executed_at', now()
  );
END;
$$;


--
-- Name: reanchor_execution_chains(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reanchor_execution_chains(p_agent_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agent RECORD;
  v_fixed_count INT := 0;
  v_agents_fixed INT := 0;
  v_results JSONB := '[]'::jsonb;
  v_last_hash TEXT;
  v_last_index INT;
BEGIN
  -- Only service_role or super_admin
  IF NOT (
    current_setting('role', true) = 'service_role' 
    OR is_current_super_admin()
  ) THEN
    RAISE EXCEPTION 'ACCESS_DENIED: requires service_role or super_admin';
  END IF;

  -- For each agent with gaps
  FOR v_agent IN 
    SELECT je.agent_id, MAX(je.execution_index) as max_idx
    FROM job_executions je
    WHERE je.execution_index IS NOT NULL
      AND je.execution_hash IS NOT NULL
      AND (p_agent_id IS NULL OR je.agent_id = p_agent_id)
    GROUP BY je.agent_id
    HAVING COUNT(*) != (MAX(je.execution_index) - MIN(je.execution_index) + 1)
  LOOP
    -- Get the last valid execution for this agent
    SELECT execution_hash, execution_index
    INTO v_last_hash, v_last_index
    FROM job_executions
    WHERE agent_id = v_agent.agent_id
      AND execution_hash IS NOT NULL
    ORDER BY execution_index DESC
    LIMIT 1;

    -- Update the chain anchor to match the last valid execution
    UPDATE agent_execution_chain
    SET last_execution_hash = v_last_hash,
        last_execution_index = v_last_index,
        updated_at = now()
    WHERE agent_id = v_agent.agent_id
      AND (last_execution_hash != v_last_hash OR last_execution_index != v_last_index);

    v_agents_fixed := v_agents_fixed + 1;
    v_results := v_results || jsonb_build_object(
      'agent_id', v_agent.agent_id,
      'new_anchor_index', v_last_index,
      'new_anchor_hash', v_last_hash
    );
  END LOOP;

  -- Log the reanchor event
  INSERT INTO security_logs (
    tenant_id, event_type, severity, source, details
  )
  SELECT 
    COALESCE(get_active_tenant_id(), (SELECT tenant_id FROM agents WHERE id = p_agent_id LIMIT 1)),
    'CHAIN_REANCHOR',
    'warning',
    'ADR-036',
    jsonb_build_object(
      'agents_fixed', v_agents_fixed,
      'initiated_by', auth.uid(),
      'results', v_results
    )
  WHERE v_agents_fixed > 0;

  RETURN jsonb_build_object(
    'success', true,
    'agents_reanchored', v_agents_fixed,
    'details', v_results,
    'executed_at', now()
  );
END;
$$;


--
-- Name: recalculate_risk_scores(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_risk_scores(p_tenant_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.detection_rules
  SET risk_score = ROUND((
    (CASE severity
      WHEN 'critical' THEN 10
      WHEN 'high' THEN 7
      WHEN 'medium' THEN 4
      WHEN 'low' THEN 1
      ELSE 0
    END) * 0.4
    + CASE WHEN (true_positive_count + false_positive_count) > 0
        THEN (true_positive_count::NUMERIC / (true_positive_count + false_positive_count)) * 6
        ELSE 3
      END * 0.3
    - CASE WHEN (true_positive_count + false_positive_count) > 0
        THEN (false_positive_count::NUMERIC / (true_positive_count + false_positive_count)) * 6
        ELSE 0
      END * 0.3
  )::NUMERIC, 2),
  updated_at = now()
  WHERE (tenant_id = p_tenant_id OR tenant_id IS NULL)
    AND mode != 'disabled';
END;
$$;


--
-- Name: recalculate_tenant_risk_score(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_tenant_risk_score(p_tenant_id uuid) RETURNS numeric
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total_rules INT;
  v_open_breakers INT;
  v_total_exec INT;
  v_total_blocked INT;
  v_failed_1h INT;
  v_total_1h INT;
  v_blocked_ratio NUMERIC;
  v_failure_rate NUMERIC;
  v_score NUMERIC;
BEGIN
  -- Count active rules
  SELECT COUNT(*) INTO v_total_rules
  FROM automation_rules WHERE tenant_id = p_tenant_id AND is_active = true;

  -- Count open circuit breakers
  SELECT COUNT(*) INTO v_open_breakers
  FROM automation_rules WHERE tenant_id = p_tenant_id AND circuit_state = 'open';

  -- 24h execution stats from decision log
  SELECT 
    COUNT(*) FILTER (WHERE executed = true),
    COUNT(*) FILTER (WHERE executed = false)
  INTO v_total_exec, v_total_blocked
  FROM automation_decision_log
  WHERE tenant_id = p_tenant_id
    AND created_at > now() - interval '24 hours';

  -- 1h failure rate from execution log
  SELECT 
    COUNT(*) FILTER (WHERE success = false),
    COUNT(*)
  INTO v_failed_1h, v_total_1h
  FROM automation_execution_log
  WHERE tenant_id = p_tenant_id
    AND executed_at > now() - interval '1 hour';

  v_blocked_ratio := CASE WHEN (v_total_exec + v_total_blocked) > 0
    THEN (v_total_blocked::NUMERIC / (v_total_exec + v_total_blocked)) * 100
    ELSE 0 END;

  v_failure_rate := CASE WHEN v_total_1h > 0
    THEN (v_failed_1h::NUMERIC / v_total_1h) * 100
    ELSE 0 END;

  -- Weighted score: breakers (40%) + failure rate (35%) + blocked ratio (25%)
  v_score := LEAST(100, (
    (LEAST(v_open_breakers, 5)::NUMERIC / 5 * 40) +
    (LEAST(v_failure_rate, 100) / 100 * 35) +
    (LEAST(v_blocked_ratio, 100) / 100 * 25)
  ));

  -- Upsert
  INSERT INTO tenant_risk_scores (
    tenant_id, risk_score, blocked_rules_ratio, open_circuit_breakers,
    failure_rate_1h, total_executions_24h, total_blocked_24h, calculated_at, updated_at
  ) VALUES (
    p_tenant_id, v_score, v_blocked_ratio, v_open_breakers,
    v_failure_rate, v_total_exec, v_total_blocked, now(), now()
  )
  ON CONFLICT (tenant_id) DO UPDATE SET
    risk_score = EXCLUDED.risk_score,
    blocked_rules_ratio = EXCLUDED.blocked_rules_ratio,
    open_circuit_breakers = EXCLUDED.open_circuit_breakers,
    failure_rate_1h = EXCLUDED.failure_rate_1h,
    total_executions_24h = EXCLUDED.total_executions_24h,
    total_blocked_24h = EXCLUDED.total_blocked_24h,
    calculated_at = EXCLUDED.calculated_at,
    updated_at = EXCLUDED.updated_at;

  RETURN v_score;
END;
$$;


--
-- Name: reconstruct_incident_timeline(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconstruct_incident_timeline(p_agent_id uuid, p_start_time timestamp with time zone, p_end_time timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
  v_events JSONB := '[]';
  v_user_id UUID;
BEGIN
  v_user_id := auth.uid();
  
  -- Verificar permissão
  SELECT a.tenant_id INTO v_tenant_id 
  FROM agents a
  JOIN user_roles ur ON ur.tenant_id = a.tenant_id
  WHERE a.id = p_agent_id AND ur.user_id = v_user_id
  LIMIT 1;
  
  IF v_tenant_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized or agent not found');
  END IF;
  
  -- Coletar todos os eventos relevantes
  WITH all_events AS (
    -- Security events
    SELECT 
      'security_event' as event_type,
      id as source_id,
      created_at as event_time,
      severity,
      title as event_title,
      description as event_description,
      jsonb_build_object('status', status, 'data', data) as event_data
    FROM security_events
    WHERE agent_id = p_agent_id 
      AND created_at BETWEEN p_start_time AND p_end_time
    
    UNION ALL
    
    -- Jobs
    SELECT 
      'job' as event_type,
      id as source_id,
      created_at as event_time,
      CASE status WHEN 'failed' THEN 'high' ELSE 'low' END as severity,
      type as event_title,
      COALESCE(error_message, 'Job ' || status) as event_description,
      jsonb_build_object('status', status, 'result', result) as event_data
    FROM jobs
    WHERE agent_id = p_agent_id 
      AND created_at BETWEEN p_start_time AND p_end_time
    
    UNION ALL
    
    -- Risk decisions
    SELECT 
      'risk_decision' as event_type,
      id as source_id,
      created_at as event_time,
      CASE decision WHEN 'blocked' THEN 'critical' WHEN 'approved' THEN 'low' ELSE 'medium' END as severity,
      decision_type as event_title,
      reasoning as event_description,
      metadata as event_data
    FROM risk_decision_log
    WHERE tenant_id = v_tenant_id 
      AND created_at BETWEEN p_start_time AND p_end_time
      AND (metadata->>'agent_id' = p_agent_id::text OR trigger_id IN (
        SELECT id::text FROM playbook_executions WHERE agent_id = p_agent_id
      ))
    
    UNION ALL
    
    -- Playbook executions
    SELECT 
      'playbook_execution' as event_type,
      pe.id as source_id,
      pe.triggered_at as event_time,
      CASE pe.status WHEN 'failed' THEN 'high' ELSE 'medium' END as severity,
      p.name as event_title,
      'Playbook ' || pe.status as event_description,
      jsonb_build_object('status', pe.status, 'actions', pe.snapshot_data->'actions') as event_data
    FROM playbook_executions pe
    JOIN playbooks p ON p.id = pe.playbook_id
    WHERE pe.agent_id = p_agent_id 
      AND pe.triggered_at BETWEEN p_start_time AND p_end_time
    
    UNION ALL
    
    -- System alerts
    SELECT 
      'system_alert' as event_type,
      id as source_id,
      created_at as event_time,
      severity,
      alert_type as event_title,
      message as event_description,
      jsonb_build_object('resolved', resolved, 'resolved_at', resolved_at) as event_data
    FROM system_alerts
    WHERE agent_id = p_agent_id 
      AND created_at BETWEEN p_start_time AND p_end_time
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'event_type', event_type,
      'source_id', source_id,
      'event_time', event_time,
      'severity', severity,
      'title', event_title,
      'description', event_description,
      'data', event_data
    ) ORDER BY event_time ASC
  ) INTO v_events
  FROM all_events;
  
  RETURN jsonb_build_object(
    'success', true,
    'agent_id', p_agent_id,
    'tenant_id', v_tenant_id,
    'period', jsonb_build_object('start', p_start_time, 'end', p_end_time),
    'events_count', jsonb_array_length(COALESCE(v_events, '[]'::jsonb)),
    'timeline', COALESCE(v_events, '[]'::jsonb)
  );
END;
$$;


