--
-- Name: redirect_metrics_to_partition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redirect_metrics_to_partition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  partition_name text;
  partition_start date;
  partition_end date;
BEGIN
  partition_start := date_trunc('month', NEW.collected_at)::date;
  partition_end := (partition_start + interval '1 month')::date;
  partition_name := 'agent_system_metrics_' || to_char(partition_start, 'YYYY_MM');
  
  -- Criar partição se não existir
  IF NOT EXISTS (
    SELECT 1 FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE c.relname = partition_name AND n.nspname = 'public'
  ) THEN
    EXECUTE format(
      'CREATE TABLE IF NOT EXISTS public.%I PARTITION OF public.agent_system_metrics_partitioned FOR VALUES FROM (%L) TO (%L)',
      partition_name, partition_start, partition_end
    );
    RAISE NOTICE 'Created partition: %', partition_name;
  END IF;
  
  -- Inserir na tabela particionada
  INSERT INTO public.agent_system_metrics_partitioned (
    id, agent_id, tenant_id, collected_at, created_at,
    cpu_usage_percent, cpu_cores, cpu_name,
    memory_usage_percent, memory_total_gb, memory_used_gb, memory_free_gb,
    disk_usage_percent, disk_total_gb, disk_used_gb, disk_free_gb,
    network_bytes_sent, network_bytes_received,
    uptime_seconds, last_boot_time
  ) VALUES (
    COALESCE(NEW.id, gen_random_uuid()),
    NEW.agent_id, NEW.tenant_id, NEW.collected_at, COALESCE(NEW.created_at, now()),
    NEW.cpu_usage_percent, NEW.cpu_cores, NEW.cpu_name,
    NEW.memory_usage_percent, NEW.memory_total_gb, NEW.memory_used_gb, NEW.memory_free_gb,
    NEW.disk_usage_percent, NEW.disk_total_gb, NEW.disk_used_gb, NEW.disk_free_gb,
    NEW.network_bytes_sent, NEW.network_bytes_received,
    NEW.uptime_seconds, NEW.last_boot_time
  );
  
  RETURN NULL; -- Impede insert na tabela original
END;
$$;


--
-- Name: FUNCTION redirect_metrics_to_partition(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.redirect_metrics_to_partition() IS '🔒 Essencial - Trigger de particionamento';


--
-- Name: redirect_network_events_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redirect_network_events_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.endpoint_network_events_partitioned 
    (id, tenant_id, agent_id, event_type, protocol, local_address,
     local_port, remote_address, remote_port, direction,
     process_name, process_pid, bytes_sent, bytes_received,
     domain, dns_query_type, dns_response, is_suspicious,
     detection_tags, geo_country, event_time, created_at)
  VALUES 
    (NEW.id, NEW.tenant_id, NEW.agent_id, NEW.event_type, NEW.protocol, NEW.local_address,
     NEW.local_port, NEW.remote_address, NEW.remote_port, NEW.direction,
     NEW.process_name, NEW.process_pid, NEW.bytes_sent, NEW.bytes_received,
     NEW.domain, NEW.dns_query_type, NEW.dns_response, NEW.is_suspicious,
     NEW.detection_tags, NEW.geo_country, NEW.event_time, NEW.created_at);
  RETURN NULL;
END;
$$;


