--
-- Name: refresh_all_incident_slos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_all_incident_slos() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fp_id uuid;
  v_count integer := 0;
BEGIN
  -- Modo híbrido: só processa fingerprints marcados como dirty
  FOR v_fp_id IN 
    SELECT id FROM failure_fingerprints 
    WHERE slo_dirty = true
  LOOP
    PERFORM calculate_incident_burn_rate(v_fp_id);
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


