--
-- Name: refresh_incident_slos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_incident_slos() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_breached integer := 0;
BEGIN
  -- Mark SLA breaches for open tasks past due
  WITH breached AS (
    UPDATE tasks 
    SET sla_breached_at = now()
    WHERE status IN ('open', 'in_progress')
      AND due_at IS NOT NULL 
      AND due_at < now()
      AND sla_breached_at IS NULL
    RETURNING id
  )
  SELECT count(*) INTO v_breached FROM breached;
  
  RETURN jsonb_build_object('sla_breaches_marked', v_breached, 'executed_at', now());
END;
$$;


--
-- Name: register_agent_signing_key(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_agent_signing_key(p_agent_id uuid, p_public_key text, p_fingerprint text, p_algorithm text DEFAULT 'RSA-SHA256'::text) RETURNS TABLE(key_id uuid, version integer, valid_from timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_new_version INT;
  v_key_id UUID;
  v_valid_from TIMESTAMPTZ;
  v_tenant_id UUID;
  v_caller_tenant UUID;
BEGIN
  v_caller_tenant := get_active_tenant_id();
  
  SELECT tenant_id INTO v_tenant_id FROM agents WHERE id = p_agent_id;
  
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'AGENT_NOT_FOUND';
  END IF;
  
  -- PSIA: cross-tenant guard (INV-001)
  IF v_caller_tenant IS NOT NULL AND v_tenant_id != v_caller_tenant AND NOT is_current_super_admin() THEN
    INSERT INTO security_logs (tenant_id, event_type, severity, details)
    VALUES (v_caller_tenant, 'cross_tenant_blocked', 'critical',
      jsonb_build_object('function', 'register_agent_signing_key', 'target_agent', p_agent_id));
    RAISE EXCEPTION 'TENANT_MISMATCH';
  END IF;
  
  SELECT COALESCE(MAX(ask.version), 0) + 1 INTO v_new_version
  FROM agent_signing_keys ask WHERE ask.agent_id = p_agent_id;
  
  v_valid_from := NOW();
  
  INSERT INTO agent_signing_keys (agent_id, public_key, key_fingerprint, version, algorithm, valid_from)
  VALUES (p_agent_id, p_public_key, p_fingerprint, v_new_version, p_algorithm, v_valid_from)
  RETURNING id INTO v_key_id;
  
  UPDATE agent_signing_keys SET is_active = false, valid_until = v_valid_from
  WHERE agent_id = p_agent_id AND id != v_key_id AND is_active = true;
  
  RETURN QUERY SELECT v_key_id, v_new_version, v_valid_from;
END;
$$;


--
-- Name: register_failure_occurrence(jsonb, uuid, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_failure_occurrence(p_signature jsonb, p_tenant_id uuid, p_source_type text, p_source_id uuid, p_agent_id uuid DEFAULT NULL::uuid, p_error_excerpt text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hash text;
  v_fingerprint_id uuid;
  v_severity text;
  v_failure_class text;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  v_hash := public.calculate_fingerprint_hash(p_signature);
  v_failure_class := COALESCE(p_signature->>'failure_class', 'UNKNOWN');
  
  v_severity := CASE v_failure_class
    WHEN 'BUG' THEN 'critical'
    WHEN 'CASCADE_FAILURE' THEN 'critical'
    WHEN 'AGENT_STALLED' THEN 'high'
    WHEN 'AGENT_INCOMPATIBLE' THEN 'high'
    WHEN 'AGENT_OFFLINE' THEN 'high'
    WHEN 'POLICY' THEN 'medium'
    WHEN 'TIMEOUT' THEN 'medium'
    ELSE 'low'
  END;
  
  INSERT INTO public.failure_fingerprints (
    fingerprint_hash,
    source_type,
    failure_class,
    normalized_signature,
    severity_hint
  ) VALUES (
    v_hash,
    p_source_type,
    v_failure_class,
    p_signature,
    v_severity
  )
  ON CONFLICT (fingerprint_hash) DO UPDATE SET
    last_seen_at = now(),
    total_occurrences = public.failure_fingerprints.total_occurrences + 1,
    is_active = true,
    updated_at = now()
  RETURNING id INTO v_fingerprint_id;
  
  INSERT INTO public.failure_occurrences (
    fingerprint_id,
    tenant_id,
    source_type,
    source_id,
    agent_id,
    error_excerpt
  ) VALUES (
    v_fingerprint_id,
    p_tenant_id,
    p_source_type,
    p_source_id,
    p_agent_id,
    p_error_excerpt
  );
  
  UPDATE public.failure_fingerprints SET
    distinct_tenants = (
      SELECT COUNT(DISTINCT tenant_id) 
      FROM public.failure_occurrences 
      WHERE fingerprint_id = v_fingerprint_id
    ),
    distinct_agents = (
      SELECT COUNT(DISTINCT agent_id) 
      FROM public.failure_occurrences 
      WHERE fingerprint_id = v_fingerprint_id
        AND agent_id IS NOT NULL
    )
  WHERE id = v_fingerprint_id;
  
  RETURN v_fingerprint_id;
END;
$$;


--
-- Name: FUNCTION register_failure_occurrence(p_signature jsonb, p_tenant_id uuid, p_source_type text, p_source_id uuid, p_agent_id uuid, p_error_excerpt text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.register_failure_occurrence(p_signature jsonb, p_tenant_id uuid, p_source_type text, p_source_id uuid, p_agent_id uuid, p_error_excerpt text) IS 'ADR-033: UPSERT fingerprint and record occurrence';


