--
-- Name: remove_agent_isolation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_agent_isolation(p_agent_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- SECURITY: Verify agent belongs to caller's tenant (or caller is super admin)
  IF NOT EXISTS (
    SELECT 1 FROM public.agents a
    WHERE a.id = p_agent_id
    AND (a.tenant_id = get_active_tenant_id() OR is_current_super_admin())
  ) THEN
    RAISE EXCEPTION 'Unauthorized: Agent % does not belong to your tenant', p_agent_id;
  END IF;

  UPDATE public.agents
  SET 
    is_isolated = false,
    isolated_at = NULL,
    isolation_reason = NULL
  WHERE id = p_agent_id;
  
  RETURN FOUND;
END;
$$;


--
-- Name: FUNCTION remove_agent_isolation(p_agent_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.remove_agent_isolation(p_agent_id uuid) IS 'SECURITY: Tenant-verified isolation removal. Requires caller to own the agent via tenant_id check. ADR-VELLUM-001.';


