--
-- Name: reprocess_job_outputs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reprocess_job_outputs(p_hours_back integer DEFAULT 48) RETURNS TABLE(job_id uuid, job_type text, agent_name text, output_type text, needs_reprocessing boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    j.id as job_id,
    j.type as job_type,
    j.agent_name,
    pg_typeof(j.output)::text as output_type,
    true as needs_reprocessing
  FROM public.jobs j
  WHERE j.status = 'completed'
    AND j.output IS NOT NULL
    AND j.type IN ('collect_web_activity', 'software_inventory_collect', 'collect_antivirus_status')
    AND j.created_at > NOW() - (p_hours_back || ' hours')::interval
    AND (
      -- Jobs de web_activity sem dados correspondentes
      (j.type = 'collect_web_activity' AND NOT EXISTS (
        SELECT 1 FROM public.agent_web_activity aw 
        WHERE aw.agent_id = j.agent_id 
          AND aw.created_at > j.created_at - INTERVAL '1 hour'
      ))
      OR
      -- Jobs de software_inventory sem dados correspondentes  
      (j.type = 'software_inventory_collect' AND NOT EXISTS (
        SELECT 1 FROM public.software_inventory si 
        WHERE si.agent_id = j.agent_id 
          AND si.collected_at > j.created_at - INTERVAL '1 hour'
      ))
      OR
      -- Jobs de antivirus sem dados correspondentes
      (j.type = 'collect_antivirus_status' AND NOT EXISTS (
        SELECT 1 FROM public.antivirus_status av 
        WHERE av.agent_id = j.agent_id 
          AND av.collected_at > j.created_at - INTERVAL '1 hour'
      ))
    )
  ORDER BY j.created_at DESC;
END;
$$;


--
-- Name: request_ai_action_rollback(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_ai_action_rollback(p_ai_action_id uuid, p_requested_by uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  act RECORD;
BEGIN
  SELECT * INTO act
  FROM public.ai_actions
  WHERE id = p_ai_action_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'AI action not found');
  END IF;

  IF act.reversible IS NOT TRUE THEN
    RETURN jsonb_build_object('success', false, 'error', 'Action is not reversible');
  END IF;

  IF act.rollback_status IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Rollback already requested');
  END IF;

  -- Mark rollback pending
  UPDATE public.ai_actions
  SET
    rollback_status = 'pending',
    rollback_reason = p_reason
  WHERE id = p_ai_action_id;

  -- Create decision event
  INSERT INTO public.decision_events (
    tenant_id,
    rule_code,
    agent_id,
    agent_name,
    action,
    decision_source,
    decision_type,
    evidence,
    created_at
  ) VALUES (
    act.tenant_id,
    'ROLLBACK_REQUEST',
    act.agent_id,
    act.agent_name,
    'rollback_requested',
    'human',
    'compensating_action',
    jsonb_build_object(
      'ai_action_id', act.id,
      'requested_by', p_requested_by,
      'reason', p_reason,
      'original_action', act.action_type
    ),
    NOW()
  );

  RETURN jsonb_build_object('success', true, 'ai_action_id', p_ai_action_id);
END;
$$;


--
-- Name: require_key_hash(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_key_hash() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- P1 SEC-001: key_hash must be present for new enrollment keys
  IF NEW.key_hash IS NULL THEN
    RAISE EXCEPTION 'SECURITY_VIOLATION: key_hash is required. Cannot store enrollment keys without hash.'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: requires_human_review(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.requires_human_review(p_tenant_id uuid, p_severity text, p_action_type text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant_setting boolean;
  v_critical_severities text[] := ARRAY['critical', 'high'];
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  -- Check tenant-level setting
  SELECT force_human_review_critical INTO v_tenant_setting
  FROM tenant_settings
  WHERE tenant_id = p_tenant_id;
  
  -- Default to true if no tenant setting exists
  v_tenant_setting := COALESCE(v_tenant_setting, true);
  
  -- If tenant has it enabled and severity is critical/high, require review
  IF v_tenant_setting AND p_severity = ANY(v_critical_severities) THEN
    RETURN true;
  END IF;
  
  RETURN false;
END;
$$;


