--
-- Name: resolve_stale_dlq_entries(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_stale_dlq_entries() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  resolved_count integer := 0;
  result jsonb;
BEGIN
  -- Resolver entradas DLQ pendentes de AGENT_OFFLINE com >24h
  UPDATE failed_jobs_dlq 
  SET 
    status = 'resolved',
    resolved_at = NOW(),
    resolution_notes = 'Auto-resolved: Agent offline job expired after 24h'
  WHERE status = 'pending'
    AND failure_class = 'AGENT_OFFLINE'
    AND created_at < NOW() - INTERVAL '24 hours';
  
  GET DIAGNOSTICS resolved_count = ROW_COUNT;
  
  result := jsonb_build_object(
    'success', true,
    'dlq_entries_resolved', resolved_count,
    'executed_at', NOW()
  );
  
  -- Reportar para cron_health_checks
  INSERT INTO cron_health_checks (cron_name, last_success_at, consecutive_failures, updated_at, last_result)
  VALUES ('resolve-stale-dlq', NOW(), 0, NOW(), result)
  ON CONFLICT (cron_name) DO UPDATE SET
    last_success_at = NOW(),
    consecutive_failures = 0,
    last_error = NULL,
    updated_at = NOW(),
    last_result = EXCLUDED.last_result;
  
  RETURN result;
  
EXCEPTION WHEN OTHERS THEN
  INSERT INTO cron_health_checks (cron_name, last_failure_at, last_error, consecutive_failures, updated_at)
  VALUES ('resolve-stale-dlq', NOW(), SQLERRM, 1, NOW())
  ON CONFLICT (cron_name) DO UPDATE SET
    last_failure_at = NOW(),
    last_error = SQLERRM,
    consecutive_failures = cron_health_checks.consecutive_failures + 1,
    updated_at = NOW();
  RAISE;
END;
$$;


--
-- Name: FUNCTION resolve_stale_dlq_entries(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.resolve_stale_dlq_entries() IS 'Resolve entradas DLQ de AGENT_OFFLINE com >24h';


--
-- Name: review_dlq_item(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_dlq_item(p_dlq_id uuid, p_review_notes text, p_risk_category text DEFAULT 'benign'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant_id uuid;
  v_result jsonb;
BEGIN
  SELECT tenant_id INTO v_tenant_id FROM user_roles WHERE user_id = auth.uid() LIMIT 1;
  IF v_tenant_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
  END IF;
  
  UPDATE failed_jobs_dlq SET 
    resolved_by = auth.uid(),
    resolved_at = NOW(),
    review_notes = p_review_notes,
    risk_category = p_risk_category,
    status = 'resolved'
  WHERE id = p_dlq_id AND tenant_id = v_tenant_id
  RETURNING jsonb_build_object('success', true, 'id', id, 'resolved_at', resolved_at) INTO v_result;
  
  RETURN COALESCE(v_result, jsonb_build_object('success', false, 'error', 'Not found'));
END;
$$;


--
-- Name: revive_agent_on_reenroll(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revive_agent_on_reenroll(p_agent_id uuid, p_new_hmac_secret text, p_expected_tenant_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agent RECORD;
BEGIN
  -- Buscar agente
  SELECT id, agent_name, tenant_id INTO v_agent 
  FROM agents WHERE id = p_agent_id;
  
  IF v_agent.id IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'AGENT_NOT_FOUND');
  END IF;
  
  -- CRIT-06: Validação de tenant para prevenir cross-tenant escalation
  -- Se p_expected_tenant_id foi fornecido, validar que o agente pertence ao tenant correto
  IF p_expected_tenant_id IS NOT NULL AND v_agent.tenant_id IS DISTINCT FROM p_expected_tenant_id THEN
    RETURN json_build_object(
      'success', false, 
      'error', 'TENANT_MISMATCH',
      'message', 'Agent does not belong to the expected tenant'
    );
  END IF;
  
  -- Desativar tokens antigos
  UPDATE agent_tokens SET is_active = false WHERE agent_id = p_agent_id;
  
  -- Reviver agente com estado limpo
  UPDATE agents SET
    status = 'active',
    hmac_secret = p_new_hmac_secret,
    last_heartbeat = NULL,
    agent_state = 'pending_enrollment',
    agent_state_changed_at = NOW(),
    agent_state_reason = 'Reenrollment iniciado',
    is_throttled = false,
    throttle_reason = NULL,
    throttled_at = NULL,
    is_isolated = false,
    isolation_reason = NULL,
    isolated_at = NULL,
    safe_mode_entered_at = NULL,
    safe_mode_reason = NULL,
    offline_detected_at = NULL,
    offline_reason = NULL,
    archived_at = NULL,
    archived_reason = NULL
  WHERE id = p_agent_id;
  
  RETURN json_build_object(
    'success', true,
    'agent_id', p_agent_id,
    'agent_name', v_agent.agent_name,
    'action', 'revived'
  );
END;
$$;


--
-- Name: revoke_agent_signing_key(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_agent_signing_key(p_agent_id uuid, p_reason text DEFAULT 'manual_revocation'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant_id uuid;
  v_caller_tenant_id uuid;
  v_agent_name text;
  v_old_hmac_hash text;
BEGIN
  SELECT tenant_id, name, encode(extensions.digest(hmac_secret::bytea, 'sha256'), 'hex')
  INTO v_tenant_id, v_agent_name, v_old_hmac_hash
  FROM agents
  WHERE id = p_agent_id;
  
  IF v_tenant_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'AGENT_NOT_FOUND', 'message', 'Agent does not exist');
  END IF;
  
  v_caller_tenant_id := get_active_tenant_id();
  
  IF v_caller_tenant_id IS NULL AND NOT is_current_super_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'NO_TENANT_CONTEXT', 'message', 'No active tenant context');
  END IF;
  
  IF v_tenant_id != v_caller_tenant_id AND NOT is_current_super_admin() THEN
    INSERT INTO security_logs (event_type, severity, user_id, tenant_id, details, ip_address)
    VALUES ('CROSS_TENANT_ACCESS_ATTEMPT', 'critical', auth.uid(), v_caller_tenant_id,
      jsonb_build_object('function', 'revoke_agent_signing_key', 'target_agent_id', p_agent_id, 'target_tenant_id', v_tenant_id, 'caller_tenant_id', v_caller_tenant_id),
      '0.0.0.0'::inet);
    RETURN jsonb_build_object('success', false, 'error', 'TENANT_MISMATCH', 'message', 'Access denied: agent belongs to different tenant');
  END IF;
  
  UPDATE agents SET hmac_secret = encode(gen_random_bytes(32), 'hex'), updated_at = now() WHERE id = p_agent_id;
  
  INSERT INTO audit_logs (tenant_id, user_id, action, resource_type, resource_id, details)
  VALUES (v_tenant_id, auth.uid(), 'SIGNING_KEY_REVOKED', 'agent', p_agent_id,
    jsonb_build_object('agent_name', v_agent_name, 'reason', p_reason, 'old_key_hash_prefix', left(v_old_hmac_hash, 8)));
  
  RETURN jsonb_build_object('success', true, 'agent_id', p_agent_id, 'agent_name', v_agent_name, 'action', 'signing_key_revoked', 'note', 'Agent must re-enroll to communicate with server');
END;
$$;


