--
-- Name: revoke_tokens_on_archive(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_tokens_on_archive() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'archived' AND OLD.status != 'archived' THEN
    UPDATE agent_tokens SET is_active = false
    WHERE agent_id = NEW.id AND is_active = true;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: rollback_soar_playbook(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rollback_soar_playbook(p_playbook_id uuid, p_target_version integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_snapshot jsonb;
  v_tenant_id uuid;
BEGIN
  SELECT config_snapshot, tenant_id INTO v_snapshot, v_tenant_id FROM soar_playbook_versions
  WHERE playbook_id = p_playbook_id AND version = p_target_version;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Version not found'); END IF;

  UPDATE soar_playbooks SET
    name = COALESCE(v_snapshot->>'name', name), trigger_type = COALESCE(v_snapshot->>'trigger_type', trigger_type),
    trigger_conditions = COALESCE(v_snapshot->'trigger_conditions', trigger_conditions),
    actions = COALESCE(v_snapshot->'actions', actions), is_active = COALESCE((v_snapshot->>'is_active')::boolean, is_active),
    auto_execute = COALESCE((v_snapshot->>'auto_execute')::boolean, auto_execute),
    requires_approval = COALESCE((v_snapshot->>'requires_approval')::boolean, requires_approval),
    cooldown_minutes = COALESCE((v_snapshot->>'cooldown_minutes')::integer, cooldown_minutes)
  WHERE id = p_playbook_id AND tenant_id = v_tenant_id;

  RETURN jsonb_build_object('success', true, 'rolled_back_to', p_target_version);
END;
$$;


--
-- Name: run_all_health_checks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_all_health_checks() RETURNS TABLE(check_name text, passed boolean, error_msg text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_check RECORD;
  v_result boolean;
  v_error text;
BEGIN
  FOR v_check IN SELECT * FROM system_health_checks LOOP
    BEGIN
      EXECUTE v_check.check_query INTO v_result;
      v_error := NULL;
      
      UPDATE system_health_checks 
      SET last_run_at = now(),
          last_result = (v_result = v_check.expected_result),
          last_error = NULL
      WHERE id = v_check.id;
      
      check_name := v_check.check_name;
      passed := (v_result = v_check.expected_result);
      error_msg := NULL;
      RETURN NEXT;
    EXCEPTION WHEN OTHERS THEN
      v_error := SQLERRM;
      
      UPDATE system_health_checks 
      SET last_run_at = now(),
          last_result = false,
          last_error = v_error
      WHERE id = v_check.id;
      
      check_name := v_check.check_name;
      passed := false;
      error_msg := v_error;
      RETURN NEXT;
    END;
  END LOOP;
END;
$$;


--
-- Name: run_correlation_engine(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_correlation_engine(p_tenant_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rule RECORD;
  v_match RECORD;
  v_count INTEGER := 0;
BEGIN
  FOR v_rule IN
    SELECT id, condition_a_event_type, condition_b_event_type, window_minutes, severity
    FROM public.correlation_rules
    WHERE tenant_id = p_tenant_id
      AND is_enabled = true
      AND mode IN ('active', 'dry_run')
  LOOP
    FOR v_match IN
      SELECT
        a.agent_id,
        a.created_at AS event_a_time,
        b.created_at AS event_b_time,
        a.event_type AS event_a_type,
        b.event_type AS event_b_type
      FROM public.agent_evidence_logs a
      JOIN public.agent_evidence_logs b
        ON a.tenant_id = b.tenant_id
        AND a.agent_id = b.agent_id
        AND b.event_type = v_rule.condition_b_event_type
        AND b.created_at > a.created_at
        AND b.created_at < a.created_at + (v_rule.window_minutes || ' minutes')::INTERVAL
      WHERE a.tenant_id = p_tenant_id
        AND a.event_type = v_rule.condition_a_event_type
        AND a.created_at > now() - INTERVAL '1 hour'
      LIMIT 100
    LOOP
      INSERT INTO public.correlation_results (
        tenant_id, correlation_rule_id, agent_id,
        event_a_time, event_b_time,
        event_a_summary, event_b_summary, severity
      ) VALUES (
        p_tenant_id, v_rule.id, v_match.agent_id,
        v_match.event_a_time, v_match.event_b_time,
        v_match.event_a_type, v_match.event_b_type,
        v_rule.severity
      );
      v_count := v_count + 1;
    END LOOP;

    UPDATE public.correlation_rules
    SET match_count = match_count + v_count,
        updated_at = now()
    WHERE id = v_rule.id;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: run_integrity_sentinel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_integrity_sentinel() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant RECORD;
  v_result RECORD;
  v_alerts_created INT := 0;
  v_tenants_checked INT := 0;
  v_window_start TIMESTAMP WITH TIME ZONE := NOW() - INTERVAL '24 hours';
BEGIN
  FOR v_tenant IN
    SELECT id FROM tenants
  LOOP
    v_tenants_checked := v_tenants_checked + 1;

    -- Check audit_logs chain
    SELECT * INTO v_result
    FROM verify_audit_log_chain(v_tenant.id, v_window_start, NOW());

    IF v_result IS NOT NULL AND NOT v_result.chain_valid THEN
      INSERT INTO system_alerts (
        tenant_id, alert_type, severity, title, message, metadata
      ) VALUES (
        v_tenant.id,
        'integrity_violation',
        'critical',
        'Audit log chain broken',
        format('Hash chain break detected at %s (log id: %s)', v_result.broken_at, v_result.broken_id),
        jsonb_build_object('table', 'audit_logs', 'broken_at', v_result.broken_at, 'broken_id', v_result.broken_id)
      );
      v_alerts_created := v_alerts_created + 1;
    END IF;

    -- Check security_logs chain
    SELECT * INTO v_result
    FROM verify_security_log_chain(v_tenant.id, v_window_start, NOW());

    IF v_result IS NOT NULL AND NOT v_result.chain_valid THEN
      INSERT INTO system_alerts (
        tenant_id, alert_type, severity, title, message, metadata
      ) VALUES (
        v_tenant.id,
        'integrity_violation',
        'critical',
        'Security log chain broken',
        format('Hash chain break detected at %s (log id: %s)', v_result.broken_at, v_result.broken_id),
        jsonb_build_object('table', 'security_logs', 'broken_at', v_result.broken_at, 'broken_id', v_result.broken_id)
      );
      v_alerts_created := v_alerts_created + 1;
    END IF;

    -- Check evidence_logs chain
    SELECT * INTO v_result
    FROM verify_evidence_log_chain(v_tenant.id, v_window_start, NOW());

    IF v_result IS NOT NULL AND NOT v_result.chain_valid THEN
      INSERT INTO system_alerts (
        tenant_id, alert_type, severity, title, message, metadata
      ) VALUES (
        v_tenant.id,
        'integrity_violation',
        'critical',
        'Evidence log chain broken',
        format('Hash chain break detected at %s (log id: %s)', v_result.broken_at, v_result.broken_id),
        jsonb_build_object('table', 'agent_evidence_logs', 'broken_at', v_result.broken_at, 'broken_id', v_result.broken_id)
      );
      v_alerts_created := v_alerts_created + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'tenants_checked', v_tenants_checked,
    'alerts_created', v_alerts_created,
    'checked_at', NOW()
  );
END;
$$;


--
-- Name: run_maintenance_v2(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_maintenance_v2(p_expire_limit integer DEFAULT 500, p_archive_limit integer DEFAULT 1000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_expired_jobs integer := 0;
  v_archived_executions integer := 0;
  v_stale_flags_cleaned integer := 0;
  v_retriggered_agents integer := 0;
BEGIN
  -- 1. Expire jobs that exceeded TTL (4h default + 2h buffer = 6h)
  WITH candidates AS (
    SELECT id FROM jobs
    WHERE status IN ('pending', 'queued', 'delivered', 'running')
      AND created_at < now() - interval '6 hours'
    LIMIT p_expire_limit
  ),
  expired AS (
    UPDATE jobs SET status = 'expired', updated_at = now()
    FROM candidates WHERE jobs.id = candidates.id
    RETURNING jobs.id
  )
  SELECT count(*) INTO v_expired_jobs FROM expired;

  -- 2. Archive old execution records (> 30 days)
  WITH candidates AS (
    SELECT id FROM job_execution_results
    WHERE created_at < now() - interval '30 days'
    LIMIT p_archive_limit
  ),
  archived AS (
    DELETE FROM job_execution_results
    USING candidates WHERE job_execution_results.id = candidates.id
    RETURNING job_execution_results.id
  )
  SELECT count(*) INTO v_archived_executions FROM archived;

  -- 3. Clean stale force_update flags (delivered but not applied after 48h)
  WITH cleaned AS (
    UPDATE agents
    SET force_update_at = NULL,
        force_update_delivered_count = 0,
        force_update_delivery_count = 0
    WHERE force_update_at IS NOT NULL
      AND force_update_at < now() - interval '48 hours'
      AND force_update_delivered_count >= 3
    RETURNING id
  )
  SELECT count(*) INTO v_stale_flags_cleaned FROM cleaned;

  -- 4. Re-trigger force_update for agents offline > 72h with outdated version
  -- CRITICAL: Does NOT auto-archive/inactivate agents
  WITH retriggered AS (
    UPDATE agents a
    SET force_update_at = now(),
        force_update_reason = 'auto_retrigger_72h_offline',
        force_update_delivered_count = 0,
        force_update_delivery_count = 0
    WHERE a.force_update_at IS NULL
      AND a.last_heartbeat < now() - interval '72 hours'
      AND a.last_heartbeat IS NOT NULL
      AND a.is_active = true
      AND a.agent_version IS DISTINCT FROM (
        SELECT ar.version 
        FROM agent_releases ar
        WHERE ar.is_active = true 
          AND ar.platform = COALESCE(a.os_type, 'windows')
        ORDER BY ar.created_at DESC 
        LIMIT 1
      )
    RETURNING a.id
  )
  SELECT count(*) INTO v_retriggered_agents FROM retriggered;

  -- 5. Auto-expire stale DLQ items (> 48h pending)
  UPDATE failed_jobs_dlq
  SET status = 'exhausted', updated_at = now()
  WHERE status = 'pending'
    AND created_at < now() - interval '48 hours';

  -- 6. Auto-resolve stale open tasks (> 48h)
  UPDATE tasks
  SET status = 'resolved', resolution = 'auto_expired_stale',
      resolved_at = now(), updated_at = now()
  WHERE status = 'open'
    AND created_at < now() - interval '48 hours';

  RETURN jsonb_build_object(
    'expired_jobs', v_expired_jobs,
    'archived_executions', v_archived_executions,
    'stale_flags_cleaned', v_stale_flags_cleaned,
    'retriggered_agents', v_retriggered_agents
  );
END;
$$;


--
-- Name: run_partition_maintenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_partition_maintenance() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    -- Create future partitions
    PERFORM maintain_partitions();
    
    -- Drop old partitions (keep 3 months)
    PERFORM drop_old_partitions('audit_logs', 3);
    PERFORM drop_old_partitions('job_executions', 3);
    PERFORM drop_old_partitions('agent_system_metrics_partitioned', 3);
    PERFORM drop_old_partitions('endpoint_process_events_partitioned', 3);
    PERFORM drop_old_partitions('endpoint_event_buffer_partitioned', 3);
    PERFORM drop_old_partitions('endpoint_network_events_partitioned', 3);
END;
$$;


--
-- Name: run_system_maintenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_system_maintenance() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb := '{}'::jsonb;
  v_stale_tasks jsonb;
  v_cancelled_jobs integer;
  v_dlq_reconciled integer := 0;
  v_jobruns_cleaned integer := 0;
  v_diskmetrics_cleaned integer := 0;
  v_hmac_cleaned integer := 0;
  v_rate_limits_cleaned integer := 0;
  v_zombie_jobs integer := 0;
  v_stuck_inprogress integer := 0;
BEGIN
  -- 1. Auto-resolve stale tasks
  v_stale_tasks := auto_resolve_stale_tasks();
  v_result := v_result || jsonb_build_object('stale_tasks', v_stale_tasks);

  -- 2. Cancel jobs for archived agents
  v_cancelled_jobs := auto_cancel_archived_agent_jobs();
  v_result := v_result || jsonb_build_object('archived_agent_jobs_cancelled', v_cancelled_jobs);

  -- 3. Auto-archive disabled
  v_result := v_result || jsonb_build_object('agents_archived', 0, 'auto_archive_disabled', true);

  -- 4. Reconcile DLQ
  WITH reconciled AS (
    UPDATE failed_jobs_dlq dlq
    SET status = 'ignored', resolved_at = now(), resolved_by = 'system_maintenance'
    FROM jobs j
    WHERE dlq.original_job_id = j.id AND j.status = 'archived' AND dlq.status = 'pending'
    RETURNING dlq.id
  )
  SELECT count(*) INTO v_dlq_reconciled FROM reconciled;
  v_result := v_result || jsonb_build_object('dlq_reconciled', v_dlq_reconciled);

  -- 5. Expire zombie jobs (delivered but past TTL)
  WITH expired AS (
    UPDATE jobs
    SET status = 'failed', 
        completed_at = now(), 
        error_message = '[DLQ:EXPIRED_TTL] Job expired during maintenance sweep',
        failure_class = 'EXPIRED'
    WHERE status = 'delivered' AND expires_at IS NOT NULL AND expires_at < now()
    RETURNING id
  )
  SELECT count(*) INTO v_zombie_jobs FROM expired;
  v_result := v_result || jsonb_build_object('zombie_jobs_expired', v_zombie_jobs);

  -- 6. SLA breach detection
  UPDATE tasks SET sla_breached_at = now()
  WHERE status IN ('open','in_progress') AND due_at IS NOT NULL AND due_at < now() AND sla_breached_at IS NULL;

  -- 7. DATA RETENTION
  WITH del1 AS (
    DELETE FROM scheduled_job_runs WHERE created_at < now() - interval '30 days' RETURNING id
  ) SELECT count(*) INTO v_jobruns_cleaned FROM del1;

  WITH del2 AS (
    DELETE FROM agent_disk_metrics WHERE collected_at < now() - interval '30 days' RETURNING id
  ) SELECT count(*) INTO v_diskmetrics_cleaned FROM del2;

  -- 8. HMAC CLEANUP
  WITH del3 AS (
    DELETE FROM hmac_signatures WHERE used_at < now() - interval '7 days' RETURNING id
  ) SELECT count(*) INTO v_hmac_cleaned FROM del3;

  -- 9. RATE LIMITS CLEANUP
  WITH del4 AS (
    DELETE FROM rate_limits WHERE window_start < now() - interval '1 hour' AND blocked_until IS NULL RETURNING id
  ) SELECT count(*) INTO v_rate_limits_cleaned FROM del4;

  v_result := v_result || jsonb_build_object(
    'data_retention', jsonb_build_object(
      'job_runs_purged', v_jobruns_cleaned,
      'disk_metrics_purged', v_diskmetrics_cleaned,
      'hmac_signatures_purged', v_hmac_cleaned,
      'rate_limits_purged', v_rate_limits_cleaned
    )
  );

  -- 10. Auto-resolve stuck in_progress tasks (>14 days)
  -- FIX: Use correct columns closed_at/closure_reason (not resolved_at/resolution_notes)
  WITH stuck AS (
    UPDATE tasks 
    SET status = 'resolved', 
        closed_at = now(),
        closure_reason = 'auto_resolved_maintenance_stuck_14d',
        updated_at = now()
    WHERE status = 'in_progress' 
      AND updated_at < now() - interval '14 days'
    RETURNING id
  )
  SELECT count(*) INTO v_stuck_inprogress FROM stuck;
  v_result := v_result || jsonb_build_object('stuck_inprogress_resolved', v_stuck_inprogress);

  v_result := v_result || jsonb_build_object('executed_at', now());
  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION run_system_maintenance(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.run_system_maintenance() IS 'Orquestra todas as funções de manutenção do sistema';


--
-- Name: sanitize_dlq_payload(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sanitize_dlq_payload() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Generate SHA-256 hash of payload
  IF NEW.payload IS NOT NULL AND NEW.payload_hash IS NULL THEN
    NEW.payload_hash := encode(extensions.digest(NEW.payload::text::bytea, 'sha256'), 'hex');
    NEW.payload_schema := jsonb_typeof(NEW.payload)::text;
    
    -- Risk classification based on suspicious patterns
    NEW.risk_category := COALESCE(NEW.risk_category,
      CASE
        WHEN NEW.payload::text ~* '(drop\s+table|delete\s+from|truncate|<script|javascript:|eval\(|exec\s*\()' THEN 'critical'
        WHEN NEW.payload::text ~* '(select\s+.*\s+from|insert\s+into|update\s+.*\s+set|curl\s|wget\s)' THEN 'high'
        WHEN NEW.payload::text ~* '(password|secret|token|api_key|private_key)' THEN 'medium'
        ELSE 'low'
      END
    );
    
    -- Safe excerpt (max 256 chars, alphanumeric only)
    NEW.payload_excerpt := left(
      regexp_replace(NEW.payload::text, '[^a-zA-Z0-9 _.,:\-]', '', 'g'), 
      256
    );
  END IF;
  
  RETURN NEW;
END;
$$;


