--
-- Name: set_cached_value(text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_cached_value(p_key text, p_value jsonb, p_ttl_seconds integer DEFAULT 300) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    INSERT INTO kv_cache (key, value, expires_at)
    VALUES (p_key, p_value, NOW() + (p_ttl_seconds || ' seconds')::INTERVAL)
    ON CONFLICT (key) DO UPDATE SET
        value = EXCLUDED.value,
        expires_at = EXCLUDED.expires_at;
END;
$$;


--
-- Name: set_job_priority(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_job_priority() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    -- Critical jobs (1): enrollment, heartbeat
    IF NEW.type IN ('enroll', 'heartbeat', 'update_agent') THEN
        NEW.priority := 1;
    -- Heavy jobs (3): scans, reports
    ELSIF NEW.type IN ('light_vuln_scan', 'report', 'full_scan') THEN
        NEW.priority := 3;
    -- Standard jobs (2): everything else
    ELSE
        NEW.priority := 2;
    END IF;
    
    RETURN NEW;
END;
$$;


