--
-- Name: severity_floor_rate(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.severity_floor_rate(p_severity text) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE p_severity
    WHEN 'critical' THEN 1.0
    WHEN 'high' THEN 0.5
    WHEN 'medium' THEN 0.2
    ELSE 0.1
  END::numeric;
$$;


--
-- Name: should_auto_execute_playbook(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.should_auto_execute_playbook(p_playbook_id uuid, p_event_type text, p_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_risk_score NUMERIC;
  v_threshold NUMERIC;
  v_require_approval BOOLEAN;
  v_has_destructive_actions BOOLEAN;
  v_is_enabled BOOLEAN;
BEGIN
  -- Calcular risk score
  v_risk_score := calculate_event_risk(p_event_type, p_context);
  
  -- Buscar threshold do evento
  SELECT auto_action_threshold INTO v_threshold
  FROM event_risk_scoring
  WHERE event_type = p_event_type AND is_active = true;
  
  IF v_threshold IS NULL THEN
    v_threshold := 0.8; -- Default conservador
  END IF;
  
  -- Verificar se playbook tem ações destrutivas
  SELECT EXISTS(
    SELECT 1 FROM playbook_actions
    WHERE playbook_id = p_playbook_id
    AND action_type IN ('isolate', 'kill_process', 'stop_service', 'disable_service', 'revoke_token', 'quarantine', 'network_isolate')
  ) INTO v_has_destructive_actions;
  
  -- Verificar configuração do playbook
  SELECT require_approval, is_enabled 
  INTO v_require_approval, v_is_enabled
  FROM playbooks WHERE id = p_playbook_id;
  
  -- Decisão final: auto-execute se:
  -- 1. Playbook está ativo
  -- 2. Não tem ações destrutivas
  -- 3. Não requer aprovação
  -- 4. Risk score >= threshold
  RETURN jsonb_build_object(
    'risk_score', ROUND(v_risk_score, 3),
    'threshold', ROUND(v_threshold, 3),
    'should_auto_execute', (
      v_is_enabled 
      AND v_risk_score >= v_threshold 
      AND NOT v_has_destructive_actions 
      AND NOT COALESCE(v_require_approval, true)
    ),
    'has_destructive_actions', v_has_destructive_actions,
    'require_approval', COALESCE(v_require_approval, true),
    'is_enabled', COALESCE(v_is_enabled, false),
    'decision_reason', CASE
      WHEN NOT COALESCE(v_is_enabled, false) THEN 'playbook_disabled'
      WHEN v_has_destructive_actions THEN 'blocked_destructive_action'
      WHEN COALESCE(v_require_approval, true) THEN 'requires_manual_approval'
      WHEN v_risk_score < v_threshold THEN 'below_risk_threshold'
      ELSE 'auto_execute_approved'
    END
  );
END;
$$;


--
-- Name: should_auto_quarantine(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.should_auto_quarantine(p_tenant_id uuid, p_context jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_enabled BOOLEAN;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  -- Buscar configuração do tenant
  SELECT enable_auto_quarantine INTO v_enabled
  FROM tenant_settings
  WHERE tenant_id = p_tenant_id;

  IF NOT COALESCE(v_enabled, false) THEN
    RETURN false;
  END IF;

  -- Critérios para auto-quarentena
  IF (p_context->>'threat_level')::INT >= 8 THEN
    RETURN true;
  END IF;

  IF p_context->>'verdict' = 'malicious' THEN
    RETURN true;
  END IF;

  IF (p_context->>'positives')::INT >= 5 THEN
    RETURN true;
  END IF;

  RETURN false;
END;
$$;


--
-- Name: snapshot_mitre_coverage(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snapshot_mitre_coverage(tenant_uuid uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  inserted_count INT := 0;
  snap_date DATE := CURRENT_DATE;
BEGIN
  -- Delete existing snapshot for today to allow re-run
  DELETE FROM mitre_coverage_snapshot
  WHERE tenant_id = tenant_uuid AND snapshot_date = snap_date;

  -- Insert coverage data
  WITH covered AS (
    SELECT
      mitre_technique_id AS technique_id,
      COUNT(*) AS detection_count,
      MAX(updated_at) AS last_detected_at
    FROM detection_rules
    WHERE is_enabled = true
      AND mitre_technique_id IS NOT NULL
      AND (tenant_id IS NULL OR tenant_id = tenant_uuid)
    GROUP BY mitre_technique_id
  )
  INSERT INTO mitre_coverage_snapshot (tenant_id, technique_id, detection_count, last_detected_at, coverage_status, snapshot_date)
  SELECT
    tenant_uuid,
    mat.technique_id,
    COALESCE(c.detection_count, 0),
    c.last_detected_at,
    CASE
      WHEN c.detection_count >= 3 THEN 'high'
      WHEN c.detection_count >= 1 THEN 'partial'
      ELSE 'none'
    END,
    snap_date
  FROM mitre_attack_techniques mat
  LEFT JOIN covered c ON mat.technique_id = c.technique_id;

  GET DIAGNOSTICS inserted_count = ROW_COUNT;

  RETURN json_build_object('snapshot_date', snap_date, 'rows_inserted', inserted_count);
END;
$$;


--
-- Name: soar_evaluate_alert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.soar_evaluate_alert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_playbook RECORD;
  v_trigger_type text;
  v_execution_id uuid;
BEGIN
  v_trigger_type := CASE NEW.alert_type
    WHEN 'vulnerability_critical' THEN 'vulnerability_critical'
    WHEN 'antivirus_outdated' THEN 'antivirus_outdated'
    WHEN 'antivirus_inactive' THEN 'antivirus_outdated'
    WHEN 'firewall_disabled' THEN 'antivirus_outdated'
    WHEN 'certificate_expiring' THEN 'certificate_expiring'
    WHEN 'usb_device_risky' THEN 'usb_device_risky'
    WHEN 'process_suspicious' THEN 'process_suspicious'
    WHEN 'behavioral_anomaly' THEN 'behavioral_anomaly'
    WHEN 'agent_compromised' THEN 'behavioral_anomaly'
    WHEN 'ai_insight_alert' THEN 'behavioral_anomaly'
    WHEN 'agent_long_offline' THEN 'behavioral_anomaly'
    WHEN 'automation_alert' THEN 'process_suspicious'
    WHEN 'network_anomaly' THEN 'network_anomaly'
    WHEN 'file_integrity_violation' THEN 'file_integrity_violation'
    WHEN 'stale_cron' THEN 'behavioral_anomaly'
    WHEN 'vulnerable_software' THEN 'vulnerability_critical'
    WHEN 'unauthorized_usb' THEN 'usb_device_risky'
    ELSE NULL
  END;

  IF v_trigger_type IS NULL THEN RETURN NEW; END IF;

  SELECT * INTO v_playbook FROM soar_playbooks
  WHERE trigger_type = v_trigger_type AND is_active = true
    AND (tenant_id = NEW.tenant_id OR tenant_id IS NULL)
    AND (last_triggered_at IS NULL OR last_triggered_at < NOW() - (cooldown_minutes || ' minutes')::interval)
  ORDER BY CASE WHEN tenant_id = NEW.tenant_id THEN 0 ELSE 1 END
  LIMIT 1;

  IF v_playbook IS NULL THEN RETURN NEW; END IF;

  v_execution_id := gen_random_uuid();

  INSERT INTO soar_executions (
    id, tenant_id, playbook_id, trigger_type, agent_id, status, actions_taken, started_at, created_at
  ) VALUES (
    v_execution_id, NEW.tenant_id, v_playbook.id, v_trigger_type, NEW.agent_id,
    CASE 
      WHEN v_playbook.auto_execute AND NOT v_playbook.requires_approval THEN 'completed'
      WHEN v_playbook.auto_approve_critical AND NEW.severity = 'critical' THEN 'completed'
      ELSE 'pending_approval' 
    END,
    v_playbook.actions, NOW(), NOW()
  );

  UPDATE soar_playbooks 
  SET last_triggered_at = NOW(), execution_count = COALESCE(execution_count, 0) + 1 
  WHERE id = v_playbook.id;

  IF (v_playbook.auto_execute AND NOT v_playbook.requires_approval) OR
     (v_playbook.auto_approve_critical AND NEW.severity = 'critical') THEN
    UPDATE soar_executions SET completed_at = NOW() WHERE id = v_execution_id;
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'SOAR trigger error for alert %: % (SQLSTATE: %)', NEW.id, SQLERRM, SQLSTATE;
  RETURN NEW;
END;
$$;


--
-- Name: submit_agent_evidence(uuid, uuid, text, text, text, jsonb, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_agent_evidence(p_tenant_id uuid, p_agent_id uuid, p_agent_name text, p_agent_version text, p_event_type text, p_event_data jsonb, p_evidence_hash text, p_state_before text DEFAULT NULL::text, p_state_after text DEFAULT NULL::text, p_severity text DEFAULT 'info'::text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_id UUID;
BEGIN
    INSERT INTO agent_evidence_logs (
        tenant_id, agent_id, agent_name, agent_version,
        event_type, event_data, evidence_hash,
        state_before, state_after, severity
    ) VALUES (
        p_tenant_id, p_agent_id, p_agent_name, p_agent_version,
        p_event_type, p_event_data, p_evidence_hash,
        p_state_before, p_state_after, p_severity
    )
    RETURNING id INTO v_id;
    
    RETURN v_id;
END;
$$;


--
-- Name: submit_alert_feedback(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_alert_feedback(p_alert_id uuid, p_tenant_id uuid, p_user_id uuid, p_is_true_positive boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rule_id UUID;
  v_feedback TEXT;
BEGIN
  v_feedback := CASE WHEN p_is_true_positive THEN 'true_positive' ELSE 'false_positive' END;

  -- Update alert feedback
  UPDATE public.system_alerts
  SET feedback = v_feedback,
      feedback_by = p_user_id,
      feedback_at = now(),
      human_reviewed = true,
      reviewed_by = p_user_id,
      reviewed_at = now()
  WHERE id = p_alert_id
    AND tenant_id = p_tenant_id
  RETURNING detection_rule_id INTO v_rule_id;

  -- If linked to a detection rule, update its counters
  IF v_rule_id IS NOT NULL THEN
    IF p_is_true_positive THEN
      UPDATE public.detection_rules
      SET true_positive_count = true_positive_count + 1,
          last_triggered_at = now(),
          updated_at = now()
      WHERE id = v_rule_id
        AND (tenant_id = p_tenant_id OR tenant_id IS NULL);
    ELSE
      UPDATE public.detection_rules
      SET false_positive_count = false_positive_count + 1,
          last_triggered_at = now(),
          updated_at = now()
      WHERE id = v_rule_id
        AND (tenant_id = p_tenant_id OR tenant_id IS NULL);
    END IF;

    -- Recalculate risk_score for the specific rule
    UPDATE public.detection_rules
    SET risk_score = ROUND((
      (CASE severity
        WHEN 'critical' THEN 10 WHEN 'high' THEN 7 WHEN 'medium' THEN 4 WHEN 'low' THEN 1 ELSE 0
      END) * 0.4
      + CASE WHEN (true_positive_count + false_positive_count) > 0
          THEN (true_positive_count::NUMERIC / (true_positive_count + false_positive_count)) * 6
          ELSE 3 END * 0.3
      - CASE WHEN (true_positive_count + false_positive_count) > 0
          THEN (false_positive_count::NUMERIC / (true_positive_count + false_positive_count)) * 6
          ELSE 0 END * 0.3
    )::NUMERIC, 2)
    WHERE id = v_rule_id
      AND (tenant_id = p_tenant_id OR tenant_id IS NULL);
  END IF;
END;
$$;


--
-- Name: submit_approval(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_approval(p_request_id uuid, p_decision text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_request RECORD;
  v_approval_count INTEGER;
  v_user_id UUID;
  v_tenant_id UUID;
  v_already_voted BOOLEAN;
BEGIN
  v_user_id := auth.uid();
  
  -- Verificar se usuário está autenticado
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
  END IF;
  
  -- Buscar request
  SELECT * INTO v_request FROM approval_requests WHERE id = p_request_id;
  
  IF v_request IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Request not found');
  END IF;
  
  -- Verificar se usuário tem permissão no tenant
  SELECT tenant_id INTO v_tenant_id FROM user_roles 
  WHERE user_id = v_user_id AND tenant_id = v_request.tenant_id AND role IN ('admin', 'super_admin')
  LIMIT 1;
  
  IF v_tenant_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Forbidden: insufficient permissions');
  END IF;
  
  -- Verificar se request ainda está pendente
  IF v_request.status != 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Request is no longer pending', 'status', v_request.status);
  END IF;
  
  -- Verificar se não expirou
  IF v_request.expires_at < NOW() THEN
    UPDATE approval_requests SET status = 'expired' WHERE id = p_request_id;
    RETURN jsonb_build_object('success', false, 'error', 'Request has expired');
  END IF;
  
  -- Verificar se é o mesmo usuário que criou (não pode aprovar própria request)
  IF v_request.requested_by = v_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot approve your own request');
  END IF;
  
  -- Verificar se já votou
  SELECT EXISTS(SELECT 1 FROM approvals WHERE request_id = p_request_id AND approved_by = v_user_id) INTO v_already_voted;
  
  IF v_already_voted THEN
    RETURN jsonb_build_object('success', false, 'error', 'Already voted on this request');
  END IF;
  
  -- Registrar aprovação
  INSERT INTO approvals (request_id, approved_by, decision, reason)
  VALUES (p_request_id, v_user_id, p_decision, p_reason);
  
  -- Se rejeitado, marcar request como rejeitada
  IF p_decision = 'rejected' THEN
    UPDATE approval_requests 
    SET status = 'rejected', rejection_reason = p_reason
    WHERE id = p_request_id;
    
    -- Log no risk_decision_log
    INSERT INTO risk_decision_log (tenant_id, decision_type, trigger_source, trigger_id, decision, reasoning, metadata)
    VALUES (v_request.tenant_id, 'approval_rejected', 'two_man_rule', p_request_id::text, 'rejected', 
            COALESCE(p_reason, 'Rejected by admin'), 
            jsonb_build_object('rejected_by', v_user_id, 'action_type', v_request.action_type));
    
    RETURN jsonb_build_object('success', true, 'status', 'rejected', 'message', 'Request rejected');
  END IF;
  
  -- Contar aprovações
  SELECT COUNT(*) INTO v_approval_count FROM approvals WHERE request_id = p_request_id AND decision = 'approved';
  
  -- Atualizar contador
  UPDATE approval_requests SET current_approvers = v_approval_count WHERE id = p_request_id;
  
  -- Verificar se atingiu quórum
  IF v_approval_count >= v_request.required_approvers THEN
    UPDATE approval_requests 
    SET status = 'approved', approved_at = NOW()
    WHERE id = p_request_id;
    
    -- Log no risk_decision_log
    INSERT INTO risk_decision_log (tenant_id, decision_type, trigger_source, trigger_id, decision, reasoning, metadata)
    VALUES (v_request.tenant_id, 'approval_granted', 'two_man_rule', p_request_id::text, 'approved', 
            'Quorum reached: ' || v_approval_count || '/' || v_request.required_approvers || ' approvers',
            jsonb_build_object('approvers_count', v_approval_count, 'action_type', v_request.action_type));
    
    RETURN jsonb_build_object('success', true, 'status', 'approved', 'message', 'Quorum reached - action approved', 'approvers', v_approval_count);
  END IF;
  
  RETURN jsonb_build_object('success', true, 'status', 'pending', 'message', 'Vote recorded', 'current_approvers', v_approval_count, 'required', v_request.required_approvers);
END;
$$;


--
-- Name: summarize_telemetry_hourly(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.summarize_telemetry_hourly(p_tenant_id uuid, p_hours_ago integer DEFAULT 2) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_start TIMESTAMPTZ;
  v_end TIMESTAMPTZ;
  v_result JSONB := '[]'::JSONB;
BEGIN
  v_end := date_trunc('hour', now() - (p_hours_ago || ' hours')::INTERVAL);
  v_start := v_end - INTERVAL '1 hour';

  -- Summarize process events
  INSERT INTO telemetry_event_summaries (tenant_id, agent_id, event_category, summary_period, period_start, period_end, total_events, suspicious_events, top_processes, mitre_techniques)
  SELECT 
    p_tenant_id,
    agent_id,
    'process',
    'hourly',
    v_start,
    v_end,
    count(*)::INTEGER,
    count(*) FILTER (WHERE is_suspicious)::INTEGER,
    (array_agg(DISTINCT process_name ORDER BY process_name) FILTER (WHERE process_name IS NOT NULL))[1:10],
    (array_agg(DISTINCT mitre_technique_id ORDER BY mitre_technique_id) FILTER (WHERE mitre_technique_id IS NOT NULL))[1:10]
  FROM endpoint_process_events
  WHERE tenant_id = p_tenant_id AND event_time >= v_start AND event_time < v_end
  GROUP BY agent_id
  ON CONFLICT (tenant_id, agent_id, event_category, summary_period, period_start) DO NOTHING;

  -- Summarize network events
  INSERT INTO telemetry_event_summaries (tenant_id, agent_id, event_category, summary_period, period_start, period_end, total_events, suspicious_events, top_destinations)
  SELECT 
    p_tenant_id,
    agent_id,
    'network',
    'hourly',
    v_start,
    v_end,
    count(*)::INTEGER,
    count(*) FILTER (WHERE is_suspicious)::INTEGER,
    (array_agg(DISTINCT remote_address ORDER BY remote_address) FILTER (WHERE remote_address IS NOT NULL))[1:10]
  FROM endpoint_network_events
  WHERE tenant_id = p_tenant_id AND event_time >= v_start AND event_time < v_end
  GROUP BY agent_id
  ON CONFLICT (tenant_id, agent_id, event_category, summary_period, period_start) DO NOTHING;

  -- Summarize file events  
  INSERT INTO telemetry_event_summaries (tenant_id, agent_id, event_category, summary_period, period_start, period_end, total_events, suspicious_events)
  SELECT 
    p_tenant_id,
    agent_id,
    'file',
    'hourly',
    v_start,
    v_end,
    count(*)::INTEGER,
    count(*) FILTER (WHERE is_suspicious)::INTEGER
  FROM endpoint_file_events
  WHERE tenant_id = p_tenant_id AND event_time >= v_start AND event_time < v_end
  GROUP BY agent_id
  ON CONFLICT (tenant_id, agent_id, event_category, summary_period, period_start) DO NOTHING;

  -- Summarize registry events
  INSERT INTO telemetry_event_summaries (tenant_id, agent_id, event_category, summary_period, period_start, period_end, total_events, suspicious_events, mitre_techniques)
  SELECT 
    p_tenant_id,
    agent_id,
    'registry',
    'hourly',
    v_start,
    v_end,
    count(*)::INTEGER,
    count(*) FILTER (WHERE is_suspicious)::INTEGER,
    (array_agg(DISTINCT mitre_technique_id ORDER BY mitre_technique_id) FILTER (WHERE mitre_technique_id IS NOT NULL))[1:10]
  FROM endpoint_registry_events
  WHERE tenant_id = p_tenant_id AND event_time >= v_start AND event_time < v_end
  GROUP BY agent_id
  ON CONFLICT (tenant_id, agent_id, event_category, summary_period, period_start) DO NOTHING;

  RETURN jsonb_build_object('summarized', true, 'period_start', v_start, 'period_end', v_end);
END;
$$;


--
-- Name: switch_tenant_atomic(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.switch_tenant_atomic(p_user_id uuid, p_new_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_has_access boolean;
  v_all_tenants uuid[];
  v_is_super_admin boolean;
  v_role_record record;
BEGIN
  -- 1. Atomic verification of access (uses SELECT FOR UPDATE to prevent race conditions)
  -- This locks the relevant rows during the transaction, preventing TOCTOU attacks
  SELECT EXISTS(
    SELECT 1 FROM public.user_roles
    WHERE user_id = p_user_id 
    AND tenant_id = p_new_tenant_id
    FOR UPDATE NOWAIT
  ) INTO v_has_access;
  
  IF NOT v_has_access THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'TENANT_ACCESS_DENIED',
      'message', 'User does not have access to the requested tenant'
    );
  END IF;
  
  -- 2. Collect all tenants and check for super_admin role atomically
  SELECT 
    ARRAY_AGG(DISTINCT tenant_id),
    BOOL_OR(role = 'super_admin')
  INTO v_all_tenants, v_is_super_admin
  FROM public.user_roles
  WHERE user_id = p_user_id;
  
  -- 3. Return success with all data needed for metadata update
  -- The edge function will use this to update app_metadata atomically
  RETURN jsonb_build_object(
    'success', true,
    'active_tenant_id', p_new_tenant_id,
    'tenants', v_all_tenants,
    'is_super_admin', COALESCE(v_is_super_admin, false),
    'tenant_count', COALESCE(array_length(v_all_tenants, 1), 0)
  );
  
EXCEPTION
  WHEN lock_not_available THEN
    -- Another process is modifying user roles - retry
    RETURN jsonb_build_object(
      'success', false,
      'error', 'CONCURRENT_MODIFICATION',
      'message', 'Tenant access is being modified. Please retry.'
    );
END;
$$;


--
-- Name: FUNCTION switch_tenant_atomic(p_user_id uuid, p_new_tenant_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.switch_tenant_atomic(p_user_id uuid, p_new_tenant_id uuid) IS 'ADR-026: Atomic tenant switch verification. Eliminates race condition between access check and metadata update by using row-level locking. Only callable by service_role.';


--
-- Name: sync_agent_state_from_heartbeat(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_agent_state_from_heartbeat() RETURNS TABLE(updated_count bigint, updated_ids uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_updated_count BIGINT := 0;
  v_updated_ids UUID[] := ARRAY[]::UUID[];
BEGIN
  WITH updated AS (
    UPDATE agents SET 
      agent_state = 'offline',
      agent_state_reason = 'Sem heartbeat há mais de 2 horas (sync automático)',
      agent_state_changed_at = NOW(),
      offline_reason = 'heartbeat_timeout',
      offline_detected_at = COALESCE(offline_detected_at, NOW())
    WHERE archived_at IS NULL
      AND agent_state NOT IN ('offline', 'archived', 'decommissioned')
      AND last_heartbeat < NOW() - INTERVAL '2 hours'
    RETURNING id
  )
  SELECT COUNT(*), ARRAY_AGG(id) INTO v_updated_count, v_updated_ids FROM updated;
  RETURN QUERY SELECT v_updated_count, COALESCE(v_updated_ids, ARRAY[]::UUID[]);
END;
$$;


--
-- Name: sync_agent_status_from_heartbeat(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_agent_status_from_heartbeat() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  offline_threshold INTERVAL := INTERVAL '2 minutes';
  updated_count INTEGER := 0;
BEGIN
  -- Marcar como offline agentes sem heartbeat há mais de 2 minutos
  UPDATE agents
  SET 
    status = 'offline',
    offline_detected_at = COALESCE(offline_detected_at, NOW()),
    offline_reason = COALESCE(offline_reason, 'Sem heartbeat por mais de 2 minutos')
  WHERE 
    status = 'active'
    AND archived_at IS NULL
    AND (
      last_heartbeat IS NULL 
      OR last_heartbeat < NOW() - offline_threshold
    );
  
  GET DIAGNOSTICS updated_count = ROW_COUNT;
  IF updated_count > 0 THEN
    RAISE NOTICE 'Marked % agents as offline', updated_count;
  END IF;
  
  -- Marcar como active agentes com heartbeat recente
  UPDATE agents
  SET 
    status = 'active',
    offline_detected_at = NULL,
    offline_reason = NULL
  WHERE 
    status = 'offline'
    AND archived_at IS NULL
    AND last_heartbeat IS NOT NULL
    AND last_heartbeat >= NOW() - offline_threshold;
    
  GET DIAGNOSTICS updated_count = ROW_COUNT;
  IF updated_count > 0 THEN
    RAISE NOTICE 'Marked % agents as active', updated_count;
  END IF;
END;
$$;


--
-- Name: FUNCTION sync_agent_status_from_heartbeat(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_agent_status_from_heartbeat() IS 'Sincroniza o status dos agentes baseado no last_heartbeat. Agentes sem heartbeat há mais de 2 minutos são marcados como offline.';


--
-- Name: sync_blocked_to_enforcement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_blocked_to_enforcement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_valid_policy_id uuid;
BEGIN
  -- Verificar se policy_id existe antes de usar
  SELECT id INTO v_valid_policy_id 
  FROM security_policies 
  WHERE id = NEW.policy_id;

  INSERT INTO policy_enforcement_logs (
    tenant_id, agent_id, policy_id,
    rule_type, action_taken, target, blocked, details, created_at
  ) VALUES (
    NEW.tenant_id, NEW.agent_id, v_valid_policy_id,
    'website_block', 'blocked', NEW.domain, true,
    jsonb_build_object('blocked_by', NEW.blocked_by, 'source', 'auto_sync'),
    NEW.attempted_at
  )
  ON CONFLICT DO NOTHING;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$;


--
-- Name: sync_execution_on_job_finalize(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_execution_on_job_finalize() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Se job está sendo finalizado (transição para estado terminal)
  IF OLD.status NOT IN ('completed', 'failed', 'cancelled', 'done')
     AND NEW.status IN ('completed', 'failed', 'cancelled', 'done') THEN
    
    -- Finalizar qualquer execution órfã em 'claimed'
    UPDATE job_executions
    SET 
      status = NEW.status,
      finished_at = COALESCE(finished_at, NOW()),
      error_message = CASE 
        WHEN NEW.status = 'failed' THEN COALESCE(error_message, NEW.error_message, 'Auto-synced on job finalization')
        ELSE error_message
      END
    WHERE job_id = NEW.id
      AND status = 'claimed';
    
    -- Garantir que current_execution_id seja limpo (P2.1 enforcement)
    NEW.current_execution_id := NULL;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION sync_execution_on_job_finalize(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_execution_on_job_finalize() IS 'ARCH-NULL-ROOT: Garante sincronização automática de job_executions quando job é finalizado. 
   Previne executions órfãs e limpa current_execution_id residual.';


--
-- Name: sync_pending_agents_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_pending_agents_status() RETURNS TABLE(agent_id uuid, agent_name text, old_status text, new_status text, minutes_since_enrollment integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH updated AS (
    UPDATE agents
    SET 
      status = 'offline',
      offline_reason = 'never_connected'
    WHERE 
      status = 'pending'
      AND last_heartbeat IS NULL
      AND enrolled_at IS NOT NULL
      AND enrolled_at < NOW() - INTERVAL '10 minutes'
      AND archived_at IS NULL
    RETURNING 
      id,
      agents.agent_name,
      'pending'::TEXT AS old_status,
      'offline'::TEXT AS new_status,
      EXTRACT(EPOCH FROM (NOW() - enrolled_at))::INT / 60 AS minutes_since_enrollment
  )
  SELECT 
    updated.id AS agent_id,
    updated.agent_name,
    updated.old_status,
    updated.new_status,
    updated.minutes_since_enrollment
  FROM updated;
END;
$$;


--
-- Name: FUNCTION sync_pending_agents_status(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_pending_agents_status() IS 'Atualiza automaticamente o status de agentes pending para offline se não enviaram heartbeat em 10 minutos após enrollment';


--
-- Name: sync_pgcron_health_from_run_details(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_pgcron_health_from_run_details() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rec record;
BEGIN
  FOR v_rec IN
    SELECT 
      j.jobname,
      jrd.status AS run_status,
      jrd.start_time,
      jrd.end_time,
      jrd.return_message
    FROM cron.job_run_details jrd
    JOIN cron.job j ON j.jobid = jrd.jobid
    WHERE jrd.start_time > now() - interval '10 minutes'
    ORDER BY jrd.start_time DESC
  LOOP
    IF v_rec.run_status = 'succeeded' THEN
      PERFORM update_cron_health(v_rec.jobname, true, NULL);
    ELSE
      PERFORM update_cron_health(v_rec.jobname, false, v_rec.return_message);
    END IF;
  END LOOP;
END;
$$;


--
-- Name: sync_task_on_alert_resolution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_task_on_alert_resolution() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.resolved = true
     AND COALESCE(OLD.resolved, false) = false THEN
    UPDATE public.tasks
    SET
      status = 'resolved',
      closed_at = COALESCE(NEW.resolved_at, now()),
      closed_by = NEW.resolved_by,
      closure_reason = NEW.resolution_notes,
      updated_at = now()
    WHERE
      source_type = 'system_alert'
      AND source_id = NEW.id  -- UUID = UUID, sem ::text
      AND status <> 'resolved';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION sync_task_on_alert_resolution(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_task_on_alert_resolution() IS 'Syncs task status when system alert is resolved';


--
-- Name: sync_task_on_dlq_resolution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_task_on_dlq_resolution() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
BEGIN
  IF NEW.status = 'resolved' AND COALESCE(OLD.status, '') != 'resolved' THEN
    UPDATE public.tasks
    SET
      status = 'resolved',
      closed_at = COALESCE(NEW.resolved_at, NOW()),
      closed_by = CASE 
        WHEN NEW.resolved_by IS NOT NULL AND NEW.resolved_by ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN NEW.resolved_by::uuid
        ELSE NULL
      END,
      closure_reason = COALESCE(NEW.resolution_notes, 'DLQ item resolvido'),
      updated_at = NOW()
    WHERE source_type = 'dlq'
      AND source_id = NEW.id
      AND status NOT IN ('resolved', 'closed');
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: FUNCTION sync_task_on_dlq_resolution(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_task_on_dlq_resolution() IS 'ADR-031: Sincroniza status da task quando DLQ item é resolvido';


--
-- Name: sync_task_on_insight_resolution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_task_on_insight_resolution() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Mark task as resolved
  IF NEW.status = 'resolved'
     AND COALESCE(OLD.status, '') <> 'resolved' THEN
    UPDATE tasks
    SET
      status = 'resolved',
      closed_at = COALESCE(NEW.resolved_at, now()),
      closed_by = NEW.resolved_by,
      closure_reason = COALESCE(NEW.final_outcome, 'Resolved via AI Insight'),
      updated_at = now()
    WHERE
      source_type = 'ai_insight'
      AND source_id = NEW.id
      AND status <> 'resolved';
  END IF;

  -- Mark task as in_progress on acknowledge
  IF NEW.acknowledged = true
     AND COALESCE(OLD.acknowledged, false) = false THEN
    UPDATE tasks
    SET
      status = 'in_progress',
      updated_at = now()
    WHERE
      source_type = 'ai_insight'
      AND source_id = NEW.id
      AND status = 'open';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION sync_task_on_insight_resolution(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_task_on_insight_resolution() IS 'Syncs task status when AI insight status changes (resolved/acknowledged)';


--
-- Name: sync_task_on_source_resolution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_task_on_source_resolution() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- When ai_insight is resolved
  IF TG_TABLE_NAME = 'ai_insights' AND NEW.status = 'resolved' AND (OLD.status IS NULL OR OLD.status != 'resolved') THEN
    UPDATE tasks SET 
      status = 'resolved',
      closed_at = COALESCE(NEW.resolved_at, now()),
      closed_by = NEW.resolved_by,
      closure_reason = COALESCE(NEW.final_outcome, 'Resolved via AI Insight'),
      updated_at = now()
    WHERE source_type = 'ai_insight' AND source_id = NEW.id;
  END IF;
  
  -- When ai_insight is acknowledged (mark in progress)
  IF TG_TABLE_NAME = 'ai_insights' AND NEW.acknowledged = true AND OLD.acknowledged = false THEN
    UPDATE tasks SET 
      status = 'in_progress',
      updated_at = now()
    WHERE source_type = 'ai_insight' AND source_id = NEW.id AND status = 'open';
  END IF;
  
  -- When system_alert is resolved
  IF TG_TABLE_NAME = 'system_alerts' AND NEW.resolved = true AND OLD.resolved = false THEN
    UPDATE tasks SET 
      status = 'resolved',
      closed_at = COALESCE(NEW.resolved_at, now()),
      closed_by = NEW.resolved_by,
      closure_reason = NEW.resolution_notes,
      updated_at = now()
    WHERE source_type = 'system_alert' AND source_id = NEW.id;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: test_tenant_isolation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.test_tenant_isolation() RETURNS TABLE(table_name text, has_tenant_id boolean, has_rls_enabled boolean, isolation_valid boolean, details text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    t.tablename::text as table_name,
    EXISTS (
      SELECT 1 FROM information_schema.columns c 
      WHERE c.table_schema = 'public' 
        AND c.table_name = t.tablename 
        AND c.column_name = 'tenant_id'
    ) as has_tenant_id,
    t.rowsecurity as has_rls_enabled,
    (
      EXISTS (
        SELECT 1 FROM information_schema.columns c 
        WHERE c.table_schema = 'public' 
          AND c.table_name = t.tablename 
          AND c.column_name = 'tenant_id'
      ) 
      AND t.rowsecurity = true
    ) as isolation_valid,
    CASE 
      WHEN NOT EXISTS (
        SELECT 1 FROM information_schema.columns c 
        WHERE c.table_schema = 'public' 
          AND c.table_name = t.tablename 
          AND c.column_name = 'tenant_id'
      ) THEN 'Table lacks tenant_id column'
      WHEN NOT t.rowsecurity THEN 'RLS not enabled'
      ELSE 'Isolation configured correctly'
    END as details
  FROM pg_tables t
  WHERE t.schemaname = 'public'
    AND t.tablename NOT LIKE 'pg_%'
    AND t.tablename NOT LIKE '_prisma%'
  ORDER BY isolation_valid, t.tablename;
END;
$$;


--
-- Name: trg_auto_unpause_on_version_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_auto_unpause_on_version_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Only fire when agent_version actually changes
  IF OLD.agent_version IS DISTINCT FROM NEW.agent_version
     AND NEW.scheduling_paused = true
     AND NEW.agent_version IS NOT NULL
  THEN
    -- Check if the new version matches the latest for this platform
    IF EXISTS (
      SELECT 1 FROM agent_versions
      WHERE is_latest = true
        AND platform = NEW.os_type
        AND version = NEW.agent_version
    ) THEN
      NEW.scheduling_paused := false;
      NEW.scheduling_paused_reason := NULL;
      RAISE NOTICE 'Auto-unpaused scheduling for agent % (updated to %)', NEW.agent_name, NEW.agent_version;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_automation_rule_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_automation_rule_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  next_version integer;
BEGIN
  SELECT COALESCE(MAX(version), 0) + 1 INTO next_version
  FROM automation_rule_versions
  WHERE rule_id = NEW.id;

  INSERT INTO automation_rule_versions (rule_id, tenant_id, version, config, changed_by)
  VALUES (
    NEW.id, NEW.tenant_id, next_version,
    jsonb_build_object(
      'name', NEW.name, 'trigger_type', NEW.trigger_type,
      'trigger_conditions', NEW.trigger_conditions,
      'action_type', NEW.action_type, 'action_config', NEW.action_config,
      'target_scope', NEW.target_scope, 'cooldown_minutes', NEW.cooldown_minutes,
      'priority', NEW.priority, 'mode', NEW.mode,
      'max_executions_per_hour', NEW.max_executions_per_hour,
      'circuit_breaker_threshold', NEW.circuit_breaker_threshold,
      'max_affected_percentage', NEW.max_affected_percentage,
      'requires_approval', NEW.requires_approval, 'dry_run', NEW.dry_run
    ),
    NEW.created_by
  );
  RETURN NEW;
END;
$$;


--
-- Name: trg_decision_event_from_ai_action(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_decision_event_from_ai_action() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Evitar duplicação
  IF EXISTS (SELECT 1 FROM decision_events WHERE evidence->>'action_id' = NEW.id::text) THEN
    RETURN NEW;
  END IF;
  
  INSERT INTO decision_events (tenant_id, rule_code, agent_id, agent_name, action, evidence, actions_executed)
  VALUES (
    NEW.tenant_id, 
    NEW.action_type, 
    NULL, 
    'ai_engine', 
    NEW.status,
    jsonb_build_object(
      'action_id', NEW.id, 
      'insight_id', NEW.insight_id, 
      'error', NEW.error_message,
      'source', 'ai_action_execution'
    ),
    jsonb_build_array(jsonb_build_object('type', NEW.action_type, 'status', NEW.status))
  );
  RETURN NEW;
END;
$$;


