--
-- Name: trg_version_soar_playbook(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_version_soar_playbook() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_next_version integer;
  v_diff text;
BEGIN
  IF OLD.name = NEW.name AND OLD.trigger_type = NEW.trigger_type 
     AND OLD.trigger_conditions = NEW.trigger_conditions 
     AND OLD.actions = NEW.actions 
     AND OLD.is_active = NEW.is_active
     AND OLD.auto_execute IS NOT DISTINCT FROM NEW.auto_execute THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(max(version), 0) + 1 INTO v_next_version FROM soar_playbook_versions WHERE playbook_id = NEW.id;

  v_diff := '';
  IF OLD.name <> NEW.name THEN v_diff := v_diff || 'name; '; END IF;
  IF OLD.trigger_type <> NEW.trigger_type THEN v_diff := v_diff || 'trigger_type; '; END IF;
  IF OLD.trigger_conditions <> NEW.trigger_conditions THEN v_diff := v_diff || 'conditions; '; END IF;
  IF OLD.actions <> NEW.actions THEN v_diff := v_diff || 'actions; '; END IF;
  IF OLD.is_active <> NEW.is_active THEN v_diff := v_diff || 'is_active; '; END IF;

  INSERT INTO soar_playbook_versions (playbook_id, tenant_id, version, config_snapshot, diff_summary)
  VALUES (NEW.id, NEW.tenant_id, v_next_version,
    jsonb_build_object('name', OLD.name, 'trigger_type', OLD.trigger_type, 'trigger_conditions', OLD.trigger_conditions,
      'actions', OLD.actions, 'is_active', OLD.is_active, 'auto_execute', OLD.auto_execute,
      'requires_approval', OLD.requires_approval, 'cooldown_minutes', OLD.cooldown_minutes),
    v_diff);

  NEW.current_version := v_next_version;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: trigger_fingerprint_job_failure(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_fingerprint_job_failure() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_signature jsonb;
BEGIN
  IF NEW.status = 'failed' AND (OLD.status IS NULL OR OLD.status IS DISTINCT FROM 'failed') THEN
    v_signature := public.normalize_job_failure(NEW);
    
    PERFORM public.register_failure_occurrence(
      v_signature,
      NEW.tenant_id,
      'job',
      NEW.id,
      NEW.agent_id,
      LEFT(NEW.error_message, 500)
    );
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: trigger_playbook_evaluation_on_job_failure(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_playbook_evaluation_on_job_failure() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  job_record RECORD;
  failure_count_24h INTEGER;
BEGIN
  -- Apenas processa se o status for 'failed'
  IF NEW.status != 'failed' THEN
    RETURN NEW;
  END IF;
  
  -- Buscar informações do job
  SELECT type, tenant_id INTO job_record
  FROM jobs
  WHERE id = NEW.job_id;
  
  -- Contar falhas nas últimas 24 horas para este job
  SELECT COUNT(*) INTO failure_count_24h
  FROM job_executions
  WHERE job_id = NEW.job_id
    AND status = 'failed'
    AND created_at > NOW() - INTERVAL '24 hours';
  
  -- Inserir evento para processamento de playbook
  INSERT INTO ai_action_logs (
    tenant_id,
    action_type,
    action_data,
    status,
    created_at
  ) VALUES (
    NEW.tenant_id,
    'playbook_trigger_evaluation',
    jsonb_build_object(
      'trigger_type', 'job_failed',
      'job_execution_id', NEW.id,
      'job_id', NEW.job_id,
      'job_type', job_record.type,
      'agent_id', NEW.agent_id,
      'failure_count_24h', failure_count_24h,
      'error_message', NEW.error_message,
      'evaluated_at', NOW()
    ),
    'pending',
    NOW()
  );
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION trigger_playbook_evaluation_on_job_failure(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trigger_playbook_evaluation_on_job_failure() IS 'Trigger que registra eventos de falha de job para avaliação de playbooks automatizada';


--
-- Name: trigger_playbook_on_multiple_dns_blocks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_playbook_on_multiple_dns_blocks() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_blocked_count INTEGER;
  v_tenant_id UUID;
  v_existing_pending INTEGER;
BEGIN
  -- Só processar bloqueios
  IF NOT NEW.is_blocked THEN
    RETURN NEW;
  END IF;
  
  -- Contar bloqueios na última hora para este agente
  SELECT COUNT(*) INTO v_blocked_count
  FROM agent_web_activity aw
  WHERE aw.agent_id = NEW.agent_id
    AND aw.is_blocked = true
    AND aw.created_at > NOW() - INTERVAL '1 hour';
  
  -- Buscar tenant do agente
  SELECT a.tenant_id INTO v_tenant_id
  FROM agents a
  WHERE a.id = NEW.agent_id;
  
  -- Se não atingiu threshold, retornar
  IF v_blocked_count < 10 OR v_tenant_id IS NULL THEN
    RETURN NEW;
  END IF;
  
  -- Anti-loop: Verificar se já existe evento pendente para este agente nas últimas 2 horas
  SELECT COUNT(*) INTO v_existing_pending
  FROM ai_action_logs
  WHERE tenant_id = v_tenant_id
    AND action_type = 'playbook_trigger_evaluation'
    AND status IN ('pending', 'processing')
    AND action_data->>'trigger_type' = 'dns_blocked'
    AND action_data->>'agent_id' = NEW.agent_id::text
    AND created_at > NOW() - INTERVAL '2 hours';
  
  IF v_existing_pending > 0 THEN
    RETURN NEW; -- Já existe evento pendente, não criar duplicado
  END IF;
  
  -- Criar evento para playbook
  INSERT INTO ai_action_logs (
    tenant_id,
    action_type,
    action_data,
    status
  ) VALUES (
    v_tenant_id,
    'playbook_trigger_evaluation',
    jsonb_build_object(
      'trigger_type', 'dns_blocked',
      'agent_id', NEW.agent_id,
      'blocked_count', v_blocked_count,
      'time_window_hours', 1,
      'latest_domain', NEW.domain,
      'category', NEW.category,
      'created_by_trigger', 'tr_playbook_on_dns_blocks'
    ),
    'pending'
  );
  
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Não falhar a inserção por causa do trigger
  RAISE WARNING 'trigger_playbook_on_multiple_dns_blocks failed: %', SQLERRM;
  RETURN NEW;
END;
$$;


