--
-- Name: update_cron_health(text, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_cron_health(p_cron_name text, p_success boolean, p_details jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.cron_health (cron_name, last_success_at, total_runs, metadata)
  VALUES (p_cron_name, CASE WHEN p_success THEN now() ELSE NULL END, 1, p_details)
  ON CONFLICT (cron_name) DO UPDATE SET
    last_success_at = CASE WHEN p_success THEN now() ELSE cron_health.last_success_at END,
    last_failure_at = CASE WHEN NOT p_success THEN now() ELSE cron_health.last_failure_at END,
    last_error = CASE WHEN NOT p_success THEN p_details->>'error' ELSE cron_health.last_error END,
    consecutive_failures = CASE 
      WHEN p_success THEN 0 
      ELSE cron_health.consecutive_failures + 1 
    END,
    total_runs = cron_health.total_runs + 1,
    total_failures = CASE WHEN NOT p_success THEN cron_health.total_failures + 1 ELSE cron_health.total_failures END,
    metadata = p_details,
    updated_at = now();
END;
$$;


--
-- Name: update_cron_health(text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_cron_health(p_cron_name text, p_success boolean, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO cron_health_checks (cron_name, last_success_at, last_failure_at, last_error, consecutive_failures, updated_at)
  VALUES (
    p_cron_name,
    CASE WHEN p_success THEN NOW() ELSE NULL END,
    CASE WHEN NOT p_success THEN NOW() ELSE NULL END,
    p_error,
    CASE WHEN p_success THEN 0 ELSE 1 END,
    NOW()
  )
  ON CONFLICT (cron_name) DO UPDATE SET
    last_success_at = CASE WHEN p_success THEN NOW() ELSE cron_health_checks.last_success_at END,
    last_failure_at = CASE WHEN NOT p_success THEN NOW() ELSE cron_health_checks.last_failure_at END,
    last_error = CASE WHEN NOT p_success THEN p_error ELSE cron_health_checks.last_error END,
    consecutive_failures = CASE 
      WHEN p_success THEN 0 
      ELSE cron_health_checks.consecutive_failures + 1 
    END,
    updated_at = NOW();
END;
$$;


--
-- Name: update_enrollment_key_on_agent_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_enrollment_key_on_agent_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Atualizar enrollment_keys quando um agente é criado
  UPDATE public.enrollment_keys
  SET 
    current_uses = current_uses + 1,
    used_by_agent = NEW.agent_name,
    used_at = NOW()
  WHERE agent_id = NEW.id
    AND used_by_agent IS NULL;
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION update_enrollment_key_on_agent_insert(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_enrollment_key_on_agent_insert() IS 'Automatically updates enrollment key usage when an agent is inserted';


--
-- Name: update_enrollment_key_usage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_enrollment_key_usage() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Encontrar a enrollment key usada por este agente e marcar como usada
  UPDATE public.enrollment_keys
  SET 
    used_by_agent = NEW.agent_name,
    used_at = COALESCE(used_at, NOW()),
    current_uses = current_uses + 1
  WHERE id IN (
    SELECT ek.id 
    FROM public.enrollment_keys ek
    WHERE ek.tenant_id = NEW.tenant_id
      AND ek.is_active = true
      AND ek.used_by_agent IS NULL
      AND ek.expires_at > NOW()
    ORDER BY ek.created_at DESC
    LIMIT 1
  );
  
  RETURN NEW;
END;
$$;


--
-- Name: update_job_heartbeat(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_job_heartbeat(p_job_key text, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO scheduled_job_heartbeat (job_key, last_seen_at, last_error, updated_at)
  VALUES (p_job_key, now(), p_error, now())
  ON CONFLICT (job_key) DO UPDATE SET
    last_seen_at = now(),
    missed_count = CASE WHEN p_error IS NULL THEN 0 ELSE scheduled_job_heartbeat.missed_count + 1 END,
    last_error = p_error,
    updated_at = now();
END;
$$;


--
-- Name: update_offline_agent_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_offline_agent_status() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  inactive_count integer := 0;
  result jsonb;
BEGIN
  -- Marcar agentes offline há >2h como inactive (trigger derivará agent_state)
  UPDATE agents 
  SET 
    status = 'inactive',
    offline_reason = COALESCE(offline_reason, 'Auto-detected: No heartbeat >2h'),
    offline_detected_at = COALESCE(offline_detected_at, NOW())
  WHERE status = 'active'
    AND archived_at IS NULL
    AND last_heartbeat < NOW() - INTERVAL '2 hours';
  
  GET DIAGNOSTICS inactive_count = ROW_COUNT;
  
  result := jsonb_build_object(
    'success', true,
    'agents_set_inactive', inactive_count,
    'executed_at', NOW()
  );
  
  -- Reportar para cron_health_checks
  INSERT INTO cron_health_checks (cron_name, last_success_at, consecutive_failures, updated_at, last_result)
  VALUES ('update-offline-agent-status', NOW(), 0, NOW(), result)
  ON CONFLICT (cron_name) DO UPDATE SET
    last_success_at = NOW(),
    consecutive_failures = 0,
    last_error = NULL,
    updated_at = NOW(),
    last_result = EXCLUDED.last_result;
  
  RETURN result;
  
EXCEPTION WHEN OTHERS THEN
  INSERT INTO cron_health_checks (cron_name, last_failure_at, last_error, consecutive_failures, updated_at)
  VALUES ('update-offline-agent-status', NOW(), SQLERRM, 1, NOW())
  ON CONFLICT (cron_name) DO UPDATE SET
    last_failure_at = NOW(),
    last_error = SQLERRM,
    consecutive_failures = cron_health_checks.consecutive_failures + 1,
    updated_at = NOW();
  RAISE;
END;
$$;


--
-- Name: FUNCTION update_offline_agent_status(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_offline_agent_status() IS 'Atualiza status de agentes offline há >2h para inactive';


