CREATE FUNCTION public.update_quota_usage(p_tenant_id uuid, p_feature_key text, p_delta integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  -- Atualizar ou criar feature com quota
  INSERT INTO public.tenant_features (tenant_id, feature_key, enabled, quota_used, quota_limit)
  VALUES (p_tenant_id, p_feature_key, true, GREATEST(0, p_delta), NULL)
  ON CONFLICT (tenant_id, feature_key) 
  DO UPDATE SET 
    quota_used = GREATEST(0, tenant_features.quota_used + p_delta),
    updated_at = now();
END;
$$;


--
-- Name: update_session_activity(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_session_activity(_session_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _is_super_admin BOOLEAN;
  _timeout_minutes INTEGER;
BEGIN
  SELECT is_super_admin INTO _is_super_admin
  FROM active_sessions WHERE id = _session_id;
  
  _timeout_minutes := CASE WHEN _is_super_admin THEN 15 ELSE 480 END;

  UPDATE active_sessions 
  SET last_activity_at = now(),
      expires_at = now() + (_timeout_minutes || ' minutes')::interval
  WHERE id = _session_id
    AND user_id = auth.uid();
END;
$$;


