--
-- Name: update_tenant_activity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_tenant_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
BEGIN
  -- Extract tenant_id from the row
  IF TG_TABLE_NAME = 'agents' THEN
    v_tenant_id := NEW.tenant_id;
  ELSIF TG_TABLE_NAME = 'system_alerts' THEN
    v_tenant_id := NEW.tenant_id;
  ELSIF TG_TABLE_NAME = 'scheduled_jobs' THEN
    v_tenant_id := NEW.tenant_id;
  ELSE
    v_tenant_id := NEW.tenant_id;
  END IF;

  IF v_tenant_id IS NOT NULL THEN
    UPDATE public.tenants 
    SET last_activity_at = now()
    WHERE id = v_tenant_id 
      AND (last_activity_at IS NULL OR last_activity_at < now() - INTERVAL '1 hour');
  END IF;

  RETURN NEW;
END;
$$;


