--
-- Name: update_user_role(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_role(p_user_id uuid, p_role text, p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_id uuid;
  v_caller_tenant uuid;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'NOT_AUTHENTICATED');
  END IF;

  v_caller_tenant := get_active_tenant_id();
  IF v_caller_tenant IS NULL OR v_caller_tenant != p_tenant_id THEN
    PERFORM log_security_violation(p_tenant_id, v_caller_id, 'internal', 'update_user_role', 'cross_tenant_privilege_escalation', 'critical',
      jsonb_build_object('target_user', p_user_id, 'target_role', p_role, 'caller_tenant', v_caller_tenant));
    RETURN jsonb_build_object('success', false, 'error', 'TENANT_MISMATCH');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM user_roles WHERE user_id = v_caller_id AND tenant_id = p_tenant_id AND role IN ('admin', 'super_admin')) THEN
    PERFORM log_security_violation(p_tenant_id, v_caller_id, 'internal', 'update_user_role', 'privilege_escalation_attempt', 'high',
      jsonb_build_object('target_user', p_user_id, 'target_role', p_role));
    RETURN jsonb_build_object('success', false, 'error', 'INSUFFICIENT_PRIVILEGES');
  END IF;

  IF v_caller_id = p_user_id AND p_role = 'super_admin' THEN
    RETURN jsonb_build_object('success', false, 'error', 'SELF_ESCALATION_BLOCKED');
  END IF;

  INSERT INTO user_roles (user_id, role, tenant_id)
  VALUES (p_user_id, p_role::app_role, p_tenant_id)
  ON CONFLICT (user_id, tenant_id) DO UPDATE SET role = p_role::app_role;

  RETURN jsonb_build_object('success', true, 'user_id', p_user_id, 'new_role', p_role);
END;
$$;


--
-- Name: update_user_role(uuid, public.app_role, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_role(_target_user_id uuid, _new_role public.app_role, _requester_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  requester_role app_role;
  actual_requester_id UUID;
BEGIN
  -- Usar auth.uid() se requester_id não fornecido
  actual_requester_id := COALESCE(_requester_id, auth.uid());
  
  -- Buscar role do requisitante
  SELECT role INTO requester_role 
  FROM user_roles 
  WHERE user_id = actual_requester_id
  LIMIT 1;
  
  -- Analyst NÃO pode alterar roles
  IF requester_role = 'analyst' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Analyst role cannot modify user roles',
      'code', 'ANALYST_DENIED'
    );
  END IF;
  
  -- Viewer NÃO pode alterar roles
  IF requester_role = 'viewer' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Viewer role cannot modify user roles',
      'code', 'VIEWER_DENIED'
    );
  END IF;
  
  -- Operator NÃO pode alterar roles
  IF requester_role = 'operator' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Operator role cannot modify user roles',
      'code', 'OPERATOR_DENIED'
    );
  END IF;
  
  -- Apenas admin e super_admin podem prosseguir
  IF requester_role NOT IN ('admin', 'super_admin') THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Insufficient permissions to modify roles',
      'code', 'INSUFFICIENT_PERMISSIONS'
    );
  END IF;
  
  -- Admin não pode criar super_admin
  IF requester_role = 'admin' AND _new_role = 'super_admin' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Admin cannot assign super_admin role',
      'code', 'ESCALATION_DENIED'
    );
  END IF;
  
  -- Atualizar role
  UPDATE user_roles 
  SET role = _new_role,
      updated_at = NOW()
  WHERE user_id = _target_user_id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'User role not found',
      'code', 'NOT_FOUND'
    );
  END IF;
  
  RETURN jsonb_build_object(
    'success', true,
    'new_role', _new_role::text
  );
END;
$$;


--
-- Name: update_user_role_rpc(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_role_rpc(p_user_id uuid, p_new_role text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor_tenant_id uuid;
  v_target_tenant_id uuid;
  v_current_role text;
  v_admin_count integer;
BEGIN
  -- PATCH #3: Use active_tenant_id from JWT (not arbitrary LIMIT 1)
  SELECT tenant_id
  INTO v_actor_tenant_id
  FROM public.user_roles
  WHERE user_id = auth.uid()
    AND role = 'admin'
    AND tenant_id = public.get_active_tenant_id();

  IF v_actor_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: user is not admin of active tenant';
  END IF;

  -- Prevent self-role change
  IF p_user_id = auth.uid() THEN
    RAISE EXCEPTION 'Cannot change own role';
  END IF;

  -- Verify target user is in same tenant
  SELECT tenant_id, role::text
  INTO v_target_tenant_id, v_current_role
  FROM public.user_roles
  WHERE user_id = p_user_id
    AND tenant_id = v_actor_tenant_id;

  IF v_target_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Target user not in same tenant';
  END IF;

  -- Prevent removing last admin
  IF v_current_role = 'admin' AND p_new_role != 'admin' THEN
    SELECT COUNT(*)
    INTO v_admin_count
    FROM public.user_roles
    WHERE tenant_id = v_actor_tenant_id
      AND role = 'admin';

    IF v_admin_count <= 1 THEN
      RAISE EXCEPTION 'Cannot remove last admin from tenant';
    END IF;
  END IF;

  -- Update role atomically
  UPDATE public.user_roles
  SET role = p_new_role::app_role,
      updated_at = now()
  WHERE user_id = p_user_id
    AND tenant_id = v_actor_tenant_id;
END;
$$;


--
-- Name: FUNCTION update_user_role_rpc(p_user_id uuid, p_new_role text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_user_role_rpc(p_user_id uuid, p_new_role text) IS 'ADR-026: Secure role update with active tenant validation - eliminates multi-tenant bypass';


