--
-- Name: validate_agent_release_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_agent_release_integrity() RETURNS TABLE(release_id uuid, version text, channel text, platform text, is_valid boolean, validation_notes text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    ar.id AS release_id,
    ar.version,
    ar.channel,
    ar.platform,
    CASE
      WHEN ar.sha256 IS NULL OR LENGTH(ar.sha256) != 64 THEN false
      WHEN ar.script_content IS NULL OR LENGTH(ar.script_content) < 100 THEN false
      ELSE true
    END AS is_valid,
    CASE
      WHEN ar.sha256 IS NULL THEN 'Missing SHA256 hash'::text
      WHEN LENGTH(ar.sha256) != 64 THEN 'Invalid SHA256 length'::text
      WHEN ar.script_content IS NULL THEN 'Missing script content'::text
      WHEN LENGTH(ar.script_content) < 100 THEN 'Script content too small'::text
      ELSE 'OK'::text
    END AS validation_notes
  FROM agent_releases ar
  WHERE ar.is_active = true
  ORDER BY ar.created_at DESC;
END;
$$;


--
-- Name: FUNCTION validate_agent_release_integrity(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.validate_agent_release_integrity() IS 'Valida integridade das releases de agentes';


--
-- Name: validate_audit_trail_integrity(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_audit_trail_integrity(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
  orphan_count integer;
  exec_no_audit integer;
  dec_no_insight integer;
  total_actions integer;
  score numeric;
BEGIN
  SELECT count(*) INTO orphan_count FROM ai_actions WHERE tenant_id = p_tenant_id AND decision_event_id IS NULL;
  SELECT count(*) INTO exec_no_audit FROM ai_action_executions e WHERE e.tenant_id = p_tenant_id
    AND NOT EXISTS (SELECT 1 FROM ai_action_logs l WHERE l.tenant_id = p_tenant_id AND l.created_at >= e.created_at - interval '1 minute' AND l.created_at <= e.created_at + interval '1 minute');
  SELECT count(*) INTO dec_no_insight FROM decision_events d WHERE d.tenant_id = p_tenant_id AND d.agent_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM ai_insights i WHERE i.tenant_id = p_tenant_id AND i.agent_id = d.agent_id AND i.created_at >= d.created_at - interval '5 minutes' AND i.created_at <= d.created_at + interval '5 minutes');
  SELECT count(*) INTO total_actions FROM ai_actions WHERE tenant_id = p_tenant_id;
  IF total_actions = 0 THEN score := 100;
  ELSE score := greatest(0, round(100 - (orphan_count::numeric / greatest(total_actions, 1) * 50) - (exec_no_audit * 2) - (dec_no_insight * 1), 1));
  END IF;
  SELECT jsonb_build_object(
    'orphan_actions', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', id, 'action_type', action_type, 'created_at', created_at))
       FROM (SELECT id, action_type, created_at FROM ai_actions WHERE tenant_id = p_tenant_id AND decision_event_id IS NULL ORDER BY created_at DESC LIMIT 10) sub), '[]'::jsonb),
    'orphan_actions_count', orphan_count,
    'executions_without_audit', exec_no_audit,
    'decisions_without_insight', dec_no_insight,
    'integrity_score', score
  ) INTO result;
  RETURN result;
END;
$$;


--
-- Name: validate_blast_radius(uuid, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_blast_radius(p_tenant_id uuid, p_action_type text, p_target_agent_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_policy RECORD;
  v_total INTEGER;
  v_affected INTEGER;
  v_percent NUMERIC;
  v_decision TEXT;
  v_reason TEXT;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  SELECT COUNT(*) INTO v_total FROM agents WHERE tenant_id = p_tenant_id AND status = 'active';
  v_affected := COALESCE(array_length(p_target_agent_ids, 1), 0);
  v_percent := CASE WHEN v_total > 0 THEN (v_affected::NUMERIC / v_total) * 100 ELSE 0 END;
  
  SELECT * INTO v_policy FROM blast_radius_policies
  WHERE tenant_id = p_tenant_id AND action_type = p_action_type AND is_active = true;
  
  IF NOT FOUND THEN
    v_policy.max_affected_percent := 10.00;
    v_policy.max_affected_count := 10;
    v_policy.require_approval_above := 5.00;
  END IF;
  
  IF v_percent > v_policy.max_affected_percent THEN
    v_decision := 'blocked'; v_reason := 'Exceeds max percent';
  ELSIF v_policy.max_affected_count IS NOT NULL AND v_affected > v_policy.max_affected_count THEN
    v_decision := 'blocked'; v_reason := 'Exceeds max count';
  ELSIF v_percent >= v_policy.require_approval_above THEN
    v_decision := 'requires_approval'; v_reason := 'Requires approval';
  ELSE
    v_decision := 'allowed'; v_reason := 'Within limits';
  END IF;
  
  INSERT INTO risk_decision_log (tenant_id, event_type, decision, decision_reason, context)
  VALUES (p_tenant_id, 'blast_radius', v_decision, v_reason, jsonb_build_object(
    'action', p_action_type, 'affected', v_affected, 'total', v_total, 'percent', v_percent
  ));
  
  RETURN jsonb_build_object(
    'decision', v_decision, 'allowed', v_decision != 'blocked',
    'requires_approval', v_decision = 'requires_approval',
    'affected_percent', ROUND(v_percent, 2), 'reason', v_reason
  );
END;
$$;


--
-- Name: validate_drift_severity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_drift_severity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NEW.severity NOT IN ('low', 'medium', 'high', 'critical') THEN
        RAISE EXCEPTION 'Invalid severity: %. Must be low, medium, high, or critical', NEW.severity;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_enrollment_key_by_hash(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_enrollment_key_by_hash(p_key_hash text) RETURNS TABLE(id uuid, tenant_id uuid, agent_id uuid, expires_at timestamp with time zone, max_uses integer, current_uses integer, is_active boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    ek.id,
    ek.tenant_id,
    ek.agent_id,
    ek.expires_at,
    ek.max_uses,
    ek.current_uses,
    ek.is_active
  FROM public.enrollment_keys ek
  WHERE ek.key_hash = p_key_hash
    AND ek.is_active = true
    AND ek.expires_at > NOW()
  ORDER BY ek.created_at DESC
  LIMIT 1;
END;
$$;


--
-- Name: validate_governance_coverage(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_governance_coverage(tenant_uuid uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
  alerts_uncovered integer := 0;
  insights_uncovered integer := 0;
  orphan_critical integer := 0;
  is_compliant boolean;
BEGIN
  SELECT count(*) INTO alerts_uncovered
  FROM public.system_alerts a
  WHERE a.severity IN ('critical', 'high')
    AND a.created_at > now() - interval '24 hours'
    AND (tenant_uuid IS NULL OR a.tenant_id = tenant_uuid)
    AND NOT EXISTS (
      SELECT 1 FROM public.tasks t
      WHERE t.source_type = 'system_alert'
        AND t.source_id = a.id::text
    );
  
  SELECT count(*) INTO insights_uncovered
  FROM public.ai_insights i
  WHERE i.severity IN ('critical', 'high')
    AND i.created_at > now() - interval '24 hours'
    AND (tenant_uuid IS NULL OR i.tenant_id = tenant_uuid)
    AND NOT EXISTS (
      SELECT 1 FROM public.tasks t
      WHERE t.source_type = 'ai_insight'
        AND t.source_id = i.id::text
    );
  
  SELECT count(*) INTO orphan_critical
  FROM public.tasks
  WHERE severity = 'critical'
    AND status IN ('open', 'in_progress')
    AND assigned_to IS NULL
    AND created_at < now() - interval '2 hours'
    AND (tenant_uuid IS NULL OR tenant_id = tenant_uuid);
  
  is_compliant := (alerts_uncovered = 0 AND insights_uncovered = 0 AND orphan_critical = 0);
  
  result := jsonb_build_object(
    'timestamp', now(),
    'is_compliant', is_compliant,
    'alerts_uncovered', alerts_uncovered,
    'insights_uncovered', insights_uncovered,
    'orphan_critical_tasks', orphan_critical,
    'gates', jsonb_build_array(
      jsonb_build_object('gate', 'all_critical_alerts_have_tasks', 'passed', alerts_uncovered = 0, 'count', alerts_uncovered),
      jsonb_build_object('gate', 'all_critical_insights_have_tasks', 'passed', insights_uncovered = 0, 'count', insights_uncovered),
      jsonb_build_object('gate', 'all_critical_tasks_have_owner', 'passed', orphan_critical = 0, 'count', orphan_critical)
    )
  );
  
  RETURN result;
END;
$$;


--
-- Name: validate_honeypot_mode(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_honeypot_mode() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.honeypot_mode NOT IN ('none', 'native', 'flipped') THEN
    RAISE EXCEPTION 'Invalid honeypot_mode: %. Must be none, native, or flipped.', NEW.honeypot_mode;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_job_agent_name(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_job_agent_name() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agent_id UUID;
BEGIN
  -- First try matching by agent_name
  SELECT id INTO v_agent_id
  FROM public.agents
  WHERE agent_name = NEW.agent_name
    AND tenant_id = NEW.tenant_id
  LIMIT 1;
  
  -- If not found by agent_name, try matching by hostname
  IF v_agent_id IS NULL THEN
    SELECT id INTO v_agent_id
    FROM public.agents
    WHERE hostname = NEW.agent_name
      AND tenant_id = NEW.tenant_id
    LIMIT 1;
    
    -- If found by hostname, update agent_name to the registered name
    IF v_agent_id IS NOT NULL THEN
      NEW.agent_name := (SELECT agent_name FROM public.agents WHERE id = v_agent_id);
    END IF;
  END IF;
  
  -- If still not found, block INSERT
  IF v_agent_id IS NULL THEN
    RAISE EXCEPTION 'Invalid agent_name: "%" does not exist in tenant %', 
      NEW.agent_name, NEW.tenant_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  
  -- Auto-fill agent_id if NULL
  IF NEW.agent_id IS NULL THEN
    NEW.agent_id := v_agent_id;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: validate_job_type_for_agent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_job_type_for_agent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agent_version text;
  v_supported_types text[];
BEGIN
  -- Get agent version
  SELECT agent_version INTO v_agent_version
  FROM agents WHERE id = NEW.agent_id;

  -- v5.x supported types (27 handlers + integration_test_v3)
  v_supported_types := ARRAY[
    'scan', 'update_agent', 'reinstall_agent', 'report', 'config',
    'collect_info', 'software_inventory_collect', 'light_vuln_scan',
    'collect_antivirus_status', 'collect_web_activity', 'collect_network_info',
    'collect_certificates', 'collect_disk_metrics',
    'sync_blocked_websites', 'setup_dns_filter', 'collect_dns_blocks',
    'remove_dns_filter', 'fix_firewall', 'kill_process', 'stop_service',
    'disable_service', 'restart_service', 'service_health_check',
    'network_diagnostics', 'quarantine_agent', 'apply_security_patch',
    'disk_cleanup', 'integration_test_v3'
  ];

  IF NEW.type IS NOT NULL AND NOT (NEW.type = ANY(v_supported_types)) THEN
    RAISE EXCEPTION 'Job type "%" not supported by agent %. Supported: %',
      NEW.type, COALESCE(v_agent_version, 'unknown'), array_to_string(v_supported_types, ', ')
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION validate_job_type_for_agent(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.validate_job_type_for_agent() IS 'Validates job types against the complete list of supported agent v5.0.4 handlers. Synchronized with _shared/validation.ts CreateJobSchema.';


--
-- Name: verify_audit_log_chain(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_audit_log_chain(p_tenant_id uuid, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(total_logs bigint, chain_valid boolean, first_broken_at timestamp with time zone, broken_log_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_log RECORD;
  v_previous_hash TEXT := NULL;
  v_expected_hash TEXT;
  v_total BIGINT := 0;
  v_broken_at TIMESTAMP WITH TIME ZONE := NULL;
  v_broken_id UUID := NULL;
  v_chain_valid BOOLEAN := true;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  FOR v_log IN 
    SELECT * FROM audit_logs
    WHERE tenant_id = p_tenant_id
      AND (p_start_date IS NULL OR created_at >= p_start_date)
      AND (p_end_date IS NULL OR created_at <= p_end_date)
    ORDER BY created_at ASC
  LOOP
    v_total := v_total + 1;
    
    -- Skip first record (genesis)
    IF v_previous_hash IS NOT NULL THEN
      -- Verify chain
      IF v_log.previous_log_hash IS DISTINCT FROM v_previous_hash THEN
        v_chain_valid := false;
        v_broken_at := v_log.created_at;
        v_broken_id := v_log.id;
        EXIT;
      END IF;
    END IF;
    
    v_previous_hash := v_log.integrity_hash;
  END LOOP;
  
  RETURN QUERY SELECT v_total, v_chain_valid, v_broken_at, v_broken_id;
END;
$$;


--
-- Name: verify_audit_log_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_audit_log_integrity() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total integer;
  v_with_hash integer;
  v_broken integer;
BEGIN
  SELECT COUNT(*) INTO v_total FROM audit_logs;
  SELECT COUNT(*) INTO v_with_hash FROM audit_logs WHERE integrity_hash IS NOT NULL;
  
  SELECT COUNT(*) INTO v_broken
  FROM audit_logs a1
  WHERE a1.previous_log_hash IS NOT NULL 
    AND NOT EXISTS (SELECT 1 FROM audit_logs a2 WHERE a2.integrity_hash = a1.previous_log_hash);

  RETURN jsonb_build_object(
    'total_entries', v_total,
    'entries_with_hash', v_with_hash,
    'broken_chains', v_broken,
    'status', CASE WHEN v_broken = 0 THEN 'healthy' ELSE 'broken' END,
    'checked_at', now()
  );
END;
$$;


--
-- Name: verify_document_signature(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_document_signature(p_document_hash text, p_signature text) RETURNS TABLE(is_valid boolean, signed_at timestamp with time zone, document_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    true as is_valid,
    sd.signed_at,
    sd.document_name
  FROM signed_documents sd
  WHERE sd.document_hash = p_document_hash
    AND sd.signature_base64 = p_signature
    AND sd.created_at > NOW() - INTERVAL '5 years'
  LIMIT 1;
  
  -- If no matching record found, return false
  IF NOT FOUND THEN
    RETURN QUERY SELECT false as is_valid, NULL::TIMESTAMP WITH TIME ZONE, NULL::TEXT;
  END IF;
END;
$$;


--
-- Name: verify_evidence_log_chain(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_evidence_log_chain(p_tenant_id uuid, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(total_records bigint, chain_valid boolean, broken_at timestamp with time zone, broken_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_log RECORD;
  v_previous_hash TEXT := NULL;
  v_total BIGINT := 0;
  v_broken_at TIMESTAMP WITH TIME ZONE := NULL;
  v_broken_id UUID := NULL;
  v_chain_valid BOOLEAN := true;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);

  FOR v_log IN
    SELECT el.id, el.integrity_hash, el.previous_log_hash, el.created_at
    FROM agent_evidence_logs el
    WHERE el.tenant_id = p_tenant_id
      AND (p_start_date IS NULL OR el.created_at >= p_start_date)
      AND (p_end_date IS NULL OR el.created_at <= p_end_date)
    ORDER BY el.created_at ASC, el.id ASC
  LOOP
    v_total := v_total + 1;

    IF v_previous_hash IS NOT NULL THEN
      IF v_log.previous_log_hash IS DISTINCT FROM v_previous_hash THEN
        v_chain_valid := false;
        v_broken_at := v_log.created_at;
        v_broken_id := v_log.id;
        EXIT;
      END IF;
    END IF;

    v_previous_hash := v_log.integrity_hash;
  END LOOP;

  RETURN QUERY SELECT v_total, v_chain_valid, v_broken_at, v_broken_id;
END;
$$;


--
-- Name: verify_log_chain(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_log_chain(p_tenant_id uuid, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(total_logs bigint, valid_links bigint, broken_links bigint, chain_integrity_percent numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH chain AS (
    SELECT 
      al.id,
      al.integrity_hash,
      al.previous_log_hash,
      al.created_at,
      LAG(al.integrity_hash) OVER (ORDER BY al.created_at ASC, al.id ASC) as expected_prev
    FROM audit_logs al
    WHERE al.tenant_id = p_tenant_id
      AND (p_start_date IS NULL OR al.created_at >= p_start_date)
      AND (p_end_date IS NULL OR al.created_at <= p_end_date)
  )
  SELECT
    COUNT(*)::BIGINT,
    COUNT(*) FILTER (WHERE 
      (expected_prev IS NULL AND chain.previous_log_hash = 'GENESIS')
      OR (expected_prev IS NOT NULL AND chain.previous_log_hash = expected_prev)
    )::BIGINT,
    COUNT(*) FILTER (WHERE 
      (expected_prev IS NOT NULL AND chain.previous_log_hash != expected_prev)
      OR (expected_prev IS NULL AND chain.previous_log_hash != 'GENESIS')
    )::BIGINT,
    ROUND(
      COUNT(*) FILTER (WHERE 
        (expected_prev IS NULL AND chain.previous_log_hash = 'GENESIS')
        OR (expected_prev IS NOT NULL AND chain.previous_log_hash = expected_prev)
      )::NUMERIC * 100.0 / GREATEST(COUNT(*), 1), 2
    )
  FROM chain;
END;
$$;


--
-- Name: verify_security_log_chain(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_security_log_chain(p_tenant_id uuid, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(total_records bigint, chain_valid boolean, broken_at timestamp with time zone, broken_id uuid)
