-- Name: agent_builds; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_builds (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    agent_id uuid NOT NULL,
    enrollment_key_id uuid,
    build_status text DEFAULT 'queued'::text NOT NULL,
    build_started_at timestamp with time zone,
    build_completed_at timestamp with time zone,
    build_duration_seconds integer,
    file_path text,
    file_size_bytes bigint,
    sha256_hash text,
    download_url text,
    download_expires_at timestamp with time zone,
    ps1_version text DEFAULT '3.0'::text,
    exe_version text DEFAULT '2.2.1'::text,
    ps2exe_version text,
    build_log jsonb DEFAULT '[]'::jsonb,
    error_message text,
    github_run_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    github_run_url text,
    script_hash text,
    cache_key text GENERATED ALWAYS AS (md5((((tenant_id)::text || COALESCE(script_hash, ''::text)) || COALESCE(exe_version, 'v3.0.0'::text)))) STORED,
    CONSTRAINT agent_builds_build_status_check CHECK ((build_status = ANY (ARRAY['queued'::text, 'building'::text, 'completed'::text, 'failed'::text]))),
    CONSTRAINT valid_duration CHECK (((build_duration_seconds IS NULL) OR (build_duration_seconds >= 0))),
    CONSTRAINT valid_file_size CHECK (((file_size_bytes IS NULL) OR (file_size_bytes > 0)))
);


