--
-- Name: agent_installation_metrics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.agent_installation_metrics WITH (security_barrier='true', security_invoker='true') AS
 SELECT tenant_id,
    platform,
    count(*) FILTER (WHERE (event_type = 'generated'::text)) AS total_generated,
    count(*) FILTER (WHERE (event_type = 'downloaded'::text)) AS total_downloaded,
    count(*) FILTER (WHERE (event_type = 'command_copied'::text)) AS total_copied,
    count(*) FILTER (WHERE (event_type = ANY (ARRAY['installed'::text, 'post_installation'::text]))) AS total_installed,
    count(*) FILTER (WHERE (success = true)) AS successful_events,
    count(*) FILTER (WHERE (success = false)) AS failed_events,
    round(avg(installation_time_seconds) FILTER (WHERE (installation_time_seconds IS NOT NULL)), 2) AS avg_install_time_seconds,
    count(*) FILTER (WHERE (network_connectivity = true)) AS with_network,
    count(*) FILTER (WHERE (network_connectivity = false)) AS without_network,
    max(created_at) AS last_event_at
   FROM public.installation_analytics
  WHERE ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin())
  GROUP BY tenant_id, platform;


