    media_processes jsonb DEFAULT '["chrome", "firefox", "msedge", "vlc", "obs64", "obs", "teams", "zoom", "discord", "spotify"]'::jsonb NOT NULL,
    duration_minutes integer DEFAULT 15 NOT NULL,
    reduced_interval_seconds integer DEFAULT 600 NOT NULL,
    active_media_processes jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    aggregation_enabled boolean DEFAULT true NOT NULL,
    aggregation_window_seconds integer DEFAULT 3 NOT NULL,
    aggregation_file_threshold integer DEFAULT 50 NOT NULL,
    aggregation_process_threshold integer DEFAULT 20 NOT NULL,
    aggregation_network_threshold integer DEFAULT 100 NOT NULL,
    aggregation_max_buffer_size integer DEFAULT 500 NOT NULL
);


