--
-- Name: agent_quarantine; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_quarantine (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    agent_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    quarantine_reason text NOT NULL,
    severity text DEFAULT 'high'::text NOT NULL,
    duration_hours integer DEFAULT 24 NOT NULL,
    restrict_network boolean DEFAULT true,
    restrict_processes boolean DEFAULT true,
    restrict_file_access boolean DEFAULT true,
    quarantined_by text DEFAULT 'system'::text NOT NULL,
    quarantine_end timestamp with time zone,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    released_at timestamp with time zone,
    released_by text,
    CONSTRAINT agent_quarantine_status_check CHECK ((status = ANY (ARRAY['active'::text, 'released'::text, 'expired'::text])))
);


