    requested_by uuid NOT NULL,
    approved_by uuid,
    signed_payload jsonb NOT NULL,
    status text DEFAULT 'pending'::text,
    expires_at timestamp with time zone NOT NULL,
    used_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT agent_recovery_authorizations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'expired'::text, 'used'::text])))
);


--
-- Name: TABLE agent_recovery_authorizations; Type: COMMENT; Schema: public; Owner: -
