--
-- Name: agent_releases; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_releases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    version text NOT NULL,
    platform text DEFAULT 'windows'::text NOT NULL,
    channel text DEFAULT 'stable'::text NOT NULL,
    script_content text NOT NULL,
    sha256 text NOT NULL,
    release_notes text,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    signature_base64 text,
    signed_at timestamp with time zone,
    signed_by text,
    signature text,
    CONSTRAINT chk_script_content_min_size CHECK (((length(script_content) > 10000) OR (script_content = 'CODEBASE_AUTHORITATIVE'::text)))
);


--
-- Name: TABLE agent_releases; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.agent_releases IS 'Releases publicados do agente para distribuição. Utilizada no módulo de atualização.';


--
