--

COMMENT ON COLUMN public.agent_releases.version IS 'Versão semântica (e.g., 3.1.0)';


--
-- Name: COLUMN agent_releases.platform; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.agent_releases.platform IS 'Plataforma: windows, linux, macos';


--
-- Name: COLUMN agent_releases.channel; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.agent_releases.channel IS 'Canal de release: stable, beta, alpha';


--
-- Name: COLUMN agent_releases.script_content; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.agent_releases.script_content IS 'Conteúdo completo do script PowerShell/Bash';


--
-- Name: COLUMN agent_releases.sha256; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.agent_releases.sha256 IS 'Hash SHA256 do script_content para validação';


--
-- Name: COLUMN agent_releases.is_active; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.agent_releases.is_active IS 'Apenas releases ativas podem ser baixadas';


--
-- Name: COLUMN agent_releases.signature_base64; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.agent_releases.signature_base64 IS 'Ed25519 signature of script_content in Base64 format';


--
-- Name: COLUMN agent_releases.signed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.agent_releases.signed_at IS 'Timestamp when the release was signed';


--
-- Name: COLUMN agent_releases.signed_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.agent_releases.signed_by IS 'Identity of the signer (e.g. super_admin email or CI pipeline)';


--
-- Name: COLUMN agent_releases.signature; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.agent_releases.signature IS 'ECDSA P-256 digital signature of script_content';


--
-- Name: agent_releases_public; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.agent_releases_public WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    version,
    channel,
    platform,
    is_active,
    release_notes,
    created_at
   FROM public.agent_releases
  WHERE ((is_active = true) AND (auth.uid() IS NOT NULL));


--
-- Name: VIEW agent_releases_public; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.agent_releases_public IS 'SSA-SEC-005: Public agent releases view restricted to authenticated users only.';


--
-- Name: agent_rollback_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_rollback_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    agent_id uuid,
    agent_name text NOT NULL,
    tenant_id uuid NOT NULL,
    from_version text NOT NULL,
    to_version text NOT NULL,
    reason text NOT NULL,
    rollback_count integer DEFAULT 1,
    safe_mode_triggered boolean DEFAULT false,
    details jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT agent_rollback_events_reason_check CHECK ((reason = ANY (ARRAY['health_check_failed'::text, 'crash_detected'::text, 'state_machine_invalid'::text, 'heartbeat_failed'::text, 'manual_rollback'::text])))
);


--
-- Name: TABLE agent_rollback_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.agent_rollback_events IS 'Eventos de rollback de atualização de agentes. Relacionada com agents e tenants.';


--
-- Name: COLUMN agent_rollback_events.reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.agent_rollback_events.reason IS 'Motivo do rollback: health_check_failed, crash_detected, state_machine_invalid, heartbeat_failed, manual_rollback';


--
-- Name: COLUMN agent_rollback_events.rollback_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.agent_rollback_events.rollback_count IS 'Contador de rollbacks consecutivos para o mesmo agente';


--
-- Name: COLUMN agent_rollback_events.safe_mode_triggered; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.agent_rollback_events.safe_mode_triggered IS 'True se o agente entrou em safe mode após múltiplos rollbacks';


--
-- Name: agent_safe_mode_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_safe_mode_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    agent_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    entered_at timestamp with time zone NOT NULL,
    reason text NOT NULL,
    failure_count integer DEFAULT 0,
    agent_version text,
    execution_hash text,
    resolved_at timestamp with time zone,
    resolved_by uuid,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT agent_safe_mode_events_reason_check CHECK ((reason = ANY (ARRAY['update_rollback'::text, 'crash_loop'::text, 'job_failure_loop'::text, 'integrity_violation'::text, 'watchdog_timeout'::text, 'manual'::text])))
);


--
-- Name: TABLE agent_safe_mode_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.agent_safe_mode_events IS 'Eventos de ativação do modo seguro dos agentes. Relacionada com agents e tenants.';


--
-- Name: agent_signing_keys; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_signing_keys (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    agent_id uuid NOT NULL,
    public_key text NOT NULL,
    key_fingerprint text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    algorithm text DEFAULT 'ECDSA-P256-SHA256'::text NOT NULL,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    revoked_at timestamp with time zone,
    revoked_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '30 days'::interval),
    rotation_signaled_at timestamp with time zone,
    tenant_id uuid,
    is_active boolean DEFAULT true NOT NULL,
    valid_until timestamp with time zone
);


--
-- Name: TABLE agent_signing_keys; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.agent_signing_keys IS 'Chaves criptográficas para assinatura de builds do agente. Relacionada com tenants.';


--
-- Name: agent_snapshots; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.agent_snapshots WITH (security_barrier='true', security_invoker='true') AS
 SELECT id AS agent_id,
    tenant_id,
    agent_name,
    display_name,
    hostname,
    status,
    agent_version,
    last_heartbeat,
    agent_mode,
    enrolled_at AS created_at
   FROM public.agents a
  WHERE ((archived_at IS NULL) AND (auth.uid() IS NOT NULL) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()));


--
-- Name: VIEW agent_snapshots; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.agent_snapshots IS 'SSA-SEC-010: Hardened with security_invoker, security_barrier, auth.uid() filter';


