CREATE TABLE public.agent_update_decisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    agent_id uuid,
    agent_name text NOT NULL,
    platform text NOT NULL,
    target_version text NOT NULL,
    bucket integer NOT NULL,
    rollout_percentage integer NOT NULL,
    decision text NOT NULL,
    current_version text,
    created_at timestamp with time zone DEFAULT now(),
    tenant_id uuid,
    CONSTRAINT agent_update_decisions_bucket_check CHECK (((bucket >= 0) AND (bucket <= 99))),
    CONSTRAINT agent_update_decisions_decision_check CHECK ((decision = ANY (ARRAY['allowed'::text, 'skipped'::text, 'no_policy'::text, 'already_current'::text])))
);


