    notes text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    created_by uuid,
    CONSTRAINT agent_update_policies_platform_check CHECK ((platform = ANY (ARRAY['windows'::text, 'linux'::text, 'macos'::text]))),
    CONSTRAINT agent_update_policies_rollout_percentage_check CHECK (((rollout_percentage >= 0) AND (rollout_percentage <= 100)))
);


