--
-- Name: agents_public; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.agents_public WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    tenant_id,
    agent_name,
    hostname,
    status,
    os_type,
    os_version,
    agent_version,
    display_name,
    enrolled_at,
    last_heartbeat,
    agent_mode,
    agent_state,
    agent_state_reason,
    agent_state_changed_at
   FROM public.agents
  WHERE ((auth.uid() IS NOT NULL) AND (archived_at IS NULL) AND (tenant_id = public.get_active_tenant_id()));


--
-- Name: agents_safe; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.agents_safe WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    tenant_id,
    agent_name,
    hostname,
    status,
    os_type,
    os_version,
    agent_version,
    agent_version_code,
    display_name,
    enrolled_at,
    last_heartbeat,
    last_block_sync_at,
    poll_interval_seconds,
    agent_mode,
    agent_state,
    agent_state_reason,
    agent_state_changed_at,
    safe_mode_reason,
    safe_mode_entered_at,
    is_throttled,
    throttled_at,
    throttle_reason,
    is_isolated,
    isolated_at,
    isolation_reason,
    archived_at,
    archived_reason,
    force_update_version,
    force_update_reason,
    force_update_at,
    force_update_override_safe_mode,
    force_update_override_safe_mode_expires_at,
    last_forced_update_applied,
    offline_reason,
    offline_detected_at,
    ed25519_supported,
    signature_mode,
    requires_revalidation,
    revalidation_reason,
    revalidation_required_at
   FROM public.agents
  WHERE ((auth.uid() IS NOT NULL) AND (archived_at IS NULL) AND (tenant_id = public.get_active_tenant_id()));


