    CONSTRAINT ai_action_validations_confidence_score_check CHECK (((confidence_score >= (0)::numeric) AND (confidence_score <= (100)::numeric))),
    CONSTRAINT ai_action_validations_validation_result_check CHECK ((validation_result = ANY (ARRAY['confirmed'::text, 'rejected'::text, 'needs_review'::text]))),
    CONSTRAINT ai_action_validations_validation_source_check CHECK ((validation_source = ANY (ARRAY['human'::text, 'secondary_ai'::text, 'rule_engine'::text, 'correlation'::text])))
);


