--
-- Name: ai_actions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_actions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    insight_id uuid,
    tenant_id uuid NOT NULL,
    action_type text NOT NULL,
    action_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    executed_at timestamp with time zone,
    executed_by uuid,
    result jsonb,
    error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    decision_event_id uuid,
    effectiveness_status text DEFAULT 'pending'::text,
    effectiveness_checked_at timestamp with time zone,
    effectiveness_evidence jsonb DEFAULT '{}'::jsonb,
    risk_level text DEFAULT 'medium'::text,
    reasoning_summary text,
    evidence_pack jsonb,
    ai_validation_score numeric,
    ai_validation_status text DEFAULT 'pending'::text,
    ai_validation_reason text,
    ai_validated_at timestamp with time zone,
    human_reviewed boolean DEFAULT false,
    review_decision text,
    review_justification text,
    reversible boolean DEFAULT false,
    rollback_status text,
    rollback_reason text,
    block_reason text,
    shadow_validation jsonb,
    approved_at timestamp with time zone,
    approved_by uuid,
    approval_request_id uuid,
    explanation text,
    reviewed_at timestamp with time zone,
    CONSTRAINT ai_actions_effectiveness_status_check CHECK ((effectiveness_status = ANY (ARRAY['pending'::text, 'resolved'::text, 'partial'::text, 'failed'::text, 'unknown'::text]))),
    CONSTRAINT ai_actions_review_decision_check CHECK (((review_decision IS NULL) OR (review_decision = ANY (ARRAY['approved'::text, 'rejected'::text, 'deferred'::text])))),
    CONSTRAINT ai_actions_risk_level_check CHECK ((risk_level = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text]))),
    CONSTRAINT ai_actions_rollback_status_check CHECK ((rollback_status = ANY (ARRAY['pending'::text, 'executed'::text, 'failed'::text]))),
    CONSTRAINT ai_actions_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'executed'::text, 'failed'::text]))),
    CONSTRAINT ai_actions_validation_status_check CHECK ((ai_validation_status = ANY (ARRAY['pending'::text, 'pass'::text, 'fail'::text, 'escalate'::text])))
);


