--

CREATE TABLE public.ai_insights (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    insight_type text NOT NULL,
    severity text NOT NULL,
    title text NOT NULL,
    description text NOT NULL,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    recommendation text,
    confidence_score numeric(3,2),
    metadata jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    acknowledged boolean DEFAULT false,
    acknowledged_by uuid,
    acknowledged_at timestamp with time zone,
    agent_id uuid,
    category text,
    recommended_actions jsonb DEFAULT '[]'::jsonb,
    affected_resources jsonb DEFAULT '[]'::jsonb,
    auto_action_mode text DEFAULT 'suggest'::text,
    auto_action_executed boolean DEFAULT false,
    auto_action_executed_at timestamp with time zone,
    status text DEFAULT 'open'::text NOT NULL,
    resolved_at timestamp with time zone,
    resolved_by uuid,
    final_outcome text,
    reasoning_summary text,
    evidence_pack jsonb,
    resolved_by_decision_event uuid,
    resolution_method text,
    dismissed_at timestamp with time zone,
    dismissed_by uuid,
    dismissal_reason text,
    rejection_reason text,
    rejected_at timestamp with time zone,
    rejected_by uuid,
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT ai_insights_auto_action_mode_check CHECK ((auto_action_mode = ANY (ARRAY['none'::text, 'suggest'::text, 'auto'::text, 'auto_with_approval'::text]))),
    CONSTRAINT ai_insights_confidence_score_check CHECK (((confidence_score >= (0)::numeric) AND (confidence_score <= (1)::numeric))),
    CONSTRAINT ai_insights_final_outcome_check CHECK (((final_outcome IS NULL) OR (final_outcome = ANY (ARRAY['resolved'::text, 'partial'::text, 'failed'::text, 'no_action_required'::text])))),
    CONSTRAINT ai_insights_resolution_method_check CHECK (((resolution_method IS NULL) OR (resolution_method = ANY (ARRAY['human_review'::text, 'automated_action'::text, 'policy_enforcement'::text, 'manual_dismiss'::text, 'manual_review_no_action'::text, 'no_action_available'::text])))),
    CONSTRAINT ai_insights_severity_check CHECK ((severity = ANY (ARRAY['info'::text, 'low'::text, 'medium'::text, 'warning'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT ai_insights_status_check CHECK ((status = ANY (ARRAY['open'::text, 'in_progress'::text, 'resolved'::text, 'ignored'::text, 'failed'::text, 'reviewed_no_action'::text, 'rejected'::text])))
);


