--
-- Name: anomaly_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.anomaly_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    agent_id uuid NOT NULL,
    type text NOT NULL,
    severity text NOT NULL,
    description text,
    data jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    acknowledged_at timestamp with time zone,
    CONSTRAINT anomaly_events_severity_check CHECK ((severity = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text])))
);


--
-- Name: TABLE anomaly_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.anomaly_events IS 'Eventos de anomalia detectados nos agentes. Utilizada no painel de segurança. Relacionada com agents e tenants.';


--
-- Name: antivirus_status; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.antivirus_status (
