);


--
-- Name: TABLE api_request_logs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.api_request_logs IS 'Logs de requisições à API para monitoramento e rate limiting. Relacionada com tenants.';


--
-- Name: approval_chains; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.approval_chains (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    name text NOT NULL,
    description text,
    min_approvers integer DEFAULT 2 NOT NULL,
    timeout_hours integer DEFAULT 24 NOT NULL,
    applies_to_actions text[] DEFAULT ARRAY['isolate'::text, 'kill_process'::text, 'stop_service'::text, 'disable_service'::text, 'revoke_token'::text, 'quarantine'::text, 'network_isolate'::text] NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    require_different_approvers boolean DEFAULT true,
    CONSTRAINT approval_chains_min_approvers_check CHECK (((min_approvers >= 1) AND (min_approvers <= 5))),
    CONSTRAINT approval_chains_timeout_hours_check CHECK (((timeout_hours >= 1) AND (timeout_hours <= 168)))
);


--
-- Name: TABLE approval_chains; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.approval_chains IS 'Cadeias de aprovação multi-nível configuráveis. Relacionada com tenants.';


--
-- Name: approval_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.approval_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    chain_id uuid,
    playbook_execution_id uuid,
    action_type text NOT NULL,
    action_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    target_agent_id uuid,
    requested_by uuid NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    required_approvers integer DEFAULT 2 NOT NULL,
    current_approvers integer DEFAULT 0 NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    approved_at timestamp with time zone,
    executed_at timestamp with time zone,
    rejection_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    approval_token text,
    approval_token_expires_at timestamp with time zone DEFAULT (now() + '24:00:00'::interval),
    CONSTRAINT approval_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'expired'::text, 'executed'::text]))),
    CONSTRAINT approval_token_requires_expiry CHECK (((approval_token IS NULL) OR (approval_token_expires_at IS NOT NULL)))
);


--
-- Name: TABLE approval_requests; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.approval_requests IS 'Solicitações de aprovação para ações sensíveis. Relacionada com tenants.';


--
-- Name: CONSTRAINT approval_token_requires_expiry ON approval_requests; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT approval_token_requires_expiry ON public.approval_requests IS 'Defense in depth: tokens de aprovação devem sempre ter expiração definida';


--
-- Name: approvals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.approvals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_id uuid NOT NULL,
    approved_by uuid NOT NULL,
    decision text NOT NULL,
    reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT approvals_decision_check CHECK ((decision = ANY (ARRAY['approved'::text, 'rejected'::text])))
);


--
-- Name: TABLE approvals; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.approvals IS 'Registros de aprovações/rejeições individuais. Relacionada com approval_requests.';


--
-- Name: attack_simulation_results; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.attack_simulation_results (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    simulation_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    agent_id uuid NOT NULL,
    agent_hostname text,
    detected boolean DEFAULT false,
    detection_time_ms integer,
    detection_method text,
    details jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now()
);


--
-- Name: attack_simulations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.attack_simulations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    simulation_type text NOT NULL,
    title text NOT NULL,
    description text,
    status text DEFAULT 'pending'::text NOT NULL,
    target_agent_ids uuid[] DEFAULT '{}'::uuid[],
    config jsonb DEFAULT '{}'::jsonb,
    results_summary jsonb DEFAULT '{}'::jsonb,
    total_agents integer DEFAULT 0,
    detected_count integer DEFAULT 0,
    missed_count integer DEFAULT 0,
    detection_rate numeric(5,2) DEFAULT 0,
    created_by uuid,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT attack_simulations_simulation_type_check CHECK ((simulation_type = ANY (ARRAY['eicar_test'::text, 'port_scan_test'::text, 'canary_file_test'::text, 'usb_policy_test'::text, 'firewall_test'::text, 'dns_filter_test'::text]))),
    CONSTRAINT attack_simulations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'completed'::text, 'failed'::text, 'cancelled'::text])))
);


