--
-- Name: COLUMN audit_logs_old.id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.audit_logs_old.id IS 'Identificador único. UUID.';


--
-- Name: COLUMN audit_logs_old.created_at; Type: COMMENT; Schema: public; Owner: -
