--

COMMENT ON COLUMN public.audit_logs_old.tenant_id IS 'FK para tenants. Multi-tenant.';


--
-- Name: COLUMN audit_logs_old.actor_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.audit_logs_old.actor_id IS 'User ID que executou a ação (referencia profiles.user_id)';


--
-- Name: audit_logs_safe; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.audit_logs_safe WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    user_id,
    tenant_id,
    action,
    resource_type,
    resource_id,
    success,
    created_at
   FROM public.audit_logs_old
  WHERE ((auth.uid() IS NOT NULL) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()));


--
-- Name: VIEW audit_logs_safe; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.audit_logs_safe IS 'ADR-027: Tenant-scoped audit logs. Excludes error_details and metadata for security.';


