--
-- Name: auto_remediation_actions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.auto_remediation_actions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    agent_id uuid,
    agent_name text,
    action_type text NOT NULL,
    trigger_source text NOT NULL,
    trigger_details jsonb DEFAULT '{}'::jsonb,
    status text DEFAULT 'pending'::text,
    result jsonb,
    error_message text,
    requires_approval boolean DEFAULT false,
    approved_by uuid,
    approved_at timestamp with time zone,
    executed_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT auto_remediation_actions_action_type_check CHECK ((action_type = ANY (ARRAY['kill_process'::text, 'firewall_block'::text, 'patch_apply'::text, 'quarantine_file'::text, 'restart_service'::text]))),
    CONSTRAINT auto_remediation_actions_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'executing'::text, 'success'::text, 'failed'::text, 'rolled_back'::text])))
);


--
-- Name: TABLE auto_remediation_actions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.auto_remediation_actions IS 'Ações de remediação automática configuradas. Relacionada com tenants.';


