--

CREATE TABLE public.automation_approvals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    rule_id uuid NOT NULL,
    agent_id uuid,
    trigger_data jsonb,
    status text DEFAULT 'pending'::text,
    approved_by uuid,
    approved_at timestamp with time zone,
    second_approved_by uuid,
    second_approved_at timestamp with time zone,
    rejected_by uuid,
    rejected_at timestamp with time zone,
    rejection_reason text,
    expires_at timestamp with time zone DEFAULT (now() + '24:00:00'::interval),
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT automation_approvals_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'expired'::text, 'executed'::text])))
);


--
-- Name: TABLE automation_approvals; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.automation_approvals IS 'Fila de aprovações para ações de automação que requerem autorização humana';


--
-- Name: automation_decision_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.automation_decision_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    rule_id uuid NOT NULL,
    rule_name text,
    agent_id uuid,
    decision text NOT NULL,
    reason text,
    risk_score numeric,
    severity text,
    executed boolean DEFAULT false,
    blocked_reason text,
    impact_percent numeric,
    mode text,
    trigger_data jsonb,
    created_at timestamp with time zone DEFAULT now(),
    trace_id text,
    CONSTRAINT automation_decision_log_decision_check CHECK ((decision = ANY (ARRAY['executed'::text, 'blocked_cooldown'::text, 'blocked_rate_limit'::text, 'blocked_circuit_breaker'::text, 'blocked_blast_radius'::text, 'blocked_approval_required'::text, 'blocked_risk_threshold'::text, 'observe_only'::text, 'dry_run'::text, 'blocked_disabled'::text, 'skipped'::text])))
);


