--
-- Name: automation_rule_dependencies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.automation_rule_dependencies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    rule_id uuid NOT NULL,
    depends_on_rule_id uuid NOT NULL,
    relationship_type text DEFAULT 'blocks'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT automation_rule_dependencies_relationship_type_check CHECK ((relationship_type = ANY (ARRAY['blocks'::text, 'requires'::text, 'conflicts'::text]))),
    CONSTRAINT no_self_dependency CHECK ((rule_id <> depends_on_rule_id))
);


