COMMENT ON TABLE public.automation_rule_versions IS 'Histórico de versões de regras de automação para rollback e auditoria';


--
-- Name: automation_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.automation_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    name text NOT NULL,
    description text,
    is_active boolean DEFAULT true NOT NULL,
    trigger_type text NOT NULL,
    trigger_conditions jsonb NOT NULL,
    action_type text NOT NULL,
    action_config jsonb NOT NULL,
    target_scope text DEFAULT 'all_agents'::text NOT NULL,
    target_ids uuid[] DEFAULT '{}'::uuid[],
    cooldown_minutes integer DEFAULT 30 NOT NULL,
    last_triggered_at timestamp with time zone,
    trigger_count integer DEFAULT 0 NOT NULL,
    priority integer DEFAULT 5 NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    max_executions_per_hour integer DEFAULT 50,
    circuit_breaker_threshold integer DEFAULT 10,
    circuit_breaker_window_minutes integer DEFAULT 5,
    circuit_state text DEFAULT 'closed'::text,
    circuit_opened_at timestamp with time zone,
    circuit_recovery_minutes integer DEFAULT 15,
    max_affected_percentage numeric DEFAULT 30,
    risk_threshold integer DEFAULT 0,
    requires_approval boolean DEFAULT false,
    requires_dual_approval boolean DEFAULT false,
    auto_execute_if_severity text DEFAULT 'critical'::text,
    dry_run boolean DEFAULT false,
    mode text DEFAULT 'active'::text,
    CONSTRAINT automation_rules_circuit_state_check CHECK ((circuit_state = ANY (ARRAY['closed'::text, 'open'::text, 'half_open'::text]))),
    CONSTRAINT automation_rules_mode_check CHECK ((mode = ANY (ARRAY['active'::text, 'observe_only'::text, 'disabled'::text])))
);


--
-- Name: TABLE automation_rules; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.automation_rules IS 'Regras de automação para ações baseadas em eventos. Utilizada no motor de regras. Relacionada com tenants.';


