--
-- Name: circuit_breaker_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.circuit_breaker_health WITH (security_barrier='true', security_invoker='true') AS
 SELECT service,
    state,
    failure_count,
    created_at AS last_event,
    tenant_id,
        CASE
            WHEN (state = 'open'::text) THEN 'critical'::text
            WHEN (state = 'half_open'::text) THEN 'warning'::text
            ELSE 'healthy'::text
        END AS health_status
   FROM public.circuit_breaker_events cb1
  WHERE ((created_at = ( SELECT max(cb2.created_at) AS max
           FROM public.circuit_breaker_events cb2
          WHERE (cb2.service = cb1.service))) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()));


