-- Name: cron_health; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.cron_health (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    cron_name text NOT NULL,
    last_success_at timestamp with time zone,
    last_failure_at timestamp with time zone,
    last_error text,
    consecutive_failures integer DEFAULT 0 NOT NULL,
    total_runs integer DEFAULT 0 NOT NULL,
    total_failures integer DEFAULT 0 NOT NULL,
    avg_duration_ms integer,
    last_duration_ms integer,
    metadata jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    status text GENERATED ALWAYS AS (
CASE
    WHEN (consecutive_failures >= 3) THEN 'critical'::text
    WHEN (consecutive_failures >= 1) THEN 'degraded'::text
    ELSE 'healthy'::text
END) STORED
);


