    decision_event_id uuid,
    resolution_source text,
    CONSTRAINT failed_jobs_dlq_classification_check CHECK ((classification = ANY (ARRAY['expected'::text, 'transient'::text, 'suspicious'::text]))),
    CONSTRAINT failed_jobs_dlq_resolution_source_check CHECK (((resolution_source IS NULL) OR (resolution_source = ANY (ARRAY['human'::text, 'system'::text, 'auto_cleanup'::text])))),
    CONSTRAINT failed_jobs_dlq_risk_category_check CHECK ((risk_category = ANY (ARRAY['unreviewed'::text, 'benign'::text, 'suspicious'::text, 'malicious'::text]))),
    CONSTRAINT failed_jobs_dlq_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'retrying'::text, 'exhausted'::text, 'resolved'::text])))
);


--
-- Name: TABLE failed_jobs_dlq; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.failed_jobs_dlq IS 'Dead Letter Queue para jobs que falharam múltiplas vezes. Relacionada com jobs.';


--
-- Name: dlq_categorized; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.dlq_categorized WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    tenant_id,
    agent_id,
    job_type,
    error_message,
    retry_count,
    status,
    created_at,
    resolved_at,
    resolved_by,
    review_notes,
    flagged_suspicious,
    COALESCE(risk_category,
        CASE
            WHEN (failure_class = ANY (ARRAY['security'::text, 'critical'::text, 'auth_failure'::text])) THEN 'security'::text
            WHEN (retry_count > 5) THEN 'reliability'::text
            ELSE 'operational'::text
        END) AS risk_category
   FROM public.failed_jobs_dlq
  WHERE ((auth.uid() IS NOT NULL) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()));


