--

COMMENT ON COLUMN public.enrollment_keys.is_active IS 'False se revogada ou expirada. True se ainda pode ser usada.';


--
-- Name: COLUMN enrollment_keys.tenant_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_keys.tenant_id IS 'FK para tenants.';


