-- Name: COLUMN enrollment_keys.auto_generated; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_keys.auto_generated IS 'Indicates if the key was automatically generated by the system when all previous keys expired';


--
-- Name: enrollment_keys_safe; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.enrollment_keys_safe WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    tenant_id,
    ("left"(key, 8) || '****'::text) AS key_masked,
    description,
    max_uses,
    current_uses,
    is_active,
    created_at,
    expires_at,
    created_by,
    used_at,
    agent_id,
    used_by_agent
   FROM public.enrollment_keys
  WHERE ((auth.uid() IS NOT NULL) AND (tenant_id = public.get_active_tenant_id()));


