    CONSTRAINT generated_reports_status_check CHECK ((status = ANY (ARRAY['generating'::text, 'generated'::text, 'failed'::text]))),
    CONSTRAINT generated_reports_triggered_by_check CHECK ((triggered_by = ANY (ARRAY['job_completion'::text, 'scheduled'::text, 'manual'::text])))
);


