--
-- Name: installation_error_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.installation_error_summary WITH (security_barrier='true', security_invoker='true') AS
 SELECT tenant_id,
    platform,
    event_type,
    error_message,
    count(*) AS error_count,
    max(created_at) AS last_occurrence
   FROM public.installation_analytics
  WHERE ((success = false) AND (error_message IS NOT NULL) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
  GROUP BY tenant_id, platform, event_type, error_message
  ORDER BY (count(*)) DESC;


--
-- Name: installation_health_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.installation_health_status WITH (security_barrier='true', security_invoker='true') AS
 SELECT tenant_id,
    count(*) AS total_agents,
    count(*) FILTER (WHERE ((status = 'active'::text) AND (last_heartbeat >= (now() - '00:05:00'::interval)))) AS active_agents,
    count(*) FILTER (WHERE ((status = 'active'::text) AND (last_heartbeat < (now() - '00:05:00'::interval)) AND (last_heartbeat >= (now() - '00:15:00'::interval)))) AS warning_agents,
    count(*) FILTER (WHERE ((status = 'active'::text) AND ((last_heartbeat < (now() - '00:15:00'::interval)) OR (last_heartbeat IS NULL)))) AS critical_agents,
    count(*) FILTER (WHERE (status = 'inactive'::text)) AS inactive_agents
   FROM public.agents
  WHERE ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin())
  GROUP BY tenant_id;


--
-- Name: installation_metrics_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.installation_metrics_summary WITH (security_barrier='true', security_invoker='true') AS
 SELECT tenant_id,
    platform,
    count(*) AS total_installations,
    count(*) FILTER (WHERE (success = true)) AS successful,
    count(*) FILTER (WHERE (success = false)) AS failed,
    round(avg(installation_time_seconds) FILTER (WHERE (installation_time_seconds IS NOT NULL)), 2) AS avg_install_time
   FROM public.installation_analytics
  WHERE ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin())
  GROUP BY tenant_id, platform;


