--
-- Name: job_failure_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.job_failure_health WITH (security_barrier='true', security_invoker='true') AS
 SELECT tenant_id,
    date_trunc('hour'::text, created_at) AS hour,
    count(*) AS total_jobs,
    count(*) FILTER (WHERE (status = 'failed'::text)) AS failed_jobs,
    round((((count(*) FILTER (WHERE (status = 'failed'::text)))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 2) AS failure_rate_pct
   FROM public.jobs
  WHERE ((created_at > (now() - '24:00:00'::interval)) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
  GROUP BY tenant_id, (date_trunc('hour'::text, created_at))
  ORDER BY (date_trunc('hour'::text, created_at)) DESC;


--
-- Name: job_integrity_violations; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.job_integrity_violations WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    tenant_id,
    agent_id,
    agent_name,
    type,
    status,
    created_at,
    payload_hash,
        CASE
            WHEN (payload_hash IS NULL) THEN 'missing_payload_hash'::text
            ELSE 'unknown'::text
        END AS violation_type
   FROM public.jobs j
  WHERE ((payload_hash IS NULL) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()));


