COMMENT ON TABLE public.job_slo_state IS 'Estado de SLO por job para monitoramento de performance. Relacionada com jobs.';


--
-- Name: jobs_normalized; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.jobs_normalized WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    tenant_id,
    agent_id,
    agent_name,
    type,
    status,
    status AS normalized_status,
    priority,
    created_at,
    delivered_at,
    completed_at,
    error_message,
    payload_hash,
        CASE
            WHEN (output IS NOT NULL) THEN true
            ELSE false
        END AS is_v3,
    output,
    (EXTRACT(epoch FROM (completed_at - delivered_at)))::integer AS duration_seconds,
    EXTRACT(epoch FROM (delivered_at - created_at)) AS queue_time_seconds,
    execution_time_seconds
   FROM public.jobs
  WHERE ((auth.uid() IS NOT NULL) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()));


