    CONSTRAINT system_alerts_alert_type_check CHECK ((alert_type = ANY (ARRAY['stuck_agent'::text, 'stale_cron'::text, 'system_maintenance'::text, 'firewall_disabled'::text, 'antivirus_inactive'::text, 'unauthorized_usb'::text, 'vulnerable_software'::text, 'ai_insight_alert'::text, 'automation_alert'::text, 'agent_long_offline'::text, 'vulnerability_critical'::text, 'antivirus_outdated'::text, 'certificate_expiring'::text, 'usb_device_risky'::text, 'process_suspicious'::text, 'behavioral_anomaly'::text, 'agent_compromised'::text, 'security_incident'::text, 'compliance_drift'::text, 'high_risk_action'::text, 'brute_force_detected'::text, 'trial_expiring'::text, 'credential_rotation_overdue'::text]))),
    CONSTRAINT system_alerts_severity_check CHECK ((severity = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text])))
);


