--
-- Name: mv_alert_summary; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_alert_summary AS
 SELECT tenant_id,
    count(*) FILTER (WHERE (resolved = false)) AS active_alerts,
    count(*) FILTER (WHERE ((severity = 'critical'::text) AND (resolved = false))) AS critical_active,
    count(*) FILTER (WHERE ((severity = 'high'::text) AND (resolved = false))) AS high_active,
    count(*) FILTER (WHERE (acknowledged = true)) AS acknowledged_total,
    count(*) AS total_alerts_24h,
    now() AS refreshed_at
   FROM public.system_alerts
  WHERE (created_at > (now() - '24:00:00'::interval))
  GROUP BY tenant_id
  WITH NO DATA;


--
-- Name: mv_fleet_summary; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_fleet_summary AS
 SELECT tenant_id,
    count(*) AS total_agents,
    count(*) FILTER (WHERE (status = 'online'::text)) AS online_agents,
    count(*) FILTER (WHERE (status = 'offline'::text)) AS offline_agents,
    count(*) FILTER (WHERE (is_isolated = true)) AS isolated_agents,
    count(DISTINCT agent_version) AS distinct_versions,
    now() AS refreshed_at
   FROM public.agents a
  WHERE (archived_at IS NULL)
  GROUP BY tenant_id
  WITH NO DATA;


--
-- Name: mv_job_metrics_24h; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_job_metrics_24h AS
 SELECT tenant_id,
    type AS job_type,
    count(*) AS total_count,
    count(*) FILTER (WHERE (status = 'completed'::text)) AS success_count,
    count(*) FILTER (WHERE (status = 'failed'::text)) AS failure_count,
    count(*) FILTER (WHERE (status = 'pending'::text)) AS pending_count,
    round(avg((EXTRACT(epoch FROM (completed_at - created_at)) * (1000)::numeric)), 0) AS avg_duration_ms,
    now() AS refreshed_at
   FROM public.jobs j
  WHERE (created_at > (now() - '24:00:00'::interval))
  GROUP BY tenant_id, type
  WITH NO DATA;


--
-- Name: mv_security_posture; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_security_posture AS
 SELECT tenant_id,
    count(*) AS total_scans,
    count(*) FILTER (WHERE (remediation_status = 'open'::text)) AS open_vulns,
    count(*) FILTER (WHERE (severity = 'critical'::text)) AS critical_vulns,
    count(*) FILTER (WHERE (severity = 'high'::text)) AS high_vulns,
    count(*) FILTER (WHERE (severity = 'medium'::text)) AS medium_vulns,
    count(*) FILTER (WHERE (severity = 'low'::text)) AS low_vulns,
    now() AS refreshed_at
   FROM public.agent_vulnerability_scans
  GROUP BY tenant_id
  WITH NO DATA;


