--
-- Name: profiles_public; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.profiles_public WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    user_id,
    username,
    full_name,
    created_at,
    updated_at
   FROM public.profiles p
  WHERE ((auth.uid() IS NOT NULL) AND (EXISTS ( SELECT 1
           FROM public.user_roles ur
          WHERE ((ur.user_id = p.user_id) AND ((ur.tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin())))));


