    status text DEFAULT 'quarantined'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT quarantined_files_status_check CHECK ((status = ANY (ARRAY['quarantined'::text, 'restored'::text, 'deleted'::text])))
);


