--

CREATE TABLE public.rate_limits (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    identifier text NOT NULL,
    endpoint text NOT NULL,
    request_count integer DEFAULT 1 NOT NULL,
    window_start timestamp with time zone DEFAULT now() NOT NULL,
    last_request_at timestamp with time zone DEFAULT now() NOT NULL,
    blocked_until timestamp with time zone,
    tenant_id text
);


--
-- Name: TABLE rate_limits; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.rate_limits IS 'Configurações de rate limiting por endpoint e tenant. Relacionada com tenants.';


--
-- Name: rate_limit_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.rate_limit_stats WITH (security_barrier='true', security_invoker='true') AS
 SELECT endpoint,
    identifier,
    request_count,
    window_start,
    blocked_until,
    (blocked_until > now()) AS is_blocked
   FROM public.rate_limits rl
  WHERE (EXISTS ( SELECT 1
           FROM public.user_roles ur
          WHERE ((ur.user_id = auth.uid()) AND (ur.role = ANY (ARRAY['admin'::public.app_role, 'super_admin'::public.app_role])))));


--
-- Name: VIEW rate_limit_stats; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.rate_limit_stats IS 'GLOBAL_VIEW: Rate limiting statistics for admin monitoring. No tenant isolation - restricted to admin/super_admin roles via RLS. Last audit: 2026-02-05.';


--
-- Name: red_team_assessments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.red_team_assessments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    threat_level text NOT NULL,
    red_score integer NOT NULL,
    attack_vectors jsonb DEFAULT '[]'::jsonb NOT NULL,
    residual_risks jsonb DEFAULT '[]'::jsonb NOT NULL,
    threat_system_identity integer,
    threat_governance integer,
    threat_evidence_proof integer,
    threat_human_oversight integer,
    threat_operational_resilience integer,
    threat_cross_tenant_isolation integer,
    threat_transparency_explainability integer,
    threat_compliance_alignment integer,
    threat_market_trust integer,
    executive_threat_summary text,
    worst_case_scenario text,
    recommended_hardening jsonb DEFAULT '[]'::jsonb,
    ai_model text,
    ai_prompt_hash text,
    ai_response_raw jsonb,
    metrics_snapshot jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    binary_criteria jsonb DEFAULT '{}'::jsonb,
    criteria_count_true integer DEFAULT 0,
    CONSTRAINT red_team_assessments_red_score_check CHECK (((red_score >= 0) AND (red_score <= 100))),
    CONSTRAINT red_team_assessments_threat_compliance_alignment_check CHECK (((threat_compliance_alignment >= 0) AND (threat_compliance_alignment <= 10))),
    CONSTRAINT red_team_assessments_threat_cross_tenant_isolation_check CHECK (((threat_cross_tenant_isolation >= 0) AND (threat_cross_tenant_isolation <= 10))),
    CONSTRAINT red_team_assessments_threat_evidence_proof_check CHECK (((threat_evidence_proof >= 0) AND (threat_evidence_proof <= 10))),
    CONSTRAINT red_team_assessments_threat_governance_check CHECK (((threat_governance >= 0) AND (threat_governance <= 10))),
    CONSTRAINT red_team_assessments_threat_human_oversight_check CHECK (((threat_human_oversight >= 0) AND (threat_human_oversight <= 10))),
    CONSTRAINT red_team_assessments_threat_level_check CHECK ((threat_level = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT red_team_assessments_threat_market_trust_check CHECK (((threat_market_trust >= 0) AND (threat_market_trust <= 10))),
    CONSTRAINT red_team_assessments_threat_operational_resilience_check CHECK (((threat_operational_resilience >= 0) AND (threat_operational_resilience <= 10))),
    CONSTRAINT red_team_assessments_threat_system_identity_check CHECK (((threat_system_identity >= 0) AND (threat_system_identity <= 10))),
    CONSTRAINT red_team_assessments_threat_transparency_explainability_check CHECK (((threat_transparency_explainability >= 0) AND (threat_transparency_explainability <= 10)))
);


--
-- Name: TABLE red_team_assessments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.red_team_assessments IS 'Avaliações de red team para teste de segurança. Relacionada com tenants.';


