--
-- Name: system_audits; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.system_audits (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    overall_score integer NOT NULL,
    score_system_identity integer NOT NULL,
    score_control_vs_monitor integer NOT NULL,
    score_evidence_proof integer NOT NULL,
    score_maturity integer NOT NULL,
    score_failure_handling integer NOT NULL,
    score_limitations integer NOT NULL,
    score_operational_trust integer NOT NULL,
    score_market_value integer NOT NULL,
    score_simplicity integer NOT NULL,
    analysis_system_identity text,
    analysis_control_vs_monitor text,
    analysis_evidence_proof text,
    analysis_maturity text,
    analysis_failure_handling text,
    analysis_limitations text,
    analysis_operational_trust text,
    analysis_market_value text,
    analysis_simplicity text,
    executive_summary text,
    final_sentence text,
    recommendation text,
    metrics_snapshot jsonb DEFAULT '{}'::jsonb,
    ai_model text,
    prompt_hash text,
    tokens_used integer,
    evidence_basis jsonb DEFAULT '[]'::jsonb,
    falsification_criteria jsonb DEFAULT '[]'::jsonb,
    raw_score integer,
    official_score integer,
    market_score integer,
    guardrail_applied boolean DEFAULT false,
    guardrail_reason text,
    deterministic_base_score integer,
    red_risk_factor numeric(4,3),
    trace_id text,
    CONSTRAINT system_audits_overall_score_check CHECK (((overall_score >= 0) AND (overall_score <= 100))),
    CONSTRAINT system_audits_recommendation_check CHECK ((recommendation = ANY (ARRAY['NOT_READY'::text, 'READY_MVP'::text, 'READY_FOR_SCALE'::text, 'ENTERPRISE_READY'::text]))),
    CONSTRAINT system_audits_score_control_vs_monitor_check CHECK (((score_control_vs_monitor >= 0) AND (score_control_vs_monitor <= 10))),
    CONSTRAINT system_audits_score_evidence_proof_check CHECK (((score_evidence_proof >= 0) AND (score_evidence_proof <= 10))),
    CONSTRAINT system_audits_score_failure_handling_check CHECK (((score_failure_handling >= 0) AND (score_failure_handling <= 10))),
    CONSTRAINT system_audits_score_limitations_check CHECK (((score_limitations >= 0) AND (score_limitations <= 10))),
    CONSTRAINT system_audits_score_market_value_check CHECK (((score_market_value >= 0) AND (score_market_value <= 10))),
    CONSTRAINT system_audits_score_maturity_check CHECK (((score_maturity >= 0) AND (score_maturity <= 10))),
    CONSTRAINT system_audits_score_operational_trust_check CHECK (((score_operational_trust >= 0) AND (score_operational_trust <= 10))),
    CONSTRAINT system_audits_score_simplicity_check CHECK (((score_simplicity >= 0) AND (score_simplicity <= 10))),
    CONSTRAINT system_audits_score_system_identity_check CHECK (((score_system_identity >= 0) AND (score_system_identity <= 10)))
);


--
-- Name: COLUMN system_audits.evidence_basis; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.system_audits.evidence_basis IS 'Array of evidence objects with claim, type (direct_evidence|observed_metric|controlled_inference), source, confidence';


--
