--
-- Name: v_action_center; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_action_center WITH (security_barrier='true', security_invoker='true') AS
 SELECT 'dlq'::text AS source,
    d.id,
    d.tenant_id,
    d.job_type AS item_type,
    d.error_message AS description,
    d.status AS item_status,
    d.created_at,
    'high'::text AS priority
   FROM public.failed_jobs_dlq d
  WHERE ((d.status = 'pending'::text) AND (auth.uid() IS NOT NULL) AND ((d.tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
UNION ALL
 SELECT 'alert'::text AS source,
    a.id,
    a.tenant_id,
    a.alert_type AS item_type,
    a.message AS description,
        CASE
            WHEN a.resolved THEN 'resolved'::text
            ELSE 'open'::text
        END AS item_status,
    a.created_at,
    a.severity AS priority
   FROM public.system_alerts a
  WHERE ((a.resolved = false) AND (auth.uid() IS NOT NULL) AND ((a.tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
  ORDER BY 7 DESC
 LIMIT 100;


--
-- Name: VIEW v_action_center; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_action_center IS 'SSA-SEC-010: Hardened with security_invoker, security_barrier, auth.uid() filter';


--
-- Name: v_active_risk_debt; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_active_risk_debt WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    tenant_id,
    title,
    description,
    severity,
    risk_accepted_by,
    risk_accepted_at,
    risk_expiry_at,
    risk_justification,
    (EXTRACT(epoch FROM (risk_expiry_at - now())) / (86400)::numeric) AS days_until_expiry,
        CASE
            WHEN (risk_expiry_at <= (now() + '7 days'::interval)) THEN 'expiring_soon'::text
            ELSE 'active'::text
        END AS risk_status
   FROM public.tasks t
  WHERE ((status = 'accepted_risk'::text) AND ((risk_expiry_at IS NULL) OR (risk_expiry_at > now())) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()));


--
-- Name: VIEW v_active_risk_debt; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_active_risk_debt IS 'ADR-026: Tenant-isolated active risk debt. Uses security_invoker=on with mandatory tenant filter.';


--
-- Name: v_agent_archive_reason_tree; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_agent_archive_reason_tree WITH (security_barrier='true', security_invoker='true') AS
 SELECT e.id AS event_id,
    e.agent_id,
    a.agent_name,
    a.tenant_id,
    e.reason,
    e.actor_type,
    e.actor_id,
    e.notes,
    e.created_at,
    a.archived_at,
    a.archived_reason
   FROM (public.agent_archive_events e
     JOIN public.agents a ON ((a.id = e.agent_id)))
  WHERE ((a.archived_at IS NOT NULL) AND ((a.tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
  ORDER BY e.created_at DESC;


--
-- Name: VIEW v_agent_archive_reason_tree; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_agent_archive_reason_tree IS 'ADR-026: Tenant-isolated agent archive events. Uses security_invoker=on with mandatory tenant filter.';


--
-- Name: v_agent_execution_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_agent_execution_health WITH (security_barrier='true', security_invoker='true') AS
 SELECT a.id AS agent_id,
    a.tenant_id,
    a.agent_name,
    a.status,
    a.last_heartbeat,
    a.agent_mode,
    a.agent_version,
    a.enrolled_at,
        CASE
            WHEN (a.last_heartbeat IS NULL) THEN 'never_seen'::text
            WHEN (a.last_heartbeat < (now() - '00:15:00'::interval)) THEN 'offline'::text
            WHEN (a.last_heartbeat < (now() - '00:05:00'::interval)) THEN 'degraded'::text
            WHEN (a.agent_mode = 'safe_mode'::text) THEN 'safe_mode'::text
            WHEN (le.last_execution_at IS NULL) THEN 'not_executing_jobs'::text
            WHEN (le.last_execution_at < (now() - '02:00:00'::interval)) THEN 'execution_stale'::text
            WHEN (COALESCE(jq.stale_queued, (0)::bigint) >= 3) THEN 'not_polling_jobs'::text
            ELSE 'healthy'::text
        END AS health_status,
        CASE
            WHEN (a.last_heartbeat IS NULL) THEN 'critical'::text
            WHEN (a.last_heartbeat < (now() - '00:15:00'::interval)) THEN 'critical'::text
            WHEN (a.last_heartbeat < (now() - '00:05:00'::interval)) THEN 'high'::text
            WHEN (a.agent_mode = 'safe_mode'::text) THEN 'high'::text
            WHEN (COALESCE(jq.stale_queued, (0)::bigint) >= 3) THEN 'medium'::text
            WHEN (le.last_execution_at IS NULL) THEN 'low'::text
            WHEN (le.last_execution_at < (now() - '02:00:00'::interval)) THEN 'medium'::text
            ELSE 'none'::text
        END AS severity,
        CASE
            WHEN (a.last_heartbeat IS NULL) THEN 'Agente nunca enviou heartbeat'::text
            WHEN (a.last_heartbeat < (now() - '00:15:00'::interval)) THEN 'Agente offline ha mais de 15 minutos'::text
            WHEN (a.last_heartbeat < (now() - '00:05:00'::interval)) THEN 'Agente com comunicacao degradada'::text
            WHEN (a.agent_mode = 'safe_mode'::text) THEN 'Agente em modo seguro'::text
            WHEN (COALESCE(jq.stale_queued, (0)::bigint) >= 3) THEN 'Jobs acumulados sem processamento'::text
            WHEN (le.last_execution_at IS NULL) THEN 'Nenhum job executado ainda'::text
            WHEN (le.last_execution_at < (now() - '02:00:00'::interval)) THEN 'Execucao de jobs estagnada'::text
            ELSE 'Agente saudavel'::text
        END AS health_description,
    now() AS checked_at,
    (EXTRACT(epoch FROM (now() - a.last_heartbeat)))::integer AS seconds_since_heartbeat,
    ((EXTRACT(epoch FROM (now() - a.last_heartbeat)) / (60)::numeric))::integer AS minutes_since_heartbeat,
    ((EXTRACT(epoch FROM (now() - le.last_execution_at)) / (60)::numeric))::integer AS minutes_since_execution,
    le.last_execution_at,
    (COALESCE(jq.stale_queued, (0)::bigint))::integer AS stale_queued_jobs,
    (COALESCE(jq.stale_delivered, (0)::bigint))::integer AS stale_delivered_jobs,
    (COALESCE(jq.pending, (0)::bigint))::integer AS pending_jobs
   FROM ((public.agents a
     LEFT JOIN LATERAL ( SELECT max(je.finished_at) AS last_execution_at
           FROM public.job_executions_old je
          WHERE (je.agent_id = a.id)) le ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) FILTER (WHERE ((j.status = 'queued'::text) AND (j.created_at < (now() - '01:00:00'::interval)))) AS stale_queued,
            count(*) FILTER (WHERE ((j.status = 'delivered'::text) AND (j.created_at < (now() - '01:00:00'::interval)))) AS stale_delivered,
            count(*) FILTER (WHERE (j.status = ANY (ARRAY['queued'::text, 'delivered'::text]))) AS pending
           FROM public.jobs j
          WHERE (j.agent_id = a.id)) jq ON (true))
  WHERE ((a.archived_at IS NULL) AND (auth.uid() IS NOT NULL) AND ((a.tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()));


--
-- Name: v_agent_health_by_node; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_agent_health_by_node WITH (security_barrier='true', security_invoker='true') AS
 SELECT tenant_id,
    hostname,
    count(*) AS total_agents,
    count(*) FILTER (WHERE ((status = 'active'::text) AND (last_heartbeat > (now() - '00:12:00'::interval)))) AS healthy,
    count(*) FILTER (WHERE (last_heartbeat < (now() - '00:12:00'::interval))) AS unhealthy,
    count(*) FILTER (WHERE (is_isolated = true)) AS isolated
   FROM public.agents
  WHERE ((archived_at IS NULL) AND (auth.uid() IS NOT NULL) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
  GROUP BY tenant_id, hostname;


--
-- Name: VIEW v_agent_health_by_node; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_agent_health_by_node IS 'SSA-SEC-010: Hardened with security_invoker, security_barrier, auth.uid() filter';


--
-- Name: v_agent_health_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_agent_health_summary WITH (security_barrier='true', security_invoker='true') AS
 SELECT tenant_id,
    count(*) AS total_agents,
    count(*) FILTER (WHERE ((status = 'active'::text) AND (last_heartbeat > (now() - '00:12:00'::interval)))) AS online,
    count(*) FILTER (WHERE ((last_heartbeat < (now() - '00:12:00'::interval)) AND (last_heartbeat > (now() - '00:30:00'::interval)))) AS degraded,
    count(*) FILTER (WHERE ((last_heartbeat < (now() - '00:30:00'::interval)) OR (last_heartbeat IS NULL))) AS offline,
    count(*) FILTER (WHERE (is_isolated = true)) AS isolated,
    count(*) FILTER (WHERE (agent_state = 'safe_mode'::text)) AS safe_mode
   FROM public.agents
  WHERE ((archived_at IS NULL) AND (auth.uid() IS NOT NULL) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
  GROUP BY tenant_id;


--
-- Name: VIEW v_agent_health_summary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_agent_health_summary IS 'SSA-SEC-010: Hardened with security_invoker, security_barrier, auth.uid() filter';


--
-- Name: v_agent_lifecycle_state; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_agent_lifecycle_state WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    id AS agent_id,
    tenant_id,
    agent_name,
    display_name,
    status,
    agent_state,
    enrolled_at,
    last_heartbeat,
    archived_at,
    archived_reason,
    enrolled_at AS command_copied_at,
    last_heartbeat AS agent_installed_at,
        CASE
            WHEN ((enrolled_at IS NOT NULL) AND (last_heartbeat IS NOT NULL)) THEN (EXTRACT(epoch FROM (last_heartbeat - enrolled_at)) / 60.0)
            ELSE NULL::numeric
        END AS minutes_between_copy_and_install,
        CASE
            WHEN (archived_at IS NOT NULL) THEN 'archived'::text
            WHEN (agent_state = 'safe_mode'::text) THEN 'safe_mode'::text
            WHEN is_isolated THEN 'isolated'::text
            WHEN (last_heartbeat < (now() - '00:30:00'::interval)) THEN 'offline'::text
            WHEN (last_heartbeat IS NOT NULL) THEN 'active'::text
            WHEN ((enrolled_at IS NOT NULL) AND (last_heartbeat IS NULL)) THEN 'pending_install'::text
            ELSE 'enrolled_only'::text
        END AS lifecycle_status,
        CASE
            WHEN ((enrolled_at IS NOT NULL) AND (last_heartbeat IS NULL) AND (enrolled_at < (now() - '00:30:00'::interval))) THEN true
            ELSE false
        END AS is_stuck
   FROM public.agents a
  WHERE ((archived_at IS NULL) AND (auth.uid() IS NOT NULL) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()));


--
-- Name: VIEW v_agent_lifecycle_state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_agent_lifecycle_state IS 'SSA-SEC-010: Hardened with security_invoker, security_barrier, auth.uid() filter';


--
-- Name: v_agent_state; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_agent_state WITH (security_barrier='true', security_invoker='true') AS
 SELECT id AS agent_id,
    id,
    tenant_id,
    hostname,
    agent_name,
    display_name,
    last_heartbeat,
    agent_version,
    agent_state,
    agent_state_reason,
    is_isolated,
    is_throttled,
    safe_mode_reason,
    safe_mode_entered_at,
        CASE
            WHEN (archived_at IS NOT NULL) THEN 'archived'::text
            WHEN is_isolated THEN 'isolated'::text
            WHEN (agent_state = 'safe_mode'::text) THEN 'safe_mode'::text
            WHEN (last_heartbeat IS NULL) THEN 'never_connected'::text
            WHEN (last_heartbeat < (now() - '00:30:00'::interval)) THEN 'offline'::text
            WHEN (last_heartbeat < (now() - '00:12:00'::interval)) THEN 'warning'::text
            ELSE 'healthy'::text
        END AS canonical_state,
    EXTRACT(epoch FROM (now() - last_heartbeat)) AS heartbeat_lag_seconds,
    round((EXTRACT(epoch FROM (now() - last_heartbeat)) / 60.0), 1) AS heartbeat_lag_minutes,
    now() AS snapshot_at
   FROM public.agents a
  WHERE ((status = 'active'::text) AND (archived_at IS NULL) AND (auth.uid() IS NOT NULL) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()));


--
-- Name: VIEW v_agent_state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_agent_state IS 'SSA-SEC-010: Hardened with security_invoker, security_barrier, auth.uid() filter';


--
-- Name: v_ai_anomalies; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_ai_anomalies WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    tenant_id,
    function_name,
    anomaly_type,
    severity,
    context,
    detected_at,
    reviewed_by,
    reviewed_at,
    resolution,
    created_at
   FROM public.ai_anomalies
  WHERE ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin());


--
-- Name: v_ai_function_performance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_ai_function_performance WITH (security_barrier='true', security_invoker='true') AS
 SELECT function_name,
    count(*) AS requests_24h,
    round(avg(latency_ms)) AS avg_latency_ms,
    round((avg(
        CASE
            WHEN success THEN 1
            ELSE 0
        END) * (100)::numeric), 1) AS success_rate_pct,
    round((sum(COALESCE(cost_usd, (0)::numeric)) * (100)::numeric), 4) AS cost_cents_24h,
    round(avg(tokens_total)) AS avg_tokens,
    max(created_at) AS last_request
   FROM public.ai_inference_metrics
  WHERE ((created_at > (now() - '24:00:00'::interval)) AND ((tenant_id = public.current_user_tenant_id()) OR public.is_current_super_admin()))
  GROUP BY function_name
  ORDER BY (count(*)) DESC;


--
-- Name: VIEW v_ai_function_performance; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_ai_function_performance IS 'Performance de funções AI por tenant - isolado via security_invoker + tenant filter';


--
-- Name: v_ai_hourly_trends; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_ai_hourly_trends WITH (security_barrier='true', security_invoker='true') AS
 SELECT date_trunc('hour'::text, created_at) AS hour,
    count(*) AS requests,
    round(avg(latency_ms)) AS avg_latency_ms,
    round((avg(
        CASE
            WHEN success THEN 1
            ELSE 0
        END) * (100)::numeric), 1) AS success_rate_pct,
    round((sum(COALESCE(cost_usd, (0)::numeric)) * (100)::numeric), 4) AS cost_cents,
    sum(tokens_total) AS total_tokens
   FROM public.ai_inference_metrics
  WHERE ((created_at > (now() - '7 days'::interval)) AND ((tenant_id = public.current_user_tenant_id()) OR public.is_current_super_admin()))
  GROUP BY (date_trunc('hour'::text, created_at))
  ORDER BY (date_trunc('hour'::text, created_at)) DESC;


--
-- Name: VIEW v_ai_hourly_trends; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_ai_hourly_trends IS 'Tendências horárias de AI por tenant - isolado via security_invoker + tenant filter';


--
-- Name: v_ai_provider_performance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_ai_provider_performance WITH (security_barrier='true', security_invoker='true') AS
 SELECT COALESCE(provider, 'unknown'::text) AS provider,
    count(*) AS requests_24h,
    round(avg(latency_ms)) AS avg_latency_ms,
    round(percentile_cont((0.95)::double precision) WITHIN GROUP (ORDER BY ((latency_ms)::double precision))) AS p95_latency_ms,
    round((avg(
        CASE
            WHEN success THEN 1
            ELSE 0
        END) * (100)::numeric), 1) AS success_rate_pct,
    round((avg(
        CASE
            WHEN used_fallback THEN 1
            ELSE 0
        END) * (100)::numeric), 1) AS fallback_rate_pct,
    sum(tokens_total) AS total_tokens,
    round((sum(COALESCE(cost_usd, (0)::numeric)) * (100)::numeric), 4) AS cost_cents_24h
   FROM public.ai_inference_metrics
  WHERE ((created_at > (now() - '24:00:00'::interval)) AND ((tenant_id = public.current_user_tenant_id()) OR public.is_current_super_admin()))
  GROUP BY COALESCE(provider, 'unknown'::text)
  ORDER BY (count(*)) DESC;


--
-- Name: VIEW v_ai_provider_performance; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_ai_provider_performance IS 'Performance de provedores AI por tenant - isolado via security_invoker + tenant filter';


--
-- Name: v_job_health_anomalies; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_job_health_anomalies WITH (security_barrier='true', security_invoker='true') AS
 SELECT 'pending_approved'::text AS anomaly_type,
    count(*) AS count,
    min(jobs.created_at) AS oldest
   FROM public.jobs
  WHERE ((jobs.status = 'pending'::text) AND (jobs.approved = true) AND ((jobs.tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
UNION ALL
 SELECT 'terminal_no_completed_at'::text AS anomaly_type,
    count(*) AS count,
    min(jobs.created_at) AS oldest
   FROM public.jobs
  WHERE ((jobs.status = ANY (ARRAY['failed'::text, 'completed'::text, 'cancelled'::text])) AND (jobs.completed_at IS NULL) AND ((jobs.tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
UNION ALL
 SELECT 'failed_no_dlq'::text AS anomaly_type,
    count(*) AS count,
    min(j.created_at) AS oldest
   FROM (public.jobs j
     LEFT JOIN public.failed_jobs_dlq dlq ON ((dlq.original_job_id = j.id)))
  WHERE ((j.status = 'failed'::text) AND (dlq.id IS NULL) AND ((j.tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
UNION ALL
 SELECT 'zombie_delivered'::text AS anomaly_type,
    count(*) AS count,
    min(jobs.delivered_at) AS oldest
   FROM public.jobs
  WHERE ((jobs.status = 'delivered'::text) AND (jobs.delivered_at < (now() - '02:00:00'::interval)) AND ((jobs.tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
UNION ALL
 SELECT 'expired_active_keys'::text AS anomaly_type,
    count(*) AS count,
    min(enrollment_keys.expires_at) AS oldest
   FROM public.enrollment_keys
  WHERE ((enrollment_keys.expires_at < now()) AND (enrollment_keys.is_active = true) AND ((enrollment_keys.tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
UNION ALL
 SELECT 'failed_no_execution'::text AS anomaly_type,
    count(*) AS count,
    min(j.completed_at) AS oldest
   FROM public.jobs j
  WHERE ((j.status = 'failed'::text) AND (NOT (EXISTS ( SELECT 1
           FROM public.job_executions_old je
          WHERE (je.job_id = j.id)))) AND (j.completed_at > (now() - '7 days'::interval)) AND ((j.tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()));


--
-- Name: VIEW v_job_health_anomalies; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_job_health_anomalies IS 'Consolidated job engine health anomalies view. Updated 2026-01-10 to include failed_no_execution detection per ADR-037.';


--
-- Name: v_anomalies_without_runbook; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_anomalies_without_runbook WITH (security_barrier='true', security_invoker='true') AS
 SELECT DISTINCT anomaly_type
   FROM public.v_job_health_anomalies
  WHERE ((NOT (anomaly_type IN ( SELECT runbooks.anomaly_type
           FROM public.runbooks))) AND (auth.uid() IS NOT NULL));


--
-- Name: v_audit_integrity_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_audit_integrity_status WITH (security_barrier='true', security_invoker='true') AS
 SELECT tenant_id,
    count(*) AS total_records,
    count(*) FILTER (WHERE (integrity_hash IS NOT NULL)) AS with_hash,
    count(*) FILTER (WHERE (integrity_hash IS NULL)) AS without_hash,
    max(created_at) AS last_audit_at
   FROM public.audit_logs_old
  WHERE ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin())
  GROUP BY tenant_id;


--
-- Name: v_audit_moving_average; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_audit_moving_average WITH (security_barrier='true', security_invoker='true') AS
 SELECT tenant_id,
    date_trunc('hour'::text, created_at) AS hour,
    count(*) AS event_count,
    count(DISTINCT user_id) AS unique_users,
    count(DISTINCT action) AS unique_actions
   FROM public.audit_logs_old
  WHERE ((created_at > (now() - '24:00:00'::interval)) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
  GROUP BY tenant_id, (date_trunc('hour'::text, created_at))
  ORDER BY (date_trunc('hour'::text, created_at)) DESC;


--
-- Name: v_confidence_gap_trend; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_confidence_gap_trend WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    tenant_id,
    audit_id,
    red_team_id,
    ana_score,
    red_score,
    confidence_gap,
    health_status,
    previous_gap,
    gap_delta,
    alert_triggered,
    alert_reason,
    dimension_gaps,
    created_at,
    lag(confidence_gap) OVER (PARTITION BY tenant_id ORDER BY created_at) AS prev_gap,
    avg(confidence_gap) OVER (PARTITION BY tenant_id ORDER BY created_at ROWS BETWEEN 30 PRECEDING AND CURRENT ROW) AS avg_gap_30d,
    avg(confidence_gap) OVER (PARTITION BY tenant_id ORDER BY created_at ROWS BETWEEN 90 PRECEDING AND CURRENT ROW) AS avg_gap_90d,
        CASE
            WHEN (confidence_gap < lag(confidence_gap) OVER (PARTITION BY tenant_id ORDER BY created_at)) THEN true
            ELSE false
        END AS is_improving
   FROM public.audit_confidence_gaps cg
  WHERE ((auth.uid() IS NOT NULL) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()));


--
-- Name: VIEW v_confidence_gap_trend; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_confidence_gap_trend IS 'ADR-026: Hardened with security_invoker and active tenant isolation.';


--
-- Name: v_critical_unassigned_tasks; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_critical_unassigned_tasks WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    tenant_id,
    title,
    severity,
    source_type,
    status,
    created_at,
    (EXTRACT(epoch FROM (now() - created_at)) / (3600)::numeric) AS age_hours,
    (sla_breached_at IS NOT NULL) AS sla_breached,
    due_at
   FROM public.tasks t
  WHERE ((status = ANY (ARRAY['open'::text, 'in_progress'::text])) AND (severity = 'critical'::text) AND (assigned_to IS NULL) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
  ORDER BY created_at;


--
-- Name: VIEW v_critical_unassigned_tasks; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_critical_unassigned_tasks IS 'Critical tasks without assignment. For auto-assignment and escalation monitoring.';


--
-- Name: v_cron_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_cron_health WITH (security_barrier='true', security_invoker='true') AS
 SELECT cron_name,
    last_success_at,
    consecutive_failures,
        CASE
            WHEN (last_success_at IS NULL) THEN 'never_run'::text
            WHEN (consecutive_failures >= 3) THEN 'critical'::text
            WHEN (consecutive_failures >= 1) THEN 'warning'::text
            WHEN ((last_success_at < (now() - '02:00:00'::interval)) AND (cron_name ~~ '%15min%'::text)) THEN 'stale'::text
            WHEN ((last_success_at < (now() - '12:00:00'::interval)) AND (cron_name ~~ '%6h%'::text)) THEN 'stale'::text
            WHEN ((last_success_at < (now() - '48:00:00'::interval)) AND (cron_name ~~ '%daily%'::text)) THEN 'stale'::text
            ELSE 'healthy'::text
        END AS status
   FROM public.cron_health_checks
  WHERE (auth.uid() IS NOT NULL);


--
-- Name: VIEW v_cron_health; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_cron_health IS 'Zero-Gap: Cron health monitoring (SSA-SEC-010 hardened)';


--
-- Name: v_cron_silence; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_cron_silence WITH (security_barrier='true', security_invoker='true') AS
 SELECT job_key,
    last_seen_at,
    expected_interval,
    (now() - last_seen_at) AS silence_duration,
    missed_count,
    last_error,
        CASE
            WHEN ((now() - last_seen_at) > (expected_interval * (3)::double precision)) THEN 'critical'::text
            WHEN ((now() - last_seen_at) > (expected_interval * (2)::double precision)) THEN 'warning'::text
            ELSE 'ok'::text
        END AS status
   FROM public.scheduled_job_heartbeat h
  WHERE (((now() - last_seen_at) > expected_interval) AND public.is_current_super_admin());


--
-- Name: VIEW v_cron_silence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_cron_silence IS 'ADR-026: Super-admin only cron silence monitoring. Uses security_invoker=on.';


--
-- Name: v_cron_silent_failures; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_cron_silent_failures WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    tenant_id,
    name AS job_name,
    cron_expr AS cron_expression,
    last_run_at,
    next_run_at,
        CASE
            WHEN (enabled = false) THEN 'disabled'::text
            WHEN (last_run_at < (now() - '02:00:00'::interval)) THEN 'failed'::text
            ELSE 'active'::text
        END AS status,
    enabled
   FROM public.scheduled_jobs
  WHERE (((enabled = false) OR ((enabled = true) AND (last_run_at < (now() - '02:00:00'::interval)))) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()));


--
-- Name: v_database_size_report; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_database_size_report WITH (security_barrier='true', security_invoker='true') AS
 SELECT schemaname,
    relname AS table_name,
    pg_size_pretty(pg_total_relation_size((relid)::regclass)) AS total_size,
    pg_size_pretty(pg_relation_size((relid)::regclass)) AS table_size,
    pg_size_pretty((pg_total_relation_size((relid)::regclass) - pg_relation_size((relid)::regclass))) AS index_size,
    n_tup_ins AS rows_inserted,
    n_tup_del AS rows_deleted,
    last_autovacuum
   FROM pg_stat_user_tables
  WHERE ((schemaname = 'public'::name) AND public.is_current_super_admin())
  ORDER BY (pg_total_relation_size((relid)::regclass)) DESC;


--
-- Name: VIEW v_database_size_report; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_database_size_report IS 'Global view - restricted to super_admin only (V-303)';


--
-- Name: v_dlq_pending_attention; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dlq_pending_attention WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    tenant_id,
    job_type,
    error_message,
    status,
    created_at,
    retry_count,
    original_job_id
   FROM public.failed_jobs_dlq
  WHERE ((status = 'pending'::text) AND (auth.uid() IS NOT NULL) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
  ORDER BY created_at DESC
 LIMIT 50;


--
-- Name: VIEW v_dlq_pending_attention; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_dlq_pending_attention IS 'SSA-SEC-010: Hardened with security_invoker, security_barrier, auth.uid() filter';


--
-- Name: v_dlq_risk_overview; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dlq_risk_overview WITH (security_barrier='true', security_invoker='true') AS
 SELECT tenant_id,
    count(*) AS total_items,
    count(*) FILTER (WHERE (status = 'resolved'::text)) AS resolved_items,
    count(*) FILTER (WHERE (resolved_by IS NOT NULL)) AS manually_reviewed,
    count(*) FILTER (WHERE flagged_suspicious) AS suspicious_items,
    count(*) FILTER (WHERE ((created_at < (now() - '24:00:00'::interval)) AND (status <> 'resolved'::text))) AS overdue_items,
    round(
        CASE
            WHEN (count(*) > 0) THEN (((count(*) FILTER (WHERE (resolved_by IS NOT NULL)))::numeric / (count(*))::numeric) * (100)::numeric)
            ELSE (0)::numeric
        END, 2) AS review_rate_pct
   FROM public.failed_jobs_dlq
  WHERE ((created_at > (now() - '30 days'::interval)) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
  GROUP BY tenant_id;


--
-- Name: v_edge_function_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_edge_function_stats WITH (security_barrier='true', security_invoker='true') AS
 SELECT tenant_id,
    function_name,
    count(*) AS total_calls,
    count(*) FILTER (WHERE (success = true)) AS successful,
    count(*) FILTER (WHERE (success = false)) AS failed,
    avg(latency_ms) AS avg_execution_ms,
    count(*) FILTER (WHERE (success = true)) AS successful_calls,
    count(*) FILTER (WHERE (success = false)) AS failed_calls,
    avg(latency_ms) AS avg_latency_ms,
    percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((latency_ms)::double precision)) AS p50_latency_ms,
    percentile_cont((0.95)::double precision) WITHIN GROUP (ORDER BY ((latency_ms)::double precision)) AS p95_latency_ms,
    percentile_cont((0.99)::double precision) WITHIN GROUP (ORDER BY ((latency_ms)::double precision)) AS p99_latency_ms,
    min(latency_ms) AS min_latency_ms,
    max(latency_ms) AS max_latency_ms,
    min(created_at) AS first_call,
    max(created_at) AS last_call
   FROM public.edge_function_metrics
  WHERE ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin())
  GROUP BY tenant_id, function_name;


--
-- Name: v_enforcement_compliance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_enforcement_compliance WITH (security_barrier='true', security_invoker='true') AS
 SELECT sp.tenant_id,
    sp.id AS policy_id,
    sp.name AS policy_name,
    sp.priority,
    sp.enabled,
    sp.is_active,
    count(pa.id) AS assigned_targets
   FROM (public.security_policies sp
     LEFT JOIN public.policy_assignments pa ON ((pa.policy_id = sp.id)))
  WHERE ((sp.tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin())
  GROUP BY sp.tenant_id, sp.id, sp.name, sp.priority, sp.enabled, sp.is_active;


--
-- Name: v_event_buffer_pending; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_event_buffer_pending WITH (security_invoker='true') AS
 SELECT id,
    tenant_id,
    agent_id,
    event_category,
    payload,
    received_at,
    processed_at,
    batch_id
   FROM public.endpoint_event_buffer_partitioned
  WHERE (processed_at IS NULL);


--
-- Name: v_execution_chain_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_execution_chain_health WITH (security_barrier='true', security_invoker='true') AS
 SELECT ec.agent_id,
    ec.last_execution_hash,
    ec.last_execution_index,
    ec.updated_at,
    a.agent_name,
    a.tenant_id,
    a.status,
    (now() - ec.updated_at) AS time_since_last_execution
   FROM (public.agent_execution_chain ec
     JOIN public.agents a ON ((a.id = ec.agent_id)))
  WHERE ((a.tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin());


--
-- Name: v_governance_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_governance_stats WITH (security_barrier='true', security_invoker='true') AS
 SELECT tenant_id,
    count(*) AS total_reports,
    count(*) FILTER (WHERE (approved_at IS NOT NULL)) AS approved,
    count(*) FILTER (WHERE (approved_at IS NULL)) AS pending,
    max(generated_at) AS last_report_at
   FROM public.governance_reports
  WHERE ((auth.uid() IS NOT NULL) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
  GROUP BY tenant_id;


--
-- Name: VIEW v_governance_stats; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_governance_stats IS 'SSA-SEC-010: Hardened with security_invoker, security_barrier, auth.uid() filter';


--
-- Name: v_incident_groups; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_incident_groups WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    fingerprint_hash,
    source_type,
    failure_class,
    normalized_signature,
    severity_hint,
    total_occurrences,
    distinct_tenants,
    distinct_agents,
    first_seen_at,
    last_seen_at,
    is_active,
    is_trending,
    (last_seen_at > (now() - '04:00:00'::interval)) AS is_ongoing,
    COALESCE(( SELECT count(*) AS count
           FROM public.failure_occurrences fo
          WHERE ((fo.fingerprint_id = fp.id) AND (fo.occurred_at > (now() - '24:00:00'::interval)) AND ((fo.tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))), (0)::bigint) AS occurrences_24h
   FROM public.failure_fingerprints fp
  WHERE ((is_active = true) AND (public.is_current_super_admin() OR (EXISTS ( SELECT 1
           FROM public.failure_occurrences fo
          WHERE ((fo.fingerprint_id = fp.id) AND (fo.tenant_id = public.get_active_tenant_id()))))))
  ORDER BY
        CASE severity_hint
            WHEN 'critical'::text THEN 1
            WHEN 'high'::text THEN 2
            WHEN 'medium'::text THEN 3
            ELSE 4
        END, last_seen_at DESC;


--
-- Name: v_incident_groups_with_slo; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_incident_groups_with_slo WITH (security_barrier='true', security_invoker='true') AS
 SELECT ig.id,
    ig.fingerprint_hash,
    ig.source_type,
    ig.failure_class,
    ig.normalized_signature,
    ig.severity_hint,
    ig.total_occurrences,
    ig.distinct_tenants,
    ig.distinct_agents,
    ig.first_seen_at,
    ig.last_seen_at,
    ig.is_active,
    ig.is_ongoing,
    COALESCE(slo.slo_target, 99.0) AS slo_target,
    COALESCE(slo.error_budget, 0.01) AS error_budget,
    COALESCE(slo.burn_rate_1h, (0)::numeric) AS burn_rate_1h,
    COALESCE(slo.burn_rate_6h, (0)::numeric) AS burn_rate_6h,
    COALESCE(slo.burn_rate_24h, (0)::numeric) AS burn_rate_24h,
    COALESCE(slo.budget_consumed, (0)::numeric) AS budget_consumed,
    COALESCE(slo.budget_remaining, (100)::numeric) AS budget_remaining,
    COALESCE(slo.status, 'ok'::text) AS slo_status,
    COALESCE(slo.occurrences_1h, 0) AS occurrences_1h,
    COALESCE(slo.occurrences_6h, 0) AS occurrences_6h,
    slo.last_evaluated_at
   FROM (public.v_incident_groups ig
     LEFT JOIN public.incident_slo_state slo ON ((slo.fingerprint_id = ig.id)))
  WHERE ((auth.uid() IS NOT NULL) AND public.is_current_super_admin())
  ORDER BY COALESCE(slo.burn_rate_1h, (0)::numeric) DESC NULLS LAST, (ig.severity_hint = 'critical'::text) DESC, ig.total_occurrences DESC;


--
-- Name: v_integrity_score; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_integrity_score WITH (security_barrier='true', security_invoker='true') AS
 WITH release_stats AS (
         SELECT count(*) FILTER (WHERE (agent_releases.is_active = true)) AS active_releases,
            count(*) FILTER (WHERE ((agent_releases.is_active = true) AND (agent_releases.signature_base64 IS NOT NULL))) AS valid_active_releases,
            count(*) AS total_releases,
            count(*) FILTER (WHERE (agent_releases.signature_base64 IS NOT NULL)) AS signed_releases
           FROM public.agent_releases
          WHERE public.is_current_super_admin()
        ), job_stats AS (
         SELECT count(*) AS total_jobs,
            count(*) FILTER (WHERE (jobs.status = 'completed'::text)) AS completed_jobs,
            count(*) FILTER (WHERE ((jobs.status = 'completed'::text) AND (jobs.output IS NOT NULL))) AS valid_completed_jobs,
            count(*) FILTER (WHERE (jobs.status = 'failed'::text)) AS failed_jobs,
            count(*) FILTER (WHERE ((jobs.status = 'failed'::text) AND (jobs.error_message IS NOT NULL))) AS failed_with_error
           FROM public.jobs
          WHERE ((jobs.created_at >= (now() - '7 days'::interval)) AND public.is_current_super_admin() AND ((jobs.tenant_id = public.get_active_tenant_id()) OR (public.get_active_tenant_id() IS NULL)))
        )
 SELECT COALESCE(
        CASE
            WHEN (rs.active_releases > 0) THEN round((((rs.valid_active_releases)::numeric / (rs.active_releases)::numeric) * (100)::numeric), 1)
            ELSE (100)::numeric
        END, (100)::numeric) AS supply_chain_score,
    COALESCE(
        CASE
            WHEN (js.completed_jobs > 0) THEN round((((js.valid_completed_jobs)::numeric / (js.completed_jobs)::numeric) * (100)::numeric), 1)
            ELSE (100)::numeric
        END, (100)::numeric) AS job_integrity_score,
    COALESCE(
        CASE
            WHEN (js.failed_jobs > 0) THEN round((((js.failed_with_error)::numeric / (js.failed_jobs)::numeric) * (100)::numeric), 1)
            ELSE (100)::numeric
        END, (100)::numeric) AS failed_jobs_score,
    COALESCE(round(((((
        CASE
            WHEN (rs.active_releases > 0) THEN ((rs.valid_active_releases)::numeric / (rs.active_releases)::numeric)
            ELSE (1)::numeric
        END * 0.4) + (
        CASE
            WHEN (js.completed_jobs > 0) THEN ((js.valid_completed_jobs)::numeric / (js.completed_jobs)::numeric)
            ELSE (1)::numeric
        END * 0.4)) + (
        CASE
            WHEN (js.failed_jobs > 0) THEN ((js.failed_with_error)::numeric / (js.failed_jobs)::numeric)
            ELSE (1)::numeric
        END * 0.2)) * (100)::numeric), 1), (100)::numeric) AS global_integrity_score,
    COALESCE(rs.active_releases, (0)::bigint) AS active_releases,
    COALESCE(rs.valid_active_releases, (0)::bigint) AS valid_active_releases,
    COALESCE(rs.total_releases, (0)::bigint) AS total_releases,
    COALESCE(rs.signed_releases, (0)::bigint) AS signed_releases,
    COALESCE(js.completed_jobs, (0)::bigint) AS completed_jobs,
    COALESCE(js.valid_completed_jobs, (0)::bigint) AS valid_completed_jobs,
    COALESCE(js.failed_jobs, (0)::bigint) AS failed_jobs,
    COALESCE(js.failed_with_error, (0)::bigint) AS failed_with_error,
    now() AS calculated_at
   FROM (release_stats rs
     CROSS JOIN job_stats js);


--
-- Name: VIEW v_integrity_score; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_integrity_score IS 'ADR-VELLUM V-201: Global integrity metrics - super_admin only via is_current_super_admin(). Intentionally global for cross-tenant monitoring.';


--
-- Name: v_job_execution_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_job_execution_health WITH (security_barrier='true', security_invoker='true') AS
 SELECT j.tenant_id,
    count(*) FILTER (WHERE (j.status = 'delivered'::text)) AS delivered_count,
    count(*) FILTER (WHERE (j.status = 'completed'::text)) AS completed_count,
    count(*) FILTER (WHERE (j.status = 'failed'::text)) AS failed_count,
    count(*) FILTER (WHERE ((j.status = 'completed'::text) AND (j.finished_at > j.expires_at))) AS expired_completed_count,
    count(*) FILTER (WHERE (j.id IN ( SELECT je2.job_id
           FROM public.job_executions_old je2
          GROUP BY je2.job_id
         HAVING (count(*) > 1)))) AS duplicate_execution_jobs,
    avg(EXTRACT(epoch FROM (j.delivered_at - j.created_at))) AS avg_queue_time_seconds,
    avg(je.execution_time_seconds) FILTER (WHERE (j.status = 'completed'::text)) AS avg_execution_time_seconds,
    now() AS calculated_at
   FROM (public.jobs j
     LEFT JOIN public.job_executions_old je ON ((j.current_execution_id = je.id)))
  WHERE ((j.created_at > (now() - '24:00:00'::interval)) AND ((j.tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
  GROUP BY j.tenant_id;


--
-- Name: v_job_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_job_health WITH (security_barrier='true', security_invoker='true') AS
 SELECT job_key,
    job_source,
    count(*) AS total_runs_24h,
    count(*) FILTER (WHERE (success IS TRUE)) AS success_count_24h,
    count(*) FILTER (WHERE (success IS FALSE)) AS failure_count_24h,
    max(ran_at) AS last_run,
    max(ran_at) FILTER (WHERE (success IS TRUE)) AS last_success,
    max(ran_at) FILTER (WHERE (success IS FALSE)) AS last_failure,
    (avg(duration_ms))::numeric(10,2) AS avg_duration_ms,
    (max(duration_ms))::numeric(10,2) AS max_duration_ms,
        CASE
            WHEN (count(*) = 0) THEN 'never_ran'::text
            WHEN (max(ran_at) < (now() - '02:00:00'::interval)) THEN 'stale'::text
            WHEN (count(*) FILTER (WHERE ((success IS FALSE) AND (ran_at > (now() - '01:00:00'::interval)))) > 3) THEN 'critical'::text
            WHEN (count(*) FILTER (WHERE ((success IS FALSE) AND (ran_at > (now() - '02:00:00'::interval)))) > 0) THEN 'warning'::text
            ELSE 'healthy'::text
        END AS health_status,
        CASE
            WHEN (count(*) = 0) THEN 'low'::text
            WHEN (max(ran_at) < (now() - '02:00:00'::interval)) THEN 'medium'::text
            WHEN (count(*) FILTER (WHERE ((success IS FALSE) AND (ran_at > (now() - '01:00:00'::interval)))) > 3) THEN 'critical'::text
            WHEN (count(*) FILTER (WHERE ((success IS FALSE) AND (ran_at > (now() - '02:00:00'::interval)))) > 0) THEN 'high'::text
            ELSE 'low'::text
        END AS severity
   FROM public.scheduled_job_runs
  WHERE ((ran_at > (now() - '24:00:00'::interval)) AND (auth.uid() IS NOT NULL) AND ((tenant_id = public.get_active_tenant_id()) OR ((public.get_active_tenant_id() IS NULL) AND public.is_current_super_admin())))
  GROUP BY job_key, job_source;


--
-- Name: v_job_hourly_trends; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_job_hourly_trends WITH (security_barrier='true', security_invoker='true') AS
 SELECT tenant_id,
    date_trunc('hour'::text, created_at) AS hour,
    count(*) AS total,
    count(*) FILTER (WHERE (status = 'completed'::text)) AS completed,
    count(*) FILTER (WHERE (status = 'failed'::text)) AS failed,
    round((((count(*) FILTER (WHERE (status = 'completed'::text)))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 1) AS success_rate_pct
   FROM public.jobs
  WHERE ((created_at > (now() - '24:00:00'::interval)) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
  GROUP BY tenant_id, (date_trunc('hour'::text, created_at))
  ORDER BY (date_trunc('hour'::text, created_at)) DESC;


--
-- Name: v_job_metrics_by_type; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_job_metrics_by_type WITH (security_barrier='true', security_invoker='true') AS
 SELECT tenant_id,
    type,
    count(*) AS total_count,
    count(*) FILTER (WHERE (status = 'completed'::text)) AS completed_count,
    count(*) FILTER (WHERE (status = 'failed'::text)) AS failed_count,
    avg(EXTRACT(epoch FROM (completed_at - created_at))) FILTER (WHERE (completed_at IS NOT NULL)) AS avg_duration_seconds
   FROM public.jobs j
  WHERE ((auth.uid() IS NOT NULL) AND (created_at > (now() - '24:00:00'::interval)) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
  GROUP BY tenant_id, type;


--
-- Name: VIEW v_job_metrics_by_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_job_metrics_by_type IS 'ADR-026: Hardened with security_invoker and active tenant isolation.';


--
-- Name: v_jobs_status_corrected; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_jobs_status_corrected WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    tenant_id,
    agent_id,
    type,
        CASE
            WHEN ((status = 'delivered'::text) AND (created_at < (now() - '02:00:00'::interval))) THEN 'stuck'::text
            WHEN ((status = 'queued'::text) AND (created_at < (now() - '01:00:00'::interval))) THEN 'stale'::text
            ELSE status
        END AS corrected_status,
    status AS original_status,
    created_at,
    completed_at,
    error_message
   FROM public.jobs j
  WHERE ((auth.uid() IS NOT NULL) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()));


--
-- Name: VIEW v_jobs_status_corrected; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_jobs_status_corrected IS 'ADR-026: Hardened with security_invoker and active tenant isolation.';


--
-- Name: v_legacy_agents_telemetry; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_legacy_agents_telemetry WITH (security_invoker='true') AS
 SELECT tenant_id,
    id AS agent_id,
    agent_name,
    agent_version,
    status,
    last_heartbeat,
    enrolled_at,
        CASE
            WHEN ((hmac_secret IS NULL) OR (hmac_secret = ''::text)) THEN false
            ELSE true
        END AS has_hmac,
        CASE
            WHEN (agent_version IS NULL) THEN 'unknown'::text
            WHEN (agent_version < '5.0.12'::text) THEN 'legacy'::text
            ELSE 'modern'::text
        END AS version_class
   FROM public.agents a
  WHERE (status = 'active'::text)
  ORDER BY tenant_id, agent_name;


--
-- Name: v_network_events_recent; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_network_events_recent WITH (security_invoker='true') AS
 SELECT id,
    tenant_id,
    agent_id,
    event_type,
    protocol,
    local_address,
    local_port,
    remote_address,
    remote_port,
    direction,
    process_name,
    process_pid,
    bytes_sent,
    bytes_received,
    domain,
    dns_query_type,
    dns_response,
    is_suspicious,
    detection_tags,
    geo_country,
    event_time,
    created_at
   FROM public.endpoint_network_events_partitioned
  WHERE (created_at >= (now() - '7 days'::interval));


--
-- Name: v_normalized_events; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_normalized_events WITH (security_barrier='true', security_invoker='true') AS
 SELECT endpoint_process_events.id,
    endpoint_process_events.tenant_id,
    endpoint_process_events.agent_id,
    endpoint_process_events.event_time,
    'process'::text AS event_category,
    endpoint_process_events.event_type,
    endpoint_process_events.process_name,
    endpoint_process_events.command_line,
    endpoint_process_events.sha256_hash AS file_hash,
    NULL::text AS file_path,
    NULL::text AS remote_address,
    NULL::integer AS remote_port,
    NULL::text AS domain,
    NULL::text AS key_path,
    endpoint_process_events.user_name,
    endpoint_process_events.pid AS process_pid,
    endpoint_process_events.parent_pid AS parent_process_pid,
    endpoint_process_events.parent_process_name,
    endpoint_process_events.mitre_technique_id,
    endpoint_process_events.mitre_tactic,
    endpoint_process_events.is_suspicious,
    endpoint_process_events.detection_tags,
    NULL::text AS severity,
    NULL::text AS detection_name,
    endpoint_process_events.created_at
   FROM public.endpoint_process_events
  WHERE (endpoint_process_events.tenant_id = public.get_active_tenant_id())
UNION ALL
 SELECT endpoint_file_events.id,
    endpoint_file_events.tenant_id,
    endpoint_file_events.agent_id,
    endpoint_file_events.event_time,
    'file'::text AS event_category,
    endpoint_file_events.event_type,
    endpoint_file_events.process_name,
    NULL::text AS command_line,
