--
-- Name: v_pending_critical_approvals; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_pending_critical_approvals WITH (security_barrier='true', security_invoker='true') AS
 SELECT ar.id,
    ar.tenant_id,
    ar.action_type,
    ar.action_payload,
    ar.status,
    ar.required_approvers,
    ar.current_approvers,
    ar.expires_at,
    ar.created_at,
    ar.playbook_execution_id,
    (pe.playbook_snapshot ->> 'name'::text) AS playbook_name,
    (pe.playbook_snapshot ->> 'severity'::text) AS severity,
    pe.risk_score,
    pe.dry_run,
    pe.trigger_source,
    a.agent_name,
    a.hostname
   FROM ((public.approval_requests ar
     LEFT JOIN public.playbook_executions pe ON ((pe.id = ar.playbook_execution_id)))
     LEFT JOIN public.agents a ON ((a.id = ar.target_agent_id)))
  WHERE ((ar.status = 'pending'::text) AND (ar.expires_at > now()) AND ((ar.tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()));


--
-- Name: VIEW v_pending_critical_approvals; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_pending_critical_approvals IS 'Human-in-the-loop: Pending approval requests requiring human review. Filtered by tenant.';


--
-- Name: v_pipeline_health_metrics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_pipeline_health_metrics WITH (security_barrier='true', security_invoker='true') AS
 SELECT tenant_id,
    date_trunc('hour'::text, created_at) AS hour,
    type,
    count(*) AS total_jobs,
    count(*) FILTER (WHERE (status = 'completed'::text)) AS completed_jobs,
    count(*) FILTER (WHERE (status = 'failed'::text)) AS failed_jobs,
    count(*) FILTER (WHERE (status = 'queued'::text)) AS queued_jobs,
    count(*) FILTER (WHERE (status = 'in_progress'::text)) AS in_progress_jobs,
    round(
        CASE
            WHEN (count(*) > 0) THEN (((count(*) FILTER (WHERE (status = 'completed'::text)))::numeric / (count(*))::numeric) * (100)::numeric)
            ELSE (0)::numeric
        END, 2) AS success_rate,
    count(*) FILTER (WHERE ((status = 'completed'::text) AND (type = 'collect_web_activity'::text) AND (EXISTS ( SELECT 1
           FROM public.agent_web_activity aw
          WHERE ((aw.agent_id = j.agent_id) AND (aw.created_at >= j.created_at)))))) AS completed_with_data,
    count(*) FILTER (WHERE ((status = 'completed'::text) AND (type = ANY (ARRAY['collect_web_activity'::text, 'software_inventory_collect'::text, 'collect_antivirus_status'::text])) AND (output IS NULL))) AS silent_failures
   FROM public.jobs j
  WHERE ((created_at >= (now() - '24:00:00'::interval)) AND (auth.uid() IS NOT NULL) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
  GROUP BY tenant_id, (date_trunc('hour'::text, created_at)), type
  ORDER BY (date_trunc('hour'::text, created_at)) DESC;


--
-- Name: VIEW v_pipeline_health_metrics; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_pipeline_health_metrics IS 'SSA-SEC-010: Hardened with security_invoker, security_barrier, auth.uid() filter';


--
-- Name: v_problematic_agents; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_problematic_agents WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    tenant_id,
    agent_name,
    display_name,
    hostname,
    status,
    agent_state,
    last_heartbeat,
    agent_version,
    enrolled_at,
    is_isolated,
    isolation_reason,
        CASE
            WHEN is_isolated THEN 'isolated'::text
            WHEN (agent_state = 'safe_mode'::text) THEN 'safe_mode'::text
            WHEN (last_heartbeat < (now() - '00:30:00'::interval)) THEN 'offline'::text
            WHEN (last_heartbeat < (now() - '00:12:00'::interval)) THEN 'degraded'::text
            ELSE 'unknown'::text
        END AS problem_type,
    GREATEST(last_heartbeat, isolated_at, agent_state_changed_at) AS problem_since
   FROM public.agents
  WHERE ((archived_at IS NULL) AND (is_isolated OR (agent_state = 'safe_mode'::text) OR (last_heartbeat < (now() - '00:12:00'::interval))) AND (auth.uid() IS NOT NULL) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()));


--
-- Name: v_problematic_jobs; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_problematic_jobs WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    tenant_id,
    agent_id,
    agent_name,
    type,
    status,
    created_at,
    delivered_at,
    error_message,
        CASE
            WHEN ((status = 'queued'::text) AND (created_at < (now() - '01:00:00'::interval))) THEN 'stuck_queued'::text
            WHEN ((status = 'delivered'::text) AND (delivered_at < (now() - '00:30:00'::interval))) THEN 'stuck_delivered'::text
            WHEN ((status = 'failed'::text) AND (error_message IS NOT NULL)) THEN 'failed_with_error'::text
            WHEN (status = 'failed'::text) THEN 'failed_silent'::text
            ELSE 'unknown'::text
        END AS problem_type,
    (EXTRACT(epoch FROM (now() - COALESCE(delivered_at, created_at))) / (60)::numeric) AS minutes_stuck
   FROM public.jobs
  WHERE ((((status = 'queued'::text) AND (created_at < (now() - '01:00:00'::interval))) OR ((status = 'delivered'::text) AND (delivered_at < (now() - '00:30:00'::interval))) OR (status = 'failed'::text)) AND (auth.uid() IS NOT NULL) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()));


--
-- Name: VIEW v_problematic_jobs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_problematic_jobs IS 'SSA-SEC-010: Hardened with security_invoker, security_barrier, auth.uid() filter';


--
-- Name: v_process_events_recent; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_process_events_recent WITH (security_invoker='true') AS
 SELECT id,
    tenant_id,
