    detection_tags,
    event_time,
    created_at
   FROM public.endpoint_process_events_partitioned
  WHERE (created_at >= (now() - '7 days'::interval));


--
-- Name: v_rbac_metrics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_rbac_metrics WITH (security_barrier='true', security_invoker='true') AS
 SELECT tenant_id,
    count(*) AS total_users,
    count(*) FILTER (WHERE (role = 'admin'::public.app_role)) AS admin_count,
    count(*) FILTER (WHERE (role = 'super_admin'::public.app_role)) AS super_admin_count,
    count(*) FILTER (WHERE (role = 'operator'::public.app_role)) AS operator_count,
    count(*) FILTER (WHERE (role = 'viewer'::public.app_role)) AS viewer_count,
    count(*) FILTER (WHERE (role = 'analyst'::public.app_role)) AS analyst_count,
    count(DISTINCT role) AS distinct_roles,
        CASE
            WHEN (count(*) > 0) THEN 'operational'::text
            ELSE 'incomplete'::text
        END AS rbac_status
   FROM public.user_roles
  WHERE ((auth.uid() IS NOT NULL) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
  GROUP BY tenant_id;


--
-- Name: v_risk_debt_active; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_risk_debt_active WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    tenant_id,
    title,
    severity,
    closed_at AS accepted_at,
    ((closure_evidence ->> 'expiry_date'::text))::timestamp with time zone AS expires_at,
    closure_reason AS justification,
    closed_by AS accepted_by,
    (closure_evidence ->> 'approved_by'::text) AS approved_by
   FROM public.tasks t
  WHERE ((status = 'accepted_risk'::text) AND ((closure_evidence ->> 'expiry_date'::text) IS NOT NULL) AND (((closure_evidence ->> 'expiry_date'::text))::timestamp with time zone > now()) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()));


--
-- Name: VIEW v_risk_debt_active; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_risk_debt_active IS 'ADR-026: Tenant-isolated active risk debt view. Uses security_invoker=on with mandatory tenant filter.';


--
-- Name: v_risk_debt_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_risk_debt_summary WITH (security_barrier='true', security_invoker='true') AS
 SELECT tenant_id,
    count(*) AS total_active,
    count(*) FILTER (WHERE (severity = 'critical'::text)) AS critical_count,
    count(*) FILTER (WHERE (severity = 'high'::text)) AS high_count,
    count(*) FILTER (WHERE ((expires_at IS NOT NULL) AND (expires_at < (now() + '7 days'::interval)))) AS expiring_soon
   FROM public.v_risk_debt_active
  WHERE ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin())
  GROUP BY tenant_id;


--
-- Name: VIEW v_risk_debt_summary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_risk_debt_summary IS 'ADR-026/V-609: Tenant-isolated risk debt summary com filtro EXPLÍCITO. Não depende apenas de herança.';


--
-- Name: v_rls_continuous_check; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_rls_continuous_check WITH (security_barrier='true', security_invoker='true') AS
 SELECT c.relname AS table_name,
    c.relrowsecurity AS rls_enabled,
    (( SELECT count(*) AS count
           FROM pg_policies p
          WHERE (p.tablename = (c.relname)::text)))::integer AS policy_count,
        CASE
            WHEN (NOT c.relrowsecurity) THEN 'CRITICAL'::text
            WHEN (( SELECT count(*) AS count
               FROM pg_policies p
              WHERE (p.tablename = (c.relname)::text)) = 0) THEN 'WARNING'::text
            ELSE 'OK'::text
        END AS status
   FROM (pg_class c
     JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
  WHERE ((c.relkind = 'r'::"char") AND (n.nspname = 'public'::name) AND public.is_current_super_admin());


--
-- Name: VIEW v_rls_continuous_check; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_rls_continuous_check IS 'ADR-VELLUM V-201: RLS continuous monitoring - super_admin only via is_current_super_admin(). Security audit view.';


--
-- Name: v_rls_security_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_rls_security_status WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    test_run_id,
    test_name,
    table_name,
    passed,
    failure_reason,
    tested_at,
    details
   FROM public.rls_test_results rt
  WHERE public.is_current_super_admin();


--
-- Name: VIEW v_rls_security_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_rls_security_status IS 'ADR-VELLUM V-201: RLS security test results - super_admin only via is_current_super_admin(). Security audit view.';


--
-- Name: v_security_dashboard; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_security_dashboard WITH (security_barrier='true', security_invoker='true') AS
 SELECT 'security_summary'::text AS metric_type,
    ( SELECT count(*) AS count
           FROM public.security_logs
          WHERE ((security_logs.created_at > (now() - '24:00:00'::interval)) AND ((security_logs.tenant_id = public.get_active_tenant_id()) OR (public.get_active_tenant_id() IS NULL)))) AS events_24h,
    ( SELECT count(*) AS count
           FROM public.security_logs
          WHERE ((security_logs.severity = 'critical'::text) AND (security_logs.created_at > (now() - '24:00:00'::interval)) AND ((security_logs.tenant_id = public.get_active_tenant_id()) OR (public.get_active_tenant_id() IS NULL)))) AS critical_events_24h,
    ( SELECT count(*) AS count
           FROM public.agents
          WHERE ((agents.archived_at IS NULL) AND ((agents.tenant_id = public.get_active_tenant_id()) OR (public.get_active_tenant_id() IS NULL)))) AS active_agents,
    now() AS generated_at
  WHERE ((auth.uid() IS NOT NULL) AND public.is_current_super_admin());


--
-- Name: VIEW v_security_dashboard; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_security_dashboard IS 'ADR-VELLUM V-201: Global security summary - super_admin only via is_current_super_admin(). Intentionally global for platform monitoring.';


--
-- Name: v_security_invariants; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_security_invariants WITH (security_barrier='true', security_invoker='true') AS
 SELECT now() AS snapshot_at,
    ( SELECT count(*) AS count
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((c.relrowsecurity = true) AND (n.nspname = 'public'::name) AND (c.relkind = 'r'::"char"))) AS inv001_tables_with_rls,
    ( SELECT count(*) AS count
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((n.nspname = 'public'::name) AND (c.relkind = 'r'::"char"))) AS inv001_total_tables,
    ( SELECT count(DISTINCT pg_policies.tablename) AS count
           FROM pg_policies
          WHERE (pg_policies.schemaname = 'public'::name)) AS inv001_tables_with_policies,
    ( SELECT count(*) AS count
           FROM public.hmac_signatures
          WHERE (hmac_signatures.used_at > (now() - '24:00:00'::interval))) AS inv002_signatures_24h,
    ( SELECT count(*) AS count
           FROM public.hmac_signatures
          WHERE (hmac_signatures.used_at > (now() - '01:00:00'::interval))) AS inv002_signatures_1h,
    ( SELECT count(DISTINCT hmac_signatures.agent_name) AS count
           FROM public.hmac_signatures
          WHERE (hmac_signatures.used_at > (now() - '24:00:00'::interval))) AS inv002_unique_agents_24h,
    ( SELECT COALESCE(( SELECT hmac_signatures.used_at
                   FROM public.hmac_signatures
                  ORDER BY hmac_signatures.used_at DESC
                 LIMIT 1), '1970-01-01 00:00:00+00'::timestamp with time zone) AS "coalesce") AS inv002_last_verification,
    ( SELECT count(DISTINCT agents.tenant_id) AS count
           FROM public.agents
          WHERE (agents.archived_at IS NULL)) AS inv003_active_tenants,
    ( SELECT count(*) AS count
           FROM public.rls_test_results
          WHERE ((rls_test_results.passed = true) AND (rls_test_results.tested_at > (now() - '7 days'::interval)))) AS inv003_rls_tests_passed_7d,
    ( SELECT count(*) AS count
           FROM public.rls_test_results
          WHERE ((rls_test_results.passed = false) AND (rls_test_results.tested_at > (now() - '7 days'::interval)))) AS inv003_rls_tests_failed_7d,
    ( SELECT (count(*) = 0)
           FROM pg_views v
          WHERE ((v.schemaname = 'public'::name) AND (v.viewname <> ALL (ARRAY['v_security_invariants'::name, 'hmac_agent_secrets'::name])) AND ((POSITION(('hmac_secret'::text) IN (v.definition)) > 0) OR (POSITION(('password'::text) IN (v.definition)) > 0)))) AS inv004_no_secrets_in_views,
    ( SELECT count(*) AS count
           FROM pg_views v
          WHERE ((v.schemaname = 'public'::name) AND (v.viewname = ANY (ARRAY['agents_public'::name, 'agents_safe'::name, 'active_agents'::name])) AND (POSITION(('hmac_secret'::text) IN (v.definition)) = 0))) AS inv004_safe_agent_views,
    ( SELECT count(*) AS count
           FROM public.audit_logs_old
          WHERE (audit_logs_old.created_at > (now() - '24:00:00'::interval))) AS inv005_audit_entries_24h,
    ( SELECT count(*) AS count
           FROM public.audit_logs_old
          WHERE (audit_logs_old.created_at > (now() - '01:00:00'::interval))) AS inv005_audit_entries_1h,
    ( SELECT count(DISTINCT audit_logs_old.action) AS count
           FROM public.audit_logs_old
          WHERE (audit_logs_old.created_at > (now() - '24:00:00'::interval))) AS inv005_unique_actions_24h,
    ( SELECT count(*) AS count
           FROM public.agent_evidence_logs
          WHERE (agent_evidence_logs.created_at > (now() - '24:00:00'::interval))) AS inv005_evidence_logs_24h,
    ( SELECT (count(*) = 0)
           FROM information_schema.role_table_grants
          WHERE (((role_table_grants.grantee)::name = 'anon'::name) AND ((role_table_grants.privilege_type)::text = ANY ((ARRAY['INSERT'::character varying, 'UPDATE'::character varying, 'DELETE'::character varying])::text[])) AND ((role_table_grants.table_schema)::name = 'public'::name))) AS inv006_no_anon_write,
    ( SELECT count(*) AS count
           FROM pg_policies
          WHERE ((pg_policies.schemaname = 'public'::name) AND ((pg_policies.roles)::text ~~ '%service_role%'::text))) AS inv006_service_role_policies,
    ( SELECT count(*) AS count
           FROM public.agents
          WHERE ((agents.archived_at IS NULL) AND (agents.last_heartbeat > (now() - '00:30:00'::interval)))) AS health_active_agents,
    ( SELECT count(*) AS count
           FROM public.ai_actions
          WHERE ((ai_actions.status = 'pending'::text) AND (ai_actions.created_at > (now() - '7 days'::interval)))) AS health_pending_actions,
    ( SELECT count(*) AS count
           FROM public.ai_actions
          WHERE ((ai_actions.status = 'completed'::text) AND (ai_actions.created_at > (now() - '7 days'::interval)))) AS health_completed_actions
  WHERE public.is_current_super_admin();


--
-- Name: VIEW v_security_invariants; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_security_invariants IS 'Global view - restricted to super_admin only (V-303)';


--
-- Name: v_security_scan_compliance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_security_scan_compliance WITH (security_barrier='true', security_invoker='true') AS
 SELECT 'profiles'::text AS object_name,
    'table'::text AS object_type,
    (EXISTS ( SELECT 1
           FROM pg_policies
          WHERE ((pg_policies.tablename = 'profiles'::name) AND (pg_policies.schemaname = 'public'::name)))) AS has_rls_policies,
    (EXISTS ( SELECT 1
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((c.relname = 'profiles'::name) AND (n.nspname = 'public'::name) AND (c.relrowsecurity = true)))) AS rls_enabled,
    'SSA-SEC-004'::text AS hardening_standard
  WHERE (auth.uid() IS NOT NULL)
UNION ALL
 SELECT 'active_sessions'::text AS object_name,
    'table'::text AS object_type,
    (EXISTS ( SELECT 1
           FROM pg_policies
          WHERE ((pg_policies.tablename = 'active_sessions'::name) AND (pg_policies.schemaname = 'public'::name)))) AS has_rls_policies,
    (EXISTS ( SELECT 1
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((c.relname = 'active_sessions'::name) AND (n.nspname = 'public'::name) AND (c.relrowsecurity = true)))) AS rls_enabled,
    'SSA-SEC-005'::text AS hardening_standard
  WHERE (auth.uid() IS NOT NULL)
UNION ALL
 SELECT 'enrollment_keys'::text AS object_name,
    'table'::text AS object_type,
    (EXISTS ( SELECT 1
           FROM pg_policies
          WHERE ((pg_policies.tablename = 'enrollment_keys'::name) AND (pg_policies.schemaname = 'public'::name)))) AS has_rls_policies,
    (EXISTS ( SELECT 1
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((c.relname = 'enrollment_keys'::name) AND (n.nspname = 'public'::name) AND (c.relrowsecurity = true)))) AS rls_enabled,
    'SSA-SEC-006'::text AS hardening_standard
  WHERE (auth.uid() IS NOT NULL);


--
-- Name: v_service_role_policies; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_service_role_policies WITH (security_barrier='true', security_invoker='true') AS
 SELECT tablename,
    policyname,
    cmd AS operation,
    'service_role'::text AS granted_to,
    'INTENTIONAL: Backend automation via Edge Functions'::text AS justification,
    'LOW'::text AS risk_level
   FROM pg_policies
  WHERE ((schemaname = 'public'::name) AND ((roles)::text = '{service_role}'::text) AND ((qual = 'true'::text) OR (with_check = 'true'::text)) AND (auth.uid() IS NOT NULL))
  ORDER BY tablename;


--
-- Name: v_soar_execution_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_soar_execution_summary WITH (security_barrier='true', security_invoker='true') AS
 SELECT se.tenant_id,
    se.status,
    se.trigger_type,
    sp.name AS playbook_name,
    count(*) AS execution_count,
    max(se.created_at) AS last_execution,
    count(*) FILTER (WHERE (se.status = 'completed'::text)) AS completed_count,
    count(*) FILTER (WHERE (se.status = 'failed'::text)) AS failed_count
   FROM (public.soar_executions se
     LEFT JOIN public.soar_playbooks sp ON ((sp.id = se.playbook_id)))
  WHERE (se.tenant_id = public.get_active_tenant_id())
  GROUP BY se.tenant_id, se.status, se.trigger_type, sp.name;


