-- Name: VIEW v_soc2_readiness; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_soc2_readiness IS 'SSA-SEC-010: Hardened with security_invoker, security_barrier, auth.uid() filter';


--
-- Name: v_stuck_jobs_report; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_stuck_jobs_report WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    agent_name,
    type,
    status,
    tenant_id,
    created_at,
    delivered_at,
    (EXTRACT(epoch FROM (now() - COALESCE(delivered_at, created_at))) / (60)::numeric) AS minutes_stuck,
        CASE
            WHEN ((status = 'delivered'::text) AND (delivered_at < (now() - '00:30:00'::interval))) THEN 'stuck_delivered'::text
            WHEN ((status = 'queued'::text) AND (created_at < (now() - '02:00:00'::interval))) THEN 'stuck_queued'::text
            WHEN ((status = 'pending'::text) AND (created_at < (now() - '01:00:00'::interval))) THEN 'stuck_pending'::text
            ELSE 'normal'::text
        END AS stuck_reason
   FROM public.jobs
  WHERE ((((status = 'delivered'::text) AND (delivered_at < (now() - '00:30:00'::interval))) OR ((status = 'queued'::text) AND (created_at < (now() - '02:00:00'::interval))) OR ((status = 'pending'::text) AND (created_at < (now() - '01:00:00'::interval)))) AND (auth.uid() IS NOT NULL) AND ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
  ORDER BY (EXTRACT(epoch FROM (now() - COALESCE(delivered_at, created_at))) / (60)::numeric) DESC;


--
-- Name: VIEW v_stuck_jobs_report; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_stuck_jobs_report IS 'SSA-SEC-010: Hardened with security_invoker, security_barrier, auth.uid() filter';


--
-- Name: v_system_contracts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_system_contracts WITH (security_barrier='true', security_invoker='true') AS
 SELECT 'task_source_type'::text AS contract,
    unnest(ARRAY['ai_insight'::text, 'system_alert'::text, 'playbook_execution'::text, 'red_team'::text, 'manual'::text, 'job'::text, 'dlq'::text]) AS value
  WHERE (public.is_current_super_admin() OR (auth.uid() IS NOT NULL))
UNION ALL
 SELECT 'job_status'::text AS contract,
    unnest(ARRAY['pending'::text, 'in_progress'::text, 'completed'::text, 'failed'::text, 'cancelled'::text, 'timeout'::text, 'delivered'::text, 'ack_timeout'::text]) AS value
  WHERE (public.is_current_super_admin() OR (auth.uid() IS NOT NULL))
UNION ALL
 SELECT 'failure_class'::text AS contract,
    unnest(ARRAY['TRANSIENT'::text, 'PERMANENT'::text, 'EXPECTED_DROP'::text, 'BUG'::text, 'UNKNOWN'::text]) AS value
  WHERE (public.is_current_super_admin() OR (auth.uid() IS NOT NULL));


--
-- Name: VIEW v_system_contracts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_system_contracts IS 'ADR-026: System contract enums. Uses security_invoker=on with auth check.';


--
-- Name: v_system_cycle_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_system_cycle_health WITH (security_barrier='true', security_invoker='true') AS
 SELECT 'ai_actions_pending_verification'::text AS cycle,
    count(*) AS pending_count,
    min(ai_actions.executed_at) AS oldest_pending
   FROM public.ai_actions
  WHERE ((ai_actions.effectiveness_status = 'pending'::text) AND (ai_actions.status = 'executed'::text) AND ((ai_actions.tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
UNION ALL
 SELECT 'insights_without_action'::text AS cycle,
    count(*) AS pending_count,
    min(i.created_at) AS oldest_pending
   FROM (public.ai_insights i
     LEFT JOIN public.ai_actions a ON ((a.insight_id = i.id)))
  WHERE ((i.severity = ANY (ARRAY['critical'::text, 'high'::text])) AND (i.acknowledged = false) AND (a.id IS NULL) AND (i.created_at > (now() - '7 days'::interval)) AND ((i.tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
UNION ALL
 SELECT 'unresolved_alerts'::text AS cycle,
    count(*) AS pending_count,
    min(system_alerts.created_at) AS oldest_pending
   FROM public.system_alerts
  WHERE ((system_alerts.resolved_at IS NULL) AND (system_alerts.created_at < (now() - '24:00:00'::interval)) AND ((system_alerts.tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()))
UNION ALL
 SELECT 'orphan_pending_jobs'::text AS cycle,
    count(*) AS pending_count,
    min(jobs.created_at) AS oldest_pending
   FROM public.jobs
  WHERE ((jobs.status = 'pending'::text) AND (jobs.expires_at < now()) AND ((jobs.tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin()));


--
-- Name: VIEW v_system_cycle_health; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_system_cycle_health IS 'ADR-023: System health metrics with security_invoker=on + tenant isolation';


--
-- Name: v_system_operations_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_system_operations_summary WITH (security_barrier='true', security_invoker='true') AS
 SELECT id AS tenant_id,
    name AS tenant_name,
    ( SELECT count(*) AS count
           FROM public.agents a
          WHERE ((a.tenant_id = t.id) AND (a.archived_at IS NULL))) AS total_agents,
    ( SELECT count(*) AS count
           FROM public.agents a
          WHERE ((a.tenant_id = t.id) AND (a.status = 'active'::text) AND (a.last_heartbeat > (now() - '00:15:00'::interval)))) AS active_agents,
    ( SELECT count(*) AS count
           FROM public.jobs j
          WHERE ((j.tenant_id = t.id) AND (j.created_at > (now() - '24:00:00'::interval)))) AS jobs_24h,
    ( SELECT count(*) AS count
           FROM public.failed_jobs_dlq d
          WHERE ((d.tenant_id = t.id) AND (d.status = 'pending'::text))) AS pending_dlq
   FROM public.tenants t
  WHERE ((id = public.get_active_tenant_id()) OR public.is_current_super_admin());


--
-- Name: v_task_automation_metrics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_task_automation_metrics WITH (security_barrier='true', security_invoker='true') AS
 SELECT tenant_id,
    date_trunc('day'::text, closed_at) AS closure_day,
    count(*) FILTER (WHERE (closure_reason ~~ 'Auto-%'::text)) AS auto_closed,
    count(*) FILTER (WHERE ((closure_reason !~~ 'Auto-%'::text) OR (closure_reason IS NULL))) AS manual_closed,
    round((((count(*) FILTER (WHERE (closure_reason ~~ 'Auto-%'::text)))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 1) AS automation_rate_percent
   FROM public.tasks
  WHERE ((closed_at IS NOT NULL) AND (closed_at > (now() - '30 days'::interval)) AND (tenant_id = public.get_active_tenant_id()))
  GROUP BY tenant_id, (date_trunc('day'::text, closed_at));


--
-- Name: v_task_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_task_stats WITH (security_barrier='true', security_invoker='true') AS
 SELECT tenant_id,
    count(*) AS total_tasks,
    count(*) FILTER (WHERE (status = 'pending'::text)) AS pending,
    count(*) FILTER (WHERE (status = 'in_progress'::text)) AS in_progress,
    count(*) FILTER (WHERE (status = 'completed'::text)) AS completed,
    count(*) FILTER (WHERE (status = 'failed'::text)) AS failed
   FROM public.tasks
  WHERE ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin())
  GROUP BY tenant_id;


