-- Name: v_tasks_requiring_closure; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_tasks_requiring_closure WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    tenant_id,
