--
-- Name: v_tenant_claim_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_tenant_claim_health WITH (security_barrier='true', security_invoker='true') AS
 SELECT date_trunc('hour'::text, created_at) AS period,
    count(*) FILTER (WHERE (((details ->> 'active_tenant_id'::text) IS NOT NULL) AND ((details ->> 'active_tenant_id'::text) <> ''::text))) AS valid_claims,
    count(*) FILTER (WHERE (((details ->> 'active_tenant_id'::text) IS NULL) OR ((details ->> 'active_tenant_id'::text) = ''::text))) AS missing_claims,
    count(*) FILTER (WHERE (action = 'tenant_switch'::text)) AS tenant_switches,
    count(*) FILTER (WHERE ((action = 'update_user_role'::text) AND (success = false))) AS cross_tenant_attempts
   FROM public.audit_logs_old
  WHERE ((created_at > (now() - '7 days'::interval)) AND public.is_current_super_admin())
  GROUP BY (date_trunc('hour'::text, created_at))
  ORDER BY (date_trunc('hour'::text, created_at)) DESC;


--
-- Name: VIEW v_tenant_claim_health; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_tenant_claim_health IS 'ADR-026: Super-admin only tenant claim health monitoring. Uses security_invoker=on.';


