-- Name: v_tenant_isolation_metrics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_tenant_isolation_metrics WITH (security_barrier='true', security_invoker='true') AS
 SELECT id AS tenant_id,
    name AS tenant_name,
    ( SELECT count(*) AS count
           FROM public.agents a
          WHERE ((a.tenant_id = t.id) AND (a.archived_at IS NULL))) AS agent_count,
    ( SELECT count(*) AS count
           FROM public.jobs j
          WHERE (j.tenant_id = t.id)) AS job_count,
    ( SELECT count(*) AS count
           FROM public.user_roles ur
          WHERE (ur.tenant_id = t.id)) AS user_count
   FROM public.tenants t
  WHERE ((auth.uid() IS NOT NULL) AND ((id = public.get_active_tenant_id()) OR public.is_current_super_admin()));


