--
-- Name: v_zero_gap_dashboard; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_zero_gap_dashboard WITH (security_barrier='true', security_invoker='true') AS
 WITH orphan_tasks AS (
         SELECT count(*) AS cnt
           FROM public.tasks
          WHERE ((tasks.assigned_to IS NULL) AND (tasks.status <> ALL (ARRAY['completed'::text, 'cancelled'::text, 'resolved'::text])) AND ((tasks.tenant_id = public.get_active_tenant_id()) OR (public.get_active_tenant_id() IS NULL)))
        ), zombie_jobs AS (
         SELECT count(*) AS cnt
           FROM public.jobs
          WHERE ((jobs.status = ANY (ARRAY['pending'::text, 'in_progress'::text, 'queued'::text])) AND (jobs.created_at < (now() - '04:00:00'::interval)) AND ((jobs.tenant_id = public.get_active_tenant_id()) OR (public.get_active_tenant_id() IS NULL)))
        ), stale_crons AS (
         SELECT count(*) AS cnt
           FROM public.cron_health
          WHERE (cron_health.last_success_at < (now() - '04:00:00'::interval))
        ), secured_views AS (
         SELECT count(*) AS cnt
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((n.nspname = 'public'::name) AND (c.relkind = 'v'::"char") AND ((c.reloptions)::text ~~ '%security_invoker=on%'::text))
        ), total_views AS (
         SELECT count(*) AS cnt
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((n.nspname = 'public'::name) AND (c.relkind = 'v'::"char"))
        ), failed_no_error AS (
         SELECT count(*) AS cnt
           FROM public.jobs
          WHERE ((jobs.status = 'failed'::text) AND (jobs.error_message IS NULL) AND ((jobs.tenant_id = public.get_active_tenant_id()) OR (public.get_active_tenant_id() IS NULL)))
        )
 SELECT ot.cnt AS orphan_tasks,
    zj.cnt AS zombie_jobs,
    sc.cnt AS stale_crons,
    sv.cnt AS secured_views,
    tv.cnt AS total_views,
    round((((sv.cnt)::numeric / (NULLIF(tv.cnt, 0))::numeric) * (100)::numeric), 1) AS view_security_coverage_pct,
    fe.cnt AS failed_jobs_no_error,
        CASE
            WHEN ((zj.cnt > 0) OR (sc.cnt > 0) OR (fe.cnt > 5)) THEN 'CRITICAL'::text
            WHEN (ot.cnt > 10) THEN 'WARNING'::text
            ELSE 'HEALTHY'::text
        END AS system_status,
    now() AS checked_at
   FROM orphan_tasks ot,
    zombie_jobs zj,
    stale_crons sc,
    secured_views sv,
    total_views tv,
    failed_no_error fe
  WHERE public.is_current_super_admin();


--
-- Name: VIEW v_zero_gap_dashboard; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_zero_gap_dashboard IS 'Global view - restricted to super_admin only (V-303)';


--
-- Name: v_zero_gap_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_zero_gap_health WITH (security_barrier='true', security_invoker='true') AS
 SELECT ( SELECT count(*) AS count
           FROM public.jobs
          WHERE ((jobs.status = ANY (ARRAY['pending'::text, 'queued'::text, 'delivered'::text])) AND (jobs.expires_at < now()) AND ((jobs.tenant_id = public.get_active_tenant_id()) OR (public.get_active_tenant_id() IS NULL)))) AS expired_jobs_stuck,
    ( SELECT count(*) AS count
           FROM public.jobs
          WHERE ((jobs.status = 'delivered'::text) AND (jobs.created_at < (now() - '02:00:00'::interval)) AND ((jobs.tenant_id = public.get_active_tenant_id()) OR (public.get_active_tenant_id() IS NULL)))) AS zombie_delivered,
    ( SELECT count(*) AS count
           FROM public.failed_jobs_dlq
          WHERE ((failed_jobs_dlq.status = 'pending'::text) AND ((failed_jobs_dlq.tenant_id = public.get_active_tenant_id()) OR (public.get_active_tenant_id() IS NULL)))) AS dlq_pending,
    ( SELECT count(*) AS count
           FROM public.failed_jobs_dlq
          WHERE ((failed_jobs_dlq.status = 'exhausted'::text) AND ((failed_jobs_dlq.tenant_id = public.get_active_tenant_id()) OR (public.get_active_tenant_id() IS NULL)))) AS dlq_exhausted,
    ( SELECT count(*) AS count
           FROM public.tasks
          WHERE ((tasks.status = ANY (ARRAY['open'::text, 'in_progress'::text])) AND (tasks.updated_at < (now() - '14 days'::interval)) AND ((tasks.tenant_id = public.get_active_tenant_id()) OR (public.get_active_tenant_id() IS NULL)))) AS stale_tasks,
    ( SELECT count(*) AS count
           FROM public.cron_health_checks
          WHERE (cron_health_checks.consecutive_failures > 3)) AS failing_crons,
    ( SELECT count(*) AS count
           FROM public.domain_events
          WHERE ((domain_events.tenant_id = public.get_active_tenant_id()) OR (public.get_active_tenant_id() IS NULL))) AS domain_events_total,
    ( SELECT count(*) AS count
           FROM public.jobs
          WHERE ((jobs.status = ANY (ARRAY['pending'::text, 'queued'::text, 'delivered'::text])) AND ((jobs.tenant_id = public.get_active_tenant_id()) OR (public.get_active_tenant_id() IS NULL)))) AS active_jobs,
    ( SELECT count(*) AS count
           FROM public.jobs
          WHERE ((jobs.status = 'completed'::text) AND (jobs.created_at > (now() - '24:00:00'::interval)) AND ((jobs.tenant_id = public.get_active_tenant_id()) OR (public.get_active_tenant_id() IS NULL)))) AS completed_24h,
    ( SELECT count(*) AS count
           FROM public.jobs
          WHERE ((jobs.status = 'failed'::text) AND (jobs.created_at > (now() - '24:00:00'::interval)) AND ((jobs.tenant_id = public.get_active_tenant_id()) OR (public.get_active_tenant_id() IS NULL)))) AS failed_24h
  WHERE ((auth.uid() IS NOT NULL) AND public.is_current_super_admin());


--
-- Name: VIEW v_zero_gap_health; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_zero_gap_health IS 'System health dashboard. Restricted to super_admin only. security_invoker=on.';


