-- Name: vendor_risk_registry; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vendor_risk_registry (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    vendor_name text NOT NULL,
    vendor_type text NOT NULL,
    criticality text DEFAULT 'medium'::text NOT NULL,
    services_provided text[],
    data_shared text[],
    compliance_certifications text[],
    contract_start_date date,
    contract_end_date date,
    last_review_date date,
    next_review_date date,
    risk_score integer,
    risk_notes text,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT vendor_risk_registry_criticality_check CHECK ((criticality = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT vendor_risk_registry_risk_score_check CHECK (((risk_score >= 0) AND (risk_score <= 100))),
    CONSTRAINT vendor_risk_registry_status_check CHECK ((status = ANY (ARRAY['active'::text, 'pending_review'::text, 'suspended'::text, 'terminated'::text])))
);


