);


--
-- Name: TABLE web_access_policies; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.web_access_policies IS 'Políticas de acesso web configuráveis por tenant. Relacionada com tenants.';


--
-- Name: COLUMN web_access_policies.action; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.web_access_policies.action IS 'Ação: allow=permitir, block=bloquear, monitor=monitorar';


--
-- Name: COLUMN web_access_policies.source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.web_access_policies.source IS 'Origem da política: manual, playbook, rule, threat_intel';


--
-- Name: COLUMN web_access_policies.applied_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.web_access_policies.applied_at IS 'Quando a política foi sincronizada com os agentes';


--
-- Name: webhook_configs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.webhook_configs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    name text NOT NULL,
    url text NOT NULL,
    secret text,
    headers jsonb DEFAULT '{}'::jsonb,
    event_types text[] DEFAULT ARRAY['security_alert'::text, 'critical_alert'::text, 'dlq_exhausted'::text],
    severity_filter text[] DEFAULT ARRAY['critical'::text, 'warning'::text],
    is_active boolean DEFAULT true NOT NULL,
    last_triggered_at timestamp with time zone,
    last_status_code integer,
    failure_count integer DEFAULT 0 NOT NULL,
    max_retries integer DEFAULT 3 NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE webhook_configs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.webhook_configs IS 'Configurações de destinos de webhook para notificações externas';


--
-- Name: COLUMN webhook_configs.url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_configs.url IS 'URL de destino para envio de alertas via POST';


--
-- Name: COLUMN webhook_configs.secret; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_configs.secret IS 'Chave HMAC para assinatura de payloads (X-Webhook-Signature)';


--
-- Name: COLUMN webhook_configs.event_types; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_configs.event_types IS 'Tipos de eventos que disparam o webhook';


--
-- Name: COLUMN webhook_configs.severity_filter; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_configs.severity_filter IS 'Filtro de severidade mínima para disparo';


--
-- Name: COLUMN webhook_configs.failure_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_configs.failure_count IS 'Contador de falhas consecutivas para circuit breaker';


--
-- Name: webhook_configs_safe; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.webhook_configs_safe WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    tenant_id,
    name,
    url,
    event_types,
    severity_filter,
    is_active,
    headers,
    max_retries,
    failure_count,
    last_triggered_at,
    last_status_code,
    created_at,
    updated_at,
    created_by
   FROM public.webhook_configs
  WHERE ((tenant_id = public.get_active_tenant_id()) OR public.is_current_super_admin());


--
-- Name: VIEW webhook_configs_safe; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.webhook_configs_safe IS 'Safe view excluding webhook secrets. Regular users should query this view. ADR-038.';


--
-- Name: weekly_security_reports; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.weekly_security_reports (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    week_start date NOT NULL,
    week_end date NOT NULL,
    metrics jsonb NOT NULL,
    executive_summary text,
    generated_at timestamp with time zone DEFAULT now(),
    sent_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now()
);


--
-- Name: xp_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.xp_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    action text NOT NULL,
    xp_earned integer NOT NULL,
    description text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


