--
-- Name: jobs Admins and operators can insert jobs; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admins and operators can insert jobs" ON public.jobs FOR INSERT TO authenticated WITH CHECK (public.user_belongs_to_tenant(tenant_id));


--
-- Name: rollback_test_results Admins can create rollback tests; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admins can create rollback tests" ON public.rollback_test_results FOR INSERT TO authenticated WITH CHECK (((EXISTS ( SELECT 1
   FROM public.user_roles
  WHERE ((user_roles.user_id = auth.uid()) AND (user_roles.role = ANY (ARRAY['admin'::public.app_role, 'super_admin'::public.app_role])) AND (user_roles.tenant_id = rollback_test_results.tenant_id)))) OR (EXISTS ( SELECT 1
   FROM public.user_roles
  WHERE ((user_roles.user_id = auth.uid()) AND (user_roles.role = 'super_admin'::public.app_role))))));


--
-- Name: tenant_software_policy Admins can insert software policy; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admins can insert software policy" ON public.tenant_software_policy FOR INSERT TO authenticated WITH CHECK ((tenant_id = public.get_active_tenant_id()));


--
-- Name: agent_updates Admins can manage agent updates; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admins can manage agent updates" ON public.agent_updates TO authenticated USING ((public.has_role(auth.uid(), 'admin'::public.app_role) AND (tenant_id = public.get_active_tenant_id()))) WITH CHECK ((public.has_role(auth.uid(), 'admin'::public.app_role) AND (tenant_id = public.get_active_tenant_id())));


--
