   FROM public.user_roles ur
  WHERE ((ur.user_id = auth.uid()) AND (ur.role = ANY (ARRAY['admin'::public.app_role, 'super_admin'::public.app_role, 'analyst'::public.app_role])) AND (ur.tenant_id = public.get_active_tenant_id())))))));


