--

CREATE POLICY profiles_select_self_or_admin ON public.profiles FOR SELECT TO authenticated USING (((user_id = auth.uid()) OR public.is_current_super_admin() OR (EXISTS ( SELECT 1
   FROM public.user_roles ur
  WHERE ((ur.user_id = auth.uid()) AND (ur.role = ANY (ARRAY['admin'::public.app_role, 'super_admin'::public.app_role])) AND (ur.tenant_id = public.get_active_tenant_id()))))));


